# ── registry projection ──────────────────────────────────────────────────────
# Checks declared via aws_checkdef (batch 2 onward) contribute their severity,
# compliance mapping and remediation here rather than being hand-written into the three
# literals above. merge_maps REFUSES to overwrite an existing id: a registry merge
# bypasses the duplicate-key ratchet, which only ever sees dict literals, so the
# collision has to be caught at merge time instead.
aws_checkdef.merge_maps(CHECK_SEVERITY, COMPLIANCE_MAP, REMEDIATION_MAP)



# ─── IAM privilege-escalation primitives ─────────────────────────────────────
# Action-level model (Rhino Security Labs / PMapper technique set). Each rule's
# `all_of` is a list of requirements; a requirement is satisfied if the principal
# is allowed ANY of its alternative actions. A rule fires when EVERY requirement
# is satisfied. Matching is at the action level only — resource ARNs and policy
# conditions are NOT evaluated, so findings are *potential* paths to verify.
IAM_PRIVESC_RULES = [
    {"id": "IAMPE-01", "name": "Modify a managed policy version",
     "all_of": [["iam:CreatePolicyVersion"]],
     "desc": "Can create a new default version of an attached managed policy and grant itself admin"},
    {"id": "IAMPE-02", "name": "Set default policy version",
     "all_of": [["iam:SetDefaultPolicyVersion"]],
     "desc": "Can roll a managed policy back to a more permissive existing version"},
    {"id": "IAMPE-03", "name": "Attach an administrator policy",
     "all_of": [["iam:AttachUserPolicy", "iam:AttachGroupPolicy", "iam:AttachRolePolicy"]],
     "desc": "Can attach AdministratorAccess to a user/group/role it controls"},
    {"id": "IAMPE-04", "name": "Inline an administrator policy",
     "all_of": [["iam:PutUserPolicy", "iam:PutGroupPolicy", "iam:PutRolePolicy"]],
     "desc": "Can write an inline admin policy onto a user/group/role"},
    {"id": "IAMPE-05", "name": "Add user to a privileged group",
     "all_of": [["iam:AddUserToGroup"]],
     "desc": "Can add itself to a group that has elevated permissions"},
    {"id": "IAMPE-06", "name": "Create access keys for another user",
     "all_of": [["iam:CreateAccessKey"]],
     "desc": "Can mint API keys for a more privileged user"},
    {"id": "IAMPE-07", "name": "Set a console password for another user",
     "all_of": [["iam:CreateLoginProfile", "iam:UpdateLoginProfile"]],
     "desc": "Can set/replace the console login profile of a privileged user"},
    {"id": "IAMPE-08", "name": "Modify a role trust policy",
     "all_of": [["iam:UpdateAssumeRolePolicy"]],
     "desc": "Can rewrite a role's trust policy to assume it, then sts:AssumeRole"},
    {"id": "IAMPE-10", "name": "PassRole to a new EC2 instance",
     "all_of": [["iam:PassRole"], ["ec2:RunInstances"]],
     "desc": "Can launch an EC2 instance with a privileged instance profile"},
    {"id": "IAMPE-11", "name": "PassRole to a new Lambda function",
     "all_of": [["iam:PassRole"], ["lambda:CreateFunction"],
                ["lambda:InvokeFunction", "lambda:AddPermission",
                 "lambda:CreateEventSourceMapping"]],
     "desc": "Can create and invoke a Lambda running a privileged execution role"},
    {"id": "IAMPE-12", "name": "PassRole to a Glue dev endpoint",
     "all_of": [["iam:PassRole"], ["glue:CreateDevEndpoint"]],
     "desc": "Can create a Glue dev endpoint with a privileged role"},
    {"id": "IAMPE-13", "name": "PassRole to a CloudFormation stack",
     "all_of": [["iam:PassRole"], ["cloudformation:CreateStack"]],
     "desc": "Can deploy a CloudFormation stack with a privileged role"},
    {"id": "IAMPE-14", "name": "PassRole to a SageMaker resource",
     "all_of": [["iam:PassRole"],
                ["sagemaker:CreateNotebookInstance", "sagemaker:CreateTrainingJob",
                 "sagemaker:CreateProcessingJob"]],
     "desc": "Can run a SageMaker notebook/job with a privileged role"},
    {"id": "IAMPE-16", "name": "Overwrite a privileged Lambda's code",
     "all_of": [["lambda:UpdateFunctionCode"]],
     "desc": "Can replace the code of an existing function that runs a privileged role"},
    {"id": "IAMPE-18", "name": "Run commands on EC2 via SSM",
     "all_of": [["ssm:SendCommand", "ssm:StartSession"]],
     "desc": "Can execute commands on instances that carry privileged roles"},
]

# Sentinel rule applied first: principal already holds full admin (*)
IAM_PRIVESC_FULL_ADMIN = {
    "id": "IAMPE-19", "name": "Full administrative access",
    "desc": "Principal is allowed Action '*' on all resources (effective administrator)",
}


def _action_allowed(action: str, allow: set, deny: set) -> bool:
    """True if `action` is matched by an allow pattern and not by a deny pattern.
    Wildcards (*, ?) in policy patterns are honoured; matching is case-insensitive."""
    a = action.lower()
    allowed = any(fnmatch.fnmatch(a, p) for p in allow)
    denied = any(fnmatch.fnmatch(a, p) for p in deny)
    return allowed and not denied


def evaluate_privesc(allow: set, deny: set) -> List[Dict]:
    """Return the list of privesc rules a principal (given its effective allow/deny
    action sets) can satisfy. Full-admin short-circuits to a single finding.
    Action-level only — see evaluate_privesc_scoped() for resource-aware scoping."""
    # Full admin: allowed literal "*" and not explicitly denied "*"
    if "*" in allow and "*" not in deny:
        return [IAM_PRIVESC_FULL_ADMIN]
    matched = []
    for rule in IAM_PRIVESC_RULES:
        if all(any(_action_allowed(act, allow, deny) for act in req)
               for req in rule["all_of"]):
            matched.append(rule)
    return matched


# ─── Resource-aware evaluation ───────────────────────────────────────────────
# sts:AssumeRole is extremely common when scoped to specific roles, so it is only
# flagged when granted account-wide (Resource "*") — exactly the false positive
# that resource awareness removes.
IAM_PRIVESC_ASSUMEROLE = {
    "id": "IAMPE-20", "name": "Assume any role (sts:AssumeRole on *)",
    "desc": "Can assume ANY role in the account (role chaining); only flagged when unrestricted",
}


def _stmt_actions_match(stmt: Dict, action: str) -> bool:
    return any(fnmatch.fnmatch(action, p) for p in stmt["actions"])


def _arn_service(arn: str) -> str:
    """Service segment of an ARN (arn:partition:service:...), or '' if not an ARN."""
    parts = arn.split(":")
    return parts[2] if len(parts) >= 3 else ""


def _resource_applies(resource: str, action_service: str) -> bool:
    """A resource is relevant to an action only if it is '*' or an ARN of the same
    service. This suppresses e.g. Action '*' scoped to an S3 bucket being treated as
    granting iam:* (the action does not apply to that resource type)."""
    if resource == "*":
        return True
    svc = _arn_service(resource)
    return svc in (action_service, "*", "")


def resource_scope(statements: List[Dict], action: str):
    """For a concrete `action`, return (label, arns) describing the resources it is
    allowed on, counting only resources of the action's own service (or '*'):
    ("account-wide", None) if granted on "*", ("resource-scoped", [arns]) if only on
    specific same-service ARNs, ("none", None) if not actually grantable.
    A missing/empty Resource is treated as "*" (broad) to avoid under-reporting."""
    a = action.lower()
    svc = a.split(":")[0] if ":" in a else a
    allow_res = set()
    for st in statements:
        if st["effect"] != "Allow" or not _stmt_actions_match(st, a):
            continue
        for r in (st["resources"] or {"*"}):
            if _resource_applies(r, svc):
                allow_res.add(r)
    if not allow_res:
        return ("none", None)
    if "*" in allow_res:
        return ("account-wide", None)
    return ("resource-scoped", sorted(allow_res))


def _has_full_admin(statements: List[Dict]) -> bool:
    """True only for Action '*' on Resource '*' (real admin), not Action '*' scoped
    to a single resource. An explicit Deny '*'/'*' revokes it."""
    deny_all = any(st["effect"] == "Deny" and "*" in st["actions"]
                   and "*" in (st["resources"] or {"*"}) for st in statements)
    if deny_all:
        return False
    return any(st["effect"] == "Allow" and "*" in st["actions"]
               and "*" in (st["resources"] or {"*"}) for st in statements)


def _pivot_action(rule: Dict, allow: set, deny: set) -> str:
    """The granting action of a rule that the principal actually holds — taken from
    the rule's first requirement (e.g. iam:PassRole for the PassRole primitives)."""
    for alt in rule["all_of"][0]:
        if _action_allowed(alt, allow, deny):
            return alt.lower()
    return rule["all_of"][0][0].lower()


def _pivot_conditioned(statements: List[Dict], pivot: str) -> bool:
    """True when EVERY Allow statement that grants the pivot action carries a
    policy Condition. Such a path is only exploitable if the caller can satisfy
    the condition (MFA, tag, SourceIp, ExternalId…), so it is downgraded from a
    hard FAIL to a WARN ('verify the condition') rather than dropped."""
    granting = [st for st in statements
                if st["effect"] == "Allow" and _stmt_actions_match(st, pivot)]
    return bool(granting) and all(st.get("condition") for st in granting)


def parse_trust_policy(doc) -> List[Dict]:
    """Parse a role's AssumeRolePolicyDocument into normalized trust statements:
    ``[{effect, aws:[arns], service:[svcs], federated:[...], wildcard:bool,
    actions:set, has_condition:bool}]``. Accepts a URL-encoded string or a dict;
    ``Principal`` may be ``"*"``, a dict of AWS/Service/Federated, or a
    single/list value. Used to build CAN_ASSUME graph edges."""
    out: List[Dict] = []
    if not doc:
        return out
    if isinstance(doc, str):
        try:
            doc = json.loads(unquote(doc))
        except Exception:
            return out
    stmts = doc.get("Statement", [])
    if isinstance(stmts, dict):
        stmts = [stmts]

    def _as_list(v):
        return [v] if isinstance(v, str) else list(v)

    for st in stmts:
        if not isinstance(st, dict):
            continue
        eff = st.get("Effect", "")
        if eff not in ("Allow", "Deny"):
            continue
        pr = st.get("Principal", "")
        aws, svc, fed, wildcard = [], [], [], False
        if pr == "*":
            wildcard = True
        elif isinstance(pr, dict):
            if "AWS" in pr:
                for v in _as_list(pr["AWS"]):
                    if v == "*":
                        wildcard = True
                    else:
                        aws.append(v)
            if "Service" in pr:
                svc = _as_list(pr["Service"])
            if "Federated" in pr:
                fed = _as_list(pr["Federated"])
        av = st.get("Action", [])
        actions = {str(a).lower() for a in _as_list(av)} if av else set()
        out.append({"effect": eff, "aws": aws, "service": svc, "federated": fed,
                    "wildcard": wildcard, "actions": actions,
                    "has_condition": bool(st.get("Condition")),
                    "condition": st.get("Condition") or None})
    return out


def _account_of(arn: str) -> str:
    """Account id segment of an ARN (arn:partition:service:region:account:...).
    Also normalizes a bare 12-digit account-id principal to itself."""
    if isinstance(arn, str) and re.fullmatch(r"\d{12}", arn):
        return arn
    parts = arn.split(":") if isinstance(arn, str) else []
    return parts[4] if len(parts) >= 5 else ""


# Condition keys that scope a grant to a specific account (own => not public/external)
_ACCOUNT_SCOPE_KEYS = {"aws:sourceaccount", "aws:principalaccount", "kms:calleraccount",
                       "aws:sourceowner", "s3:resourceaccount", "aws:resourceaccount"}
_ORG_SCOPE_KEYS = {"aws:principalorgid", "aws:principalorgpaths"}


def _flatten_condition_keys(condition) -> Dict[str, List[str]]:
    """Lowercased condition-key -> values, flattened across POSITIVE-match operator
    blocks only (StringEquals, ArnLike, StringLike, ForAllValues:*, *IfExists, …).
    NEGATED operators (StringNotEquals/StringNotLike/ArnNotEquals/NotIpAddress/…) are
    EXCLUDED: a wildcard principal gated only by 'StringNotEquals CallerAccount == own'
    grants to the whole world EXCEPT the owner — it does NOT pin the grant to own, so
    it must not be read as an account-scoping (private-making) condition."""
    out: Dict[str, List[str]] = {}
    if not isinstance(condition, dict):
        return out
    for op, block in condition.items():
        base = str(op).lower()
        if "notequals" in base or "notlike" in base or "notipaddress" in base:
            continue
        if not isinstance(block, dict):
            continue
        for k, v in block.items():
            vals = v if isinstance(v, list) else [v]
            out.setdefault(str(k).lower(), []).extend(str(x) for x in vals)
    return out


def classify_resource_policy_stmt(stmt: Dict, own_account: str) -> Optional[Dict]:
    """Classify one resource-policy statement's exposure (KMS key policy, Secrets
    resource policy, S3/SNS/SQS-style bucket policy). Returns None for non-Allow
    or purely own-account/service statements. Otherwise a dict:
      {kind: 'public'|'public_conditioned'|'org'|'cross_account',
       external_accounts: [ids], org_id: str|None, has_condition: bool}
    - public              = wildcard principal, no scoping condition (worst case)
    - public_conditioned  = wildcard principal gated only by an unrecognized condition
    - org                 = wildcard/principal gated by aws:PrincipalOrgID (org-shared)
    - cross_account       = explicit external-account principal(s)
    A wildcard gated by an account-scope condition pinned to own_account => None (private)."""
    if not isinstance(stmt, dict) or stmt.get("Effect") != "Allow":
        return None
    principal = stmt.get("Principal")
    not_principal = stmt.get("NotPrincipal")
    cond = stmt.get("Condition")
    ckeys = _flatten_condition_keys(cond)
    has_cond = bool(cond)
    org_vals = [v for k in _ORG_SCOPE_KEYS if k in ckeys for v in ckeys[k]]
    acct_scope_vals = [v for k in _ACCOUNT_SCOPE_KEYS if k in ckeys for v in ckeys[k]]

    # normalize AWS principals -> wildcard flag + list of raw principal strings
    wildcard = False
    aws_principals: List[str] = []
    if principal == "*":
        wildcard = True
    elif isinstance(principal, dict):
        aws_p = principal.get("AWS")
        if aws_p is not None:
            for v in (aws_p if isinstance(aws_p, list) else [aws_p]):
                if v == "*":
                    wildcard = True
                else:
                    aws_principals.append(v)
        # Service / Federated / CanonicalUser principals are handled by callers
    # Allow + NotPrincipal == "everyone except X" == effectively public
    if not_principal is not None and principal is None:
        wildcard = True

    if wildcard:
        if org_vals:
            return {"kind": "org", "external_accounts": [], "org_id": org_vals[0],
                    "has_condition": True}
        if acct_scope_vals:
            # pinned to a specific account via condition
            if own_account and all(v == own_account for v in acct_scope_vals):
                return None                                  # private (own account only)
            return {"kind": "cross_account", "external_accounts": sorted(set(acct_scope_vals)),
                    "org_id": None, "has_condition": True}
        if has_cond:
            return {"kind": "public_conditioned", "external_accounts": [], "org_id": None,
                    "has_condition": True}
        return {"kind": "public", "external_accounts": [], "org_id": None,
                "has_condition": False}

    # explicit AWS principals -> collect external accounts. Only REAL 12-digit account ids
    # count: a legacy CloudFront OAI principal (arn:aws:iam::cloudfront:user/...) resolves to
    # the pseudo-account 'cloudfront' — an AWS-managed service identity used in the documented
    # private-S3-origin pattern, NOT an external customer account, so it must not be flagged.
    external = sorted({acct for p in aws_principals
                       if (acct := _account_of(p)) and acct != own_account
                       and acct.isdigit() and len(acct) == 12})
    if external:
        if org_vals:
            return {"kind": "org", "external_accounts": external, "org_id": org_vals[0],
                    "has_condition": True}
        return {"kind": "cross_account", "external_accounts": external, "org_id": None,
                "has_condition": has_cond}
    return None                                              # own-account only / service


_ECR_HOST_RE = re.compile(r"^(\d{12})\.dkr\.ecr(?:-fips)?\.([a-z0-9-]+)\.amazonaws\.com(?:\.cn)?$")

#: Sentence boundary used to take the first sentence of a catalogued risk write-up as
#: a check's one-line summary. Deliberately conservative: it splits only on a period,
#: question or exclamation mark FOLLOWED BY WHITESPACE, so "PubliclyAccessible=true."
#: mid-sentence abbreviations and "0.0.0.0/0" do not split the line.
_SENTENCE_END = re.compile(r"(?<=[.!?])\s+")


def _framework_citation(framework_id: str, control: str) -> str:
    """Qualify a compliance citation with the framework's name and edition.

    Thin wrapper so the exports do not each carry registry knowledge, and so a
    missing/corrupt reference file degrades to today's unqualified string rather
    than raising inside an export. `compliance_crosswalk` is imported lazily here
    for the same reason every other reference to it in this module is."""
    try:
        from engine import compliance_crosswalk as _cc
        return _cc.framework_citation(framework_id, control)
    except Exception:
        return "%s %s" % (framework_id, control)


def _asff_impact_suffix(check_id: str) -> str:
    """The catalogued business impact, appended to an ASFF Description.

    Security Hub shows Description under the finding, and the per-resource message
    alone says what was found without saying why it matters. Empty string when the
    check has no catalogued impact, so the Description is unchanged rather than
    carrying a dangling separator."""
    d = aws_finding_detail.get_detail(check_id) or {}
    impact = str(d.get("impact") or "").strip()
    return (" | Impact: " + impact) if impact else ""


def _asff_steps_text(check_id: str) -> str:
    """Numbered remediation steps as one line, the FALLBACK for an ASFF finding whose
    check has no one-line CLI in REMEDIATION_MAP.

    Without it Security Hub receives a finding with no Remediation block at all, even
    though the catalogue holds full steps for every registered check -- the operator
    is told what is wrong and nothing about how to fix it."""
    steps = aws_finding_detail.steps_for(check_id)
    if not steps:
        return ""
    return " ".join("%d) %s" % (i, str(s).strip())
                    for i, s in enumerate(steps, 1) if str(s).strip())


def parse_ecr_image_ref(ref: str) -> Optional[Dict]:
    """Parse a container image reference into {account, region, repo, tag, digest}
    for a PRIVATE ECR image, else None (Docker Hub / public.ecr.aws / gcr.io / a
    tagless official image all return None so no bogus ECRImage node is fabricated)."""
    if not ref or not isinstance(ref, str):
        return None
    body, digest = ref, None
    if "@" in ref:
        body, _, digest = ref.partition("@")
    if "/" not in body:
        return None                          # official Docker Hub image, no registry host
    host, path = body.split("/", 1)
    m = _ECR_HOST_RE.match(host)
    if not m:
        return None                          # not a private ECR host
    repo, tag = path, None
    if ":" in path.rsplit("/", 1)[-1]:       # tag only within the final path component
        repo, tag = path.rsplit(":", 1)
    return {"account": m.group(1), "region": m.group(2), "repo": repo, "tag": tag,
            "digest": digest}


def ecr_image_node_ids(account: str, region: str, repo: str, digest: str) -> tuple:
    """Both ECRImage node-id conventions for the SAME image — CNT-02's
    repositoryUri@digest AND Inspector's repository ARN — so RUNS_IMAGE dual-emits
    and joins whichever producer (native scan or Inspector) created the node. Partition/
    host suffix are derived from the region so China/GovCloud ids match their producers."""
    if region.startswith("cn-"):
        partition, host = "aws-cn", "amazonaws.com.cn"
    elif region.startswith("us-gov-"):
        partition, host = "aws-us-gov", "amazonaws.com"
    else:
        partition, host = "aws", "amazonaws.com"
    repo_uri = f"{account}.dkr.ecr.{region}.{host}/{repo}"
    return (f"{repo_uri}@{digest}",
            f"arn:{partition}:ecr:{region}:{account}:repository/{repo}/{digest}")


def evaluate_privesc_scoped(statements: List[Dict], boundary: Optional[List[Dict]] = None,
                            scp_levels: Optional[List] = None,
                            pruned: Optional[List[Dict]] = None) -> List[Dict]:
    """Resource-aware privesc evaluation. Returns matched rules annotated with
    `scope` (account-wide | resource-scoped) and `scope_arns`. Reduces false
    positives vs the action-level model: full admin requires Action '*' on
    Resource '*', and sts:AssumeRole is only flagged when unrestricted.

    Phase 5: when a permission `boundary` and/or `scp_levels` ceiling is supplied,
    each matched pivot is passed through the effective-permissions solver:
    a pivot the ceiling provably neutralizes (unconditional deny / not-allowed) is
    DROPPED (and recorded in `pruned` if given); a pivot gated only by a Condition
    on the boundary/SCP is downgraded to `conditioned`. With both ceilings None
    (the default), no pivot is ever dropped -> byte-for-byte identical to before.

    NB: when the '*' megapivot of a full-admin identity is itself capped by the
    ceiling, we do NOT return []; we fall through and enumerate the granular IAM
    pivots that survive the ceiling — otherwise a boundary/SCP-capped admin would
    hide every real escalation it still holds (the dangerous over-prune)."""

    def _verdict(pivot: str) -> str:
        return aws_effperm.pivot_effective(pivot, statements, boundary, scp_levels)

    def _record_drop(pivot: str, rule_id: str) -> None:
        if pruned is not None:
            pruned.append({"pivot": pivot, "rule": rule_id,
                           "reason": aws_effperm.drop_reason(
                               pivot, statements, boundary, scp_levels)})

    if _has_full_admin(statements):
        v = _verdict("*")
        if v != aws_effperm.DROP:
            return [{**IAM_PRIVESC_FULL_ADMIN, "scope": "account-wide",
                     "scope_arns": None, "pivot": "*",
                     "conditioned": _pivot_conditioned(statements, "*") or v == aws_effperm.CONDITIONED,
                     "effperm": v}]
        # Ceiling caps the '*' megapivot — record it, then fall through to find
        # the granular pivots (iam:AttachUserPolicy, PassRole, …) that survive.
        _record_drop("*", IAM_PRIVESC_FULL_ADMIN["id"])

    allow, deny = set(), set()
    for st in statements:
        if st["effect"] == "Allow":
            allow |= st["actions"]
        elif st["effect"] == "Deny":
            deny |= st["actions"]

    findings = []
    for rule in IAM_PRIVESC_RULES:
        if all(any(_action_allowed(act, allow, deny) for act in req)
               for req in rule["all_of"]):
            pivot = _pivot_action(rule, allow, deny)
            label, arns = resource_scope(statements, pivot)
            if label == "none":
                continue  # pivot action not grantable on any compatible resource
            v = _verdict(pivot)
            if v == aws_effperm.DROP:
                _record_drop(pivot, rule["id"])   # ceiling neutralizes it
                continue
            findings.append({**rule, "scope": label, "scope_arns": arns,
                             "pivot": pivot,
                             "conditioned": _pivot_conditioned(statements, pivot)
                             or v == aws_effperm.CONDITIONED,
                             "effperm": v})

    # IAMPE-20: only when sts:AssumeRole is granted account-wide
    if _action_allowed("sts:assumerole", allow, deny):
        label, arns = resource_scope(statements, "sts:assumerole")
        if label == "account-wide":
            v = _verdict("sts:assumerole")
            if v == aws_effperm.DROP:
                _record_drop("sts:assumerole", IAM_PRIVESC_ASSUMEROLE["id"])
            else:
                findings.append({**IAM_PRIVESC_ASSUMEROLE, "scope": label,
                                 "scope_arns": None, "pivot": "sts:assumerole",
                                 "conditioned": _pivot_conditioned(statements, "sts:assumerole")
                                 or v == aws_effperm.CONDITIONED,
                                 "effperm": v})
    return findings


# ─── Risk scoring ────────────────────────────────────────────────────────────
def compute_risk_score(results: List[Result]) -> float:
    """Compute posture score: 100 − (CRIT×15 + HIGH×5 + MED×2 + LOW×0.5).
    Clamped to 0–100.  Only FAIL results count as penalties."""
    penalty = 0.0
    for r in results:
        if r.status == "FAIL" and r.severity:
            penalty += SEVERITY_WEIGHTS.get(r.severity, 0)
    return max(0.0, min(100.0, round(100 - penalty, 1)))


def qualified_posture(results: List[Result],
                     not_evaluated: Optional[Dict[str, str]] = None):
    """Posture score plus what the scan could not evaluate.

    ``compute_risk_score`` is 100 - the penalty for every FAIL it SAW. A check that
    returned AccessDenied contributes no penalty, so losing a permission raises the
    score: on a four-check example, losing iam:ListUsers moved an account from 75/C
    to 85/B. The scan got worse and the grade improved.

    This does not change that arithmetic -- the score is written to
    ``scans.posture_score`` and accumulates into 24 months of history, and silently
    re-weighting it would rewrite every dashboard and every trend line. It adds the
    half that was always missing, and withholds the LETTER GRADE when coverage is
    too low, because the grade is the artefact that travels without its caveat.
    """
    from engine import aws_riskscore
    return aws_riskscore.qualify(
        compute_risk_score(results),
        {r.check_id for r in results},
        not_evaluated or {},
        check_severity=CHECK_SEVERITY,
        severity_weights=SEVERITY_WEIGHTS,
        grade_fn=score_to_grade)


def score_to_grade(score: float) -> str:
    if score >= 90: return "A"
    if score >= 80: return "B"
    if score >= 70: return "C"
    if score >= 60: return "D"
    return "F"


# ─── Compliance rollup (per-framework control pass/fail) ─────────────────────
COMPLIANCE_FRAMEWORKS = ["CIS", "PCI-DSS", "HIPAA", "SOC2", "NIST"]


def compliance_scorecard(results: List[Result],
                         compliance_map: Optional[Dict] = None) -> Dict[str, Dict]:
    """Aggregate per-finding compliance tags into a per-framework control rollup.

    The control *universe* is every control declared in ``COMPLIANCE_MAP`` (so
    coverage is stable regardless of which checks fired). A control is marked
    FAILED if any FAIL or WARN result references it, otherwise PASSED. Returns
    ``{framework: {controls_total, controls_passed, controls_failed, pass_rate,
    failed_controls}}``.
    """
    cmap = compliance_map if compliance_map is not None else COMPLIANCE_MAP
    universe = {f: set() for f in COMPLIANCE_FRAMEWORKS}
    for comp in cmap.values():
        for f, ctrl in (comp or {}).items():
            if f in universe and ctrl:
                universe[f].add(ctrl)

    failed = {f: set() for f in COMPLIANCE_FRAMEWORKS}
    for r in results:
        if r.status in ("FAIL", "WARN"):
            for f, ctrl in (r.compliance or {}).items():
                if f in failed and ctrl:
                    failed[f].add(ctrl)

    out: Dict[str, Dict] = {}
    for f in COMPLIANCE_FRAMEWORKS:
        controls = universe[f] | failed[f]        # a stray tag still counts
        fail = failed[f] & controls
        total = len(controls)
        passed = total - len(fail)
        out[f] = {
            "controls_total":   total,
            "controls_passed":  passed,
            "controls_failed":  len(fail),
            "pass_rate":        round(100 * passed / total, 1) if total else 100.0,
            "failed_controls":  sorted(fail),
        }
    return out


# ─── Crosswalk-derived compliance (NIST 800-53 spine → 30+ frameworks) ──────────
# Every check carries a NIST 800-53 control, so the NIST axis is TOTAL: we derive
# per-framework coverage for 30+ non-native frameworks purely from the NIST rollup
# via an authoritative crosswalk (see compliance_crosswalk.py). Emitted under a
# SEPARATE key from compliance_scorecard so the 5 native frameworks stay byte-
# identical and every frozen/lockstep test is unaffected.
_CONF_RANK = {"low": 0, "medium": 1, "high": 2}


def _nist_universe_from_map(cmap: Dict) -> frozenset:
    """The distinct NIST controls the product actually tags — derived from
    COMPLIANCE_MAP so the crosswalk can never reference a control we don't use."""
    return frozenset(v["NIST"] for v in cmap.values() if v.get("NIST"))


def _min_conf_present(mix: Dict[str, int]) -> str:
    for c in ("low", "medium", "high"):
        if mix.get(c, 0) > 0:
            return c
    return "high"


def crosswalk_scorecard(native_card: Dict, crosswalk: Optional[Dict] = None,
                        frameworks: Optional[Dict] = None,
                        nist_universe: Optional[frozenset] = None,
                        min_confidence: Optional[str] = None) -> Dict[str, Dict]:
    """Derive per-framework rollups for the NON-native frameworks purely from the
    NIST axis of an already-computed native scorecard. Returns ``{}`` when
    ``crosswalk`` is falsy (feature off / fail-open) so every existing caller is
    unchanged. A derived control FAILS iff ANY contributing NIST control failed
    (conservative, auditor-safe — same direction as native); its confidence is the
    MAX over contributing edges (best available provenance). ``min_confidence``
    (high|medium|low) drops edges below that tier BEFORE folding, so the universe,
    failures, and pass_rate are all computed precisely at the requested tier."""
    if not crosswalk:
        return {}

    def _maxc(a, b):
        return a if _CONF_RANK.get(a, 0) >= _CONF_RANK.get(b, 0) else b

    floor = _CONF_RANK.get(min_confidence, 0)
    nist_all = frozenset(nist_universe or _nist_universe_from_map(COMPLIANCE_MAP))
    failed_nist = set(native_card.get("NIST", {}).get("failed_controls", []))
    out: Dict[str, Dict] = {}
    for fid, meta in (frameworks or {}).items():
        if meta.get("native"):                 # never derive a native framework
            continue
        universe: set = set()
        failed: set = set()
        prov: Dict[str, dict] = {}
        for n in sorted(nist_all):             # deterministic — the note/first-edge for a
            edge = crosswalk.get(n, {}).get(fid)   # multi-edge control must not depend on set order
            if not edge:
                continue
            if _CONF_RANK.get(edge["confidence"], 0) < floor:
                continue                       # below the requested confidence tier
            for t in edge["targets"]:
                universe.add(t)
                p = prov.setdefault(t, {"control": t, "via_nist": [], "confidence": "low",
                                        "note": edge.get("note", ""),
                                        "sources": edge.get("sources") or meta.get("sources", [])})
                p["via_nist"].append(n)
                p["confidence"] = _maxc(p["confidence"], edge["confidence"])
                if n in failed_nist:
                    failed.add(t)
        if not universe:                        # framework maps nothing → omit it
            continue
        failed_in = failed & universe
        total = len(universe)
        mix = {"high": 0, "medium": 0, "low": 0}
        for t in universe:
            mix[prov[t]["confidence"]] += 1
        passed = total - len(failed_in)
        out[fid] = {
            "controls_total": total,
            "controls_passed": passed,
            "controls_failed": len(failed_in),
            "pass_rate": round(100 * passed / total, 1) if total else 100.0,
            "failed_controls": sorted(failed_in),
            # additive, derived-only metadata (native dicts NEVER get these keys):
            "derived": True, "via": "NIST-800-53",
            "confidence_mix": mix, "min_confidence": _min_conf_present(mix),
            # provenance only for FAILED controls (payload discipline):
            "control_provenance": {t: {**prov[t], "via_nist": sorted(prov[t]["via_nist"])}
                                   for t in sorted(failed_in)},
        }
    return out


def compliance_payload(results: List[Result], *, crosswalk: Optional[Dict] = None,
                       frameworks: Optional[Dict] = None,
                       version: Optional[str] = None) -> Dict:
    """The 3 compliance keys emitted into every serialized scan — the SINGLE source
    of truth so ``save_json`` and ``cnapp_service.serialize_scanner`` stay byte-
    identical (the lockstep invariant). ``compliance_scorecard`` (the native 5) is
    unchanged; ``compliance_crosswalk`` derives 30+ frameworks from the NIST spine;
    ``compliance_crosswalk_meta`` self-describes the export for reproducibility.
    Fail-open: an absent/corrupt crosswalk yields an empty derived block."""
    card = compliance_scorecard(results)
    if crosswalk is None:
        from engine import compliance_crosswalk as _cc
        crosswalk, frameworks, version = _cc.get_crosswalk()
    derived = crosswalk_scorecard(card, crosswalk, frameworks)
    return {
        "compliance_scorecard": card,
        "compliance_crosswalk": derived,
        "compliance_crosswalk_meta": {
            "crosswalk_version": version or "",
            "generated_from": "NIST-800-53-Rev5",
            "frameworks": len(derived),
        },
    }


# ─── Workflow-integration helpers (SARIF / ASFF / gating / diff) ─────────────
# Ordinal ranking so we can compare severities for --fail-on thresholds.
SEVERITY_ORDER = {"CRITICAL": 5, "HIGH": 4, "MEDIUM": 3, "LOW": 2, "INFO": 1, "": 0}

# Map internal severity → SARIF result level.
SARIF_LEVEL = {"CRITICAL": "error", "HIGH": "error", "MEDIUM": "warning",
               "LOW": "note", "INFO": "none", "": "warning"}

# Map internal severity → AWS Security Finding Format (ASFF) severity label.
ASFF_SEVERITY = {"CRITICAL": "CRITICAL", "HIGH": "HIGH", "MEDIUM": "MEDIUM",
                 "LOW": "LOW", "INFO": "INFORMATIONAL", "": "INFORMATIONAL"}

# Map status → ASFF Compliance.Status.
ASFF_COMPLIANCE_STATUS = {"FAIL": "FAILED", "WARN": "WARNING",
                          "PASS": "PASSED", "INFO": "NOT_AVAILABLE"}


def finding_key(check_id: str, resource: str) -> str:
    """Stable identity for a finding, used for diffing and fingerprints."""
    return f"{check_id}|{resource}"


def fails_threshold(results: List[Result], threshold: str) -> bool:
    """True if any FAIL result is at or above `threshold` severity."""
    floor = SEVERITY_ORDER.get(threshold.upper(), 0)
    return any(r.status == "FAIL"
               and SEVERITY_ORDER.get(r.severity, 0) >= floor
               for r in results)


def diff_findings(current: List[Result], baseline_results: List[Dict]) -> Dict:
    """Compare current findings against a previously-saved JSON report's results.
    Only FAIL/WARN entries are treated as findings. Returns new + resolved lists
    keyed by (check_id, resource)."""
    def _key_set(items, getter):
        return {finding_key(getter(i, "check_id"), getter(i, "resource")): i
                for i in items
                if getter(i, "status") in ("FAIL", "WARN")}

    cur = _key_set(current, lambda r, a: getattr(r, a))
    base = _key_set(baseline_results, lambda d, a: d.get(a, ""))

    new_keys = cur.keys() - base.keys()
    resolved_keys = base.keys() - cur.keys()
    return {
        "new": [cur[k] for k in sorted(new_keys)],
        "resolved": [base[k] for k in sorted(resolved_keys)],
    }


# ─── IAM credential-report age helpers (used by IAM-06/07/08) ────────────────
def _cred_age_days(iso_ts: str) -> Optional[int]:
    """Days since an IAM credential-report timestamp, or None when the field is
    empty / 'N/A' / 'no_information' / 'not_supported' or unparseable."""
    if not iso_ts or iso_ts in ("N/A", "no_information", "not_supported"):
        return None
    try:
        return (datetime.now(timezone.utc) - datetime.fromisoformat(iso_ts)).days
    except Exception:
        return None


def _cred_idle_days(last_used: str, created: str) -> Optional[int]:
    """How long a credential has been idle: days since last use, or (if never used)
    days since it was created/rotated. None if neither timestamp is usable, so the
    caller skips the credential rather than false-flagging it."""
    d = _cred_age_days(last_used)
    return d if d is not None else _cred_age_days(created)


# ─── Scanner ──────────────────────────────────────────────────────────────────
def _op_action(op: str) -> str:
    """boto3 operation name -> the IAM action it authorizes against.

    ``list_agent_runtimes`` -> ``ListAgentRuntimes``. Needed so a refused read can name
    the exact action the operator withheld, which is the whole contract of the coverage
    manifest."""
    return "".join(p.title() for p in (op or "").split("_"))


def _looks_like_account_scoped(bucket: str) -> bool:
    """Whether a bucket name carries a 12-digit account id.

    The only ownership signal available without a second API call, and used ONLY to
    suppress MART-03 on obviously-own buckets rather than to assert foreignness. A name
    is weak evidence, so the check it feeds is a WARN.
    """
    parts = (bucket or "").replace(".", "-").split("-")
    return any(len(p) == 12 and p.isdigit() for p in parts)


def _op_to_api(op: str) -> str:
    """boto3 snake_case operation -> the IAM action name.

    `list_feature_groups` -> `ListFeatureGroups`. Used so a denial names the permission
    an operator must grant rather than the Python method they cannot see."""
    return "".join(part.title() for part in (op or "").split("_"))


def _checks_gated_by(action: str) -> tuple:
    """Every check id the permission ledger says depends on `action`.

    Exists so a runtime AccessDenied can record the FULL set of checks it just cost us.
    The alternative — naming them at the call site — drifts the moment another check
    starts needing the same read, and drifts silently, leaving the newly-added check
    looking evaluated when it was refused."""
    want = (action or "").lower()
    return tuple(sorted(
        cid for cid, reqs in aws_perm_ledger.REQUIREMENTS.items()
        if any((r.action or "").lower() == want for r in reqs)))


#: slice 5.2 — one check per AWS data-perimeter objective.
_PERIM_CHECK = {
    aws_perimeter.OBJ_IDENTITY: "PERIM-01",
    aws_perimeter.OBJ_RESOURCE: "PERIM-02",
    aws_perimeter.OBJ_NETWORK: "PERIM-03",
}


class AWSLiveScanner:
    """Live, read-only AWS security audit scanner."""

    # Sections that enumerate global (region-agnostic) resources — run once even
    # when --all-regions sweeps every enabled region for the rest.
    # AI_THREAT is global because its quota-dodging rule needs to see EVERY region
    # at once — one key invoking across three regions in an hour is the signal, and
    # a per-region pass can never observe it. It sweeps regions internally instead.
    # SHADOW_AI is global for AI_THREAT's reason: `_check_undeclared_ai_creators`
    # sweeps `_ai_scan_regions()` itself, so a per-region pass would repeat the
    # whole CloudTrail sweep once per region. AI_LOGGING and VECTORSTORE hold no
    # internal sweep and are regional, so --all-regions visits them properly.
    GLOBAL_SECTIONS = {"IAM", "S3", "ROUTE53", "CLOUDFRONT", "IAMPRIVESC", "CORRELATE",
                       "CLOUDWATCH", "AI_THREAT", "SHADOW_AI",
                       # IAM is global, so NHI reads the same principals in every
                       # region. Regional would emit each finding once per region.
                       "NHI",
                       # ORGANIZATIONS is global for NHI's reason and more strongly:
                       # every client it builds is pinned to us-east-1, because
                       # Organizations and the account contact APIs have no regional
                       # endpoints. Left regional, --all-regions would re-run the same
                       # us-east-1 reads once per enabled region and emit every ORG-*
                       # and ACCT-* finding N times over — including the "not evaluated"
                       # coverage statements, which is the worst version of it: a member
                       # account would report the same denial thirty times.
                       "ORGANIZATIONS"}

    def __init__(
        self,
        region:   str = "eu-west-1",
        verbose:  bool = False,
        sections: Optional[List[str]] = None,
        session:  object = None,
        all_regions: bool = False,
    ):
        self.region   = region
        self.verbose  = verbose
        _req = [s.upper() for s in sections] if sections else list(SECTIONS)
        # Run in canonical SECTIONS order regardless of --sections ordering: graph-building
        # sections have dependencies (IAMPRIVESC must precede EXPOSURE/COGNITO_IDENTITY,
        # which augment its graph; CORRELATE runs last). Unknown sections keep their order.
        _idx = {s: i for i, s in enumerate(SECTIONS)}
        self.sections = sorted(_req, key=lambda s: _idx.get(s, len(SECTIONS)))
        self.results:  List[Result] = []
        self.account   = ""
        self.trusted_accounts: set = set()  # allowlist: cross-account grants to these are not flagged
        # AMI-04 (CIS-Compute 2.1.1). A naming convention is an organisational fact that
        # nothing in an AMI reveals, so the check reports NOT EVALUATED until this is set
        # rather than guessing a pattern and failing correct estates.
        self.ami_name_pattern: Optional[str] = os.environ.get(
            "OVERWATCH_AMI_NAME_PATTERN") or None
        self._session  = session          # boto3.Session for assumed-role scans; None = ambient creds
        self.all_regions_scan = all_regions
        self.graph: Optional[SecurityGraph] = None
        self.attack_paths: List = []       # ranked AttackPath objects (Phase 4 correlate)
        self.choke_points: List = []       # ranked ChokePoint objects
        self._clients: Dict[str, object] = {}
        # DB (cluster) parameter groups, cached per scan by (service, kind, name). A
        # group is shared by every instance using it, and reading one is several pages
        # of a few hundred parameters -- fetching it per instance would multiply that by
        # the size of the fleet for no new information. A failed read caches None so it
        # is attempted once rather than once per resource.
        self._param_cache: Dict[tuple, Optional[List[Dict]]] = {}
        self._cred_report:  Optional[List[Dict]] = None
        self._cred_report_ok: bool = False
        self._all_regions:  Optional[List[str]]  = None
        self._iam_principals: Optional[List[Dict]] = None
        # Live access key ids, lazily collected by `_access_key_ids`. None means NOT
        # COLLECTED (denied, or never asked for) as opposed to an empty list, which
        # means this account genuinely has none — see that method.
        self._access_keys: Optional[List[str]] = None
        self._managed_policy_cache: Dict[str, tuple] = {}
        # ── Phase 5: effective-permissions ceiling refinement ────────────────
        self._scp_context: Optional[List] = None    # ordered SCP levels root->acct
        self._scp_fetched = False                   # None is a valid result -> sentinel
        self._boundary_evaluated = False            # a boundary doc was resolved
        self._scp_evaluated = False                 # SCP layer was evaluated
        self._pruned_edges: List[Dict] = []         # edges dropped by the ceiling
        self._downgraded_edges: List[Dict] = []     # edges downgraded to conditioned
        self._state_report: Optional[Dict] = None   # lifecycle/drift/trend/mttr (if --state)
        self._unused_report: Optional[List] = None  # CIEM right-sizing signals
        self._least_priv_report: Optional[List] = None  # CIEM-02 generated least-priv policies
        # ── Phase 6: agentless side-scan + persistence/export metadata ───────
        self.side_scan = False                      # --side-scan opt-in
        self.side_scan_targets = "exposed"          # exposed | all | tagged
        self.side_scan_tags: List[str] = []
        self.side_scan_max = 20                     # hard target ceiling
        self.side_scan_secrets = True
        # ── Phase 4 Slice-5: agentless ECR registry coverage ─────────────────
        # Tier A (always-on, no new grant): CNT-02 native-scan findings across the
        # newest-N *tagged* images per repo (was: newest image only). Bounded per
        # repo; tunable via the per-account knob. Untagged images are skipped.
        self.ecr_scan_max_images = 20               # Tier-A newest-N tagged per repo
        self.ecr_scan_max_total = 400               # Tier-A aggregate per-scan image budget
        self._ecr_scan_mode: Optional[str] = None   # ENHANCED|BASIC|DISABLED (registry-wide)
        # Tier B (OPT-IN, two-key: this flag + the CnappImageLayerPull IAM grant):
        # pull image layers → own SBOM → OSV match, Inspector-independent. Inert
        # until --side-scan-images is set; the layer bytes are fetched via the
        # injected _layer_get seam (raw HTTPS GET of the presigned S3 URL).
        self.side_scan_images = False               # --side-scan-images opt-in
        self.side_scan_images_max = 1               # hard per-repo pull ceiling (expensive)
        self.ecr_image_max_bytes = 2 * 1024 ** 3    # per-image compressed size cap (2 GiB)
        self._layer_get = None                      # test/prod seam: (url)->bytes|None
        # LMB-07 artifact side-scan. OFF by default for the same reason as
        # --side-scan-images: it downloads deployment packages, so it is an
        # egress decision the operator makes, not one a default scan makes.
        self.side_scan_lambda = False               # --side-scan-lambda opt-in
        self.side_scan_lambda_max = 20              # hard per-region function ceiling
        self.registry_sboms: List[Dict] = []        # pulled-image SBOMs -> hosted snapshot persist
        # ── Phase 3 Layer B: VPC Flow-Log observed-traffic overlay (--flow-logs) ──
        # Off by default: reading flow-log CONTENT needs an OPTIONAL, resource-scoped
        # logs:StartQuery grant NOT in the default role, and Insights bills per GB
        # scanned. When on, it FAILS OPEN to FLOW-00 (never a phantom PASS). The read
        # is behind an injected seam (self._flow_read), like the K8s seam above.
        self.flow_logs = False                      # --flow-logs opt-in
        self.flow_logs_window_hours = aws_flowlog.WINDOW_HOURS
        self._flow_read = None                      # test/prod seam: (logs, groups, q, s, e) -> rows|None
        self.vuln_db_path: Optional[str] = None
        self.vuln_db_pubkey: Optional[str] = None   # opt-in: hex key or .pub path — verify the signed feed
        self._side_scan_report: Optional[Dict] = None
        self._backend_meta: Optional[Dict] = None
        self._graph_export_meta: Optional[Dict] = None
        self._sidescan_extractor_opener = None      # test seam: (vol_ids, iid) -> CM
        self._remediation_report: Optional[Dict] = None   # Phase 7 --remediate
        self._code_to_cloud_meta: Optional[Dict] = None
        # ── Phase 5b: managed-service engine-EOL axis ────────────────────────
        self._today: Optional[date] = None   # test clock seam; None -> utcnow().date()
        # Stashed (node_id, node_kind, matches, node_props) HAS_VULN payloads from EOL
        # checks. Emitted LATE (in _check_vuln, after IAMPRIVESC hard-replaces the graph)
        # so the identity-graph rebuild can't clobber them.
        self._eol_graph_payloads: List[tuple] = []
        # Phase-7 fusion: workloads found internet-reachable in EXPOSURE#37 (feeds the
        # HAS_VULN reachable_service tag in VULN#39); RUNS_IMAGE edges stashed pre-clobber
        # in ECS#20 for replay in VULN#39 (image-CVE inheritance survives the graph rebuild).
        self._reachable_workloads: set = set()
        self._runs_image_payloads: List[tuple] = []
        # Phase-3 Fargate: running ECS-Fargate tasks stashed in ECS#20 (pre-clobber),
        # replayed in VULN#40 (node + RUNS_IMAGE + HAS_ROLE) and folded into internet
        # exposure in EXPOSURE#37 — the running task, not the task-def, is the exposure +
        # identity anchor a serverless-container attack path needs.
        self._fargate_payloads: List[dict] = []
        # EXPOSURE#37 (re)builds these region-locally from the stash + region ENIs so an
        # ALB ip-target / public-IP ENI resolves to the owning Fargate task node.
        self._ip_to_fargate: Dict[tuple, str] = {}   # (vpc_id, private_ip) -> taskArn
        self._exposed_fargate: set = set()           # internet-reachable Fargate task nodes
        # Phase-3 KSPM/KIEM: K8s graph edges (principal->KubeAdminCap, SA->IRSA role, pod->SA,
        # SA->KubeAdminCap) stashed in EKS#18 (pre-clobber), replayed in VULN#40 so the
        # cross-plane path survives IAMPRIVESC's graph rebuild. Injected read-only K8s API seam.
        self._kube_payloads: List[dict] = []
        self._k8s_get = None                          # test/prod seam: (cluster_ctx, path) -> dict|None
        self._ip_to_kube_pod: Dict[tuple, str] = {}   # (vpc_id, pod_ip) -> KubePod node
        self._exposed_kube: set = set()               # internet-reachable KubePod nodes
        # CloudFront is GLOBAL but EXPOSURE runs per-region; guard so --all-regions does
        # not re-emit the same distributions once per region (the graph merges anyway).
        self._l7_cf_done = False
        self._identity_fusion_done = False          # IDENTITY-01 is global (IAM); run once
        self._l7_read_error = False                 # any L7 describe denied -> suppress phantom PASS
        self._l7_lb_dns: Dict[str, str] = {}        # DNS->LB node id, ACCUMULATED across regions
        # AI-SPM: AI resources (SageMaker notebooks/domains, Bedrock agents) stashed pre-clobber
        # in BEDROCK_AGENTS#16 / SAGEMAKER#33 (name, execution role ARN, normalized network flags,
        # data_bearing) and fused onto the graph in DATA#42 (_collect_aispm) — post-clobber, where
        # principals + CAN_READ_DATA edges are complete. No AWS re-fetch, no aws_correlate change.
        self._aispm_resources: List[dict] = []
        # Consume-once latch for _collect_aispm. DATA is NOT in GLOBAL_SECTIONS, so
        # with --all-regions it runs once PER REGION; the stash is filled earlier by
        # BEDROCK_AGENTS (idx 17) and SAGEMAKER (idx 33), which sweep every region
        # before DATA (idx 42) starts. Without this latch each DATA region re-emits
        # the COMPLETE accumulated set, and compute_risk_score charges every
        # duplicate FAIL again (CRITICAL=15) — one AIPATH-01 across 17 regions
        # subtracts 255 and floors the WHOLE account's posture score at 0.
        # Note this is NOT the _replay_*_edges pattern: those are merge-idempotent
        # because add_edge merges; findings append to a list and do not.
        self._aispm_collected = False
        # One coverage note per scan, not one per AI section — three identical
        # notes would be noise, and noise is how a true note gets skipped.
        self._aispm_region_noted = False
        # Negative assurance for THIS run: what was refused, what was skipped. Built
        # as the scan goes rather than reconstructed afterwards, because the only
        # moment we know a check was denied is when it is denied.
        self._coverage = aws_perm_ledger.CoverageManifest()
        # D3 — cryptographic material for the CBOM, collected from reads the
        # scanner already performs. Populated only as those sections run, so a
        # --sections subset produces a CBOM scoped to what was actually looked at.
        self._crypto_material = {"kms": [], "acm": [], "tls": []}
        # D3 sibling: GuardDuty AI Protection findings, collected in THREAT (where
        # the detector is) and assessed in AI_THREAT (after DATA, where the crown
        # edges exist). All three types ship at severity Low, so THREAT's own
        # severity>=4 query never sees them.
        self._ai_protection = []
        # Slice 3.1 — guardrail grades by id, stashed in BEDROCK (which runs
        # before BEDROCK_AGENTS) so an agent can be asked whether the guardrail it
        # names actually blocks anything.
        self._guardrail_grades = {}
        # Slice 3.2 — an operator-supplied tool-description pattern set. Empty
        # unless --tool-patterns names one, and deliberately so: OverWatch does not
        # author injection phrasings.
        self._tool_patterns = aws_toolpoison.load_patterns(None)
        # Slice 3.5 — adversarial test verdicts the operator supplies. Empty unless
        # --pentest-results names a file; OverWatch never produces these itself.
        self._pentest_results = {}
        # Slice 4.7 -- the operator's own AI runtime detections, vendor
        # neutral. OverWatch produces none of these itself.
        self._ai_detections = {}
        # An operator-supplied breach corpus, normalised by aws_ingest_credexp before
        # it reaches here. Empty = the flag was not given, and CREDEXP emits nothing.
        self._cred_exposures = {}
        # Slice 3.3: one entry per gateway, compared against the state DB AFTER the
        # scan. The scan path stays stateless -- a DB is a --state opt-in, and a check
        # that needs one to run at all would make the config half hostage to it.
        self._mcp_surfaces = []
        # SageMaker.6/.7's requiredKeyTags parameter. AWS ships no default, and with
        # none set the control checks only that SOME non-system tag key exists -- so
        # an empty tuple here IS the documented default, not an unset option.
        self._sm_required_tags = ()
        # Slice 4.4: the operator's declared AI owner set. Empty means the
        # question has not been answered, which SHAI-00 reports -- it does NOT
        # mean every creator is undeclared.
        self._ai_owners = ()
        # Slice 4.6: the artifact opcode scan is the ONE check that reads
        # object bytes, so it is off unless --scan-model-artifacts asks.
        self._scan_model_artifacts = False
        # knowledgeBaseId -> injection surface, from the data sources AGT-03 reads.
        self._kb_surface = {}
        self._perm_ledger = None            # set by _preflight_permissions()
        # Action-group Lambda names, collected while auditing agents. Without
        # them the UpdateFunctionCode rule stays silent rather than firing on
        # every Lambda deploy in the account.
        self._agent_lambda_names = set()

    def _boto_config(self):
        """The retry and identification policy every client is built with.

        WHY THIS IS NOT THE DEFAULT'S PROBLEM TO SOLVE. botocore's default retry mode is
        `legacy`: a small fixed number of attempts with no client-side rate limiting. That
        is sized for an application making a handful of calls, and a scan is the opposite
        shape — 94 sections, each enumerating a service, multiplied by every region when
        --all-regions is set. The account most likely to throttle is the large one, which
        is also the one whose posture matters most.

        WHAT THROTTLING USED TO PRODUCE. Until the change that added this, a throttled
        read did not merely go missing: 22 call sites reported the exception's own text
        as a FAIL finding, five of them CRITICAL, each carrying that check's remediation.
        So the estate most likely to throttle was the one most likely to be handed
        fabricated findings. `_read_failed` fixed the reporting; this reduces how often
        the situation arises at all.

        ADAPTIVE, NOT JUST MORE ATTEMPTS. `adaptive` adds a client-side rate limiter that
        slows down BEFORE being throttled, which is what stops a wide scan from spending
        its retry budget fighting itself. `max_attempts` is raised to 10 for the same
        reason a scan differs from an application: there is no user waiting on any single
        call, and a section that gives up early reports silence that looks like a clean
        result.

        THE USER AGENT IS NOT DECORATION. It puts `OverWatch/<version>` in CloudTrail's
        `userAgent` for every call this tool makes, so an operator reviewing their own
        trail can tell our reads from anything else using the same role — which is the
        first question asked when an unfamiliar burst of Describe calls shows up."""
        return BotoConfig(  # type: ignore[name-defined]
            retries={"max_attempts": 10, "mode": "adaptive"},
            user_agent_extra=f"OverWatch/{VERSION}",
        )

    # ── boto3 client factory (lazy, cached) ───────────────────────────────────
    def _client(self, service: str, region: Optional[str] = None):
        if not HAS_BOTO3:
            raise ImportError(
                "boto3 is not installed. Run: pip install boto3"
            )
        key = f"{service}:{region or self.region}"
        if key not in self._clients:
            factory = self._session or boto3  # assumed-role session or ambient creds
            self._clients[key] = factory.client(  # type: ignore[name-defined]
                service, region_name=region or self.region,
                config=self._boto_config(),
            )
        return self._clients[key]

    @property
    def k8s_get(self):
        """The read-only Kubernetes-API seam ``(cluster_ctx, path) -> dict | None``. Lazily bound
        to ``aws_kube.default_k8s_get`` (the only socket-touching fn: mints an EKS bearer token,
        TLS-pins to the cluster CA, GETs). Tests assign ``s._k8s_get = fake``. GET-only."""
        if self._k8s_get is None:
            self._k8s_get = aws_kube.default_k8s_get
        return self._k8s_get

    @property
    def flow_read(self):
        """The read-only VPC-Flow-Log seam ``(logs_client, log_groups, query, start_s,
        end_s) -> rows | None``. Lazily bound to ``aws_flowlog.default_flow_read`` (the
        only socket-touching fn: runs a CloudWatch Logs Insights start_query→poll loop).
        Tests assign ``s._flow_read = fake``. Returns None on ANY failure ⇒ fail open."""
        if self._flow_read is None:
            self._flow_read = aws_flowlog.default_flow_read
        return self._flow_read

    def _cluster_ctx(self, c: Dict, cname: str) -> Dict:
        creds = None
        try:
            creds = self._session.get_credentials() if self._session else None
        except Exception:
            creds = None
        return {"cluster": cname, "region": self.region, "endpoint": c.get("endpoint", ""),
                "ca_data": (c.get("certificateAuthority") or {}).get("data", ""),
                "credentials": creds}

    # ── Result helpers ────────────────────────────────────────────────────────
    def _add(self, status: str, check_id: str, section: str,
             resource: str, message: str):
        severity = ""
        compliance = {}
        remediation = ""
        if status == "FAIL":
            severity = CHECK_SEVERITY.get(check_id, "MEDIUM")
            compliance = COMPLIANCE_MAP.get(check_id, {})
            remediation = REMEDIATION_MAP.get(check_id, "")
        elif status == "WARN":
            severity = "LOW"
            compliance = COMPLIANCE_MAP.get(check_id, {})
        self.results.append(Result(
            status, check_id, section, resource, message,
            severity, compliance, remediation,
        ))

    def _remediation_for(self, r) -> str:
        """The remediation a finding carries, resolved ONE way for every export.

        `_add` fills `Result.remediation` from REMEDIATION_MAP only when the status is
        FAIL, so a WARN finding reaches the exports with an empty string. The four
        output paths then disagreed about the same finding: `_build_finding_catalog`
        looked the text up by check id and showed it (HTML cards), `save_json` and
        `save_sarif` emitted nothing, and `save_asff` substituted the literal "Review
        and apply least privilege" — so the export that feeds a customer's own
        Security Hub carried invented generic advice while the HTML report beside it
        carried the real, specific fix.

        RESOLVED BY CHECK ID, LIKE THE CATALOGUE, because the catalogue is the one that
        was right: the remediation is a property of the CHECK, not of how severely a
        particular observation happened to land. 82 checks in this catalogue only ever
        emit WARN, so under the old rule their written remediation could never be
        shown by three of the four exports.

        STATUS STILL GATES IT. PASS and INFO get nothing: there is no fix to offer for
        a control that is in place, and the two exports that carry every status would
        otherwise attach remediation to good news.
        """
        if r.status not in ("FAIL", "WARN"):
            return ""
        return REMEDIATION_MAP.get(r.check_id, "")
        if self.verbose or status in ("FAIL", "WARN"):
            col = STATUS_COLOR.get(status, RESET)
            res = f" | {resource}" if resource else ""
            sev_tag = f" [{severity}]" if severity else ""
            print(f"  {col}{STATUS_ICON[status]}{RESET} {check_id}{sev_tag}: {message}{res}")

    def _log(self, msg: str):
        print(f"{BLUE}[*]{RESET} {msg}")

    def _section_header(self, section: str):
        label = SECTION_LABELS.get(section, section)
        print(f"\n{BOLD}{BLUE}══ {label} ══{RESET}")

    # ── IAM credential report (cached) ───────────────────────────────────────
    def _get_credential_report(self) -> List[Dict]:
        if self._cred_report is not None:
            # a pre-populated non-empty report counts as successfully obtained
            if self._cred_report:
                self._cred_report_ok = True
            return self._cred_report
        # None (not []) records "could not evaluate" so credential checks can tell an
        # empty account apart from an unavailable report and avoid a false all-clear.
        self._cred_report_ok = False
        try:
            iam = self._client("iam")
            # generate_credential_report is async; poll its State rather than a fixed
            # sleep (a fresh account is not COMPLETE immediately). Bounded to ~18s so a
            # never-COMPLETE state can't stall the scan (old fixed sleep was 6s).
            for attempt in range(CRED_REPORT_ATTEMPTS):
                state = iam.generate_credential_report().get("State", "")
                if state == "COMPLETE":
                    break
                # A State that is not a string can never become "COMPLETE", so there is
                # nothing to wait for. In production State is always a string (an absent
                # one defaults to "" and legitimately keeps polling); this only
                # short-circuits a non-string, which is how a mocked client burned the
                # whole retry budget in every test that reached this method.
                if not isinstance(state, str):
                    break
                if attempt < CRED_REPORT_ATTEMPTS - 1:
                    time.sleep(CRED_REPORT_POLL_SECONDS)
            resp    = iam.get_credential_report()
            content = base64.b64decode(resp["Content"]).decode("utf-8")
            self._cred_report = list(csv.DictReader(io.StringIO(content)))
            self._cred_report_ok = True
        except Exception as e:
            # one retry: get_credential_report can still be ReportInProgress
            try:
                time.sleep(CRED_REPORT_RETRY_SECONDS)
                resp    = iam.get_credential_report()
                content = base64.b64decode(resp["Content"]).decode("utf-8")
                self._cred_report = list(csv.DictReader(io.StringIO(content)))
                self._cred_report_ok = True
            except Exception:
                self._log(f"Could not generate credential report: {e}")
                self._cred_report = []
        return self._cred_report

    # ── All enabled regions (cached) ─────────────────────────────────────────
    def _get_all_regions(self) -> List[str]:
        if self._all_regions is not None:
            return self._all_regions
        try:
            ec2 = self._client("ec2")
            self._all_regions = [
                r["RegionName"]
                for r in ec2.describe_regions()["Regions"]
            ]
        except Exception:
            self._all_regions = [self.region]
        return self._all_regions

    # ══════════════════════════════════════════════════════════════════════════
    # SECTION 0: AWS ORGANIZATIONS — CIS AWS Foundations v7.0.0 §2.1, 2.2, 2.3
    # ══════════════════════════════════════════════════════════════════════════
    def _org_not_evaluated(self, check_id: str, resource: str, reason: str,
                           action: str = "") -> None:
        """A read that did not happen, reported as a coverage statement.

        NOT A PASS, and the distinction is the entire reason this helper exists. Six of
        the eight checks in this section are refused in an ordinary member account, and a
        section that answered a refusal with silence would present an organisation nobody
        could inspect as an organisation with nothing wrong with it. Every refusal names
        the action, and `note_denied` shrinks the evidence pack's denominator rather than
        letting its numerator grow."""
        if action:
            self._coverage.note_denied(check_id, action)
        self._add("INFO", check_id, "ORGANIZATIONS", resource,
                  f"NOT EVALUATED — {reason}")

    def _org_ancestors(self, org, account_id: str,
                       cache: Dict[str, List[str]]) -> Optional[List[str]]:
        """``account_id`` plus every OU and root above it, nearest first.

        WHY THE WALK IS NECESSARY. ``ListPoliciesForTarget`` returns the policies attached
        DIRECTLY to a target, and service-control policies are inherited down the tree. An
        account with no policy of its own can therefore be perfectly well governed by one
        attached to its OU, and checking the account alone would report every properly
        structured organisation as ungoverned. The cache matters because accounts share
        ancestors: an organisation of 200 accounts in 8 OUs walks 8 chains, not 200."""
        chain: List[str] = [account_id]
        node = account_id
        for _ in range(8):                      # AWS caps OU nesting at five levels
            if node in cache:
                chain.extend(cache[node])
                break
            try:
                parents = org.list_parents(ChildId=node).get("Parents") or []
            except Exception:
                return None
            if not parents:
                break
            pid = parents[0].get("Id")
            if not pid:
                break
            chain.append(pid)
            node = pid
            if str(pid).startswith("r-"):
                break
        cache[account_id] = chain[1:]
        return chain

    def _check_organizations(self):
        """ORG-01..06 and ACCT-01/02 — CIS Foundations v7.0.0 2.1.1–2.1.6, 2.2 and 2.3.

        v7.0.0's new §2.1 asks six questions about the ORGANISATION rather than about the
        account, and every one of them is readable only from the management account. That
        makes this the one section whose normal outcome in a member account is "not
        evaluated", so it runs first and says so plainly — see `_org_not_evaluated`.

        The two contact checks are here rather than in IAM because they share that
        property of being account-global and read through the `account` API, and because
        the benchmark files them alongside the organisation controls."""
        self._section_header("ORGANIZATIONS")

        org = None
        org_meta: Dict = {}
        org_available = False
        try:
            org = self._client("organizations", region="us-east-1")
            org_meta = org.describe_organization().get("Organization") or {}
            org_available = bool(org_meta)
        except Exception as e:
            denied = self._is_access_denied(e)
            reason = ("organizations:DescribeOrganization is denied here, which is normal "
                      "outside the management account"
                      if denied else
                      "this account is not a member of an AWS Organization")
            for cid in ("ORG-01", "ORG-02", "ORG-03", "ORG-04", "ORG-05", "ORG-06"):
                self._org_not_evaluated(
                    cid, "organizations", reason,
                    action="organizations:DescribeOrganization" if denied else "")

        if org_available:
            self._org_root_access()
            self._org_guardrails(org)
            self._org_management_workloads(org_meta)
            self._org_structure(org)
            self._org_delegation(org)
        self._account_contacts()

    def _org_root_access(self) -> None:
        """ORG-01 / 2.1.1 — centralized root access. Read through IAM, not Organizations."""
        self._log("ORG-01: centralized root access")
        try:
            iam = self._client("iam", region="us-east-1")
            feats = iam.list_organizations_features().get("EnabledFeatures")
        except Exception as e:
            if self._is_access_denied(e):
                self._org_not_evaluated(
                    "ORG-01", "root-credentials",
                    "iam:ListOrganizationsFeatures is denied here, which is normal "
                    "outside the management account",
                    action="iam:ListOrganizationsFeatures")
            else:
                self._org_not_evaluated(
                    "ORG-01", "root-credentials",
                    "iam:ListOrganizationsFeatures is unavailable in this partition or "
                    "SDK version, so central root management could not be read")
            return
        r = aws_cis_foundations.central_root_access(feats)
        if r.get("failed"):
            self._add("FAIL", "ORG-01", "ORGANIZATIONS", "root-credentials",
                      r["statement"])
        elif r.get("unknown"):
            self._org_not_evaluated("ORG-01", "root-credentials", r["reason"])
        else:
            self._add("PASS", "ORG-01", "ORGANIZATIONS", "root-credentials",
                      "Root credentials are centrally managed and privileged root "
                      "sessions are available")

    def _org_guardrails(self, org) -> None:
        """ORG-02 / 2.1.2 — every account inherits something other than FullAWSAccess."""
        self._log("ORG-02: authorization guardrails")
        try:
            accounts = self._paginate_strict(org, "list_accounts", "Accounts")
        except Exception as e:
            self._org_not_evaluated(
                "ORG-02", "organizations",
                "organizations:ListAccounts is denied here, which is normal outside the "
                "management account" if self._is_access_denied(e)
                else f"the organisation's accounts could not be listed ({e})",
                action="organizations:ListAccounts" if self._is_access_denied(e) else "")
            return

        cache: Dict[str, List[str]] = {}
        reach: Dict[str, List[str]] = {}
        for acct in accounts:
            aid = str(acct.get("Id") or "")
            if not aid or str(acct.get("Status")) != "ACTIVE":
                continue
            chain = self._org_ancestors(org, aid, cache)
            if chain is None:
                self._org_not_evaluated(
                    "ORG-02", aid,
                    "organizations:ListParents is denied, so inherited policies could "
                    "not be resolved and an attached-only reading would be wrong",
                    action="organizations:ListParents")
                return
            pols: List[str] = []
            for node in chain:
                # RESOURCE_CONTROL_POLICY raises when the type is not enabled in the
                # organisation, which is not a failure and must not abort the SCP read.
                for filt in ("SERVICE_CONTROL_POLICY", "RESOURCE_CONTROL_POLICY"):
                    try:
                        for p in self._paginate_strict(
                                org, "list_policies_for_target", "Policies",
                                TargetId=node, Filter=filt):
                            pols.append(str(p.get("Id") or ""))
                    except Exception:
                        continue
            reach[aid] = pols

        if not reach:
            self._org_not_evaluated("ORG-02", "organizations",
                                    "no active accounts were returned for this "
                                    "organisation")
            return
        r = aws_cis_foundations.authorization_guardrails(reach)
        if r.get("failed"):
            for aid in r["accounts"]:
                self._add("FAIL", "ORG-02", "ORGANIZATIONS", aid, r["statement"])
        else:
            self._add("PASS", "ORG-02", "ORGANIZATIONS", "organizations",
                      f"All {len(reach)} active account(s) inherit at least one "
                      f"authorization policy beyond the FullAWSAccess default")

    def _org_management_workloads(self, org_meta: Dict) -> None:
        """ORG-03 / 2.1.3 — workloads in the management account.

        SCOPED TO THE SCANNED REGION, and the message says so. A full answer would sweep
        every region, which is a different and much more expensive scan; reporting a
        region-scoped finding as if it were estate-wide would be the more common mistake
        and the worse one."""
        self._log("ORG-03: management account workloads")
        mgmt = str(org_meta.get("MasterAccountId") or "")
        is_mgmt = (mgmt == str(self.account)) if mgmt else None
        if not is_mgmt:
            r = aws_cis_foundations.management_account_workloads(is_mgmt)
            self._org_not_evaluated("ORG-03", mgmt or "organizations", r["reason"])
            return

        counts: Dict[str, int] = {}
        probes = (
            ("EC2 instance(s)", "ec2", "describe_instances", "Reservations"),
            ("Lambda function(s)", "lambda", "list_functions", "Functions"),
            ("RDS instance(s)", "rds", "describe_db_instances", "DBInstances"),
        )
        for label, svc, method, key in probes:
            try:
                items = self._paginate_strict(self._client(svc), method, key)
            except Exception:
                continue                       # a denied probe is not evidence of absence
            if key == "Reservations":
                n = sum(len(rv.get("Instances") or []) for rv in items)
            else:
                n = len(items)
            if n:
                counts[label] = n

        r = aws_cis_foundations.management_account_workloads(True, counts)
        if r.get("failed"):
            self._add("FAIL", "ORG-03", "ORGANIZATIONS", mgmt,
                      r["statement"] + f" (counted in {self.region} only)")
        else:
            self._add("PASS", "ORG-03", "ORGANIZATIONS", mgmt,
                      f"No EC2, Lambda or RDS workloads found in the management account "
                      f"in {self.region}")

    def _org_structure(self, org) -> None:
        """ORG-04 / 2.1.4 — accounts parented directly to the organisation root."""
        self._log("ORG-04: organizational unit structure")
        try:
            roots = self._paginate_strict(org, "list_roots", "Roots")
        except Exception as e:
            self._org_not_evaluated(
                "ORG-04", "organizations",
                "organizations:ListRoots is denied here, which is normal outside the "
                "management account" if self._is_access_denied(e)
                else f"the organisation root could not be read ({e})",
                action="organizations:ListRoots" if self._is_access_denied(e) else "")
            return
        stray: List[str] = []
        ous = 0
        for root in roots:
            rid = root.get("Id")
            if not rid:
                continue
            try:
                stray.extend(
                    str(a.get("Id")) for a in self._paginate_strict(
                        org, "list_accounts_for_parent", "Accounts", ParentId=rid))
                ous += len(self._paginate_strict(
                    org, "list_organizational_units_for_parent",
                    "OrganizationalUnits", ParentId=rid))
            except Exception as e:
                self._org_not_evaluated(
                    "ORG-04", str(rid),
                    "the accounts and organizational units under the root could not be "
                    "listed, so accounts outside an OU could not be identified",
                    action="organizations:ListAccountsForParent"
                    if self._is_access_denied(e) else "")
                return
        r = aws_cis_foundations.accounts_outside_an_ou(stray, ou_count=ous)
        if r.get("failed"):
            for aid in r["accounts"]:
                self._add("FAIL", "ORG-04", "ORGANIZATIONS", aid, r["statement"])
        else:
            self._add("PASS", "ORG-04", "ORGANIZATIONS", "organizations",
                      f"Every account sits inside an organizational unit ({ous} OU(s) "
                      f"at the root)")

    def _org_delegation(self, org) -> None:
        """ORG-05 / 2.1.5 and ORG-06 / 2.1.6 — delegated administration."""
        self._log("ORG-05/06: delegated administration")
        try:
            delegated = self._paginate_strict(
                org, "list_delegated_administrators", "DelegatedAdministrators")
        except Exception as e:
            delegated = None
            if self._is_access_denied(e):
                self._coverage.note_denied("ORG-05",
                                           "organizations:ListDelegatedAdministrators")
        policy = None
        try:
            rp = (org.describe_resource_policy().get("ResourcePolicy") or {})
            policy = (rp.get("Content") or "") or None
        except Exception as e:
            # No resource policy at all raises ResourcePolicyNotFoundException, which IS
            # the finding — an access denial is not. Only the second is unknown.
            if self._is_access_denied(e):
                self._org_not_evaluated(
                    "ORG-05", "organizations",
                    "organizations:DescribeResourcePolicy is denied here, so whether "
                    "policy administration is delegated could not be read",
                    action="organizations:DescribeResourcePolicy")
                delegated = None

        if delegated is not None or policy is not None:
            r = aws_cis_foundations.delegated_policy_admin(delegated, policy)
            if r.get("failed"):
                self._add("FAIL", "ORG-05", "ORGANIZATIONS", "organizations",
                          r["statement"])
            elif not r.get("unknown"):
                self._add("PASS", "ORG-05", "ORGANIZATIONS", "organizations",
                          "An Organizations resource policy delegates policy "
                          "administration off the management account")

        try:
            trusted = [str(s.get("ServicePrincipal")) for s in self._paginate_strict(
                org, "list_aws_service_access_for_organization",
                "EnabledServicePrincipals")]
        except Exception as e:
            self._org_not_evaluated(
                "ORG-06", "organizations",
                "organizations:ListAWSServiceAccessForOrganization is denied here, which "
                "is normal outside the management account" if self._is_access_denied(e)
                else "the organisation's trusted services could not be listed",
                action="organizations:ListAWSServiceAccessForOrganization"
                if self._is_access_denied(e) else "")
            return
        have: List[str] = []
        for d in (delegated or []):
            aid = d.get("Id")
            if not aid:
                continue
            try:
                have.extend(str(s.get("ServicePrincipal")) for s in
                            self._paginate_strict(
                                org, "list_delegated_services_for_account",
                                "DelegatedServices", AccountId=aid))
            except Exception:
                continue
        r = aws_cis_foundations.delegated_service_admins(trusted, have)
        if r.get("failed"):
            self._add("FAIL", "ORG-06", "ORGANIZATIONS", "organizations", r["statement"])
        else:
            self._add("PASS", "ORG-06", "ORGANIZATIONS", "organizations",
                      f"Every one of the {len(trusted)} service(s) with trusted access "
                      f"has a delegated administrator")

    def _account_contacts(self) -> None:
        """ACCT-01 / 2.2 and ACCT-02 / 2.3 — the contact record, and the security contact.

        These run for every account, member or management, because they are properties of
        the account rather than of the organisation."""
        self._log("ACCT-01/02: account contact information")
        try:
            acct = self._client("account", region="us-east-1")
        except Exception:
            self._org_not_evaluated("ACCT-01", "account",
                                    "the account API is unavailable in this SDK version")
            self._org_not_evaluated("ACCT-02", "account",
                                    "the account API is unavailable in this SDK version")
            return

        try:
            info = acct.get_contact_information().get("ContactInformation") or {}
        except Exception as e:
            info = None
            self._org_not_evaluated(
                "ACCT-01", "account",
                "account:GetContactInformation is denied, so whether the contact record "
                "is complete could not be read",
                action="account:GetContactInformation" if self._is_access_denied(e)
                else "")
        if info is not None:
            r = aws_cis_foundations.contact_details(info)
            if r.get("failed"):
                self._add("FAIL", "ACCT-01", "ORGANIZATIONS", "primary-contact",
                          r["statement"])
            else:
                self._add("PASS", "ACCT-01", "ORGANIZATIONS", "primary-contact",
                          "The account's primary contact record is fully populated "
                          "(currency is not readable and is not claimed)")

        readable = True
        contact = None
        try:
            contact = (acct.get_alternate_contact(AlternateContactType="SECURITY")
                       .get("AlternateContact") or {})
        except Exception as e:
            # ResourceNotFoundException means there is no security contact, which IS the
            # finding. Only a denial makes the answer unknown.
            if self._is_access_denied(e):
                readable = False
        if not readable:
            self._org_not_evaluated(
                "ACCT-02", "account",
                "account:GetAlternateContact is denied, so whether a security contact is "
                "registered could not be read",
                action="account:GetAlternateContact")
            return
        r = aws_cis_foundations.security_contact(contact, readable=True)
        if r.get("failed"):
            self._add("FAIL", "ACCT-02", "ORGANIZATIONS", "security-contact",
                      r["statement"])
        else:
            self._add("PASS", "ACCT-02", "ORGANIZATIONS", "security-contact",
                      "A SECURITY alternate contact is registered")

    # ══════════════════════════════════════════════════════════════════════════
    # SECTION 1: IDENTITY & ACCESS MANAGEMENT
    # ══════════════════════════════════════════════════════════════════════════
    def _check_iam(self):
        self._section_header("IAM")
        # Slice 5.2 -- AWS's three data-perimeter objectives. Run first so the estate's
        # perimeter posture heads the section: it is the ceiling every per-principal
        # finding below sits under.
        self._check_data_perimeter()
        iam = self._client("iam")

        # IAM-01 / IAM-02 — Root account MFA and access keys
        self._log("IAM-01/02: Root account MFA and access keys")
        try:
            summary   = iam.get_account_summary()["SummaryMap"]
            root_mfa  = summary.get("AccountMFAEnabled", 0)
            root_keys = summary.get("AccountAccessKeysPresent", 0)
            if root_mfa == 1:
                self._add("PASS", "IAM-01", "IAM", "root", "Root MFA is enabled")
            else:
                self._add("FAIL", "IAM-01", "IAM", "root",
                          "Root MFA is NOT enabled — CRITICAL")
            if root_keys == 0:
                self._add("PASS", "IAM-02", "IAM", "root",
                          "No root access keys present")
            else:
                self._add("FAIL", "IAM-02", "IAM", "root",
                          "Root access keys EXIST — CRITICAL: remove immediately")
        except Exception as e:
            self._add("FAIL", "IAM-01", "IAM", "root",
                      f"Could not check root account: {e}")

        # IAM-04 — Console users without MFA
        self._log("IAM-04: Console users without MFA")
        no_mfa_found = False
        for row in self._get_credential_report():
            if row.get("user") == "<root_account>":
                continue
            if (row.get("password_enabled") == "true"
                    and row.get("mfa_active") == "false"):
                self._add("FAIL", "IAM-04", "IAM", row["user"],
                          f"Console user WITHOUT MFA: {row['user']}")
                no_mfa_found = True
        if not no_mfa_found and self._cred_report_ok:
            self._add("PASS", "IAM-04", "IAM", "all-users",
                      "All console users have MFA enabled")
        elif not self._cred_report_ok:
            self._add("WARN", "IAM-04", "IAM", "all-users",
                      "Credential report unavailable — console-user MFA could not be "
                      "evaluated (retry the scan)")

        # IAM-05 — Password policy
        self._log("IAM-05: Password policy")
        try:
            p      = iam.get_account_password_policy()["PasswordPolicy"]
            issues = []
            if p.get("MinimumPasswordLength", 0) < 14:
                issues.append(
                    f"MinLength={p.get('MinimumPasswordLength')} (need ≥14)"
                )
            if not p.get("RequireSymbols"):
                issues.append("RequireSymbols=false")
            if not p.get("RequireNumbers"):
                issues.append("RequireNumbers=false")
            if not p.get("RequireUppercaseCharacters"):
                issues.append("RequireUppercase=false")
            if p.get("MaxPasswordAge", 999) > 90:
                issues.append(f"MaxAge={p.get('MaxPasswordAge')} (need ≤90)")
            if not p.get("PreventPasswordReuse") or \
                    p.get("PasswordReusePrevention", 0) < 24:
                issues.append("PasswordReuse<24")
            if issues:
                self._add("FAIL", "IAM-05", "IAM", "password-policy",
                          f"Password policy issues: {', '.join(issues)}")
            else:
                self._add("PASS", "IAM-05", "IAM", "password-policy",
                          "Password policy meets CIS requirements")
        except ClientError as e:
            if e.response["Error"]["Code"] == "NoSuchEntity":
                self._add("FAIL", "IAM-05", "IAM", "password-policy",
                          "No account password policy set")
            else:
                self._read_failed("IAM-05", "IAM", "password-policy",
                                  "iam:GetAccountPasswordPolicy", e)

        # IAM-06 — Stale access keys (>90 days)
        self._log("IAM-06: Stale access keys (>90 days)")
        for row in self._get_credential_report():
            for k in ["access_key_1", "access_key_2"]:
                if row.get(f"{k}_active") == "true":
                    rotated = row.get(f"{k}_last_rotated", "")
                    if rotated and rotated not in ("N/A", "no_information"):
                        age = (
                            datetime.now(timezone.utc)
                            - datetime.fromisoformat(rotated)
                        ).days
                        user = row["user"]
                        if age > 90:
                            self._add("FAIL", "IAM-06", "IAM",
                                      f"{user}/{k}",
                                      f"{user} {k} is {age} days old — rotate immediately")
                        else:
                            self._add("PASS", "IAM-06", "IAM",
                                      f"{user}/{k}",
                                      f"{user} {k} age={age}d OK")

        # IAM-07 — Root account recent use (CIS 2.7); zero new API (cached report)
        self._log("IAM-07: Root account recent use")
        report = self._get_credential_report()
        root = next((r for r in report if r.get("user") == "<root_account>"), None)
        if root:
            recent = []
            for f in ("password_last_used", "access_key_1_last_used_date",
                      "access_key_2_last_used_date"):
                d = _cred_age_days(root.get(f, ""))
                if d is not None and d <= 30:
                    recent.append(f"{f.replace('_last_used_date','').replace('_',' ')}={d}d")
            if recent:
                self._add("FAIL", "IAM-07", "IAM", "root",
                          f"Root account used within 30 days ({', '.join(recent)}) — "
                          f"CIS 2.7: use IAM roles, not root, for daily tasks")
            else:
                self._add("PASS", "IAM-07", "IAM", "root",
                          "No root credential use in the last 30 days")
        elif not self._cred_report_ok:
            # never silently skip — tell the operator the root audit could not run
            self._add("WARN", "IAM-07", "IAM", "root",
                      "Credential report unavailable — IAM-07/08 root & unused-credential "
                      "audit could not be evaluated (retry the scan)")

        # IAM-08 — Credentials unused for 45+ days (CIS 2.11); zero new API
        self._log("IAM-08: Credentials unused for 45+ days")
        for row in self._get_credential_report():
            user = row.get("user", "")
            if user == "<root_account>":
                continue
            if row.get("password_enabled") == "true":
                # never-used fallback = the password's own age (password_last_changed),
                # not the user's age — a freshly set unused password isn't "45d unused".
                idle = _cred_idle_days(row.get("password_last_used", ""),
                                       row.get("password_last_changed", ""))
                if idle is not None and idle > 45:
                    self._add("FAIL", "IAM-08", "IAM", user,
                              f"Console password unused {idle}d (>45) — disable it | {user}")
            for k in ("access_key_1", "access_key_2"):
                if row.get(f"{k}_active") == "true":
                    idle = _cred_idle_days(row.get(f"{k}_last_used_date", ""),
                                           row.get(f"{k}_last_rotated", ""))
                    if idle is not None and idle > 45:
                        self._add("FAIL", "IAM-08", "IAM", f"{user}/{k}",
                                  f"{k} unused {idle}d (>45) — deactivate it | {user}")

        # IAM-10 — Access Analyzer in all regions
        self._log("IAM-10: Access Analyzer enabled in all regions")
        for rgn in self._get_all_regions():
            try:
                aa    = self._client("accessanalyzer", region=rgn)
                count = len(aa.list_analyzers()["analyzers"])
                if count > 0:
                    self._add("PASS", "IAM-10", "IAM", rgn,
                              f"Access Analyzer active in {rgn}")
                else:
                    self._add("FAIL", "IAM-10", "IAM", rgn,
                              f"No Access Analyzer in {rgn}")
            except Exception as e:
                self._add("WARN", "IAM-10", "IAM", rgn,
                          f"Could not check Access Analyzer in {rgn}: {e}")

        self._check_iam_foundations()
        self._emit_credential_exposures()

    def _iam_partition(self) -> str:
        """The ARN partition for AWS-managed policy ARNs in this region.

        Hard-coding ``arn:aws:`` would make IAM-13 and IAM-15 silently unable to fire in
        China and GovCloud — the read would raise NoSuchEntity, be swallowed as "no
        entities hold it", and IAM-13 would then report the support role as ABSENT in
        every account in those partitions. A wrong ARN producing a confident FAIL is
        worse than one producing an error."""
        r = str(self.region or "")
        if r.startswith("cn-"):
            return "aws-cn"
        if r.startswith("us-gov-"):
            return "aws-us-gov"
        if r.startswith("us-iso"):
            return "aws-iso-b" if r.startswith("us-isob-") else "aws-iso"
        return "aws"

    def _managed_policy_entities(self, check_id: str, policy: str) -> Optional[Dict]:
        """Who holds an AWS-managed policy, or None if the read did not happen."""
        arn = f"arn:{self._iam_partition()}:iam::aws:policy/{policy}"
        try:
            iam = self._client("iam", region="us-east-1")
            out = {"PolicyRoles": [], "PolicyUsers": [], "PolicyGroups": []}
            for page in iam.get_paginator("list_entities_for_policy").paginate(
                    PolicyArn=arn):
                for k in out:
                    out[k].extend(page.get(k) or [])
            return out
        except Exception as e:
            if self._is_access_denied(e):
                self._coverage.note_denied(check_id, "iam:ListEntitiesForPolicy")
                self._add("INFO", check_id, "IAM", policy,
                          f"NOT EVALUATED — iam:ListEntitiesForPolicy is denied, so who "
                          f"holds {policy} could not be read")
            else:
                self._add("INFO", check_id, "IAM", policy,
                          f"NOT EVALUATED — {policy} could not be resolved in this "
                          f"partition ({e})")
            return None

    def _check_iam_foundations(self):
        """IAM-11..15 — CIS Foundations v7.0.0 2.6, 2.13, 2.15, 2.19 and 2.20.

        Grouped in one method because they share the credential report this section has
        already fetched and cached, and because four of the five are single reads that do
        not warrant a section of their own."""
        iam = None
        try:
            iam = self._client("iam", region="us-east-1")
        except Exception:
            return
        report = self._get_credential_report()

        # ── IAM-11 / 2.6 — root MFA is virtual rather than hardware ──────────────
        self._log("IAM-11: root MFA is a hardware device")
        root_row = next((r for r in report if r.get("user") == "<root_account>"), {})
        root_mfa_on = str(root_row.get("mfa_active", "")).lower() == "true"
        if not root_mfa_on:
            # IAM-01 already reports "no MFA on root", which is the more serious
            # finding. Repeating it here as a weaker one would double-count it.
            self._add("INFO", "IAM-11", "IAM", "root",
                      "NOT EVALUATED — root has no MFA device at all; IAM-01 reports "
                      "that, and it is the more serious finding")
        else:
            serial = None
            try:
                for page in iam.get_paginator("list_virtual_mfa_devices").paginate(
                        AssignmentStatus="Assigned"):
                    for d in page.get("VirtualMFADevices") or []:
                        if str((d.get("User") or {}).get("Arn", "")).endswith(":root"):
                            serial = d.get("SerialNumber")
            except Exception as e:
                if self._is_access_denied(e):
                    self._coverage.note_denied("IAM-11", "iam:ListVirtualMFADevices")
                self._add("INFO", "IAM-11", "IAM", "root",
                          "NOT EVALUATED — iam:ListVirtualMFADevices could not be read, "
                          "so virtual and hardware MFA could not be told apart")
                serial = False                 # sentinel: read failed, do not decide
            if serial is not False:
                # A root user with MFA that appears in NO virtual-device listing is
                # holding a hardware device, which is the passing state.
                r = aws_cis_foundations.root_mfa_is_virtual(serial or "", mfa_enabled=True)
                if r.get("failed"):
                    self._add("FAIL", "IAM-11", "IAM", "root", r["statement"])
                elif not r.get("unknown"):
                    self._add("PASS", "IAM-11", "IAM", "root",
                              "Root MFA is a hardware device")

        # ── IAM-12 / 2.13 — permissions attached straight to a user ──────────────
        self._log("IAM-12: IAM users receive permissions only through groups")
        users = [r.get("user", "") for r in report
                 if r.get("user") and r.get("user") != "<root_account>"]
        checked = 0
        for user in users:
            try:
                att = [p.get("PolicyName") for p in iam.list_attached_user_policies(
                    UserName=user).get("AttachedPolicies") or []]
                inl = list(iam.list_user_policies(UserName=user).get("PolicyNames") or [])
            except Exception as e:
                if self._is_access_denied(e):
                    self._coverage.note_denied("IAM-12", "iam:ListAttachedUserPolicies")
                continue
            checked += 1
            r = aws_cis_foundations.user_attached_policies(user, att, inl)
            if r.get("failed"):
                self._add("FAIL", "IAM-12", "IAM", user, r["statement"])
        if checked and not any(x.check_id == "IAM-12" and x.status == "FAIL"
                               for x in self.results):
            self._add("PASS", "IAM-12", "IAM", "all-users",
                      f"All {checked} IAM user(s) receive permissions only through groups")

        # ── IAM-13 / 2.15 — a support role exists ────────────────────────────────
        self._log("IAM-13: a role can raise AWS Support cases")
        ents = self._managed_policy_entities("IAM-13", "AWSSupportAccess")
        if ents is not None:
            r = aws_cis_foundations.support_role(ents)
            if r.get("failed"):
                self._add("FAIL", "IAM-13", "IAM", "AWSSupportAccess", r["statement"])
            else:
                self._add("PASS", "IAM-13", "IAM", "AWSSupportAccess",
                          "A principal holds AWSSupportAccess and can raise a case "
                          "without administrator rights")

        # ── IAM-14 / 2.19 — human sign-in goes through federation ────────────────
        self._log("IAM-14: human access is federated")
        console = [r.get("user", "") for r in report
                   if r.get("user") != "<root_account>"
                   and str(r.get("password_enabled", "")).lower() == "true"]
        sources: List[str] = []
        try:
            if iam.list_saml_providers().get("SAMLProviderList"):
                sources.append("SAML")
        except Exception:
            pass
        try:
            if iam.list_open_id_connect_providers().get(
                    "OpenIDConnectProviderList"):
                sources.append("OIDC")
        except Exception:
            pass
        try:
            if self._client("sso-admin", region=self.region).list_instances().get(
                    "Instances"):
                sources.append("IAM Identity Center")
        except Exception:
            pass
        r = aws_cis_foundations.federated_human_access(console, sources)
        if r.get("failed"):
            self._add("FAIL", "IAM-14", "IAM", "console-users", r["statement"])
        elif r.get("unknown"):
            self._add("INFO", "IAM-14", "IAM", "console-users",
                      f"NOT EVALUATED — {r['reason']}")
        else:
            self._add("PASS", "IAM-14", "IAM", "console-users",
                      "No IAM user has a console password; human sign-in does not use "
                      "local credentials")

        # ── IAM-15 / 2.20 — CloudShell full access is not broadly granted ────────
        self._log("IAM-15: AWSCloudShellFullAccess is restricted")
        ents = self._managed_policy_entities("IAM-15", "AWSCloudShellFullAccess")
        if ents is not None:
            r = aws_cis_foundations.cloudshell_access(ents)
            if r.get("failed"):
                self._add("FAIL", "IAM-15", "IAM", "AWSCloudShellFullAccess",
                          r["statement"])
            else:
                self._add("PASS", "IAM-15", "IAM", "AWSCloudShellFullAccess",
                          "No principal holds AWSCloudShellFullAccess")

    def _emit_credential_exposures(self):
        """CREDEXP-00..03 — leaked credentials the operator supplied, joined to identity.

        Reported in the IAM section rather than a section of its own, because that is
        what these findings are ABOUT: an IAM user whose credential is in a breach
        corpus, and an access key id that is both leaked and live. IAM is also
        already a GLOBAL section, so the join happens once per scan rather than once
        per region.

        A HIT IS AN OBSERVATION OF A CORPUS, NEVER A COMPROMISE. Somebody genuinely
        saw this data in a compilation; that does not establish that the credential
        still works, that it was ever used against this account, or that this account
        was breached. The wording of every message below is deliberate about that
        distinction, because "leaked credential found" is exactly the phrase that
        gets read as "we were hacked" — and the corpus cannot support it.

        NO CREDENTIAL MATERIAL ENTERS THE PRODUCT. `aws_ingest_credexp.normalize`
        builds each record from an allowlist and stores a salted digest, so the
        plaintext never reaches a finding, a report or the state store.
        """
        parsed = self._cred_exposures
        if not parsed or not parsed.get("exposures"):
            return

        exposures = parsed["exposures"]
        domains = parsed.get("estate_domains") or ()
        keys = self._access_key_ids()

        principals = []
        for p in self._get_iam_principals():
            # An `email` tag is the only place an IAM user carries one, and the tags
            # arrive on the GetAccountAuthorizationDetails page already read, so
            # matching on it costs no call and no grant.
            tags = p.get("tags") or {}
            principals.append({
                "name": p.get("name") or "",
                "email": tags.get("email") or tags.get("Email") or "",
                "type": p.get("type") or "",
                "arn": p.get("arn") or ""})

        joined = aws_ingest_credexp.correlate(
            exposures, principals, estate_domains=domains,
            known_key_ids=keys or ())

        cov = aws_ingest_credexp.coverage(
            exposures, known_key_ids=keys or (), estate_domains=domains,
            salt=parsed.get("salt") or "")

        # The coverage statement is emitted whether or not anything matched, and that
        # is the point of it: with no key inventory an empty result means "we could
        # not look", and an operator who reads it as "nothing was exposed" has drawn
        # the opposite conclusion from the evidence.
        notes = "; ".join(cov.get("not_evaluated") or []) or "no gaps recorded"
        self._add("INFO", "CREDEXP-00", "IAM", "credential-exposure",
                  f"Ingested {cov['total_exposures']} credential exposure(s): "
                  f"{cov['with_credential']} carry a credential digest, "
                  f"{cov['with_access_key']} carry an AWS access key id; "
                  f"{len(joined)} joined to this estate. "
                  f"{cov['provenance_note']} "
                  f"NOT EVALUATED: {notes} | credential-exposure")

        if keys is None:
            # Named as a denial rather than left as an empty join, so the coverage
            # manifest carries it too.
            self._coverage.note_denied("CREDEXP-01", "iam:ListAccessKeys")

        for hit in joined:
            exp = hit["exposure"]
            src = exp.get("source") or exp.get("kind") or "an unnamed corpus"
            who = ", ".join(sorted(
                p.get("name") or "?" for p in hit.get("principals") or [])) or "-"

            if hit.get("matched_on") == "access_key_id":
                kid = exp.get("access_key_id")
                self._add("FAIL", "CREDEXP-01", "IAM", kid,
                          f"Access key {kid} is LIVE in this account and appears in "
                          f"{src}. This is the strongest join a breach corpus "
                          f"supports: the identifier is not a guess and the key is "
                          f"not retired. It does NOT establish that the secret half "
                          f"is still valid or that it was used here — rotate it and "
                          f"read CloudTrail for its usage | {kid}")
            elif hit.get("domain_match_only"):
                self._add("FAIL", "CREDEXP-03", "IAM", exp.get("domain") or "estate",
                          f"An exposure in {src} carries an address at "
                          f"{exp.get('domain')}, one of this estate's domains, but "
                          f"matches no IAM principal. It is a signal about the "
                          f"organisation rather than about this account: the person "
                          f"may hold no IAM identity, or hold one under another "
                          f"name | {exp.get('domain')}")
            else:
                self._add("FAIL", "CREDEXP-02", "IAM", who,
                          f"IAM principal '{who}' matches an exposure in {src} on "
                          f"its {hit.get('matched_on')}. The corpus says this "
                          f"identifier appeared with a credential; it says nothing "
                          f"about whether that credential was ever this account's, "
                          f"so treat it as a prompt to rotate and to check for MFA "
                          f"rather than as evidence of a breach | {who}")

    # ══════════════════════════════════════════════════════════════════════════
    # SECTION 2: S3 SECURITY
    # ══════════════════════════════════════════════════════════════════════════
    def _check_s3(self):
        self._section_header("S3")
        s3  = self._client("s3")
        s3c = self._client("s3control")

        # S3-01 — Account-level Block Public Access
        self._log("S3-01: Account-level Block Public Access")
        cfg = None   # account-level BPA config; reused by S3-09 neutralization
        try:
            cfg = s3c.get_public_access_block(AccountId=self.account)[
                "PublicAccessBlockConfiguration"
            ]
            if all(cfg.values()):
                self._add("PASS", "S3-01", "S3", "account",
                          "Account-level Block Public Access fully enabled")
            else:
                disabled = [k for k, v in cfg.items() if not v]
                self._add("FAIL", "S3-01", "S3", "account",
                          f"Block Public Access not fully enabled — Disabled: {disabled}")
        except Exception as e:
            self._add("FAIL", "S3-01", "S3", "account",
                      f"Could not retrieve account-level BPA: {e}")

        # Per-bucket checks
        self._log("S3-01/S3-03/S3-05: Per-bucket security scan")
        try:
            buckets = s3.list_buckets().get("Buckets", [])
        except Exception as e:
            self._add("FAIL", "S3-01", "S3", "all-buckets",
                      f"Cannot list S3 buckets: {e}")
            return

        for b in buckets:
            bname = b["Name"]

            # BPA per bucket
            bpa = None   # reused by S3-09 neutralization
            try:
                bpa = s3.get_public_access_block(Bucket=bname)[
                    "PublicAccessBlockConfiguration"
                ]
                if all(bpa.values()):
                    self._add("PASS", "S3-01", "S3", bname,
                              f"BPA fully enabled | {bname}")
                else:
                    self._add("FAIL", "S3-01", "S3", bname,
                              f"BPA NOT fully enabled | {bname}")
            except Exception as e:
                # ABSENCE AND REFUSAL ARE DIFFERENT ANSWERS, and S3 signals both by
                # raising. NoSuchPublicAccessBlockConfiguration means the bucket
                # genuinely has no Block Public Access config; AccessDenied means we
                # were not allowed to look, which is common on buckets owned by another
                # account. Stating the first for both asserts a fact about the bucket
                # that was never established — the S3-07 defect the bucket-B pass fixed.
                if self._error_code(e) == "NoSuchPublicAccessBlockConfiguration":
                    self._add("FAIL", "S3-01", "S3", bname,
                              f"No BPA config | {bname}")
                else:
                    self._read_failed("S3-01", "S3", bname,
                                      "s3:GetBucketPublicAccessBlock", e)

            # Encryption
            try:
                enc = s3.get_bucket_encryption(Bucket=bname)[
                    "ServerSideEncryptionConfiguration"
                ]
                alg = enc["Rules"][0]["ApplyServerSideEncryptionByDefault"][
                    "SSEAlgorithm"
                ]
                self._add("PASS", "S3-03", "S3", bname,
                          f"Encryption={alg} | {bname}")
            except Exception as e:
                # Same split. ServerSideEncryptionConfigurationNotFoundError IS the
                # detection here — S3 has no other way to say "no default encryption" —
                # so it stays a FAIL. Everything else is a read we could not make.
                if self._error_code(e) in (
                        "ServerSideEncryptionConfigurationNotFoundError",
                        "ServerSideEncryptionConfigurationNotFoundException"):
                    self._add("FAIL", "S3-03", "S3", bname,
                              f"No default encryption | {bname}")
                else:
                    self._read_failed("S3-03", "S3", bname,
                                      "s3:GetEncryptionConfiguration", e)

            # Access logging
            try:
                log_cfg = s3.get_bucket_logging(Bucket=bname).get(
                    "LoggingEnabled"
                )
                if log_cfg:
                    self._add("PASS", "S3-05", "S3", bname,
                              f"Access logging enabled | {bname}")
                else:
                    self._add("FAIL", "S3-05", "S3", bname,
                              f"Access logging disabled | {bname}")
            except Exception:
                pass

            # S3-07/09/10 — ONE bucket-policy fetch feeds TLS-only + public + cross-account
            stmts = None
            try:
                stmts = json.loads(s3.get_bucket_policy(Bucket=bname)["Policy"]).get(
                    "Statement", [])
                if isinstance(stmts, dict):
                    stmts = [stmts]
            except Exception as e:
                # No policy at all -> not public (S3-09 silent); TLS-only also not
                # enforced. But AccessDenied is not "no policy" -- it is "we could not
                # read it", and reporting that as an absent policy states a fact we do
                # not have. S3-09 below already split these two; S3-07 did not.
                if "denied" in str(e).lower():
                    self._add("WARN", "S3-07", "S3", bname,
                              f"Cannot evaluate bucket policy (access denied) — TLS-only "
                              f"enforcement UNKNOWN, not absent | {bname}")
                else:
                    self._add("FAIL", "S3-07", "S3", bname,
                              f"No bucket policy, so nothing denies plaintext HTTP "
                              f"access to this bucket | {bname}")
                # AccessDenied (not NoSuchBucketPolicy) means exposure is UNKNOWN, not clean.
                if "denied" in str(e).lower():
                    self._add("WARN", "S3-09", "S3", bname,
                              f"Cannot evaluate bucket policy (access denied — possibly "
                              f"cross-account owned) | {bname}")
            if stmts is not None:
                # S3-07 — TLS-only (deny non-SecureTransport)
                if any(self._stmt_denies_insecure_transport(st, bname) for st in stmts):
                    self._add("PASS", "S3-07", "S3", bname,
                              f"Bucket policy denies non-TLS access | {bname}")
                else:
                    self._add("FAIL", "S3-07", "S3", bname,
                              f"Bucket policy does NOT enforce TLS "
                              f"(no aws:SecureTransport deny) | {bname}")
                # S3-09/10 — public + cross-account exposure classification
                self._check_bucket_policy_exposure(bname, stmts, cfg, bpa)

            # S3-08 — Versioning (rollback protection vs overwrite/ransomware)
            # S3-11 — MFA Delete (CIS Foundations v7.0.0 3.1.2). ONE call answers both:
            # GetBucketVersioning returns Status and MFADelete together, and MFA Delete is
            # a property OF versioning rather than a separate setting.
            try:
                vcfg = s3.get_bucket_versioning(Bucket=bname)
                ver = vcfg.get("Status")
                if ver == "Enabled":
                    self._add("PASS", "S3-08", "S3", bname,
                              f"Versioning enabled | {bname}")
                else:
                    self._add("FAIL", "S3-08", "S3", bname,
                              f"Versioning not enabled — no rollback from object "
                              f"overwrite/ransomware | {bname}")
                r = aws_cis_foundations.bucket_mfa_delete(bname, vcfg)
                if r.get("failed"):
                    self._add("FAIL", "S3-11", "S3", bname, r["statement"])
                elif not r.get("unknown"):
                    self._add("PASS", "S3-11", "S3", bname,
                              f"MFA Delete enabled | {bname}")
            except Exception:
                pass

    @staticmethod
    def _stmt_denies_insecure_transport(st: Dict, bucket: str = "") -> bool:
        """True only if a bucket-policy statement EFFECTIVELY denies all non-TLS
        access: Effect=Deny + aws:SecureTransport=false, applied to EVERY principal,
        ALL S3 actions, and at least the object-level resource (bucket/*). A
        narrowly-scoped deny (single action/principal/resource) does NOT count —
        plaintext HTTP to other actions/objects would still be possible."""
        if st.get("Effect") != "Deny":
            return False
        # (a) aws:SecureTransport=false condition (Bool / BoolIfExists, str or list)
        cond = st.get("Condition", {}) or {}
        has_cond = False
        for op in ("Bool", "BoolIfExists"):
            val = (cond.get(op) or {}).get("aws:SecureTransport")
            if val is None:
                continue
            vals = val if isinstance(val, list) else [val]
            if any(str(v).lower() == "false" for v in vals):
                has_cond = True
                break
        if not has_cond:
            return False
        # (b) every principal ("*" or {"AWS": "*"})
        princ = st.get("Principal")
        if princ != "*":
            if not isinstance(princ, dict):
                return False
            aws_p = princ.get("AWS")
            aws_list = aws_p if isinstance(aws_p, list) else [aws_p]
            if "*" not in aws_list:
                return False
        # (c) all S3 actions ("s3:*" or "*")
        actions = st.get("Action", [])
        actions = actions if isinstance(actions, list) else [actions]
        if not any(a in ("*", "s3:*") for a in actions):
            return False
        # (d) at least the object-level resource is covered
        obj_arn = f"arn:aws:s3:::{bucket}/*" if bucket else None
        res = st.get("Resource")
        if res is not None:
            res = res if isinstance(res, list) else [res]
            return any(r == "*" or (isinstance(r, str) and r.endswith("/*")) or r == obj_arn
                       for r in res)
        # NotResource form: the deny covers everything EXCEPT the listed ARNs, so it is
        # effective for this bucket unless a NotResource entry excludes its objects.
        not_res = st.get("NotResource")
        if not_res is not None:
            not_res = not_res if isinstance(not_res, list) else [not_res]
            excludes_objects = any(
                r == "*" or r == obj_arn or (bucket and r == f"arn:aws:s3:::{bucket}")
                for r in not_res)
            return not excludes_objects
        return False

    def _check_bucket_policy_exposure(self, bname, stmts, acct_bpa, bucket_bpa):
        """S3-09 (public grant, BPA-neutralization aware) + S3-10 (cross-account/org grant,
        NOT BPA-neutralized) off one already-parsed bucket policy. Findings-only in Phase 6."""
        # A wildcard-principal ('*') public grant is neutralized when Block Public Access is
        # fully on (account OR bucket). A NAMED cross-account grant is NOT — BPA blocks
        # anonymous '*', never a specific external account — so S3-10 ignores BPA.
        acct_full   = bool(acct_bpa) and all(acct_bpa.values())
        bucket_full = bool(bucket_bpa) and all(bucket_bpa.values())
        for st in stmts:
            res = classify_resource_policy_stmt(st, self.account or "")
            if not res:
                continue
            kind = res["kind"]
            if kind == "public":
                if acct_full or bucket_full:
                    self._add("WARN", "S3-09", "S3", bname,
                              f"Latent PUBLIC bucket-policy statement neutralized by Block "
                              f"Public Access — remove the stale grant | {bname}")
                else:
                    self._add("FAIL", "S3-09", "S3", bname,
                              f"Bucket policy grants PUBLIC access (Principal:*, "
                              f"unconditioned) | {bname}")
            elif kind == "public_conditioned":
                self._add("WARN", "S3-09", "S3", bname,
                          f"Wildcard principal gated by an unrecognized condition — "
                          f"manual review | {bname}")
            elif kind == "cross_account":
                ext = [a for a in res.get("external_accounts", [])
                       if a not in self.trusted_accounts]
                if ext:
                    self._add("FAIL", "S3-10", "S3", bname,
                              f"Bucket policy grants CROSS-ACCOUNT access to "
                              f"{', '.join(ext)} | {bname}")
            elif kind == "org":
                self._add("WARN", "S3-10", "S3", bname,
                          f"Bucket shared to AWS Organization {res.get('org_id')} — "
                          f"verify scope | {bname}")

    # ══════════════════════════════════════════════════════════════════════════
    # SECTION 3: NETWORK SECURITY
    # ══════════════════════════════════════════════════════════════════════════
    def _check_vpc(self):
        self._section_header("VPC")
        ec2 = self._client("ec2")

        RISKY_PORTS = {
            22:    "SSH",   3389: "RDP",     1433: "MSSQL",
            3306:  "MySQL", 5432: "PostgreSQL", 27017: "MongoDB",
            6379:  "Redis", 9200: "Elasticsearch", 9300: "Elasticsearch",
            8080:  "HTTP-alt", 445: "SMB",
        }

        # VPC-01 — Security groups with risky ports open to 0.0.0.0/0 or ::/0
        # VPC-04 — default Security Group must restrict all traffic (CIS 6.5)
        self._log("VPC-01: Security Groups — risky ports open to 0.0.0.0/0 or ::/0")
        found_any = False
        default_seen = False
        sg_error = False
        default_sg_issues = []
        try:
            sgs = []
            for page in ec2.get_paginator("describe_security_groups").paginate():
                sgs.extend(page.get("SecurityGroups", []))
            for sg in sgs:
                if sg.get("GroupName") == "default":
                    default_seen = True
                    inbound  = sg.get("IpPermissions", [])
                    outbound = sg.get("IpPermissionsEgress", [])
                    if inbound or outbound:
                        default_sg_issues.append(
                            (f"{sg['GroupId']} (vpc {sg.get('VpcId', '?')})",
                             len(inbound), len(outbound)))
                for perm in sg.get("IpPermissions", []):
                    fp = perm.get("FromPort", 0)
                    tp = perm.get("ToPort", 65535)
                    open_cidrs = (
                        [r["CidrIp"]   for r in perm.get("IpRanges",   [])
                         if r["CidrIp"]   == "0.0.0.0/0"]
                        + [r["CidrIpv6"] for r in perm.get("Ipv6Ranges", [])
                           if r["CidrIpv6"] == "::/0"]
                    )
                    if open_cidrs:
                        for port, svc in RISKY_PORTS.items():
                            if fp <= port <= tp:
                                self._add(
                                    "FAIL", "VPC-01", "VPC",
                                    f"{sg['GroupId']} ({sg.get('GroupName', '')})",
                                    f"Exposes port {port}/{svc} to "
                                    f"{', '.join(open_cidrs)}",
                                )
                                found_any = True
        except Exception as e:
            sg_error = True
            self._read_failed("VPC-01", "VPC", "security-groups",
                              "ec2:DescribeSecurityGroups", e)

        if not found_any and not sg_error:
            self._add("PASS", "VPC-01", "VPC", "all-sgs",
                      "No Security Groups expose high-risk ports to 0.0.0.0/0 or ::/0")

        for res, ni, no in default_sg_issues:
            self._add("FAIL", "VPC-04", "VPC", res,
                      f"Default SG has {ni} inbound / {no} outbound rule(s) — CIS 6.5 "
                      f"requires it to restrict ALL traffic | {res}")
        if default_seen and not default_sg_issues:
            self._add("PASS", "VPC-04", "VPC", "default-sgs",
                      "All default Security Groups restrict all traffic (no rules)")

        # VPC-03 — VPC Flow Logs
        self._log("VPC-03: VPC Flow Logs enabled on all VPCs")
        try:
            vpcs   = {v["VpcId"]: v for v in ec2.describe_vpcs()["Vpcs"]}
            fl_ids = {
                fl["ResourceId"]
                for fl in ec2.describe_flow_logs()["FlowLogs"]
            }
            for vid, vpc in vpcs.items():
                is_default = vpc.get("IsDefault", False)
                if vid in fl_ids:
                    self._add("PASS", "VPC-03", "VPC", vid,
                              f"Flow Logs enabled | {vid}")
                elif is_default:
                    self._add("WARN", "VPC-03", "VPC", vid,
                              f"No Flow Logs on default VPC | {vid}")
                else:
                    self._add("FAIL", "VPC-03", "VPC", vid,
                              f"No Flow Logs | {vid}")
        except Exception as e:
            self._read_failed("VPC-03", "VPC", "vpcs", "ec2:DescribeVpcs", e)

        # VPC-05 — NACL allows internet ingress to admin ports 22/3389. NACLs are STATELESS
        # and RuleNumber first-match-wins, so a low-numbered deny before an allow-all negates
        # exposure — a naive 'any allow to 0.0.0.0/0' scan produces false FAILs.
        self._log("VPC-05: Network ACLs allowing 0.0.0.0/0 to admin ports 22/3389")
        _ADMIN = {22: "SSH", 3389: "RDP"}
        try:
            nacls = []
            for page in ec2.get_paginator("describe_network_acls").paginate():
                nacls.extend(page.get("NetworkAcls", []))
        except Exception as e:
            self._add("WARN", "VPC-05", "VPC", "network-acls",
                      f"describe_network_acls failed: {e}")
            nacls = None
        if nacls is not None:
            evaluated, world_open = 0, 0
            for nacl in nacls:
                evaluated += 1
                nid = nacl.get("NetworkAclId", "unknown")
                is_default = nacl.get("IsDefault", False)
                ingress = sorted((e for e in nacl.get("Entries", []) if not e.get("Egress")),
                                 key=lambda e: e.get("RuleNumber", 32767))
                for port, pname in _ADMIN.items():
                    # IPv4 and IPv6 are evaluated INDEPENDENTLY by AWS — a packet only matches
                    # rules of its own family — so run first-match-wins over each chain
                    # separately (an IPv6 deny must NOT mask an IPv4 allow-all, or vice versa).
                    open_families = []
                    for fam, key, world_cidr in (("IPv4", "CidrBlock", "0.0.0.0/0"),
                                                 ("IPv6", "Ipv6CidrBlock", "::/0")):
                        decided = None
                        for e in ingress:             # first matching rule of this family wins
                            if (e.get(key) == world_cidr
                                    and self._nacl_covers_port(e, port)):
                                decided = e.get("RuleAction")
                                break
                        if decided == "allow":
                            open_families.append(fam)
                    if open_families:
                        world_open += 1
                        # default NACL ships allow-all (SGs are the primary control) -> WARN
                        self._add("WARN" if is_default else "FAIL", "VPC-05", "VPC", nid,
                                  f"NACL allows {pname}({port}) from the internet "
                                  f"({'/'.join(open_families)}, "
                                  f"{'default' if is_default else 'custom'} NACL) | {nid}")
            # AGGREGATE-PASS-MUST-COUNT: only all-clear when NACLs were actually read
            if evaluated and world_open == 0:
                self._add("PASS", "VPC-05", "VPC", "network-acls",
                          "All NACLs restrict admin ports 22/3389 from the internet")

        # VPC-06 — active cross-account VPC peering (trust-boundary crossing)
        self._log("VPC-06: active cross-account VPC peering connections")
        try:
            pcxs = []
            for page in ec2.get_paginator("describe_vpc_peering_connections").paginate():
                pcxs.extend(page.get("VpcPeeringConnections", []))
        except Exception as e:
            self._add("WARN", "VPC-06", "VPC", "vpc-peering",
                      f"describe_vpc_peering_connections failed: {e}")
            pcxs = None
        if pcxs is not None:
            active = [p for p in pcxs if (p.get("Status") or {}).get("Code") == "active"]
            if not active:
                self._add("INFO", "VPC-06", "VPC", "vpc-peering",
                          "No active VPC peering connections")
            for p in active:
                pid = p.get("VpcPeeringConnectionId", "unknown")
                acc = (p.get("AccepterVpcInfo") or {}).get("OwnerId")
                req = (p.get("RequesterVpcInfo") or {}).get("OwnerId")
                # requester/accepter roles are not stable — compare the two owner ids
                if acc and req and acc != req:
                    other = acc if req == self.account else req
                    self._add("WARN", "VPC-06", "VPC", pid,
                              f"Cross-account peering {pid}: peer account {other} "
                              f"(verify authorized) | {pid}")
                else:
                    self._add("PASS", "VPC-06", "VPC", pid, f"Intra-account peering {pid}")

        self._check_vpc_foundations(ec2, pcxs)

    def _check_vpc_foundations(self, ec2, pcxs) -> None:
        """VPC-07 / 6.6 and VPC-08 / 6.8 — peering route scope, and VPC endpoint usage.

        Both read route tables, so they share the one call. VPC-08 needs them for a second
        reason: an endpoint-less VPC is only a finding when it HAS a path to the internet,
        and the route tables are where that is decided."""
        try:
            rtbs = self._paginate_strict(ec2, "describe_route_tables", "RouteTables")
        except Exception as e:
            if self._is_access_denied(e):
                self._coverage.note_denied("VPC-07", "ec2:DescribeRouteTables")
                self._coverage.note_denied("VPC-08", "ec2:DescribeRouteTables")
            self._add("INFO", "VPC-07", "VPC", "route-tables",
                      f"NOT EVALUATED — ec2:DescribeRouteTables could not be read ({e})")
            self._add("INFO", "VPC-08", "VPC", "route-tables",
                      f"NOT EVALUATED — ec2:DescribeRouteTables could not be read ({e})")
            return

        # ── VPC-07 / 6.6 — peering routes carrying a whole peer CIDR ─────────────
        self._log("VPC-07: VPC peering routes are least-access")
        peer_cidrs = {}
        for p in (pcxs or []):
            pid = p.get("VpcPeeringConnectionId")
            info = p.get("AccepterVpcInfo") or {}
            if pid and info.get("CidrBlock"):
                peer_cidrs[str(pid)] = str(info["CidrBlock"])
        wide = 0
        peering_seen = False
        for rtb in rtbs:
            if any(r.get("VpcPeeringConnectionId") for r in (rtb.get("Routes") or [])):
                peering_seen = True
            r = aws_cis_foundations.peering_route_scope(rtb, peer_cidrs)
            if r.get("failed"):
                wide += 1
                self._add("FAIL", "VPC-07", "VPC",
                          str(rtb.get("RouteTableId") or "?"), r["statement"])
        if peering_seen and not wide:
            self._add("PASS", "VPC-07", "VPC", "route-tables",
                      "Every peering route names a specific subnet rather than a whole "
                      "peer VPC")
        elif not peering_seen:
            self._add("INFO", "VPC-07", "VPC", "route-tables",
                      "No VPC peering routes exist, so there is nothing to scope")

        # ── VPC-08 / 6.8 — VPC endpoints for AWS service traffic ─────────────────
        self._log("VPC-08: VPC endpoints are used for AWS service access")
        try:
            eps = self._paginate_strict(ec2, "describe_vpc_endpoints", "VpcEndpoints")
            vpcs = self._paginate_strict(ec2, "describe_vpcs", "Vpcs")
        except Exception as e:
            if self._is_access_denied(e):
                self._coverage.note_denied("VPC-08", "ec2:DescribeVpcEndpoints")
            self._add("INFO", "VPC-08", "VPC", "vpc-endpoints",
                      f"NOT EVALUATED — the VPC endpoint inventory could not be read ({e})")
            return
        per_vpc: Dict[str, int] = {}
        for ep in eps:
            v = str(ep.get("VpcId") or "")
            if v and str(ep.get("State", "available")) in ("available", "pendingAcceptance"):
                per_vpc[v] = per_vpc.get(v, 0) + 1
        # A VPC has a path to the internet when some route table in it targets an
        # internet gateway or a NAT. Egress-only gateways count: they carry IPv6 traffic
        # to the same public endpoints.
        outbound: Set[str] = set()
        for rtb in rtbs:
            v = str(rtb.get("VpcId") or "")
            for r in (rtb.get("Routes") or []):
                if (r.get("GatewayId", "").startswith("igw-")
                        or r.get("NatGatewayId")
                        or r.get("EgressOnlyInternetGatewayId")):
                    outbound.add(v)
        bad = 0
        for vpc in vpcs:
            vid = str(vpc.get("VpcId") or "?")
            r = aws_cis_foundations.vpc_endpoint_usage(
                vid, per_vpc.get(vid, 0), vid in outbound)
            if r.get("failed"):
                bad += 1
                self._add("FAIL", "VPC-08", "VPC", vid, r["statement"])
        if vpcs and not bad:
            self._add("PASS", "VPC-08", "VPC", "vpc-endpoints",
                      f"Every internet-connected VPC of {len(vpcs)} has at least one "
                      f"VPC endpoint")

    @staticmethod
    def _nacl_covers_port(entry, port):
        """Does a NACL entry's protocol/port-range cover `port`? Protocol is a STRING
        ('-1' all, '6' tcp, '17' udp). PortRange is ABSENT when Protocol=='-1' (all ports)."""
        proto = str(entry.get("Protocol", "-1"))
        if proto == "-1":
            return True
        if proto != "6":                              # admin ports are TCP
            return False
        pr = entry.get("PortRange")
        if not pr:
            return True                               # tcp with no explicit range = all ports
        return pr.get("From", 0) <= port <= pr.get("To", 65535)

    # ══════════════════════════════════════════════════════════════════════════
    # SECTION 4: LOGGING & MONITORING
    # ══════════════════════════════════════════════════════════════════════════
    def _check_logging(self):
        self._section_header("LOGGING")

        # LOG-01 — CloudTrail
        self._log("LOG-01: CloudTrail configuration")
        try:
            ct     = self._client("cloudtrail")
            trails = ct.describe_trails(includeShadowTrails=False)["trailList"]
            if not trails:
                self._add("FAIL", "LOG-01", "LOGGING", "cloudtrail",
                          "No CloudTrail trails configured — CRITICAL")
            else:
                for t in trails:
                    issues = []
                    if not t.get("IsMultiRegionTrail"):
                        issues.append("not multi-region")
                    if not t.get("LogFileValidationEnabled"):
                        issues.append("log validation OFF")
                    try:
                        status = ct.get_trail_status(Name=t["Name"])
                        if not status.get("IsLogging"):
                            issues.append("LOGGING IS OFF")
                    except Exception:
                        issues.append("could not get trail status")
                    if issues:
                        self._add("FAIL", "LOG-01", "LOGGING", t["Name"],
                                  f"Trail '{t['Name']}' issues: {', '.join(issues)}")
                    else:
                        self._add("PASS", "LOG-01", "LOGGING", t["Name"],
                                  f"Trail '{t['Name']}' OK (multi-region, "
                                  "validation enabled, logging active)")
        except Exception as e:
            self._read_failed("LOG-01", "LOGGING", "cloudtrail",
                              "cloudtrail:DescribeTrails", e)

        # LOG-03 — AWS Config recorder
        self._log("LOG-03: AWS Config recorder status")
        try:
            cfg  = self._client("config")
            recs = cfg.describe_configuration_recorder_status()[
                "ConfigurationRecordersStatus"
            ]
            if not recs:
                self._add("FAIL", "LOG-03", "LOGGING", "config",
                          "No AWS Config recorders found")
            for r in recs:
                if r.get("recording"):
                    self._add("PASS", "LOG-03", "LOGGING", r["name"],
                              f"AWS Config recording | {r['name']}")
                else:
                    self._add("FAIL", "LOG-03", "LOGGING", r["name"],
                              f"AWS Config NOT recording | {r['name']}")
        except Exception as e:
            self._read_failed("LOG-03", "LOGGING", "config",
                              "config:DescribeConfigurationRecorderStatus", e)

        # LOG-04 — GuardDuty
        self._log("LOG-04: GuardDuty enabled in current region")
        try:
            gd   = self._client("guardduty")
            dids = gd.list_detectors().get("DetectorIds", [])
            if not dids:
                self._add("FAIL", "LOG-04", "LOGGING", "guardduty",
                          "GuardDuty NOT enabled — CRITICAL")
            else:
                for did in dids:
                    d      = gd.get_detector(DetectorId=did)
                    status = d.get("Status", "DISABLED")
                    if status == "ENABLED":
                        self._add("PASS", "LOG-04", "LOGGING", did,
                                  f"GuardDuty ENABLED | {did}")
                        self._check_guardduty_features(did, d)
                    else:
                        self._add("FAIL", "LOG-04", "LOGGING", did,
                                  f"GuardDuty {status} | {did}")
        except Exception as e:
            self._read_failed("LOG-04", "LOGGING", "guardduty",
                              "guardduty:ListDetectors", e)

        # LOG-05 — Security Hub standards
        self._log("LOG-05: Security Hub standards")
        try:
            sh        = self._client("securityhub")
            standards = sh.get_enabled_standards()["StandardsSubscriptions"]
            if not standards:
                self._add("FAIL", "LOG-05", "LOGGING", "securityhub",
                          "Security Hub enabled but no standards subscribed")
            else:
                for s in standards:
                    std_name = s.get("StandardsArn", "").split("/")[-2]
                    self._add("PASS", "LOG-05", "LOGGING", std_name,
                              f"Security Hub standard: {std_name} — "
                              f"{s.get('StandardsStatus', '')}")
        except Exception as e:
            # TWO ANSWERS, NOT ONE. InvalidAccessException and AccessDenied were treated
            # as the same finding, and they are opposites: the first means Security Hub
            # genuinely is not subscribed in this region (a real posture FAIL), the
            # second means we were refused the read and know nothing about it. Reporting
            # the second as the first states a fact about the account that was never
            # established -- the S3-07 defect, in a third place.
            #
            # `except Exception`, not `except ClientError`: the name is bound only when
            # boto3 imported (see the top of this module), so catching it by name raises
            # NameError wherever boto3 is absent -- which is every environment the test
            # suite runs in. Reading the code off whatever was raised works either way.
            if self._error_code(e) == "InvalidAccessException":
                self._add("FAIL", "LOG-05", "LOGGING", "securityhub",
                          "Security Hub not enabled in this region")
            else:
                self._read_failed("LOG-05", "LOGGING", "securityhub",
                                  "securityhub:GetEnabledStandards", e)

        # LOG-07..LOG-10 — CloudTrail configuration depth
        self._check_cloudtrail_config()

    def _check_cloudtrail_config(self) -> None:
        """LOG-07 (SSE-KMS) / LOG-08 (data events) / LOG-09 (trail-bucket public) /
        LOG-10 (delivery health). Uses includeShadowTrails=True for full multi-region
        coverage and dedups by TrailARN. Each sub-call in its own try/except."""
        self._log("LOG-07/08/09/10: CloudTrail depth (SSE-KMS, data events, bucket, delivery)")
        try:
            ct = self._client("cloudtrail")
            trails = ct.describe_trails(includeShadowTrails=True).get("trailList", [])
        except Exception as e:
            self._add("WARN", "LOG-07", "LOGGING", "cloudtrail", str(e))
            return
        unique = {}
        for t in trails:
            arn = t.get("TrailARN") or t.get("Name")
            if arn and arn not in unique:
                unique[arn] = t
        for arn, t in unique.items():
            name = t.get("Name", arn)
            # LOG-07 — log-file SSE-KMS
            if t.get("KmsKeyId"):
                self._add("PASS", "LOG-07", "LOGGING", name, f"Trail '{name}' encrypted with a KMS CMK")
            else:
                self._add("FAIL", "LOG-07", "LOGGING", name,
                          f"Trail '{name}' log files not encrypted with a KMS CMK "
                          f"(default SSE-S3 only)")
            # LOG-08 — data events
            try:
                es = ct.get_event_selectors(TrailName=arn)
                has_data = any(s.get("DataResources") for s in es.get("EventSelectors", [])) or any(
                    fs.get("Field") == "eventCategory" and "Data" in (fs.get("Equals") or [])
                    for aes in es.get("AdvancedEventSelectors", [])
                    for fs in aes.get("FieldSelectors", []))
                if has_data:
                    self._add("PASS", "LOG-08", "LOGGING", name,
                              f"Trail '{name}' records data-plane events")
                else:
                    self._add("FAIL", "LOG-08", "LOGGING", name,
                              f"Trail '{name}' logs management events only; no S3/Lambda/"
                              f"DynamoDB data-event visibility")
            except Exception as e:
                self._add("INFO", "LOG-08", "LOGGING", name, f"could not read event selectors: {e}")
            # LOG-09 — trail S3 bucket not public
            self._check_trail_bucket(t, name)

            # LOG-11 — log file validation (CIS Foundations v7.0.0 4.2). The flag is
            # already on the trail description; no additional call.
            r = aws_cis_foundations.trail_log_validation(t)
            if r.get("failed"):
                self._add("FAIL", "LOG-11", "LOGGING", name, r["statement"])
            else:
                self._add("PASS", "LOG-11", "LOGGING", name,
                          f"Trail '{name}' writes signed digest files")

            # LOG-12 — server access logging on the trail's OWN bucket (4.4). S3-05 asks
            # the same question of every bucket and only WARNs; this one fails, because
            # this is the bucket whose readers are worth recording.
            bkt = t.get("S3BucketName")
            try:
                lg = (self._client("s3").get_bucket_logging(Bucket=bkt)
                      if bkt else None)
            except Exception as e:
                lg = None
                if self._is_access_denied(e):
                    self._coverage.note_denied("LOG-12", "s3:GetBucketLogging")
            r = aws_cis_foundations.trail_bucket_access_logging(name, bkt, lg)
            if r.get("failed"):
                self._add("FAIL", "LOG-12", "LOGGING", str(bkt), r["statement"])
            elif r.get("unknown"):
                self._add("INFO", "LOG-12", "LOGGING", str(bkt or name),
                          f"NOT EVALUATED — {r['reason']}")
            else:
                self._add("PASS", "LOG-12", "LOGGING", str(bkt),
                          f"CloudTrail bucket {bkt} records server access logs")
            # LOG-10 — delivery health
            try:
                st = ct.get_trail_status(Name=arn)
                if st.get("IsLogging"):
                    err = st.get("LatestDeliveryError")
                    ldt = st.get("LatestDeliveryTime")
                    if err:
                        self._add("FAIL", "LOG-10", "LOGGING", name,
                                  f"Trail '{name}' log delivery FAILING: {err}")
                    elif ldt is None:
                        self._add("WARN", "LOG-10", "LOGGING", name,
                                  f"Trail '{name}' has no log delivery yet")
                    elif (datetime.now(timezone.utc) - ldt).total_seconds() > 24 * 3600:
                        self._add("WARN", "LOG-10", "LOGGING", name,
                                  f"Trail '{name}' last delivered "
                                  f"{(datetime.now(timezone.utc) - ldt).days}d ago (stale)")
                    else:
                        self._add("PASS", "LOG-10", "LOGGING", name,
                                  f"Trail '{name}' delivering logs healthily")
            except Exception as e:
                self._add("INFO", "LOG-10", "LOGGING", name, f"could not read trail status: {e}")

    @staticmethod
    def _is_access_denied(e) -> bool:
        code = ""
        if hasattr(e, "response"):
            code = (getattr(e, "response", {}) or {}).get("Error", {}).get("Code", "")
        return code in ("AccessDenied", "AccessDeniedException") or "AccessDenied" in str(e)

    def _db_parameters(self, client, group: str, *, service: str,
                       cluster: bool) -> List[Dict]:
        """Every parameter in a DB (cluster) parameter group, once per group per scan.

        Raises on a failed read rather than swallowing it — TLS enforcement is decided
        from this listing, and an empty list would read as "the parameter is absent",
        which the pure rule correctly reports as UNDECIDED but which would then be
        indistinguishable from a group that genuinely lacks it. The caller turns the
        exception into a `_read_failed` WARN, which says what actually happened.
        """
        key = (service, "cluster" if cluster else "instance", group)
        if key in self._param_cache:
            cached = self._param_cache[key]
            if cached is None:
                raise RuntimeError(
                    f"{service} parameter group {group} could not be read earlier in "
                    f"this scan")
            return cached
        op = ("describe_db_cluster_parameters" if cluster
              else "describe_db_parameters")
        kw = ({"DBClusterParameterGroupName": group} if cluster
              else {"DBParameterGroupName": group})
        params: List[Dict] = []
        try:
            for page in client.get_paginator(op).paginate(**kw):
                params.extend(page.get("Parameters", []) or [])
        except Exception:
            self._param_cache[key] = None
            raise
        self._param_cache[key] = params
        return params

    def _check_tls_enforced(self, client, *, check_id: str, section: str,
                            resource: str, engine: str, group: str,
                            service: str, cluster: bool, action: str) -> None:
        """One TLS-enforcement verdict, shared by RDS-14, AUR-06, DOCDB-06 and NEP-05.

        The four checks differ only in which client holds the parameter group and
        whether it is an instance or a cluster group; the decision itself is one pure
        function, so it is written once.
        """
        if not group:
            self._add("WARN", check_id, section, resource,
                      f"{check_id} NOT EVALUATED — {resource} names no parameter "
                      f"group, so TLS enforcement cannot be read")
            return
        try:
            params = self._db_parameters(client, group, service=service,
                                         cluster=cluster)
        except Exception as e:
            self._read_failed(check_id, section, resource, action, e)
            return
        r = aws_cis_db.tls_enforcement(engine, params, group)
        if not r["known"]:
            # Undecided is NOT a pass. Saying nothing here renders as "encrypted in
            # transit" in a report, which is the failure this whole check exists to end.
            self._add("WARN", check_id, section, resource,
                      f"{r['statement']} | {resource}")
        elif r["enforced"]:
            self._add("PASS", check_id, section, resource,
                      f"{r['statement']} | {resource}")
        else:
            self._add("FAIL", check_id, section, resource,
                      f"{r['statement']} | {resource}")

    def _read_failed(self, check_id: str, section: str, resource: str,
                     action: str, e) -> None:
        """A read we could not make is NOT a security finding. Report it as one.

        THE DEFECT THIS REPLACES. Ten checks answered a failed AWS call with
        ``_add("FAIL", <id>, ..., str(e))``, which is wrong twice over. First, a denied
        or throttled call rendered as a FAIL carrying that check's remediation — advice
        for a problem nobody observed, addressed to an operator whose actual problem is a
        missing grant. Second, and worse, for all ten that error path was the check's
        ONLY literal FAIL: `_add` reads severity, compliance and remediation from the
        catalogue for no other status, so a check declared HIGH could reach HIGH only by
        the call failing, while the misconfiguration it exists to find was a WARN forced
        to LOW with no remediation. The catalogue described the error handler.

        WARN, NOT INFO, AND NOT SILENCE. "We could not look" is not "nothing is wrong",
        and dropping it would be the phantom-pass this codebase has removed elsewhere
        (LOG-09's AccessDenied path, WINVULN-03's whole reason for existing). The
        coverage ledger records the denial so the finding can say which grant would
        answer the question."""
        if self._is_access_denied(e):
            self._coverage.note_denied(check_id, action)
        self._add("WARN", check_id, section, resource,
                  f"{check_id} NOT EVALUATED — {action} failed ({e}). "
                  f"Not assessed, not clean")

    @staticmethod
    def _error_code(e) -> str:
        """The AWS error code on an exception, or "" if it carries none.

        WHY NOT `except ClientError`. The name is bound only when boto3 imported (see
        the top of this module), so catching it by name raises NameError wherever boto3
        is absent — on the COMMON path, since ResourceNotFoundException is the ordinary
        answer for a function with no URL, a layer with no policy, and a Lambda with no
        resource policy. Reading the code off whatever was raised works either way."""
        resp = getattr(e, "response", None)
        if isinstance(resp, dict):
            return str((resp.get("Error") or {}).get("Code") or "")
        return ""

    def _check_trail_bucket(self, t: Dict, name: str) -> None:
        """LOG-09 — the CloudTrail log S3 bucket must not be public. AccessDenied =>
        INFO (org/centralized-logging bucket in another account), NEVER a false FAIL."""
        bucket = t.get("S3BucketName")
        if not bucket:
            self._add("INFO", "LOG-09", "LOGGING", name, f"Trail '{name}' has no S3 bucket configured")
            return
        s3 = self._client("s3")
        s3c = self._client("s3control")
        # Probe the BUCKET's own BPA FIRST. AccessDenied here => the bucket is owned by
        # another account (org/centralized logging) — the scanning account's own BPA
        # would NOT protect it, so we must not apply the account-level shortcut.
        bpa_full = False
        try:
            b_bpa = s3.get_public_access_block(Bucket=bucket).get(
                "PublicAccessBlockConfiguration", {})
            bpa_full = bool(b_bpa) and all(b_bpa.values())
        except Exception as e:
            if self._is_access_denied(e):
                self._add("INFO", "LOG-09", "LOGGING", name,
                          f"Trail bucket '{bucket}' owned by another account "
                          f"(centralized logging) — cannot verify from here")
                return
            # NoSuchPublicAccessBlockConfiguration => owned, no bucket BPA => check account BPA
        # bucket is readable (owned) — now the account-level BPA superset legitimately applies
        try:
            acct_bpa = s3c.get_public_access_block(AccountId=self.account).get(
                "PublicAccessBlockConfiguration", {})
            if acct_bpa and all(acct_bpa.values()):
                self._add("PASS", "LOG-09", "LOGGING", bucket,
                          f"Trail bucket '{bucket}' shielded by account-level BPA")
                return
        except Exception:
            pass
        # bucket policy — look for an unconditioned public grant
        public = False
        try:
            stmts = json.loads(s3.get_bucket_policy(Bucket=bucket)["Policy"]).get("Statement", [])
            if isinstance(stmts, dict):
                stmts = [stmts]
            for st in stmts:
                c = classify_resource_policy_stmt(st, self.account or "")
                if c and c["kind"] == "public":
                    public = True
        except Exception as e:
            if self._is_access_denied(e):
                self._add("INFO", "LOG-09", "LOGGING", name,
                          f"Trail bucket '{bucket}' owned by another account "
                          f"(centralized logging) — cannot verify from here")
                return
            if "NoSuchBucketPolicy" not in str(e) and "NoSuchBucket" in str(e):
                self._add("FAIL", "LOG-09", "LOGGING", bucket,
                          f"Trail bucket '{bucket}' does not exist — logs not being stored")
                return
            # NoSuchBucketPolicy => no policy => not public
        if public and not bpa_full:
            g = self._ensure_graph()
            barn = f"arn:aws:s3:::{bucket}".lower()
            g.add_node("internet", "InternetSource", cidr="0.0.0.0/0")
            g.add_node(barn, "S3Bucket", name=bucket)
            g.add_edge("internet", barn, "EXPOSED_TO", basis="cloudtrail-bucket-policy",
                       scan_source="cloudtrail")
            self._add("FAIL", "LOG-09", "LOGGING", bucket,
                      f"Trail log bucket '{bucket}' has a PUBLIC bucket policy — "
                      f"audit logs readable/tamperable")
        elif public:
            # RestrictPublicBuckets (full bucket BPA) neutralizes the public grant
            self._add("WARN", "LOG-09", "LOGGING", bucket,
                      f"Trail bucket '{bucket}' has a latent public policy statement but "
                      f"Block Public Access neutralizes it — remove the stale grant")
        elif bpa_full:
            self._add("PASS", "LOG-09", "LOGGING", bucket,
                      f"Trail bucket '{bucket}' has Block Public Access enabled")
        else:
            self._add("WARN", "LOG-09", "LOGGING", bucket,
                      f"Trail bucket '{bucket}' lacks full Block Public Access — "
                      f"verify it is not exposed")

    # GuardDuty protection plans expected enabled for full threat coverage
    _GD_FEATURES = {
        "S3_DATA_EVENTS":         "S3 Protection",
        "EKS_AUDIT_LOGS":         "EKS Audit Log Monitoring",
        "EBS_MALWARE_PROTECTION": "Malware Protection (EBS)",
        "RDS_LOGIN_EVENTS":       "RDS Protection",
        "LAMBDA_NETWORK_LOGS":    "Lambda Protection",
        "RUNTIME_MONITORING":     "Runtime Monitoring",
    }

    def _check_guardduty_features(self, did: str, detector: Dict) -> None:
        """LOG-06 — GuardDuty protection plans. An ENABLED detector still leaves
        S3/EKS/malware/RDS/Lambda/runtime coverage off unless each feature is
        explicitly enabled. Silent on the legacy API that omits the feature list."""
        feats = {f.get("Name"): f.get("Status") for f in detector.get("Features", [])}
        if not feats:
            return
        for name, label in self._GD_FEATURES.items():
            if name not in feats:
                continue
            if feats[name] == "ENABLED":
                self._add("PASS", "LOG-06", "LOGGING", f"{did}:{name}",
                          f"GuardDuty {label} ENABLED | {did}")
            else:
                self._add("FAIL", "LOG-06", "LOGGING", f"{did}:{name}",
                          f"GuardDuty {label} DISABLED — reduced threat coverage | {did}")

    # ══════════════════════════════════════════════════════════════════════════
    # SECTION: CLOUDWATCH ALARMS (CIS AWS Foundations Benchmark v7.0.0 §5)
    # ══════════════════════════════════════════════════════════════════════════
    # (check_id, CIS §, human name, required lowercased tokens a matching filter must
    #  contain). CW-02..CW-16 == CIS 5.1..5.15 (5.16 = Security Hub == LOG-05).
    #
    # THE SECTION NUMBER MOVED FROM 4 TO 5 in v7.0.0, which inserted the Introduction as
    # section 1. The numbers here are shown to operators in every message this section
    # emits, so leaving them at §4 would have had the product citing a control number
    # that no longer describes what it just reported.
    _CIS5_CONTROLS = [
        ("CW-02", "5.1",  "unauthorized API calls",          ["unauthorizedoperation", "accessdenied"]),
        ("CW-03", "5.2",  "console sign-in without MFA",      ["consolelogin", "mfaused"]),
        ("CW-04", "5.3",  "root account usage",              ["useridentity.type", "root"]),
        ("CW-05", "5.4",  "IAM policy changes",              ["deleterolepolicy", "putrolepolicy"]),
        ("CW-06", "5.5",  "CloudTrail configuration changes", ["createtrail", "deletetrail"]),
        ("CW-07", "5.6",  "console authentication failures",  ["consolelogin", "failedauthentication"]),
        ("CW-08", "5.7",  "CMK disable/scheduled deletion",   ["disablekey", "schedulekeydeletion"]),
        ("CW-09", "5.8",  "S3 bucket policy changes",         ["putbucketpolicy", "deletebucketpolicy"]),
        ("CW-10", "5.9",  "AWS Config changes",              ["stopconfigurationrecorder"]),
        # `modifysecuritygrouprules` is REQUIRED as of v7.0.0, and it is the one token
        # change in this table that alters a verdict. ModifySecurityGroupRules is the API
        # the console has used for rule edits since 2021, so a filter written to the older
        # two-token pattern is blind to the way most security-group changes are actually
        # made. An estate that passed 4.10 under v6.0.0 can legitimately fail 5.10 here,
        # and that is the finding rather than a false positive: their alarm does not fire.
        ("CW-11", "5.10", "security group changes",          ["authorizesecuritygroupingress", "revokesecuritygroupingress", "modifysecuritygrouprules"]),
        ("CW-12", "5.11", "network ACL changes",             ["createnetworkaclentry", "deletenetworkaclentry"]),
        ("CW-13", "5.12", "network gateway changes",         ["createinternetgateway", "deleteinternetgateway"]),
        ("CW-14", "5.13", "route table changes",             ["createroute", "deleteroutetable"]),
        ("CW-15", "5.14", "VPC changes",                     ["createvpc", "deletevpc"]),
        ("CW-16", "5.15", "organization changes",            ["organizations.amazonaws.com"]),
    ]

    @staticmethod
    def _norm_filter(s: str) -> str:
        """Normalize a metric-filter pattern for token matching: lowercase + strip all
        whitespace, quotes and parentheses (so '($.errorCode = "AccessDenied*")' and
        '$.errorCode="AccessDenied*"' compare equal)."""
        return re.sub(r'[\s"\'()]', "", s or "").lower()

    def _check_cloudwatch(self):
        self._section_header("CLOUDWATCH")
        self._log("CW-01..16: CloudWatch CIS v7.0.0 §5 metric-filter + alarm coverage")
        try:
            ct = self._client("cloudtrail")
            trails = ct.describe_trails(includeShadowTrails=True).get("trailList", [])
        except Exception as e:
            self._add("WARN", "CW-01", "CLOUDWATCH", "cloudtrail", str(e))
            return
        unique = {}
        for t in trails:
            arn = t.get("TrailARN") or t.get("Name")
            if arn and arn not in unique:
                unique[arn] = t
        # qualifying trails: multi-region + logging + wired to CloudWatch Logs
        log_groups = []                        # (region, logGroupName, account)
        for arn, t in unique.items():
            if not t.get("IsMultiRegionTrail") or not t.get("CloudWatchLogsLogGroupArn"):
                continue
            try:
                logging = ct.get_trail_status(Name=arn).get("IsLogging")
            except Exception:
                logging = None                 # GetTrailStatus denied — don't drop the trail
            if logging is False:
                continue                       # only skip when EXPLICITLY not logging
            parts = t["CloudWatchLogsLogGroupArn"].split(":")
            if len(parts) >= 7:
                log_groups.append((parts[3], parts[6], parts[4]))
        if not log_groups:
            self._add("FAIL", "CW-01", "CLOUDWATCH", "cloudwatch",
                      "No multi-region CloudTrail delivering to CloudWatch Logs — CIS §5 "
                      "metric-filter alarms cannot exist")
            return
        # collect the union of metric filters across owner-account log groups
        filters, owner_group_seen = [], False
        for region, lg_name, acct in log_groups:
            if acct and self.account and acct != self.account:
                continue                       # org-trail log group in another account
            owner_group_seen = True
            try:
                logs = self._client("logs", region=region)
                for page in logs.get_paginator("describe_metric_filters").paginate(
                        logGroupName=lg_name):
                    for mf in page.get("metricFilters", []):
                        pat = self._norm_filter(mf.get("filterPattern", ""))
                        for mt in mf.get("metricTransformations", []):
                            filters.append({"pat": pat, "metric": mt.get("metricName"),
                                            "ns": mt.get("metricNamespace"), "region": region})
            except Exception:
                pass
        if not owner_group_seen:
            self._add("INFO", "CW-01", "CLOUDWATCH", "cloudwatch",
                      "CloudTrail→CW-Logs monitoring is owned by the org/management account; "
                      "CIS §5 metric filters are evaluated in the resource-owner account")
            return
        self._add("PASS", "CW-01", "CLOUDWATCH", "cloudwatch",
                  f"CloudTrail→CloudWatch Logs present ({len(filters)} metric filters found)")
        for cid, cis, name, tokens in self._CIS5_CONTROLS:
            self._eval_cis4_control(cid, cis, name, tokens, filters)

    def _eval_cis4_control(self, cid, cis, name, tokens, filters) -> None:
        """3-state CIS §5 control: FAIL (no matching filter, or filter without an
        alarm/SNS action), WARN (alarm+SNS but no confirmed subscription), PASS
        (filter + alarm + ≥1 confirmed subscription)."""
        # Boundary-aware: a token must not be immediately followed by another
        # alphanumeric (so 'createroute' does NOT match inside 'createroutetable',
        # nor 'createvpc' inside 'createvpcpeeringconnection').
        def _has(pat, tok):
            return re.search(re.escape(tok) + r"(?![a-z0-9])", pat) is not None
        matched = [f for f in filters if all(_has(f["pat"], tok) for tok in tokens)]
        if not matched:
            self._add("FAIL", cid, "CLOUDWATCH", f"CIS-{cis}",
                      f"No CloudWatch metric filter for {name} (CIS {cis})")
            return
        best = 0                               # 0 no-alarm/action, 1 no-subs, 2 ok
        for f in matched:
            try:
                cw = self._client("cloudwatch", region=f["region"])
                alarms = cw.describe_alarms_for_metric(
                    Namespace=f["ns"], MetricName=f["metric"]).get("MetricAlarms", [])
            except Exception:
                alarms = []
            for al in alarms:
                if not al.get("ActionsEnabled", True):
                    continue
                sns_actions = [a for a in al.get("AlarmActions", []) if ":sns:" in a]
                if not sns_actions:
                    continue
                best = max(best, 1)
                for topic in sns_actions:
                    tparts = topic.split(":")
                    treg = tparts[3] if len(tparts) >= 4 else f["region"]
                    try:
                        sns = self._client("sns", region=treg)
                        confirmed = False
                        for page in sns.get_paginator("list_subscriptions_by_topic").paginate(
                                TopicArn=topic):
                            for sub in page.get("Subscriptions", []):
                                if (sub.get("SubscriptionArn") or "").startswith("arn:"):
                                    confirmed = True
                        if confirmed:
                            best = 2
                    except Exception:
                        pass
        if best == 2:
            self._add("PASS", cid, "CLOUDWATCH", f"CIS-{cis}",
                      f"Metric filter + alarm + confirmed subscription for {name} (CIS {cis})")
        elif best == 1:
            self._add("WARN", cid, "CLOUDWATCH", f"CIS-{cis}",
                      f"Alarm for {name} has no confirmed SNS subscription (CIS {cis})")
        else:
            self._add("FAIL", cid, "CLOUDWATCH", f"CIS-{cis}",
                      f"Metric filter for {name} has no alarm/SNS action (CIS {cis})")

    # ══════════════════════════════════════════════════════════════════════════
    # SECTION 5: ENCRYPTION & KMS
    # ══════════════════════════════════════════════════════════════════════════
    def _check_kms(self):
        self._section_header("KMS")
        self._log("ENC-03: Customer-managed KMS key rotation")
        kms   = self._client("kms")
        found = False
        try:
            paginator = kms.get_paginator("list_keys")
            for page in paginator.paginate():
                for key in page["Keys"]:
                    kid = key["KeyId"]
                    try:
                        meta = kms.describe_key(KeyId=kid)["KeyMetadata"]
                        self._crypto_material["kms"].append(meta)
                        # KMS-03 — CMK pending deletion / disabled (data-access risk)
                        if meta.get("KeyManager") == "CUSTOMER":
                            _st = meta.get("KeyState")
                            _dsc = meta.get("Description") or kid[:8]
                            if _st in ("PendingDeletion", "PendingReplicaDeletion"):
                                self._add("FAIL", "KMS-03", "KMS", kid,
                                          f"CMK scheduled for deletion "
                                          f"({meta.get('DeletionDate','')}) — irreversible "
                                          f"data loss if still in use | {_dsc}")
                            elif _st == "Disabled":
                                self._add("FAIL", "KMS-03", "KMS", kid,
                                          f"CMK is disabled — ciphertext under this key "
                                          f"cannot be decrypted | {_dsc}")
                            # KMS-02/04 — key-policy public / cross-account exposure
                            if _st not in ("PendingDeletion", "PendingReplicaDeletion"):
                                self._check_kms_key_policy(kms, kid, meta)
                        if (meta.get("KeyManager") == "CUSTOMER"
                                and meta.get("KeyState") == "Enabled"):
                            found    = True
                            rotation = kms.get_key_rotation_status(
                                KeyId=kid
                            ).get("KeyRotationEnabled", False)
                            desc = meta.get("Description") or kid[:8]
                            if rotation:
                                self._add("PASS", "ENC-03", "KMS", kid,
                                          f"Key rotation=ON | {desc}")
                            else:
                                self._add("FAIL", "ENC-03", "KMS", kid,
                                          f"Key rotation=OFF | {desc}")
                    except Exception:
                        pass
            if not found:
                self._add("WARN", "ENC-03", "KMS", "all-keys",
                          "No customer-managed KMS keys found")
        except Exception as e:
            self._read_failed("ENC-03", "KMS", "kms", "kms:ListKeys", e)

    def _check_kms_key_policy(self, kms, kid: str, meta: Dict) -> None:
        """KMS-02 (public) / KMS-04 (cross-account or org) key-policy exposure. Its own
        try/except so a GetKeyPolicy AccessDenied surfaces as WARN, not the KMS loop's
        silent `except: pass`."""
        try:
            pol_str = kms.get_key_policy(KeyId=kid, PolicyName="default").get("Policy")
            pol = json.loads(pol_str) if pol_str else {}
        except Exception as e:
            self._add("WARN", "KMS-02", "KMS", kid, f"could not evaluate key policy: {e}")
            return
        stmts = pol.get("Statement", [])
        if isinstance(stmts, dict):
            stmts = [stmts]
        node = (meta.get("Arn") or kid).lower()
        desc = meta.get("Description") or kid[:8]
        trusted = getattr(self, "trusted_accounts", set())
        public = public_cond = False
        cross_accts: set = set()
        org_id = None
        for st in stmts:
            c = classify_resource_policy_stmt(st, self.account or "")
            if not c:
                continue
            if c["kind"] == "public":
                public = True
            elif c["kind"] == "public_conditioned":
                public_cond = True
            elif c["kind"] == "org":
                org_id = c.get("org_id") or org_id
            elif c["kind"] == "cross_account":
                cross_accts.update(a for a in c["external_accounts"] if a not in trusted)
        g = self._ensure_graph()
        g.add_node(node, "KMSKey", key_id=kid, multi_region=meta.get("MultiRegion"),
                   scan_source="kms-policy")
        # KMS-02 (public)
        if public:
            g.add_node("principal:*", "AnyPrincipal")
            g.add_edge("principal:*", node, "PUBLIC_KMS", basis="key-policy",
                       scan_source="kms-policy")
            self._add("FAIL", "KMS-02", "KMS", kid,
                      f"KMS key policy grants PUBLIC access (wildcard principal, "
                      f"unconditioned) | {desc}")
        elif public_cond:
            self._add("WARN", "KMS-02", "KMS", kid,
                      f"KMS key policy wildcard principal gated only by an unrecognized "
                      f"condition — manual review | {desc}")
        else:
            self._add("PASS", "KMS-02", "KMS", kid,
                      f"KMS key policy has no public grant | {desc}")
        # KMS-04 (cross-account / org)
        if cross_accts:
            for acct in sorted(cross_accts):
                g.add_node("account:" + acct, "AWSAccount", account=acct, external=True,
                           scan_source="kms-policy")
                g.add_edge("account:" + acct, node, "SHARED_KMS", acct=acct,
                           basis="key-policy", scan_source="kms-policy")
            self._add("FAIL", "KMS-04", "KMS", kid,
                      f"KMS key policy grants CROSS-ACCOUNT access to "
                      f"{', '.join(sorted(cross_accts))} | {desc}")
        elif org_id:
            self._add("WARN", "KMS-04", "KMS", kid,
                      f"KMS key policy shares to AWS Organization {org_id} — verify it "
                      f"is your org | {desc}")
        else:
            self._add("PASS", "KMS-04", "KMS", kid,
                      f"KMS key policy has no cross-account grant | {desc}")

    # ══════════════════════════════════════════════════════════════════════════
    # SECTION 6: COMPUTE / EC2
    # ══════════════════════════════════════════════════════════════════════════
    def _scan_ec2_user_data(self, ec2, iid: str, name: str) -> None:
        """EC2-07 — secrets embedded in instance user-data. User-data is readable by
        anything that can reach IMDS on the host (and via the console/API), so an
        embedded credential is effectively plaintext-at-rest on every boot."""
        try:
            ud = ec2.describe_instance_attribute(
                InstanceId=iid, Attribute="userData"
            ).get("UserData", {}).get("Value")
        except Exception:
            return
        if not ud:
            return
        try:
            raw = base64.b64decode(ud)
        except Exception:
            return
        if raw[:2] == b"\x1f\x8b":                     # gzip (cloud-init) — best-effort inflate
            try:
                raw = gzip.decompress(raw)
            except Exception:
                pass
        for sec in aws_sidescan.scan_text_secrets(raw, source=f"userdata:{iid}"):
            self._add("FAIL", "EC2-07", "EC2", name,
                      f"Secret in user-data ({sec.kind}, preview {sec.match_preview}) "
                      f"— readable via IMDS/console | {iid}")

    def _check_ec2(self):
        self._section_header("EC2")
        # Slice 5.3 -- the platform layer beneath TLS, run first so the estate summary
        # heads the section rather than trailing the per-instance findings.
        self._check_platform_encryption()
        ec2 = self._client("ec2")

        # EC2-04 — IMDSv2 enforcement
        self._log("EC2-04: IMDSv2 enforcement on all instances")
        all_pass = True
        try:
            paginator = ec2.get_paginator("describe_instances")
            for page in paginator.paginate(
                Filters=[{
                    "Name":   "instance-state-name",
                    "Values": ["running", "stopped"],
                }]
            ):
                for res in page["Reservations"]:
                    for i in res["Instances"]:
                        iid    = i["InstanceId"]
                        name   = next(
                            (t["Value"] for t in i.get("Tags", [])
                             if t["Key"] == "Name"),
                            iid,
                        )
                        tokens = i.get("MetadataOptions", {}).get(
                            "HttpTokens", "optional"
                        )
                        if tokens != "required":
                            self._add("FAIL", "EC2-04", "EC2", name,
                                      f"IMDSv2 not enforced "
                                      f"(HttpTokens={tokens}) | {name}")
                            all_pass = False
                        # EC2-08 — SSRF->credential choke: public IP + reachable IMDSv1
                        # + an attached role to steal (all facts in hand; no extra API).
                        endpoint = i.get("MetadataOptions", {}).get("HttpEndpoint", "enabled")
                        has_role = bool(i.get("IamInstanceProfile"))
                        if (tokens != "required" and endpoint == "enabled"
                                and i.get("PublicIpAddress") and has_role):
                            self._add("FAIL", "EC2-08", "EC2", name,
                                      f"SSRF-to-credential exposure: public IP "
                                      f"{i['PublicIpAddress']} + IMDSv1 "
                                      f"(HttpTokens={tokens}) + attached IAM role — an SSRF "
                                      f"on this host can read its role credentials | {name}")
                        # EC2-07 — plaintext secret embedded in instance user-data
                        self._scan_ec2_user_data(ec2, iid, name)
            if all_pass:
                self._add("PASS", "EC2-04", "EC2", "all-instances",
                          "All EC2 instances enforce IMDSv2")
        except Exception as e:
            self._read_failed("EC2-04", "EC2", "ec2", "ec2:DescribeInstances", e)

        # EC2-06 — EBS volume encryption
        self._log("EC2-06: EBS volume encryption")
        try:
            volumes    = ec2.describe_volumes()["Volumes"]
            enc_count  = sum(1 for v in volumes if v.get("Encrypted", False))
            unenc_vols = [v for v in volumes if not v.get("Encrypted", False)]
            if enc_count:
                self._add("PASS", "EC2-06", "EC2", "ebs-volumes",
                          f"Encrypted volumes: {enc_count}")
            for v in unenc_vols:
                self._add("FAIL", "EC2-06", "EC2", v["VolumeId"],
                          f"UNENCRYPTED EBS volume: {v['VolumeId']} "
                          f"State={v['State']}")
        except Exception as e:
            self._read_failed("EC2-06", "EC2", "ebs", "ec2:DescribeVolumes", e)

        # EC2-05 — EC2 instances with public IPs
        self._log("EC2-05: EC2 instances with public IPs")
        try:
            paginator = ec2.get_paginator("describe_instances")
            for page in paginator.paginate(
                Filters=[{
                    "Name": "instance-state-name", "Values": ["running"]
                }]
            ):
                for res in page["Reservations"]:
                    for i in res["Instances"]:
                        if i.get("PublicIpAddress"):
                            name = next(
                                (t["Value"] for t in i.get("Tags", [])
                                 if t["Key"] == "Name"),
                                i["InstanceId"],
                            )
                            self._add("WARN", "EC2-05", "EC2", name,
                                      f"Public IP {i['PublicIpAddress']} on "
                                      f"{name} — verify if intentional")
        except Exception as e:
            self._read_failed("EC2-05", "EC2", "ec2", "ec2:DescribeInstances", e)

        # ── Phase 6 compute depth: SSM patch posture + launch-template/ASG IMDSv2
        # scale-out drift. Each sub-check is self-guarding; isolate so one failing does
        # not skip the others (findings emit under section="EC2").
        for _cid, _fn in (("SSM-01", self._check_ssm),
                          ("LT-01", self._check_launch_templates),
                          ("ASG-01", self._check_asg),
                          ("EC2-12", self._check_ec2_hygiene),
                          ("EC2-10", self._check_ec2_tag_policy)):
            try:
                _fn()
            except Exception as e:
                self._add("WARN", _cid, "EC2", "ec2",
                          f"compute-depth sub-check {_fn.__name__} failed: {e}")

        # EC2-09 — Unassociated Elastic IPs (cost/hygiene). A VPC EIP with an AllocationId but
        # no AssociationId/InstanceId/NetworkInterfaceId is allocated-but-unattached = billed.
        try:
            for addr in ec2.describe_addresses().get("Addresses", []):
                if not (addr.get("AssociationId") or addr.get("InstanceId")
                        or addr.get("NetworkInterfaceId")):
                    eip = addr.get("PublicIp") or addr.get("AllocationId") or "unknown"
                    self._add("WARN", "EC2-09", "EC2", eip,
                              f"Unassociated Elastic IP — allocated but unattached, incurring cost | {eip}")
        except Exception:
            pass                                     # fail-open (cost/hygiene, not security) — a
            # throttled/denied describe_addresses must NOT emit a finding or flip CM-8 to FAILED

    # ══════════════════════════════════════════════════════════════════════════
    # CIS AWS Compute Services Benchmark v2.0.0 — EC2 estate hygiene
    # ══════════════════════════════════════════════════════════════════════════
    def _check_ec2_hygiene(self):
        """EC2-12..EC2-18 (CIS-Compute 2.5, 2.6, 2.7, 2.10, 2.11, 2.12) + ASG-02 (2.14).

        EC2-18 (CIS Foundations v7.0.0 2.16 — an instance with no IAM instance profile)
        rides the same describe_instances page rather than making a seventh call, and is
        scoped to RUNNING instances: a stopped instance is making no API calls, so it is
        not currently reaching AWS with a static key and the finding would be noise.

        ONE describe_instances page covers five of the six. Age, monitoring state,
        default-group membership, stop time and block-device mappings all arrive on the
        same instance description, so batching them here costs one call rather than five
        — which is the difference between a benchmark being implementable and being an
        argument about scan cost."""
        ec2 = self._client("ec2")
        # Default security groups are per-VPC and identified by NAME, so the ids have to
        # be resolved before any instance can be judged against them.
        default_sgs: List[str] = []
        try:
            for sg in self._paginate_strict(
                    ec2, "describe_security_groups", "SecurityGroups",
                    Filters=[{"Name": "group-name", "Values": ["default"]}]):
                if sg.get("GroupId"):
                    default_sgs.append(str(sg["GroupId"]))
        except Exception as e:
            if self._is_access_denied(e):
                self._coverage.note_denied("EC2-14", "ec2:DescribeSecurityGroups")

        instances: List[Dict] = []
        try:
            for res in self._paginate_strict(
                    ec2, "describe_instances", "Reservations",
                    Filters=[{"Name": "instance-state-name",
                              "Values": ["running", "stopped"]}]):
                instances += res.get("Instances", [])
        except Exception as e:
            if self._is_access_denied(e):
                self._coverage.note_denied("EC2-12", "ec2:DescribeInstances")
            return

        now = self._today_dt()
        counts = {"EC2-12": 0, "EC2-13": 0, "EC2-14": 0, "EC2-16": 0, "EC2-17": 0,
                  "EC2-18": 0}
        running = [i for i in instances
                   if str((i.get("State") or {}).get("Name")) == "running"]
        for inst in instances:
            iid = str(inst.get("InstanceId") or "?")
            is_running = str((inst.get("State") or {}).get("Name")) == "running"
            if is_running:
                age = aws_cis_compute.instance_age(inst, now)
                if age["old"]:
                    counts["EC2-12"] += 1
                    self._add("FAIL", "EC2-12", "EC2", iid, f"{age['statement']} | {iid}")
                mon = aws_cis_compute.instance_monitoring(inst)
                if not mon["detailed"]:
                    counts["EC2-13"] += 1
                    self._add("FAIL", "EC2-13", "EC2", iid, f"{mon['statement']} | {iid}")
                # EC2-18 / CIS Foundations v7.0.0 2.16 — running instances only. A
                # stopped instance is making no API calls, so it is not currently
                # reaching AWS with a static key and the finding would be noise.
                role = aws_cis_foundations.instance_without_role(inst)
                if role.get("failed"):
                    counts["EC2-18"] += 1
                    self._add("FAIL", "EC2-18", "EC2", iid, role["statement"])
            sg = aws_cis_compute.instance_default_sg(inst, default_sgs)
            if sg["uses_default"]:
                counts["EC2-14"] += 1
                self._add("FAIL", "EC2-14", "EC2", iid, f"{sg['statement']} | {iid}")
            stopped = aws_cis_compute.instance_stopped_age(inst, now)
            if stopped["stale"]:
                counts["EC2-16"] += 1
                self._add("FAIL", "EC2-16", "EC2", iid, f"{stopped['statement']} | {iid}")
            dot = aws_cis_compute.instance_delete_on_termination(inst)
            if dot["persists"]:
                counts["EC2-17"] += 1
                self._add("FAIL", "EC2-17", "EC2", iid, f"{dot['statement']} | {iid}")

        if running and not counts["EC2-12"]:
            self._add("PASS", "EC2-12", "EC2", "ec2",
                      f"All {len(running)} running instance(s) are within the 180-day age "
                      f"limit")
        if running and not counts["EC2-13"]:
            self._add("PASS", "EC2-13", "EC2", "ec2",
                      f"All {len(running)} running instance(s) publish detailed monitoring")
        if instances and not counts["EC2-14"]:
            self._add("PASS", "EC2-14", "EC2", "ec2",
                      f"No instance is attached to a default security group")
        if instances and not counts["EC2-17"]:
            self._add("PASS", "EC2-17", "EC2", "ec2",
                      f"All attached volumes are deleted on instance termination")
        if running and not counts["EC2-18"]:
            self._add("PASS", "EC2-18", "EC2", "ec2",
                      f"All {len(running)} running instance(s) carry an IAM instance "
                      f"profile")

        # EC2-15 — detached ENIs. Its own call and its own guard: a denied
        # DescribeNetworkInterfaces must not discard the five findings above.
        try:
            enis = self._paginate_strict(ec2, "describe_network_interfaces",
                                         "NetworkInterfaces")
        except Exception as e:
            if self._is_access_denied(e):
                self._coverage.note_denied("EC2-15", "ec2:DescribeNetworkInterfaces")
            enis = None
        if enis is not None:
            idle = 0
            for eni in enis:
                r = aws_cis_compute.eni_unused(eni)
                if r["unused"]:
                    idle += 1
                    self._add("FAIL", "EC2-15", "EC2", r["eni_id"],
                              f"{r['statement']} | {r['eni_id']}")
            if enis and not idle:
                self._add("PASS", "EC2-15", "EC2", "ec2",
                          f"All {len(enis)} network interface(s) are attached")

        # ASG-02 — tag propagation. describe_auto_scaling_groups again rather than
        # threading state out of _check_asg: that method has its own failure handling and
        # coupling them would make either one's denial break the other.
        try:
            asgs = self._paginate_strict(self._client("autoscaling"),
                                         "describe_auto_scaling_groups", "AutoScalingGroups")
        except Exception as e:
            if self._is_access_denied(e):
                self._coverage.note_denied("ASG-02",
                                           "autoscaling:DescribeAutoScalingGroups")
            return
        bad = 0
        for asg in asgs:
            r = aws_cis_compute.asg_tag_propagation(asg)
            if r["bad"]:
                bad += 1
                self._add("FAIL", "ASG-02", "EC2", r["asg"], f"{r['statement']} | {r['asg']}")
        if asgs and not bad:
            self._add("PASS", "ASG-02", "EC2", "asg",
                      f"All {len(asgs)} Auto Scaling group(s) propagate their tags at launch")

    def _check_ec2_tag_policy(self):
        """EC2-10/EC2-11 (CIS-Compute 2.3, 2.4) — organisational tag policy.

        ORGANIZATIONS IS GLOBAL AND OFTEN DENIED. A standalone account has no
        organisation at all, and a member account is normally refused ListPolicies — only
        the management account can read them. Neither is a failure, and reporting one as
        a FAIL would put an unfixable finding in front of every member account in an org."""
        try:
            org = self._client("organizations", region="us-east-1")
            policies = self._paginate_strict(org, "list_policies", "Policies",
                                             Filter="TAG_POLICY")
        except Exception as e:
            if self._is_access_denied(e):
                self._coverage.note_denied("EC2-10", "organizations:ListPolicies")
                self._add("INFO", "EC2-10", "EC2", "organizations",
                          "Tag policies NOT EVALUATED — organizations:ListPolicies is "
                          "denied here, which is normal outside the management account")
            else:
                self._add("INFO", "EC2-10", "EC2", "organizations",
                          "Tag policies NOT EVALUATED — this account is not in an AWS "
                          "Organization")
            return

        r = aws_cis_compute.org_tag_policy(policies)
        if r["applicable"] and r["count"] == 0:
            self._add("FAIL", "EC2-10", "EC2", "organizations", r["statement"])
            # 2.4 asks whether a tag policy covers EC2. With no policy at all, 2.3 is the
            # finding and repeating it as 2.4 is one problem reported twice.
            return
        self._add("PASS", "EC2-10", "EC2", "organizations",
                  f"The organisation has {r['count']} tag policy/policies")

        docs = []
        for p in policies:
            try:
                content = (org.describe_policy(PolicyId=p.get("Id"))
                           .get("Policy", {}).get("Content"))
                docs.append(json.loads(content) if isinstance(content, str) else content)
            except Exception as e:
                if self._is_access_denied(e):
                    self._coverage.note_denied("EC2-11", "organizations:DescribePolicy")
        if not docs:
            self._add("INFO", "EC2-11", "EC2", "organizations",
                      "Tag policy contents could not be read, so EC2 coverage is unknown")
            return
        cov = aws_cis_compute.ec2_tag_policy(docs)
        if not cov["covers_ec2"]:
            self._add("FAIL", "EC2-11", "EC2", "organizations", cov["statement"])
        else:
            self._add("PASS", "EC2-11", "EC2", "organizations",
                      "A tag policy enforces tags for ec2 resource types")

    def _today_dt(self) -> datetime:
        """The clock, honouring the `_today` test seam so age-based checks are drivable.

        `self._today` is a date (the EOL checks set it); age arithmetic needs a datetime,
        and it must be tz-aware or subtracting an AWS timestamp raises."""
        if self._today is not None:
            return datetime(self._today.year, self._today.month, self._today.day,
                            tzinfo=timezone.utc)
        return datetime.now(timezone.utc)

    # ── Phase 6: helper reused by _check_launch_templates + _check_asg ────────────
    def _lt_http_tokens(self, ec2, lt_id: str, version) -> Optional[str]:
        """The HttpTokens value ('required'/'optional') of a launch-template version, or
        None if it could not be resolved. An ABSENT MetadataOptions block means IMDSv1
        ('optional') — the killer under-report if treated as unknown. `version` may be a
        number or the literals '$Default'/'$Latest' (describe_launch_template_versions
        accepts all three)."""
        resp = ec2.describe_launch_template_versions(
            LaunchTemplateId=lt_id, Versions=[str(version)])
        vers = resp.get("LaunchTemplateVersions", [])
        if not vers:
            return None
        md = (vers[0].get("LaunchTemplateData") or {}).get("MetadataOptions") or {}
        return md.get("HttpTokens", "optional")

    # ══════════════════════════════════════════════════════════════════════════
    # SECTION: AMAZON LINUX — CIS Amazon Linux 2 Benchmark v4.0.0, via SSM Inventory
    # ══════════════════════════════════════════════════════════════════════════
    def _al2_inventory(self, ssm, iid: str, type_name: str) -> Optional[List[Dict]]:
        """One instance's inventory of one type, or None if it could not be read.

        None and [] are DIFFERENT ANSWERS and the checks treat them differently: [] means
        the type was collected and is empty, None means nobody collected it. Conflating
        them would let a host nobody has inventoried report as having no prohibited
        packages."""
        try:
            out: List[Dict] = []
            token = None
            for _ in range(20):                      # bounded: inventory is not huge
                kw = {"InstanceId": iid, "TypeName": type_name, "MaxResults": 50}
                if token:
                    kw["NextToken"] = token
                resp = ssm.list_inventory_entries(**kw)
                out.extend(resp.get("Entries") or [])
                token = resp.get("NextToken")
                if not token:
                    break
            return out
        except Exception as e:
            if self._is_access_denied(e):
                self._coverage.note_denied("AL2-01", "ssm:ListInventoryEntries")
            return None

    def _check_amazonlinux(self):
        """AL2-01..03 — CIS Amazon Linux 2 Benchmark v4.0.0, the part that is reachable.

        THE BENCHMARK IS 287 RECOMMENDATIONS AND THIS SECTION DECIDES 44 OF THEM. The rest
        read file content, file modes and kernel state, which needs a filesystem the
        agentless side-scan cannot parse yet -- see engine/aws_cis_al2_map.py, which
        records every one of them and what would unblock it. Registering checks for those
        would put 250 registered-but-unreachable ids in the catalogue, which is the exact
        failure docs/CHECK_FIRING.md exists to measure.

        SSM INVENTORY IS THE ONLY READ-ONLY PATH TO IN-GUEST STATE. Reading a file would
        need ssm:SendCommand, which executes code on the host and is a write -- outside
        the read-only-of-CONFIG charter this product's role is built on."""
        self._section_header("AMAZONLINUX")
        try:
            ssm = self._client("ssm")
            ec2 = self._client("ec2")
        except Exception:
            return

        # Which running instances are Linux and SSM-managed. PlatformType is what SSM
        # reports; an instance it has never reached carries none, which is why the
        # unmanaged case is answered from the EC2 listing rather than from SSM's.
        try:
            running = {}
            for page in ec2.get_paginator("describe_instances").paginate(
                    Filters=[{"Name": "instance-state-name", "Values": ["running"]}]):
                for res in page.get("Reservations", []):
                    for i in res.get("Instances", []):
                        running[i["InstanceId"]] = i
        except Exception as e:
            self._add("INFO", "AL2-00", "AMAZONLINUX", "ec2",
                      f"NOT EVALUATED — the instance list could not be read ({e})")
            return
        if not running:
            self._add("INFO", "AL2-00", "AMAZONLINUX", "ec2",
                      "No running EC2 instances in this region")
            return

        managed: Dict[str, Dict] = {}
        try:
            for page in ssm.get_paginator("describe_instance_information").paginate():
                for info in page.get("InstanceInformationList", []) or []:
                    if info.get("ResourceType") == "EC2Instance":
                        managed[str(info.get("InstanceId"))] = info
        except Exception as e:
            if self._is_access_denied(e):
                self._coverage.note_denied("AL2-01",
                                           "ssm:DescribeInstanceInformation")
            self._add("INFO", "AL2-00", "AMAZONLINUX", "ssm",
                      f"NOT EVALUATED — SSM instance information could not be read "
                      f"({e}), so no host could be assessed against the Amazon Linux "
                      f"benchmark")
            return

        assessed = 0
        for iid in sorted(running):
            info = managed.get(iid) or {}
            platform = str(info.get("PlatformType") or "")
            # Windows hosts are WINVULN's business, not this benchmark's.
            if platform and platform.lower() != "linux":
                continue
            is_managed = bool(info) and info.get("PingStatus") == "Online"
            apps = (self._al2_inventory(ssm, iid, aws_cis_al2.APPLICATION_TYPE)
                    if is_managed else None)
            svcs = (self._al2_inventory(ssm, iid, aws_cis_al2.SERVICE_TYPE)
                    if is_managed else None)

            cov = aws_cis_al2.assessability(
                iid, ssm_managed=is_managed, platform=platform or None,
                app_entries=apps, svc_entries=svcs)
            self._add("INFO", "AL2-00", "AMAZONLINUX", iid, cov["statement"])
            if not cov["assessed"]:
                continue
            assessed += 1

            for hit in aws_cis_al2.prohibited_packages(iid, apps):
                self._add("FAIL", "AL2-01", "AMAZONLINUX", f"{iid}/{hit['package']}",
                          f"{hit['statement']} (CIS-AL2 {hit['recommendation']})")
            for hit in aws_cis_al2.missing_required_packages(iid, apps):
                self._add("FAIL", "AL2-02", "AMAZONLINUX", f"{iid}/{hit['package']}",
                          f"{hit['statement']} (CIS-AL2 {hit['recommendation']})")
            for hit in aws_cis_al2.prohibited_units(iid, svcs):
                self._add("FAIL", "AL2-03", "AMAZONLINUX", f"{iid}/{hit['unit']}",
                          f"{hit['statement']} (CIS-AL2 {hit['recommendation']})")

        if assessed and not [r for r in self.results
                             if r.check_id == "AL2-01" and r.status == "FAIL"]:
            self._add("PASS", "AL2-01", "AMAZONLINUX", "amazonlinux",
                      f"None of the {assessed} assessed host(s) carries a package the "
                      f"benchmark prohibits")

    def _check_ssm(self):
        """SSM-01 unmanaged running instances (patch blind spot) + SSM-02 patch compliance.
        Both inline-paginate in their OWN try/except (never _paginate_all); SSM read failure
        is WARN, never a false PASS; managed-but-unscanned is INFO (unknown), not compliant."""
        ec2 = self._client("ec2")
        ssm = self._client("ssm")

        # SSM-01 — running EC2 not covered by SSM
        self._log("SSM-01: running EC2 instances not managed by AWS Systems Manager")
        try:
            ec2_ids = set()
            for page in ec2.get_paginator("describe_instances").paginate(
                Filters=[{"Name": "instance-state-name", "Values": ["running"]}]):
                for res in page.get("Reservations", []):
                    for i in res.get("Instances", []):
                        ec2_ids.add(i["InstanceId"])
        except Exception as e:
            self._add("WARN", "SSM-01", "EC2", "ssm",
                      f"describe_instances failed (SSM coverage not evaluated): {e}")
            return
        if not ec2_ids:
            self._add("INFO", "SSM-01", "EC2", "ssm", "No running EC2 instances in this region")
            return
        try:
            managed = set()
            for page in ssm.get_paginator("describe_instance_information").paginate():
                for info in page.get("InstanceInformationList", []):
                    # only EC2 (not on-prem mi-* nodes) that are actually reachable
                    if (info.get("ResourceType") == "EC2Instance"
                            and info.get("PingStatus") == "Online"):
                        managed.add(info["InstanceId"])
        except Exception as e:
            self._add("WARN", "SSM-01", "EC2", "ssm",
                      f"SSM coverage UNDETERMINED (describe_instance_information failed): {e}")
            return
        unmanaged = ec2_ids - managed
        for iid in sorted(unmanaged):
            self._add("FAIL", "SSM-01", "EC2", iid,
                      f"Running EC2 not SSM-managed — cannot be patch-audited or centrally "
                      f"patched | {iid}")
        if not unmanaged:
            self._add("PASS", "SSM-01", "EC2", "ec2",
                      f"All {len(ec2_ids)} running instances are SSM-managed")

        # SSM-02 — missing critical/security patches on the managed instances
        self._log("SSM-02: SSM-managed instances missing critical/security patches")
        managed_ec2 = sorted(ec2_ids & managed)
        if not managed_ec2:
            return
        states, read_err = {}, False
        for i in range(0, len(managed_ec2), 50):        # InstanceIds capped at 50/call
            batch = managed_ec2[i:i + 50]
            token = None
            try:
                for _ in range(50):                     # bounded: page through NextToken
                    kwargs = {"InstanceIds": batch}
                    if token:
                        kwargs["NextToken"] = token
                    resp = ssm.describe_instance_patch_states(**kwargs)
                    for st in resp.get("InstancePatchStates", []):
                        states[st["InstanceId"]] = st
                    token = resp.get("NextToken")
                    if not token or not isinstance(token, str):
                        break
            except Exception as e:
                read_err = True
                self._add("WARN", "SSM-02", "EC2", "ssm",
                          f"patch-state read failed for a batch: {e}")
        bad, unknown = 0, 0
        for iid in managed_ec2:
            st = states.get(iid)
            if st is None:                              # never scanned / no baseline -> unknown
                unknown += 1
                self._add("INFO", "SSM-02", "EC2", iid,
                          f"No patch state (never scanned / no baseline) | {iid}")
                continue
            crit = st.get("CriticalNonCompliantCount", 0)
            sec = st.get("SecurityNonCompliantCount", 0)
            missing = st.get("MissingCount", 0)
            pending = st.get("InstalledPendingRebootCount", 0)
            if crit or sec:
                bad += 1
                self._add("FAIL", "SSM-02", "EC2", iid,
                          f"Non-compliant patches: {crit} critical, {sec} security | {iid}")
            elif missing:
                self._add("WARN", "SSM-02", "EC2", iid, f"{missing} missing patches | {iid}")
            elif pending:
                self._add("WARN", "SSM-02", "EC2", iid, f"Patched, awaiting reboot | {iid}")
        # AGGREGATE-PASS-MUST-COUNT: only all-clear when every managed instance was
        # actually evaluated compliant (no unknown, no read error).
        if managed_ec2 and bad == 0 and unknown == 0 and not read_err:
            self._add("PASS", "SSM-02", "EC2", "ec2",
                      f"All {len(managed_ec2)} managed instances patch-compliant")
        elif bad == 0 and (unknown or read_err):
            self._add("WARN", "SSM-02", "EC2", "ssm",
                      f"Patch compliance UNDETERMINED for {unknown} of {len(managed_ec2)} "
                      f"managed instances (unscanned / read denied)")

    def _check_launch_templates(self):
        """LT-01 — a launch template whose $Default version permits IMDSv1: every instance
        launched from it is SSRF-to-credential exploitable."""
        self._log("LT-01: launch-template default version permits IMDSv1")
        ec2 = self._client("ec2")
        try:
            templates = []
            for page in ec2.get_paginator("describe_launch_templates").paginate():
                templates.extend(page.get("LaunchTemplates", []))
        except Exception as e:
            self._add("WARN", "LT-01", "EC2", "launch-templates",
                      f"describe_launch_templates failed: {e}")
            return
        if not templates:
            self._add("INFO", "LT-01", "EC2", "launch-templates",
                      "No launch templates in this region")
            return
        resolved, bad, unresolved = 0, 0, 0
        for lt in templates:
            lt_id = lt.get("LaunchTemplateId")
            name = lt.get("LaunchTemplateName", lt_id)
            try:
                tokens = self._lt_http_tokens(ec2, lt_id, "$Default")
            except Exception:
                tokens = None
            if tokens is None:
                unresolved += 1
                self._add("WARN", "LT-01", "EC2", name,
                          f"Could not resolve $Default version IMDS config | {name}")
                continue
            resolved += 1
            if tokens != "required":
                bad += 1
                self._add("FAIL", "LT-01", "EC2", name,
                          f"Launch template $Default permits IMDSv1 (HttpTokens={tokens}) — "
                          f"instances launched from it are SSRF-to-credential exploitable | {name}")
        if templates and bad == 0 and unresolved == 0:
            self._add("PASS", "LT-01", "EC2", "launch-templates",
                      f"All {resolved} launch templates require IMDSv2")

    def _check_asg(self):
        """ASG-01 — an Auto Scaling group whose effective launch spec permits IMDSv1
        re-creates IMDSv1 instances on scale-out, silently undoing per-instance remediation."""
        self._log("ASG-01: Auto Scaling group re-spawns IMDSv1 instances")
        asg = self._client("autoscaling")
        ec2 = self._client("ec2")
        try:
            groups = []
            for page in asg.get_paginator("describe_auto_scaling_groups").paginate():
                groups.extend(page.get("AutoScalingGroups", []))
        except Exception as e:
            self._add("WARN", "ASG-01", "EC2", "asg",
                      f"describe_auto_scaling_groups failed: {e}")
            return
        if not groups:
            self._add("INFO", "ASG-01", "EC2", "asg", "No Auto Scaling groups in this region")
            return
        bad, unresolved = 0, 0
        for g in groups:
            gname = g.get("AutoScalingGroupName", "unknown")
            tokens = None
            try:
                lt_spec = None
                if g.get("LaunchTemplate"):                       # direct launch template
                    lt_spec = g["LaunchTemplate"]
                elif g.get("MixedInstancesPolicy"):               # mixed-instances policy
                    lt_spec = ((g["MixedInstancesPolicy"].get("LaunchTemplate") or {})
                               .get("LaunchTemplateSpecification"))
                if lt_spec and lt_spec.get("LaunchTemplateId"):
                    tokens = self._lt_http_tokens(
                        ec2, lt_spec["LaunchTemplateId"], lt_spec.get("Version") or "$Default")
                elif g.get("LaunchConfigurationName"):            # legacy launch config
                    lc = asg.describe_launch_configurations(
                        LaunchConfigurationNames=[g["LaunchConfigurationName"]]
                    ).get("LaunchConfigurations", [])
                    if lc:
                        # launch configs predate IMDSv2 default: absent MetadataOptions = IMDSv1
                        tokens = (lc[0].get("MetadataOptions") or {}).get("HttpTokens", "optional")
            except Exception:
                tokens = None
            if tokens is None:
                unresolved += 1
                self._add("WARN", "ASG-01", "EC2", gname,
                          f"Could not resolve launch-spec IMDS config | {gname}")
                continue
            if tokens != "required":
                bad += 1
                self._add("FAIL", "ASG-01", "EC2", gname,
                          f"ASG scale-out re-creates IMDSv1 instances (HttpTokens={tokens}) — "
                          f"silently undoes per-instance remediation | {gname}")
        if groups and bad == 0 and unresolved == 0:
            self._add("PASS", "ASG-01", "EC2", "asg",
                      f"All {len(groups)} Auto Scaling groups enforce IMDSv2 on scale-out")

    # ══════════════════════════════════════════════════════════════════════════
    # SECTION 7: CONTAINER SECURITY (ECR)
    # ══════════════════════════════════════════════════════════════════════════
    # ══════════════════════════════════════════════════════════════════════════
    # SECTION 7b: MACHINE IMAGES (AMI)
    # ══════════════════════════════════════════════════════════════════════════
    def _check_ami(self):
        self._section_header("AMI")
        self._log("AMI-01: self-owned AMIs shared publicly or cross-account "
                  "(a public AMI exposes its full root-volume snapshot to every AWS account)")
        try:
            ec2    = self._client("ec2")
            images = ec2.describe_images(Owners=["self"]).get("Images", [])
        except Exception as e:
            self._add("WARN", "AMI-01", "AMI", "ami", str(e))
            return
        if not images:
            self._add("INFO", "AMI-01", "AMI", "ami", "No self-owned AMIs in this region")
            # AMI-05 asks about the images running INSTANCES were launched from, and a
            # third-party AMI is by definition not self-owned — so returning here would
            # make the check unreachable in exactly the estate it is about.
            self._check_ami_provenance()
            return
        exposed = 0
        for img in images:
            aid  = img.get("ImageId", "ami-?")
            name = img.get("Name") or aid
            label = f"{name} ({aid})" if name != aid else aid
            if img.get("Public") is True:
                exposed += 1
                self._add("FAIL", "AMI-01", "AMI", label,
                          f"AMI shared PUBLICLY — root-volume snapshot readable by any AWS "
                          f"account | {aid}")
                continue
            # non-public: enumerate explicit cross-account launch shares
            try:
                perms = ec2.describe_image_attribute(
                    ImageId=aid, Attribute="launchPermission"
                ).get("LaunchPermissions", [])
            except Exception:
                perms = []
            accounts = [p.get("UserId") for p in perms if p.get("UserId")]
            # AMIs can also be shared to an entire AWS Organization / OU (GA feature) —
            # readable by every account in it, so treat those as cross-account shares too.
            orgs = [p.get("OrganizationArn") or p.get("OrganizationalUnitArn")
                    for p in perms if p.get("OrganizationArn") or p.get("OrganizationalUnitArn")]
            group_all = any(p.get("Group") == "all" for p in perms)
            if group_all:
                exposed += 1
                self._add("FAIL", "AMI-01", "AMI", label,
                          f"AMI launch permission grants Group=all (public) | {aid}")
            elif accounts or orgs:
                exposed += 1
                shared = accounts + orgs
                self._add("WARN", "AMI-01", "AMI", label,
                          f"AMI shared with {len(shared)} external principal(s): "
                          f"{', '.join(shared[:5])}{'…' if len(shared) > 5 else ''} | {aid}")
        if exposed == 0:
            self._add("PASS", "AMI-01", "AMI", "ami",
                      f"All {len(images)} self-owned AMI(s) are private (no public/cross-account share)")

        # AMI-02/03 — image supply-chain depth (reuses the same describe_images result, 0 new API)
        now = datetime.now(timezone.utc)
        enc_ok = True
        for img in images:
            aid  = img.get("ImageId", "ami-?")
            name = img.get("Name") or aid
            label = f"{name} ({aid})" if name != aid else aid
            # AMI-02 — unencrypted backing snapshot (Encrypted absent == unencrypted)
            unenc = [m for m in img.get("BlockDeviceMappings", [])
                     if m.get("Ebs") and m["Ebs"].get("Encrypted") is not True]
            if unenc:
                enc_ok = False
                self._add("FAIL", "AMI-02", "AMI", label,
                          f"AMI backed by {len(unenc)} unencrypted snapshot(s) — plaintext disk "
                          f"at rest (full plaintext volume if the AMI is ever shared) | {aid}")
            # AMI-03 — past its deprecation date (FAIL) or very old (WARN)
            try:
                dep = img.get("DeprecationTime")
                created = img.get("CreationDate")
                if dep and datetime.fromisoformat(dep.replace("Z", "+00:00")) < now:
                    self._add("FAIL", "AMI-03", "AMI", label,
                              f"AMI past its deprecation date ({dep[:10]}) — launches start on an "
                              f"unsupported/unpatched base | {aid}")
                elif created:
                    age = (now - datetime.fromisoformat(created.replace("Z", "+00:00"))).days
                    if age > 730:
                        self._add("WARN", "AMI-03", "AMI", label,
                                  f"AMI ~{age} days old — baked base OS likely unpatched | {aid}")
            except Exception:
                self._add("INFO", "AMI-03", "AMI", label,
                          f"Could not parse AMI timestamps | {aid}")
        if images and enc_ok:
            self._add("PASS", "AMI-02", "AMI", "ami",
                      f"All {len(images)} self-owned AMI(s) use encrypted snapshots")

        # AMI-04 — naming convention (CIS-Compute 2.1.1). Same describe_images result,
        # no new call. Reports NOT EVALUATED rather than PASS when no convention is
        # configured: "we did not check" and "it complies" are different claims.
        if not self.ami_name_pattern:
            self._add("INFO", "AMI-04", "AMI", "ami",
                      "AMI naming convention NOT EVALUATED — set ami_name_pattern (or "
                      "OVERWATCH_AMI_NAME_PATTERN) to the organisation's convention")
        else:
            offenders = 0
            for img in images:
                r = aws_cis_compute.ami_naming(img, self.ami_name_pattern)
                if r["evaluated"] and not r["matches"]:
                    offenders += 1
                    self._add("FAIL", "AMI-04", "AMI",
                              f"{r['name'] or r['image_id']}",
                              f"{r['statement']} | {r['image_id']}")
            if images and not offenders:
                self._add("PASS", "AMI-04", "AMI", "ami",
                          f"All {len(images)} self-owned AMI(s) match the configured "
                          f"naming convention")

        # AMI-05 — provenance of the images instances are actually RUNNING (CIS-Compute
        # 2.1.3). Deliberately not driven off the self-owned list above: a third-party
        # AMI is by definition not self-owned, so an audit that only looks at images you
        # own is blind to exactly the case this asks about.
        self._check_ami_provenance()

    def _check_ami_provenance(self):
        """AMI-05 — running instances launched from AMIs nobody in this estate published.

        Own try/except so a denied describe_instances cannot take AMI-01/02/03/04 down
        with it: those have already emitted by the time this runs."""
        try:
            ec2 = self._client("ec2")
            instances: List[Dict] = []
            for res in self._paginate_strict(
                    ec2, "describe_instances", "Reservations",
                    Filters=[{"Name": "instance-state-name", "Values": ["running"]}]):
                instances += res.get("Instances", [])
        except Exception as e:
            if self._is_access_denied(e):
                self._coverage.note_denied("AMI-05", "ec2:DescribeInstances")
            return
        wanted = sorted({str(i.get("ImageId")) for i in instances if i.get("ImageId")})
        if not wanted:
            self._add("INFO", "AMI-05", "AMI", "ami",
                      "No running instances to check AMI provenance for")
            return
        try:
            # ONE describe_images for every distinct image, not one per instance: a large
            # ASG can run hundreds of instances off a single AMI.
            found = {str(im.get("ImageId")): im for im in
                     ec2.describe_images(ImageIds=wanted).get("Images", [])}
        except Exception as e:
            if self._is_access_denied(e):
                self._coverage.note_denied("AMI-05", "ec2:DescribeImages")
            return
        untrusted = 0
        for inst in instances:
            r = aws_cis_compute.ami_provenance(
                inst, found.get(str(inst.get("ImageId"))), self.account,
                self.trusted_accounts)
            if r["untrusted"]:
                untrusted += 1
                self._add("FAIL", "AMI-05", "AMI", r["instance_id"],
                          f"{r['statement']} | {r['instance_id']}")
        if not untrusted:
            self._add("PASS", "AMI-05", "AMI", "ami",
                      f"All {len(instances)} running instance(s) launched from AMIs owned "
                      f"by this account, Amazon, or a trusted account")

    def _check_ecr(self):
        self._section_header("ECR")
        self._log("CNT-01: ECR scan-on-push and encryption")
        try:
            ecr   = self._client("ecr")
            self._record_ecr_scan_mode(ecr)             # Tier-A: registry scan mode
            repos = ecr.describe_repositories()["repositories"]
            self._ecr_budget = self.ecr_scan_max_total  # Tier-A aggregate image budget (this region)
            if not repos:
                self._add("WARN", "CNT-01", "ECR", "ecr",
                          "No ECR repositories found")
            # do NOT return on empty repos — the registry-level CNT-06 (below) is
            # repo-independent and must still run. The loop is simply skipped when empty.
            for repo in repos:
                rname = repo["repositoryName"]
                scan  = repo.get("imageScanningConfiguration", {}).get(
                    "scanOnPush", False
                )
                enc   = repo.get("encryptionConfiguration", {}).get(
                    "encryptionType", "AES256"
                )
                if scan:
                    self._add("PASS", "CNT-01", "ECR", rname,
                              f"Scan-on-push=ON enc={enc} | {rname}")
                else:
                    self._add("FAIL", "CNT-01", "ECR", rname,
                              f"Scan-on-push=OFF enc={enc} | {rname}")
                # CNT-04 — image tag immutability (already in the describe_repositories response)
                mut = repo.get("imageTagMutability")
                if mut == "IMMUTABLE":
                    self._add("PASS", "CNT-04", "ECR", rname,
                              f"Tag immutability=IMMUTABLE | {rname}")
                elif mut:
                    self._add("FAIL", "CNT-04", "ECR", rname,
                              f"Tag mutability={mut} — tags overwritable "
                              f"(supply-chain poisoning) | {rname}")
                self._check_ecr_repo_policy(ecr, repo)      # CNT-03
                self._check_ecr_lifecycle(ecr, repo)        # CNT-05
                self._ingest_ecr_scan(ecr, repo)            # CNT-02 Tier-A (native, always-on)
                try:
                    self._scan_registry_images(ecr, repo)   # Tier-B (opt-in layer-pull)
                except Exception as e:                      # one repo's pull never aborts the sweep
                    self._add("INFO", "CWPP-04", "ECR", rname,
                              f"registry image side-scan failed for {rname}: {e}")
        except Exception as e:
            self._add("WARN", "CNT-01", "ECR", "ecr", str(e))

        # CNT-06 — registry-level image signing (run ONCE, in its OWN try/except so a
        # brand-new-API error never masquerades as a CNT-01 WARN). getattr availability
        # guard: an older botocore lacking the op is skipped silently, not flagged.
        try:
            ecr = self._client("ecr")
            fn = getattr(ecr, "get_signing_configuration", None)
            if fn is not None:
                rules = (fn().get("signingConfiguration") or {}).get("rules") or []
                if rules:
                    prof = rules[0].get("signingProfileArn", "")
                    self._add("PASS", "CNT-06", "ECR", "registry",
                              f"ECR image signing configured ({len(rules)} rule(s)) {prof}")
                else:
                    self._add("FAIL", "CNT-06", "ECR", "registry",
                              "ECR registry has no image-signing configuration — images are "
                              "unsigned (no cryptographic provenance / supply-chain integrity)")
        except AttributeError:
            pass                                            # SDK lacks the op -> skip
        except Exception as e:
            if "denied" in str(e).lower() or "throttl" in str(e).lower():
                self._add("WARN", "CNT-06", "ECR", "registry",
                          f"cannot read ECR signing configuration: {e}")
            # any other error (UnknownOperation on an old region/SDK) -> skip silently

    def _check_ecr_repo_policy(self, ecr, repo: Dict) -> None:
        """CNT-03 — ECR repository policy public/cross-account exposure (mirrors SEC-05
        via the shared classifier). No policy attached => not a finding (silent)."""
        rname = repo["repositoryName"]
        try:
            pol = ecr.get_repository_policy(repositoryName=rname).get("policyText")
        except Exception:
            return                              # RepositoryPolicyNotFoundException / AccessDenied
        if not pol:
            return
        try:
            stmts = json.loads(pol).get("Statement", [])
        except Exception:
            return
        if isinstance(stmts, dict):
            stmts = [stmts]
        trusted = getattr(self, "trusted_accounts", set())
        public = public_cond = False
        cross: set = set()
        org_id = None
        for st in stmts:
            c = classify_resource_policy_stmt(st, self.account or "")
            if not c:
                continue
            if c["kind"] == "public":
                public = True
            elif c["kind"] == "public_conditioned":
                public_cond = True
            elif c["kind"] == "org":
                org_id = c.get("org_id") or org_id
            elif c["kind"] == "cross_account":
                cross.update(a for a in c["external_accounts"] if a not in trusted)
        if not (public or public_cond or cross or org_id):
            return
        g = self._ensure_graph()
        rarn = repo.get("repositoryArn", rname)
        g.add_node(rarn, "ECRRepository", name=rname, uri=repo.get("repositoryUri", rname),
                   scan_source="ecr")
        if public:
            g.add_node("internet", "InternetSource", cidr="0.0.0.0/0")
            g.add_edge("internet", rarn, "SHARED_IMAGE", public=True, scan_source="ecr")
            self._add("FAIL", "CNT-03", "ECR", rname,
                      f"ECR repository policy grants PUBLIC pull/push access | {rname}")
        elif cross:
            for acct in sorted(cross):
                g.add_node("account:" + acct, "AWSAccount", account=acct, external=True)
                g.add_edge("account:" + acct, rarn, "SHARED_IMAGE", external_account=acct,
                           scan_source="ecr")
            self._add("FAIL", "CNT-03", "ECR", rname,
                      f"ECR repository policy grants CROSS-ACCOUNT access to "
                      f"{', '.join(sorted(cross))} | {rname}")
        elif public_cond:
            self._add("WARN", "CNT-03", "ECR", rname,
                      f"ECR repository policy wildcard principal is condition-guarded — "
                      f"verify | {rname}")
        elif org_id:
            self._add("WARN", "CNT-03", "ECR", rname,
                      f"ECR repository shared to AWS Organization {org_id} — verify | {rname}")

    def _check_ecr_lifecycle(self, ecr, repo: Dict) -> None:
        """CNT-05 — a lifecycle policy prevents untagged/old images (cost + stale-vuln
        surface) accumulating. Absent => WARN."""
        rname = repo["repositoryName"]
        try:
            ecr.get_lifecycle_policy(repositoryName=rname)
            self._add("PASS", "CNT-05", "ECR", rname, f"Lifecycle policy configured | {rname}")
        except Exception as e:
            if "LifecyclePolicyNotFound" in str(e) or "NotFound" in str(e):
                self._add("WARN", "CNT-05", "ECR", rname,
                          f"No lifecycle policy — untagged/old images accumulate | {rname}")

    def _record_ecr_scan_mode(self, ecr) -> None:
        """Best-effort: record the registry-wide scanning mode. ENHANCED (Inspector)
        already yields application-package CVEs natively; BASIC (Clair) is OS-package
        only, so the opt-in Tier-B layer-pull adds the most value on BASIC registries.
        Stored for the API/console + to hint Tier-B worth — never a finding here."""
        try:
            fn = getattr(ecr, "get_registry_scanning_configuration", None)
            if fn is None:
                return
            cfg = fn().get("scanningConfiguration") or {}
            self._ecr_scan_mode = ((cfg.get("scanType") or "").upper() or None)
        except Exception:
            self._ecr_scan_mode = None          # denied/old-SDK -> unknown, no finding

    def _ingest_ecr_scan(self, ecr, repo: Dict) -> None:
        """CNT-02 (Tier A) — pull the ECR *native* image-scan findings for the newest-N
        *tagged* images in a repo (bounded by self.ecr_scan_max_images) and project
        HIGH/CRITICAL CVEs into the graph as ECRImage --HAS_VULN-->. Free basic-scan
        signal that surfaces even when Amazon Inspector (enhanced scanning) is off.
        Untagged images are skipped (usually orphaned build artifacts). Best-effort."""
        rname = repo["repositoryName"]
        ruri  = repo.get("repositoryUri", rname)
        try:
            imgs: List[Dict] = []
            for page in ecr.get_paginator("describe_images").paginate(
                repositoryName=rname, filter={"tagStatus": "TAGGED"}
            ):
                imgs.extend(page.get("imageDetails", []))
        except Exception:
            return
        # imagePushedAt is a tz-aware datetime in real boto3 (and optional). Use a
        # comparable epoch sentinel so a missing field can't raise TypeError.
        _epoch = datetime(1970, 1, 1, tzinfo=timezone.utc)
        tagged = [d for d in imgs if d.get("imageTags") and d.get("imageDigest")]
        tagged.sort(key=lambda d: d.get("imagePushedAt") or _epoch, reverse=True)
        # per-repo clamp (defense in depth beyond argparse) AND a per-scan aggregate budget so
        # a large estate (many repos x newest-N) can't multiply describe_image_scan_findings
        # into a throttle/wall-time blow-up.
        per_repo = max(1, min(self.ecr_scan_max_images, 100))
        budget = getattr(self, "_ecr_budget", None)
        for img in tagged[:per_repo]:
            if budget is not None:
                if self._ecr_budget <= 0:
                    break
                self._ecr_budget -= 1
            self._ingest_ecr_image_findings(ecr, rname, ruri, img)

    def _ingest_ecr_image_findings(self, ecr, rname: str, ruri: str, img: Dict) -> None:
        """Emit CNT-02 ECRImage --HAS_VULN--> CVE edges for ONE image's native ECR scan
        findings (basic `findings[]` or enhanced `enhancedFindings[]`). Shared by the
        Tier-A sweep. The ECRImage node id (`{ruri}@{digest}`) converges with the
        Inspector / RUNS_IMAGE / Tier-B side-scan lanes via `ecr_image_node_ids`."""
        digest = img.get("imageDigest")
        if not digest:
            return
        try:
            resp = ecr.describe_image_scan_findings(
                repositoryName=rname, imageId={"imageDigest": digest}
            )
        except Exception:
            return   # ScanNotFoundException / not scanned yet — CNT-01 already flags this
        sf = resp.get("imageScanFindings", {}) or {}
        # normalise basic-scan (findings) and enhanced-scan (enhancedFindings) shapes
        norm: List[tuple] = []
        for f in sf.get("findings", []):
            norm.append((f.get("name", ""), (f.get("severity") or "").upper()))
        for ef in sf.get("enhancedFindings", []):
            cve = (ef.get("packageVulnerabilityDetails", {}) or {}).get("vulnerabilityId", "")
            norm.append((cve, (ef.get("severity") or "").upper()))
        cves = [(c, sev) for c, sev in norm if c and sev in ("CRITICAL", "HIGH")]
        if not cves:
            return
        g = self._ensure_graph()
        node = f"{ruri}@{digest}"
        g.add_node(node, "ECRImage", repository=rname, digest=digest, image_uri=ruri)
        tags = img.get("imageTags") or []
        tag_s = f":{tags[0]}" if tags else ""
        for cve, sev in cves[:100]:
            # NB: prop key must NOT be "source"/"target"/"id"/"kind" — those collide
            # with the node-link endpoint keys in SecurityGraph.to_dict().
            g.add_node(cve, "Vulnerability", severity=sev, scan_source="ecr-native-scan")
            g.add_edge(node, cve, "HAS_VULN", cve=cve, severity=sev, scan_source="ecr-native-scan")
            self._add("FAIL", "CNT-02", "ECR", f"{rname}{tag_s}",
                      f"container-image {sev} {cve} in {rname}{tag_s} "
                      f"(ECR native scan) | {rname}@{digest[:19]}")

    def _scan_registry_images(self, ecr, repo: Dict) -> None:
        """Tier B (OPT-IN, two-key: --side-scan-images + the CnappImageLayerPull IAM grant)
        — pull the newest-N *tagged* images' layers, run OverWatch's own SBOM->OSV side-scan
        (Inspector-independent), and emit ECRImage --HAS_VULN--> edges (scan_source=
        'ecr-sidescan') that MERGE-converge with the Tier-A native-scan / Inspector /
        RUNS_IMAGE lanes on the SAME node id. A registry-only image (no inbound RUNS_IMAGE
        from a reachable workload) carries HAS_VULN but never enters E_PATH, so it ranks
        shift-left and aws_correlate.py stays byte-frozen. Fully best-effort / fail-open;
        the default (no-flag) path never runs it (the guard below returns immediately)."""
        if not self.side_scan_images:
            return
        from engine import aws_registry_sbom
        from engine import aws_layer_fetch
        rname = repo["repositoryName"]
        ruri  = repo.get("repositoryUri", rname)
        bundle = self._load_vuln_db()
        feed = bundle[0] if bundle else None
        epss = bundle[1] if bundle else {}
        kev  = bundle[2] if bundle else set()
        exploits = bundle[3] if bundle else set()
        http_get = self._layer_get or aws_layer_fetch.http_get
        cap = self.ecr_image_max_bytes
        # one-time INFO when CVE matching will be skipped (no --vuln-db) — mirrors the host
        # side-scan so a side-scan-images run without a feed isn't a silent "all clean".
        if feed is None and self.vuln_db_path is None and not getattr(self, "_registry_vulndb_warned", False):
            self._registry_vulndb_warned = True
            self._add("INFO", "CWPP-04", "ECR", "registry",
                      "no --vuln-db supplied; registry image inventory + secrets only, CVE match skipped")
        sel_notes: List[str] = []                       # select-level notes (emitted ONCE, below)
        images = aws_registry_sbom.select_registry_images(
            ecr, rname, newest_n=self.side_scan_images_max, max_image_bytes=cap, notes=sel_notes)
        g = self._ensure_graph()
        for img in images:
            # per-image notes are diagnostic and carried in r.note — pass a throwaway list so a
            # failure reason is surfaced exactly ONCE (the skip INFO), never double-emitted.
            r = aws_registry_sbom.scan_registry_image(
                ecr, rname, ruri, img, http_get=http_get, feed=feed, epss=epss, kev=kev,
                exploits=exploits, max_image_bytes=cap,
                do_secrets=self.side_scan_secrets, notes=[])
            if not r.ok or r.result is None:
                self._add("INFO", "CWPP-04", "ECR", rname,
                          f"registry image side-scan skipped for {rname}@{r.digest[:19]}: {r.note}")
                continue
            tag_s = f":{r.tags[0]}" if r.tags else ""
            # only CRITICAL/HIGH (or KEV) CVEs become graph edges + findings — matches the
            # Tier-A native-scan filter, so severity is honest (not fixed by the check id).
            sev_vulns = [m for m in r.result.vulns
                         if m.kev or (m.severity or "").upper() in ("CRITICAL", "HIGH")]
            aws_sidescan.emit_node_vuln_edges(
                g, r.node_id, "ECRImage", sev_vulns, snapshot_id=(r.doc_id or ""),
                scan_source="ecr-sidescan", repository=rname, digest=r.digest, image_uri=ruri)
            for m in sev_vulns:
                fid = "CWPP-06" if m.kev else "CWPP-05"
                self._add("FAIL", fid, "ECR", f"{rname}{tag_s}",
                          f"registry image {m.severity} {m.cve} (EPSS {m.epss}, "
                          f"exploit={m.exploit_available}, fix={'YES' if m.fixed_version else 'NO'}) "
                          f"in {m.package} {m.installed_version} (agentless SBOM) "
                          f"| {rname}@{r.digest[:19]}")
            for s in r.result.secrets:
                self._add("FAIL", "CWPP-03", "ECR", f"{rname}{tag_s}",
                          f"{s.kind} in image layer at {s.path}:{s.line} ({s.match_preview}) "
                          f"| {rname}@{r.digest[:19]}")
            # stash the FULL SBOM (all components, not just the sev-filtered CVEs) so the hosted
            # worker persists it as a durable snapshot (diff / license / VEX), best-effort.
            if r.components:
                self.registry_sboms.append(
                    {"node_id": r.node_id,
                     "doc": aws_registry_sbom.to_cyclonedx(r.node_id, r.components)})
        for note in sel_notes:
            self._add("INFO", "CWPP-04", "ECR", rname, f"{note} | {rname}")

    # ══════════════════════════════════════════════════════════════════════════
    # SECTION 8: BACKUP & DR
    # ══════════════════════════════════════════════════════════════════════════
    def _check_backup(self):
        self._section_header("BACKUP")
        self._log("BCK-01: AWS Backup vaults and plans")
        try:
            bk     = self._client("backup")
            vaults = bk.list_backup_vaults()["BackupVaultList"]
            if vaults:
                for v in vaults:
                    self._add("PASS", "BCK-01", "BACKUP",
                              v["BackupVaultName"],
                              f"Vault: {v['BackupVaultName']} "
                              f"(RecoveryPoints: {v.get('NumberOfRecoveryPoints', 0)})")
            else:
                self._add("FAIL", "BCK-01", "BACKUP", "vaults",
                          "No AWS Backup vaults configured")
            plans = bk.list_backup_plans()["BackupPlansList"]
            if not plans:
                self._add("FAIL", "BCK-01", "BACKUP", "plans",
                          "No AWS Backup plans configured")
            else:
                for p in plans:
                    self._add("PASS", "BCK-01", "BACKUP", p["BackupPlanName"],
                              f"Backup plan: {p['BackupPlanName']}")
        except Exception as e:
            self._add("WARN", "BCK-01", "BACKUP", "backup", str(e))

        # BCK-02/03 — Vault Lock immutability + vault access-policy exposure. Inline-paginate
        # (BCK-01 does NOT paginate, so vaults past page 1 would be silently skipped).
        self._log("BCK-02/03: Backup Vault Lock immutability + access-policy exposure")
        try:
            bk = self._client("backup")
            all_vaults = []
            for page in bk.get_paginator("list_backup_vaults").paginate():
                all_vaults.extend(page.get("BackupVaultList", []))
        except Exception as e:
            self._add("WARN", "BCK-02", "BACKUP", "backup",
                      f"could not enumerate backup vaults for Vault Lock evaluation: {e}")
            all_vaults = None
        if all_vaults:
            now = datetime.now(timezone.utc)
            for v in all_vaults:
                name = v.get("BackupVaultName", "unknown")
                # BCK-02 — Vault Lock immutability. Governance mode reports Locked=True with
                # NO LockDate; compliance mode reports LockDate = the immutability date — the
                # only distinguishing signal in the shape.
                if not v.get("Locked", False):
                    self._add("FAIL", "BCK-02", "BACKUP", name,
                              f"Vault Lock NOT enabled — recovery points are mutable/deletable "
                              f"(no ransomware/insider immutability) | {name}")
                else:
                    lock_date = v.get("LockDate")
                    if lock_date is None:
                        self._add("WARN", "BCK-02", "BACKUP", name,
                                  f"GOVERNANCE-mode Vault Lock — a privileged principal can "
                                  f"still delete the lock/vault; use compliance mode for true "
                                  f"immutability | {name}")
                    elif self._as_utc(lock_date) > now:
                        self._add("WARN", "BCK-02", "BACKUP", name,
                                  f"Compliance Vault Lock still in CHANGEABLE grace period until "
                                  f"{lock_date} — the lock can still be removed | {name}")
                    else:
                        self._add("PASS", "BCK-02", "BACKUP", name,
                                  f"Compliance-mode Vault Lock ACTIVE (immutable) | {name}")
                # BCK-03 — vault access-policy exposure
                self._check_backup_vault_policy(bk, name)
                # BCK-05 — whose key is the vault on? Read EncryptionKeyType rather
                # than inferring ownership from the ARN, which is populated for both
                # kinds.
                try:
                    detail = bk.describe_backup_vault(BackupVaultName=name) or {}
                except Exception as e:
                    if self._is_access_denied(e):
                        self._coverage.note_denied(
                            "BCK-05", "backup:DescribeBackupVault")
                    detail = None
                if detail is not None:
                    k = aws_cis_storage.backup_vault_key_posture(detail)
                    if k["known"] and k["aws_owned"]:
                        self._add("FAIL", "BCK-05", "BACKUP", name,
                                  f"Backup vault {name} encrypts recovery points with "
                                  f"an AWS-owned key, which this account cannot audit, "
                                  f"rotate or revoke — so the copy of last resort is "
                                  f"held under a key you have no control over "
                                  f"| {name}")
                    elif k["known"]:
                        self._add("PASS", "BCK-05", "BACKUP", name,
                                  f"Backup vault {name} uses a customer-managed key "
                                  f"| {name}")

        # BCK-04 — does any plan copy the recovery point out of this region/account?
        # THE BENCHMARK NEVER ASKS THIS. Its whole AWS Backup section asks that
        # backups be created and never once that they survive losing the region or
        # the account, which is why this check carries no CIS-STORAGE key.
        self._log("BCK-04: backup plans copy recovery points off-region/off-account")
        try:
            bk = self._client("backup")
            plans = []
            for page in bk.get_paginator("list_backup_plans").paginate():
                plans.extend(page.get("BackupPlansList", []))
        except Exception as e:
            if self._is_access_denied(e):
                self._coverage.note_denied("BCK-04", "backup:ListBackupPlans")
            plans = None
        for plan in (plans or []):
            plan_id = (plan or {}).get("BackupPlanId")
            if not plan_id:
                continue
            try:
                full = bk.get_backup_plan(BackupPlanId=plan_id) or {}
            except Exception as e:
                if self._is_access_denied(e):
                    self._coverage.note_denied("BCK-04", "backup:GetBackupPlan")
                continue
            c = aws_cis_storage.backup_plan_copy_posture(full)
            nm = c["name"] or plan_id
            # A plan with no rules backs nothing up at all, which is BCK-01's
            # finding rather than this one's. Reporting it here too would say the
            # same thing twice under different severities.
            if not c["known"]:
                continue
            if not c["any_copy"]:
                self._add("FAIL", "BCK-04", "BACKUP", nm,
                          f"Backup plan {nm} has {c['rules']} rule(s) and none of "
                          f"them copies the recovery point anywhere else — the "
                          f"backup lives in the same account and region as the thing "
                          f"it protects, so a region loss or an account compromise "
                          f"takes the original and the copy together | {nm}")
            else:
                self._add("PASS", "BCK-04", "BACKUP", nm,
                          f"Backup plan {nm} copies recovery points via rule(s) "
                          f"{', '.join(c['with_copy'])} | {nm}")

    @staticmethod
    def _as_utc(ts):
        """Coerce a boto3 timestamp (datetime, usually tz-aware) or ISO string to a
        tz-aware UTC datetime for comparison."""
        if isinstance(ts, datetime):
            return ts if ts.tzinfo else ts.replace(tzinfo=timezone.utc)
        return datetime.fromisoformat(str(ts).replace("Z", "+00:00"))

    def _check_backup_vault_policy(self, bk, name):
        """BCK-03 — a Backup vault access policy granting public/cross-account access. Only
        PUBLIC is a FAIL (CRITICAL); cross-account is a legitimate DR-copy pattern -> WARN."""
        try:
            pol_str = bk.get_backup_vault_access_policy(BackupVaultName=name).get("Policy")
        except Exception as e:
            if "denied" in str(e).lower():
                self._add("WARN", "BCK-03", "BACKUP", name,
                          f"could not evaluate vault access policy (access denied) | {name}")
            return                       # ResourceNotFound == no policy attached (private)
        if not pol_str:
            return
        try:
            stmts = json.loads(pol_str).get("Statement", [])
            if isinstance(stmts, dict):
                stmts = [stmts]
        except Exception:
            return
        for st in stmts:
            res = classify_resource_policy_stmt(st, self.account or "")
            if not res:
                continue
            kind = res["kind"]
            if kind == "public":
                self._add("FAIL", "BCK-03", "BACKUP", name,
                          f"Backup vault access policy grants PUBLIC access — recovery points "
                          f"(full data copies) restorable/deletable by any principal | {name}")
            elif kind == "public_conditioned":
                self._add("WARN", "BCK-03", "BACKUP", name,
                          f"Vault policy wildcard principal condition-guarded — verify | {name}")
            elif kind == "cross_account":
                ext = [a for a in res.get("external_accounts", [])
                       if a not in self.trusted_accounts]
                if ext:
                    self._add("WARN", "BCK-03", "BACKUP", name,
                              f"Vault shared cross-account to {', '.join(ext)} — legitimate for "
                              f"AWS Backup cross-account COPY, but verify the target | {name}")
            elif kind == "org":
                self._add("WARN", "BCK-03", "BACKUP", name,
                          f"Vault shared to AWS Organization {res.get('org_id')} — verify | {name}")

    # ══════════════════════════════════════════════════════════════════════════
    # SECTION 9: AMAZON RDS
    # ══════════════════════════════════════════════════════════════════════════
    # ── Phase 5b: managed-service engine-EOL helpers ──────────────────────────
    def _scan_date(self) -> date:
        """The date EOL verdicts are evaluated against — injectable for deterministic
        tests (self._today), else today (UTC)."""
        return self._today or datetime.now(timezone.utc).date()

    def _stash_eol_edge(self, node_id: str, node_kind: str, matches, **node_props):
        """Queue a HAS_VULN payload for LATE emission (after IAMPRIVESC rebuilds the
        graph). Findings themselves are added inline via self._add; only the graph edge
        is deferred, because _build_identity_graph does a hard graph replace."""
        if node_id and matches:
            self._eol_graph_payloads.append((node_id, node_kind, list(matches), node_props))

    def _eol_check(self, service: str, engine: str, version: str):
        """Evaluate one managed engine version. Returns (verdict, matches):
        verdict in {'EOL','OK','UNKNOWN'}; matches is the synthetic EnrichedMatch list."""
        if not aws_engine_eol.evaluable(service, engine, version):
            return "UNKNOWN", []
        matches = aws_engine_eol.managed_engine_cve(
            service, engine, version, today=self._scan_date())
        return ("EOL" if matches else "OK"), matches

    def _check_rds(self):
        self._section_header("RDS")
        rds = self._client("rds")

        def _rds_instances():
            """Genuine RDS instances only.

            THE SAME DEFECT THE AURORA CLUSTER FILTER FIXED, one level down, and it stood
            for as long as it did because nothing looked. Neptune and DocumentDB share the
            RDS control plane, so rds:DescribeDBInstances returns their instances too, and
            this generator used to yield them unfiltered. A single Neptune instance
            produced four findings -- RDS-01, RDS-02, RDS-03, RDS-04 -- none of which said
            Neptune anywhere, two of which duplicated NEP-01/NEP-02 with contradictory
            remediation, and two of which were the only coverage Neptune's public
            accessibility and backups had.

            That last part is why the filter could not ship alone: dropping these
            instances without NEP-06/07 and DOCDB-07/08 would have deleted real coverage
            rather than relabelled it, which is exactly the trap the cluster fix avoided
            by growing from zero new checks to six.

            DENY-list, not allow-list, and for the same reason as
            NON_AURORA_CLUSTER_ENGINES: a new RDS engine must keep being scored by
            default. Only an engine that POSITIVELY declares itself as another service is
            dropped; an absent Engine is kept.
            """
            try:
                paginator = rds.get_paginator("describe_db_instances")
                for page in paginator.paginate():
                    for db in page["DBInstances"]:
                        engine = ((db or {}).get("Engine") or "").lower()
                        if engine in NON_AURORA_CLUSTER_ENGINES:
                            continue
                        yield db
            except Exception:
                return

        # RDS-01 — Encryption at rest
        self._log("RDS-01: RDS instances — encryption at rest")
        found = False
        for db in _rds_instances():
            found  = True
            iid    = db["DBInstanceIdentifier"]
            engine = db.get("Engine", "unknown")
            if db.get("StorageEncrypted", False):
                self._add("PASS", "RDS-01", "RDS", iid,
                          f"Storage encryption=ON | {iid} ({engine})")
            else:
                self._add("FAIL", "RDS-01", "RDS", iid,
                          f"Storage encryption=OFF | {iid} ({engine})")
        if not found:
            self._add("WARN", "RDS-01", "RDS", "rds",
                      "No RDS instances found in this region")

        # RDS-02 — Publicly accessible
        self._log("RDS-02: RDS instances — publicly accessible")
        all_private = True
        for db in _rds_instances():
            iid    = db["DBInstanceIdentifier"]
            engine = db.get("Engine", "unknown")
            if db.get("PubliclyAccessible", False):
                self._add("FAIL", "RDS-02", "RDS", iid,
                          f"DB PUBLICLY ACCESSIBLE | {iid} ({engine}) — CRITICAL")
                all_private = False
        if all_private:
            self._add("PASS", "RDS-02", "RDS", "all-dbs",
                      "No RDS instances are publicly accessible")

        # RDS-03 — Backup retention + Multi-AZ
        self._log("RDS-03: Backup retention (≥7 days) and Multi-AZ")
        for db in _rds_instances():
            iid       = db["DBInstanceIdentifier"]
            retention = db.get("BackupRetentionPeriod", 0)
            multi_az  = db.get("MultiAZ", False)
            if retention == 0:
                self._add("FAIL", "RDS-03", "RDS", iid,
                          f"Automated backups DISABLED | {iid}")
            elif retention < 7:
                self._add("WARN", "RDS-03", "RDS", iid,
                          f"Backup retention={retention}d (recommend ≥7) | {iid}")
            else:
                self._add("PASS", "RDS-03", "RDS", iid,
                          f"Backup retention={retention}d | {iid}")
            if multi_az:
                self._add("PASS", "RDS-03", "RDS", iid, f"Multi-AZ=ON | {iid}")
            else:
                self._add("WARN", "RDS-03", "RDS", iid, f"Multi-AZ=OFF | {iid}")

        # RDS-04 — Deletion protection + auto minor upgrade
        self._log("RDS-04: Deletion protection and auto minor version upgrade")
        for db in _rds_instances():
            iid        = db["DBInstanceIdentifier"]
            del_prot   = db.get("DeletionProtection", False)
            auto_minor = db.get("AutoMinorVersionUpgrade", False)
            if del_prot:
                self._add("PASS", "RDS-04", "RDS", iid,
                          f"Deletion protection=ON | {iid}")
            else:
                self._add("FAIL", "RDS-04", "RDS", iid,
                          f"Deletion protection=OFF | {iid}")
            if auto_minor:
                self._add("PASS", "RDS-04", "RDS", iid,
                          f"Auto minor upgrade=ON | {iid}")
            else:
                self._add("WARN", "RDS-04", "RDS", iid,
                          f"Auto minor upgrade=OFF | {iid}")

        # RDS-05 — Enhanced monitoring + CloudWatch log exports
        self._log("RDS-05: Enhanced monitoring and CloudWatch log exports")
        for db in _rds_instances():
            iid        = db["DBInstanceIdentifier"]
            monitoring = db.get("MonitoringInterval", 0)
            logs       = db.get("EnabledCloudwatchLogsExports", [])
            if monitoring > 0:
                self._add("PASS", "RDS-05", "RDS", iid,
                          f"Enhanced monitoring interval={monitoring}s | {iid}")
            else:
                self._add("WARN", "RDS-05", "RDS", iid,
                          f"Enhanced monitoring=OFF | {iid}")
            if logs:
                self._add("PASS", "RDS-05", "RDS", iid,
                          f"CloudWatch log exports={logs} | {iid}")
            else:
                self._add("WARN", "RDS-05", "RDS", iid,
                          f"No CloudWatch log exports | {iid}")

        # RDS-08 — IAM database authentication (defense-in-depth vs static passwords)
        self._log("RDS-08: IAM database authentication enabled")
        for db in _rds_instances():
            iid    = db["DBInstanceIdentifier"]
            engine = db.get("Engine", "")
            # IAM auth only applies to MySQL/PostgreSQL/MariaDB/Aurora engines
            if not any(e in engine for e in ("mysql", "postgres", "mariadb", "aurora")):
                continue
            if db.get("IAMDatabaseAuthenticationEnabled", False):
                self._add("PASS", "RDS-08", "RDS", iid,
                          f"IAM DB authentication=ON | {iid} ({engine})")
            else:
                self._add("FAIL", "RDS-08", "RDS", iid,
                          f"IAM DB authentication=OFF — relies on static DB passwords "
                          f"| {iid} ({engine})")

        # RDS-14 — TLS enforced for client connections.
        # Every RDS engine ACCEPTS TLS; almost none REQUIRE it, and nothing in
        # describe_db_instances says which. The setting lives in the instance parameter
        # group, so this is the first check in the product to read one — the read is
        # cached per group, because a group is shared by every instance using it.
        self._log("RDS-14: TLS enforced for client connections")
        for db in _rds_instances():
            iid    = db["DBInstanceIdentifier"]
            engine = db.get("Engine", "")
            groups = db.get("DBParameterGroups") or []
            group  = (groups[0] or {}).get("DBParameterGroupName", "") if groups else ""
            self._check_tls_enforced(
                rds, check_id="RDS-14", section="RDS", resource=iid,
                engine=engine, group=group, service="rds", cluster=False,
                action="rds:DescribeDBParameters")

        # RDS-06 — Public snapshot visibility  +  RDS-11 — snapshot encryption at rest
        self._log("RDS-06/RDS-11: RDS snapshot public visibility and encryption at rest")
        try:
            snaps = []
            for page in rds.get_paginator("describe_db_snapshots").paginate(
                SnapshotType="manual"
            ):
                snaps.extend(page.get("DBSnapshots", []))
            public_snaps = []
            unencrypted  = 0
            for s in snaps:
                sid = s["DBSnapshotIdentifier"]
                if not s.get("Encrypted", False):
                    unencrypted += 1
                    self._add("FAIL", "RDS-11", "RDS", sid,
                              f"Manual RDS snapshot NOT encrypted at rest: {sid} "
                              f"— plaintext DB data if the snapshot is shared/leaked")
                try:
                    attrs = rds.describe_db_snapshot_attributes(
                        DBSnapshotIdentifier=sid
                    )["DBSnapshotAttributesResult"]["DBSnapshotAttributes"]
                    for a in attrs:
                        if (a["AttributeName"] == "restore"
                                and "all" in a.get("AttributeValues", [])):
                            public_snaps.append(sid)
                except Exception:
                    pass
            if public_snaps:
                for snap in public_snaps:
                    self._add("FAIL", "RDS-06", "RDS", snap,
                              f"RDS snapshot PUBLICLY ACCESSIBLE: {snap}")
            else:
                self._add("PASS", "RDS-06", "RDS", "snapshots",
                          f"No public RDS snapshots "
                          f"({len(snaps)} manual snapshots checked)")
            if snaps and unencrypted == 0:
                self._add("PASS", "RDS-11", "RDS", "snapshots",
                          f"All {len(snaps)} manual RDS snapshots encrypted at rest")
        except Exception as e:
            self._read_failed("RDS-06", "RDS", "rds-snapshots",
                              "rds:DescribeDBSnapshots", e)

        # RDS-12 — Instance engine end-of-life (Aurora skipped here; AUR-03 covers it at
        # the cluster level). Inline-paginate in OWN try/except — do NOT reuse
        # _rds_instances() which swallows API errors (false-clean trap).
        self._log("RDS-12: RDS instance engine end-of-life / past standard support")
        try:
            instances = []
            for page in rds.get_paginator("describe_db_instances").paginate():
                instances.extend(page.get("DBInstances", []))
        except Exception as e:
            self._add("WARN", "RDS-12", "RDS", "rds",
                      f"describe_db_instances failed (engine EOL not evaluated): {e}")
            instances = None
        if instances is not None:
            if not instances:
                self._add("INFO", "RDS-12", "RDS", "rds", "No RDS instances found in this region")
            for db in instances:
                engine = db.get("Engine", "")
                if engine.startswith("aurora"):
                    continue
                iid = db["DBInstanceIdentifier"]
                ev  = db.get("EngineVersion", "")
                verdict, matches = self._eol_check("rds", engine, ev)
                if verdict == "EOL":
                    self._add("FAIL", "RDS-12", "RDS", iid,
                              f"Engine END-OF-LIFE: {engine} {ev} past standard support "
                              f"(upgrade to >= {matches[0].fixed_version}) | {iid}")
                    self._stash_eol_edge(db.get("DBInstanceArn", iid), "RDSInstance", matches,
                                         engine=engine, engine_version=ev, region=self.region)
                elif verdict == "OK":
                    self._add("PASS", "RDS-12", "RDS", iid,
                              f"Engine supported: {engine} {ev} | {iid}")
                else:
                    self._add("INFO", "RDS-12", "RDS", iid,
                              f"Engine EOL not evaluable: {engine} {ev} | {iid}")

        # AUR-01/02/03 — Aurora / Multi-AZ DB CLUSTER: encryption, deletion protection,
        # engine EOL. describe_db_clusters is a SEPARATE plane from describe_db_instances —
        # today's RDS-01..11 never see a cluster, so Aurora Serverless-v1 / headless
        # clusters are entirely unscanned without this.
        self._log("AUR-01/02/03: Aurora cluster encryption, deletion protection, engine EOL")
        try:
            clusters = []
            for page in rds.get_paginator("describe_db_clusters").paginate():
                clusters.extend(page.get("DBClusters", []))
        except Exception as e:
            self._add("WARN", "AUR-01", "RDS", "rds", f"describe_db_clusters failed: {e}")
            clusters = None
        if clusters is not None:
            # DocumentDB and Neptune come back from this API too. They are scored by
            # _check_docdb and _check_neptune under their own ids — see
            # NON_AURORA_CLUSTER_ENGINES. Filter BEFORE the empty test, so an account
            # holding only DocumentDB does not read as "no clusters" here.
            clusters = [c for c in clusters
                        if (c.get("Engine") or "").lower()
                        not in NON_AURORA_CLUSTER_ENGINES]
            if not clusters:
                self._add("INFO", "AUR-01", "RDS", "rds",
                          "No Aurora/Multi-AZ DB clusters found in this region")
            for cl in clusters:
                cid    = cl.get("DBClusterIdentifier", "unknown")
                carn   = cl.get("DBClusterArn", cid)
                engine = cl.get("Engine", "")
                ev     = cl.get("EngineVersion", "")
                # AUR-01 cluster encryption at rest
                if cl.get("StorageEncrypted", False):
                    self._add("PASS", "AUR-01", "RDS", cid,
                              f"Cluster storage encryption=ON | {cid} ({engine})")
                else:
                    self._add("FAIL", "AUR-01", "RDS", cid,
                              f"Cluster storage encryption=OFF | {cid} ({engine})")
                # AUR-02 cluster deletion protection (authoritative for Aurora; distinct from RDS-04)
                if cl.get("DeletionProtection", False):
                    self._add("PASS", "AUR-02", "RDS", cid,
                              f"Cluster deletion protection=ON | {cid}")
                else:
                    self._add("FAIL", "AUR-02", "RDS", cid,
                              f"Cluster deletion protection=OFF | {cid}")
                # AUR-03 cluster engine EOL
                verdict, matches = self._eol_check("rds", engine, ev)
                if verdict == "EOL":
                    self._add("FAIL", "AUR-03", "RDS", cid,
                              f"Cluster engine END-OF-LIFE: {engine} {ev} "
                              f"(upgrade to >= {matches[0].fixed_version}) | {cid}")
                    self._stash_eol_edge(carn, "RDSCluster", matches,
                                         engine=engine, engine_version=ev, region=self.region)
                elif verdict == "OK":
                    self._add("PASS", "AUR-03", "RDS", cid,
                              f"Cluster engine supported: {engine} {ev} | {cid}")
                else:
                    self._add("INFO", "AUR-03", "RDS", cid,
                              f"Cluster engine EOL not evaluable: {engine} {ev} | {cid}")
                # AUR-06 — TLS enforced for client connections. A CLUSTER parameter for
                # Aurora, which is why RDS-14 (the instance-group equivalent) cannot
                # answer it: a Serverless v1 cluster has no instances to read at all.
                self._check_tls_enforced(
                    rds, check_id="AUR-06", section="RDS", resource=cid,
                    engine=engine, group=cl.get("DBClusterParameterGroup", ""),
                    service="rds", cluster=True,
                    action="rds:DescribeDBClusterParameters")
                # AUR-07 — CLUSTER backup retention. RDS-03 reads this from
                # describe_db_instances, where for an Aurora cluster it is not the
                # authoritative value and for a Serverless v1 cluster there is no
                # instance to read at all. The threshold is <7 rather than ==0 because a
                # cluster's minimum is 1 day: "backups off" is unreachable here, and the
                # real gap is the DEFAULT of one day, which loses anything discovered
                # more than a day late.
                retention = cl.get("BackupRetentionPeriod")
                if isinstance(retention, int) and retention < 7:
                    self._add("FAIL", "AUR-07", "RDS", cid,
                              f"Cluster backup retention={retention}d (recommend >=7) "
                              f"| {cid} — a problem found later than that is "
                              f"unrecoverable")
                elif isinstance(retention, int):
                    self._add("PASS", "AUR-07", "RDS", cid,
                              f"Cluster backup retention={retention}d | {cid}")
                # AUR-08 — CLUSTER IAM database authentication. Same split as AUR-07:
                # RDS-08 reads the instance field, and the cluster owns this for Aurora.
                if engine and not any(e in engine for e in
                                      ("mysql", "postgres", "mariadb", "aurora")):
                    pass                      # IAM auth is not offered on this engine
                elif cl.get("IAMDatabaseAuthenticationEnabled") is True:
                    self._add("PASS", "AUR-08", "RDS", cid,
                              f"Cluster IAM DB authentication=ON | {cid} ({engine})")
                elif cl.get("IAMDatabaseAuthenticationEnabled") is False:
                    self._add("FAIL", "AUR-08", "RDS", cid,
                              f"Cluster IAM DB authentication=OFF — relies on static DB "
                              f"passwords | {cid} ({engine})")

        # AUR-04/05 — Aurora CLUSTER snapshots: public visibility + encryption at rest.
        # Distinct API + id-namespace from instance snapshots (RDS-06/11) — zero overlap.
        self._log("AUR-04/05: Aurora cluster snapshot public visibility and encryption")
        try:
            csnaps = []
            for page in rds.get_paginator("describe_db_cluster_snapshots").paginate(
                SnapshotType="manual"
            ):
                csnaps.extend(page.get("DBClusterSnapshots", []))
        except Exception as e:
            self._add("WARN", "AUR-04", "RDS", "rds",
                      f"describe_db_cluster_snapshots failed: {e}")
            csnaps = None
        if csnaps is not None:
            # Same overlap as the cluster loop above: DBClusterSnapshot carries Engine,
            # and DocumentDB/Neptune snapshots arrive here. DOCDB-01/05 and NEP-03/04
            # own those.
            csnaps = [s for s in csnaps
                      if (s.get("Engine") or "").lower()
                      not in NON_AURORA_CLUSTER_ENGINES]
            if not csnaps:
                self._add("INFO", "AUR-04", "RDS", "cluster-snapshots",
                          "No manual Aurora/RDS cluster snapshots in this region")
            public_c = 0
            unenc_c  = 0
            read_ok  = 0    # snapshots whose restore-attribute was actually evaluated
            read_err = 0    # snapshots whose attribute read failed (visibility UNKNOWN)
            for s in csnaps:
                sid = s["DBClusterSnapshotIdentifier"]
                # AUR-05 cluster-snapshot encryption (field is StorageEncrypted — the
                # cluster-snapshot shape differs from the instance-snapshot 'Encrypted')
                if not s.get("StorageEncrypted", False):
                    unenc_c += 1
                    self._add("FAIL", "AUR-05", "RDS", sid,
                              f"Manual Aurora cluster snapshot NOT encrypted at rest: {sid} "
                              f"— plaintext DB data if shared/leaked")
                # AUR-04 public visibility — OWN try/except per snapshot (surface the error,
                # do NOT silently `pass` like RDS-06 which can mis-read a public snapshot as private)
                try:
                    attrs = rds.describe_db_cluster_snapshot_attributes(
                        DBClusterSnapshotIdentifier=sid
                    )["DBClusterSnapshotAttributesResult"]["DBClusterSnapshotAttributes"]
                    read_ok += 1
                    if any(a.get("AttributeName") == "restore"
                           and "all" in a.get("AttributeValues", []) for a in attrs):
                        public_c += 1
                        self._add("FAIL", "AUR-04", "RDS", sid,
                                  f"Aurora cluster snapshot PUBLICLY RESTORABLE by any AWS "
                                  f"account: {sid} — CRITICAL")
                except Exception as e:
                    read_err += 1
                    self._add("WARN", "AUR-04", "RDS", sid,
                              f"cluster-snapshot attribute read failed (public visibility "
                              f"UNDETERMINED): {e}")
            # Only an all-clear when EVERY snapshot's restore attribute was actually read.
            # A denied/throttled read leaves public visibility unknown — never a false PASS
            # (the whole point of the per-snapshot try/except above).
            if csnaps and public_c == 0 and read_err == 0:
                self._add("PASS", "AUR-04", "RDS", "cluster-snapshots",
                          f"No public Aurora cluster snapshots ({read_ok} manual checked)")
            elif csnaps and public_c == 0 and read_err:
                self._add("WARN", "AUR-04", "RDS", "cluster-snapshots",
                          f"Public visibility UNDETERMINED for {read_err} of {len(csnaps)} "
                          f"manual cluster snapshots (attribute read denied/throttled) — "
                          f"{read_ok} confirmed not public")
            if csnaps and unenc_c == 0:
                self._add("PASS", "AUR-05", "RDS", "cluster-snapshots",
                          f"All {len(csnaps)} manual Aurora cluster snapshots encrypted at rest")

        # RDS-13 — Idle RDS instance (cost/hygiene): zero DatabaseConnections over the window.
        # Read-only CloudWatch GetMetricStatistics (no new dependency/primitive). RDS instances
        # only (Aurora has its own series). Fail-open: a throttled/denied metric read is skipped.
        try:
            cw = self._client("cloudwatch")
            end = datetime.now(timezone.utc)
            start = end - timedelta(days=IDLE_DB_WINDOW_DAYS)
            for db in _rds_instances():
                iid = db.get("DBInstanceIdentifier")
                if not iid:
                    continue
                try:
                    pts = cw.get_metric_statistics(
                        Namespace="AWS/RDS", MetricName="DatabaseConnections",
                        Dimensions=[{"Name": "DBInstanceIdentifier", "Value": iid}],
                        StartTime=start, EndTime=end,
                        Period=IDLE_DB_PERIOD_SECONDS, Statistics=["Maximum"],
                    ).get("Datapoints", [])
                except Exception:
                    continue                             # fail-open per DB
                # Only flag when we actually have datapoints AND every one is zero-connection.
                if pts and all((p.get("Maximum") or 0) == 0 for p in pts):
                    self._add("WARN", "RDS-13", "RDS", iid,
                              f"Idle RDS instance — zero DatabaseConnections over "
                              f"{IDLE_DB_WINDOW_DAYS}d, incurring cost | {iid}")
        except Exception:
            pass                                         # fail-open (cost/hygiene, not security)

    # ══════════════════════════════════════════════════════════════════════════
    # SECTION 10: AMAZON S3 GLACIER
    # ══════════════════════════════════════════════════════════════════════════
    def _check_glacier(self):
        self._section_header("GLACIER")
        glacier = self._client("glacier")

        try:
            vaults = glacier.list_vaults(accountId="-")["VaultList"]
        except Exception as e:
            self._read_failed("GLC-01", "GLACIER", "glacier", "glacier:ListVaults", e)
            return

        if not vaults:
            self._add("WARN", "GLC-01", "GLACIER", "glacier",
                      "No Glacier vaults found in this region")
            return

        for v in vaults:
            vname = v["VaultName"]
            count = v.get("NumberOfArchives", 0)
            size  = v.get("SizeInBytes", 0)
            self._add("INFO", "GLC-00", "GLACIER", vname,
                      f"Vault: {vname} Archives={count} "
                      f"Size={size / 1024 / 1024:.1f}MB")

            # GLC-01 — Access policy wildcard check
            try:
                policy = glacier.get_vault_access_policy(
                    accountId="-", vaultName=vname
                )
                doc  = json.loads(policy["policy"]["Policy"])
                wild = False
                for stmt in doc.get("Statement", []):
                    principal = stmt.get("Principal", {})
                    effect    = stmt.get("Effect", "")
                    p_val     = (
                        principal
                        if isinstance(principal, str)
                        else principal.get("AWS", "")
                    )
                    if effect == "Allow" and p_val in ("*", ["*"]):
                        self._add("FAIL", "GLC-01", "GLACIER", vname,
                                  f"Vault '{vname}' has wildcard Allow in "
                                  "access policy — CRITICAL")
                        wild = True
                if not wild:
                    self._add("PASS", "GLC-01", "GLACIER", vname,
                              f"Vault '{vname}' access policy scoped "
                              "(no wildcard principal)")
            except glacier.exceptions.ResourceNotFoundException:
                self._add("WARN", "GLC-01", "GLACIER", vname,
                          f"Vault '{vname}' has no access policy — "
                          "verify intentional")
            except Exception as e:
                self._add("WARN", "GLC-01", "GLACIER", vname,
                          f"Could not read policy for '{vname}': {e}")

            # GLC-02 — Vault Lock (WORM) status
            try:
                lock  = glacier.get_vault_lock(accountId="-", vaultName=vname)
                state = lock.get("State", "Unknown")
                cd    = (lock.get("CreationDate", "N/A") or "N/A")[:10]
                if state == "Locked":
                    self._add("PASS", "GLC-02", "GLACIER", vname,
                              f"Vault Lock=Locked | {vname} (created: {cd})")
                else:
                    self._add("FAIL", "GLC-02", "GLACIER", vname,
                              f"Vault Lock state={state}, not Locked — the WORM "
                              f"policy is not yet enforceable | {vname}")
            except glacier.exceptions.ResourceNotFoundException:
                # Not an error: the API says this vault has no lock, which is the
                # finding. The generic handler below stays WARN, because there the
                # answer is genuinely unknown.
                self._add("FAIL", "GLC-02", "GLACIER", vname,
                          f"No Vault Lock on '{vname}' — WORM protection absent")
            except Exception as e:
                self._add("WARN", "GLC-02", "GLACIER", vname, str(e))

            # GLC-03 — SNS notifications
            try:
                notif  = glacier.get_vault_notifications(
                    accountId="-", vaultName=vname
                )
                topic  = notif["vaultNotificationConfig"].get("SNSTopic", "None")
                events = notif["vaultNotificationConfig"].get("Events", [])
                self._add("PASS", "GLC-03", "GLACIER", vname,
                          f"Notifications configured | {vname} → {topic} "
                          f"| Events: {events}")
            except glacier.exceptions.ResourceNotFoundException:
                self._add("WARN", "GLC-03", "GLACIER", vname,
                          f"No SNS notifications on '{vname}' — "
                          "job completion alerts absent")
            except Exception as e:
                self._add("WARN", "GLC-03", "GLACIER", vname, str(e))

    # ══════════════════════════════════════════════════════════════════════════
    # SECTION 11: AMAZON SNS
    # ══════════════════════════════════════════════════════════════════════════
    def _check_sns(self):
        self._section_header("SNS")
        sns = self._client("sns")

        def _topics():
            try:
                paginator = sns.get_paginator("list_topics")
                for page in paginator.paginate():
                    yield from page["Topics"]
            except Exception:
                return

        topics = list(_topics())
        if not topics:
            self._add("WARN", "SNS-01", "SNS", "sns",
                      "No SNS topics found in this region")
            return

        # SNS-01 — SSE-KMS encryption
        self._log("SNS-01: SNS topics — SSE-KMS encryption")
        for t in topics:
            arn  = t["TopicArn"]
            name = arn.split(":")[-1]
            try:
                attrs = sns.get_topic_attributes(TopicArn=arn)["Attributes"]
                kms   = attrs.get("KmsMasterKeyId", "")
                if kms:
                    self._add("PASS", "SNS-01", "SNS", name,
                              f"SSE-KMS={kms} | {name}")
                else:
                    self._add("WARN", "SNS-01", "SNS", name,
                              f"SSE-KMS=OFF | {name}")
            except Exception as e:
                self._read_failed("SNS-01", "SNS", name, "sns:GetTopicAttributes", e)

        # SNS-02 — Access policy wildcard check
        self._log("SNS-02: SNS topics — access policy (no wildcard Principal)")
        for t in topics:
            arn  = t["TopicArn"]
            name = arn.split(":")[-1]
            try:
                attrs  = sns.get_topic_attributes(TopicArn=arn)["Attributes"]
                policy = json.loads(attrs.get("Policy", '{"Statement":[]}'))
                issues = []
                for stmt in policy.get("Statement", []):
                    principal = stmt.get("Principal", {})
                    effect    = stmt.get("Effect", "")
                    condition = stmt.get("Condition", {})
                    p_val = (
                        principal
                        if isinstance(principal, str)
                        else (
                            principal.get("AWS", "")
                            or principal.get("Service", "")
                        )
                    )
                    if (effect == "Allow"
                            and p_val in ("*", ["*"])
                            and not condition):
                        issues.append(
                            f"Action={stmt.get('Action', '*')} allows "
                            "wildcard with no Condition"
                        )
                if issues:
                    for i in issues:
                        self._add("FAIL", "SNS-02", "SNS", name,
                                  f"Overly permissive policy: {i}")
                else:
                    self._add("PASS", "SNS-02", "SNS", name,
                              f"Access policy OK (no unconstrained wildcard) "
                              f"| {name}")
            except Exception as e:
                self._read_failed("SNS-02", "SNS", name, "sns:GetTopicAttributes", e)

        # SNS-03 — No insecure HTTP subscriptions
        self._log("SNS-03: SNS topics — no HTTP subscriptions")
        for t in topics:
            arn  = t["TopicArn"]
            name = arn.split(":")[-1]
            try:
                subs = sns.list_subscriptions_by_topic(
                    TopicArn=arn
                ).get("Subscriptions", [])
                for sub in subs:
                    protocol = sub.get("Protocol", "")
                    endpoint = sub.get("Endpoint", "")
                    if protocol == "http":
                        self._add("FAIL", "SNS-03", "SNS", name,
                                  f"Insecure HTTP subscription on '{name}' "
                                  f"→ {endpoint}")
                    elif protocol == "https":
                        self._add("PASS", "SNS-03", "SNS", name,
                                  f"HTTPS subscription on '{name}' "
                                  f"→ {endpoint[:60]}")
            except Exception as e:
                self._read_failed("SNS-03", "SNS", name,
                                  "sns:ListSubscriptionsByTopic", e)

        # SNS-04 — Cross-account subscriptions
        self._log("SNS-04: SNS cross-account subscriptions")
        try:
            paginator = sns.get_paginator("list_subscriptions")
            for page in paginator.paginate():
                for sub in page["Subscriptions"]:
                    endpoint = sub.get("Endpoint", "")
                    if endpoint.startswith("arn:aws") and ":" in endpoint:
                        parts = endpoint.split(":")
                        # The trusted-account allowlist is what makes this a FAIL rather
                        # than noise: a subscription to a partner account you have named
                        # is a decision, one to an account nobody listed is a standing
                        # copy of every message on the topic leaving the estate. Same
                        # gate as LMB-14, AMI-05 and ECS-14.
                        known = {str(a) for a in self.trusted_accounts}
                        known.add(str(self.account))
                        if (len(parts) > 4
                                and parts[4]
                                and parts[4] not in known):
                            topic_name = sub["TopicArn"].split(":")[-1]
                            self._add("FAIL", "SNS-04", "SNS", topic_name,
                                      f"Cross-account subscription | "
                                      f"Topic={topic_name} → Account={parts[4]}"
                                      f" (not this account and not on the "
                                      f"trusted-account list)")
        except Exception as e:
            self._read_failed("SNS-04", "SNS", "sns", "sns:ListSubscriptions", e)

    # ══════════════════════════════════════════════════════════════════════════
    # SECTION 12: AMAZON SQS
    # ══════════════════════════════════════════════════════════════════════════
    def _check_sqs(self):
        self._section_header("SQS")
        sqs = self._client("sqs")

        try:
            queues = sqs.list_queues().get("QueueUrls", [])
        except Exception as e:
            self._read_failed("SQS-01", "SQS", "sqs", "sqs:ListQueues", e)
            return

        if not queues:
            self._add("WARN", "SQS-01", "SQS", "sqs",
                      "No SQS queues found in this region")
            return

        # SQS-01 — Encryption at rest
        self._log("SQS-01: SQS queues — encryption at rest")
        for url in queues:
            name = url.split("/")[-1]
            try:
                attrs = sqs.get_queue_attributes(
                    QueueUrl=url, AttributeNames=["All"]
                )["Attributes"]
                kms = attrs.get("KmsMasterKeyId", "")
                sse = attrs.get("SqsManagedSseEnabled", "false")
                if kms:
                    self._add("PASS", "SQS-01", "SQS", name,
                              f"SSE-KMS={kms} | {name}")
                elif sse.lower() == "true":
                    self._add("PASS", "SQS-01", "SQS", name,
                              f"SSE-SQS (managed) enabled | {name}")
                else:
                    self._add("FAIL", "SQS-01", "SQS", name,
                              f"No encryption at rest | {name}")
            except Exception as e:
                self._read_failed("SQS-01", "SQS", name, "sqs:GetQueueAttributes", e)

        # SQS-02 — Access policy (no unauthenticated public access)
        self._log("SQS-02: SQS queues — no unauthenticated public access")
        for url in queues:
            name = url.split("/")[-1]
            try:
                attrs      = sqs.get_queue_attributes(
                    QueueUrl=url, AttributeNames=["Policy"]
                )["Attributes"]
                policy_str = attrs.get("Policy", "")
                if not policy_str:
                    self._add("WARN", "SQS-02", "SQS", name,
                              f"No resource policy on '{name}' — "
                              "access governed by IAM only")
                    continue
                policy = json.loads(policy_str)
                issues = []
                for stmt in policy.get("Statement", []):
                    effect    = stmt.get("Effect", "")
                    principal = stmt.get("Principal", {})
                    condition = stmt.get("Condition", {})
                    p_val     = (
                        principal
                        if isinstance(principal, str)
                        else principal.get("AWS", "")
                    )
                    if (effect == "Allow"
                            and p_val in ("*", ["*"])
                            and not condition):
                        issues.append(stmt.get("Action", "*"))
                if issues:
                    self._add("FAIL", "SQS-02", "SQS", name,
                              f"Queue '{name}' allows unauthenticated access "
                              f"to: {issues}")
                else:
                    self._add("PASS", "SQS-02", "SQS", name,
                              f"Queue policy OK | {name}")
            except Exception as e:
                self._read_failed("SQS-02", "SQS", name, "sqs:GetQueueAttributes", e)

        # SQS-03 — Dead Letter Queue configured
        self._log("SQS-03: SQS queues — Dead Letter Queue configured")
        for url in queues:
            name = url.split("/")[-1]
            if (name.endswith("-dlq") or name.endswith("_dlq")
                    or "dead" in name.lower()):
                continue  # skip DLQs themselves
            try:
                attrs   = sqs.get_queue_attributes(
                    QueueUrl=url, AttributeNames=["RedrivePolicy"]
                )["Attributes"]
                redrive = attrs.get("RedrivePolicy", "")
                if redrive:
                    dlq_arn = json.loads(redrive).get(
                        "deadLetterTargetArn", "N/A"
                    )
                    self._add("PASS", "SQS-03", "SQS", name,
                              f"DLQ configured | {name} → "
                              f"{dlq_arn.split(':')[-1]}")
                else:
                    self._add("WARN", "SQS-03", "SQS", name,
                              f"No DLQ for queue '{name}' — "
                              "unprocessed messages may be lost")
            except Exception as e:
                self._read_failed("SQS-03", "SQS", name, "sqs:GetQueueAttributes", e)

        # SQS-04 — Message retention and visibility timeout
        self._log("SQS-04: SQS queues — retention and visibility timeout")
        for url in queues:
            name = url.split("/")[-1]
            try:
                attrs = sqs.get_queue_attributes(
                    QueueUrl=url,
                    AttributeNames=["MessageRetentionPeriod",
                                    "VisibilityTimeout"],
                )["Attributes"]
                retention  = int(attrs.get("MessageRetentionPeriod", 0))
                visibility = int(attrs.get("VisibilityTimeout", 0))
                ret_days   = retention / 86400
                if ret_days > 14:
                    self._add("WARN", "SQS-04", "SQS", name,
                              f"Retention={ret_days:.1f}d (>14d may indicate "
                              f"stuck messages) VisibilityTimeout={visibility}s"
                              f" | {name}")
                else:
                    self._add("PASS", "SQS-04", "SQS", name,
                              f"Retention={ret_days:.1f}d "
                              f"VisibilityTimeout={visibility}s | {name}")
            except Exception as e:
                self._read_failed("SQS-04", "SQS", name, "sqs:GetQueueAttributes", e)

    # ══════════════════════════════════════════════════════════════════════════
    # SECTION 13: AMAZON CLOUDFRONT
    # ══════════════════════════════════════════════════════════════════════════
    def _check_cloudfront(self):
        self._section_header("CLOUDFRONT")
        # CloudFront is a global service — must use us-east-1
        cf = self._client("cloudfront", region="us-east-1")

        INSECURE_PROTOS = {"SSLv3", "TLSv1", "TLSv1_2016", "TLSv1.1_2016"}

        try:
            dists = cf.list_distributions().get(
                "DistributionList", {}
            ).get("Items", [])
        except Exception as e:
            self._read_failed("CFN-01", "CLOUDFRONT", "cloudfront",
                              "cloudfront:ListDistributions", e)
            return

        if not dists:
            self._add("WARN", "CFN-01", "CLOUDFRONT", "cloudfront",
                      "No CloudFront distributions found")
            return

        # CFN-01 — HTTPS-only viewer protocol policy
        self._log("CFN-01: CloudFront distributions — HTTPS-only viewer protocol")
        for d in dists:
            did        = d["Id"]
            domain     = d.get("DomainName", did)
            status     = d.get("Status", "Unknown")
            viewer_pol = d.get("DefaultCacheBehavior", {}).get(
                "ViewerProtocolPolicy", "allow-all"
            )
            if viewer_pol == "allow-all":
                self._add("FAIL", "CFN-01", "CLOUDFRONT", domain,
                          f"HTTP allowed (allow-all) | {domain} [{status}]")
            elif viewer_pol == "redirect-to-https":
                self._add("WARN", "CFN-01", "CLOUDFRONT", domain,
                          f"HTTP redirects to HTTPS (consider https-only) "
                          f"| {domain}")
            else:
                self._add("PASS", "CFN-01", "CLOUDFRONT", domain,
                          f"HTTPS-only enforced | {domain} [{status}]")
            for cb in d.get("CacheBehaviors", {}).get("Items", []):
                path = cb.get("PathPattern", "?")
                pol  = cb.get("ViewerProtocolPolicy", "allow-all")
                if pol == "allow-all":
                    self._add("FAIL", "CFN-01", "CLOUDFRONT", domain,
                              f"HTTP allowed on path '{path}' | {domain}")

        # CFN-02 — Minimum TLS version
        self._log("CFN-02: CloudFront — minimum TLS protocol version")
        for d in dists:
            domain      = d.get("DomainName", d["Id"])
            viewer_cert = d.get("ViewerCertificate", {})
            min_proto   = viewer_cert.get("MinimumProtocolVersion", "TLSv1")
            cert_src    = viewer_cert.get("CertificateSource", "cloudfront")
            if min_proto in INSECURE_PROTOS:
                self._add("FAIL", "CFN-02", "CLOUDFRONT", domain,
                          f"Insecure TLS version '{min_proto}' | {domain}")
            else:
                self._add("PASS", "CFN-02", "CLOUDFRONT", domain,
                          f"TLS min={min_proto} cert={cert_src} | {domain}")

        # CFN-03 — WAF Web ACL association
        self._log("CFN-03: CloudFront — WAF Web ACL association")
        for d in dists:
            domain = d.get("DomainName", d["Id"])
            waf    = d.get("WebACLId", "")
            if waf:
                self._add("PASS", "CFN-03", "CLOUDFRONT", domain,
                          f"WAF Web ACL attached | {domain}")
            else:
                self._add("FAIL", "CFN-03", "CLOUDFRONT", domain,
                          f"No WAF Web ACL | {domain} — at risk from OWASP/DDoS")

        # CFN-04 — Access logging
        self._log("CFN-04: CloudFront — access logging enabled")
        for d in dists:
            did    = d["Id"]
            domain = d.get("DomainName", did)
            try:
                config  = cf.get_distribution_config(Id=did)["DistributionConfig"]
                logging = config.get("Logging", {})
                if logging.get("Enabled", False):
                    self._add("PASS", "CFN-04", "CLOUDFRONT", domain,
                              f"Access logging → {logging.get('Bucket', '')} "
                              f"| {domain}")
                else:
                    self._add("FAIL", "CFN-04", "CLOUDFRONT", domain,
                              f"Access logging DISABLED | {domain}")
            except Exception as e:
                self._add("WARN", "CFN-04", "CLOUDFRONT", domain, str(e))

        # CFN-05 — Origin protocol policy (HTTPS to origin)
        self._log("CFN-05: CloudFront — origin protocol (HTTPS to origin)")
        for d in dists:
            domain = d.get("DomainName", d["Id"])
            for origin in d.get("Origins", {}).get("Items", []):
                oid          = origin.get("Id", "N/A")
                custom_cfg   = origin.get("CustomOriginConfig", {})
                origin_proto = custom_cfg.get("OriginProtocolPolicy", "")
                # CFN-06 — origin-side TLS (custom origins only; complements CFN-02 which
                # only checks the VIEWER side). Skip http-only (CFN-05 owns plaintext-to-origin)
                # and S3 origins (no CustomOriginConfig).
                if custom_cfg and origin_proto != "http-only":
                    ssl_protos = set(custom_cfg.get("OriginSslProtocols", {}).get("Items", []))
                    weak = ssl_protos & {"SSLv3", "TLSv1", "TLSv1.1"}
                    if weak:
                        self._add("FAIL", "CFN-06", "CLOUDFRONT", domain,
                                  f"Origin '{oid}' negotiates weak TLS to origin {sorted(weak)} "
                                  f"(policy={origin_proto}) | {domain}")
                    elif ssl_protos:
                        self._add("PASS", "CFN-06", "CLOUDFRONT", domain,
                                  f"Origin '{oid}' negotiates TLS>=1.2 to origin | {domain}")
                    else:
                        self._add("INFO", "CFN-06", "CLOUDFRONT", domain,
                                  f"Origin '{oid}' SSL protocols not reported | {domain}")
                if origin_proto == "http-only":
                    self._add("FAIL", "CFN-05", "CLOUDFRONT", domain,
                              f"Origin '{oid}' uses HTTP-only | {domain}")
                elif origin_proto == "match-viewer":
                    self._add("WARN", "CFN-05", "CLOUDFRONT", domain,
                              f"Origin '{oid}' uses match-viewer "
                              "(may allow HTTP) | {domain}")
                elif origin_proto == "https-only":
                    self._add("PASS", "CFN-05", "CLOUDFRONT", domain,
                              f"Origin '{oid}' enforces HTTPS | {domain}")
                elif not origin_proto:
                    # S3 origins — check OAC/OAI
                    oac_id = origin.get("OriginAccessControlId", "")
                    oai_id = origin.get("S3OriginConfig", {}).get(
                        "OriginAccessIdentity", ""
                    )
                    if oac_id:
                        self._add("PASS", "CFN-05", "CLOUDFRONT", domain,
                                  f"S3 origin '{oid}' uses OAC | {domain}")
                    elif oai_id:
                        self._add("WARN", "CFN-05", "CLOUDFRONT", domain,
                                  f"S3 origin '{oid}' uses legacy OAI "
                                  "(migrate to OAC) | {domain}")
                    else:
                        self._add("FAIL", "CFN-05", "CLOUDFRONT", domain,
                                  f"S3 origin '{oid}' has no OAC/OAI — "
                                  f"bucket may be publicly accessible | {domain}")

    # ══════════════════════════════════════════════════════════════════════════
    # SECTION 14: AMAZON ROUTE 53
    # ══════════════════════════════════════════════════════════════════════════
    def _check_route53(self):
        self._section_header("ROUTE53")
        # Route 53 public APIs are in us-east-1
        r53 = self._client("route53", region="us-east-1")

        # R53-01 — Query logging on hosted zones
        self._log("R53-01: Route 53 hosted zones — query logging")
        try:
            zones = r53.list_hosted_zones()["HostedZones"]
            if not zones:
                self._add("WARN", "R53-01", "ROUTE53", "route53",
                          "No Route 53 hosted zones found")
            try:
                log_configs  = r53.list_query_logging_configs()[
                    "QueryLoggingConfigs"
                ]
                logged_zones = {c["HostedZoneId"] for c in log_configs}
            except Exception:
                logged_zones = set()
            for z in zones:
                zid    = z["Id"].split("/")[-1]
                zname  = z["Name"]
                is_prv = z.get("Config", {}).get("PrivateZone", False)
                tag    = "[private]" if is_prv else "[public]"
                if zid in logged_zones:
                    self._add("PASS", "R53-01", "ROUTE53", zname,
                              f"Query logging enabled | {zname} {tag}")
                elif is_prv:
                    self._add("WARN", "R53-01", "ROUTE53", zname,
                              f"Query logging DISABLED | {zname} {tag}")
                else:
                    self._add("FAIL", "R53-01", "ROUTE53", zname,
                              f"Query logging DISABLED | {zname} {tag}")
        except Exception as e:
            self._read_failed("R53-01", "ROUTE53", "route53",
                              "route53:ListHostedZones", e)

        # R53-02 — DNSSEC signing on public zones
        self._log("R53-02: Route 53 — DNSSEC signing on public hosted zones")
        try:
            zones        = r53.list_hosted_zones()["HostedZones"]
            public_zones = [
                z for z in zones
                if not z.get("Config", {}).get("PrivateZone", False)
            ]
            if not public_zones:
                self._add("WARN", "R53-02", "ROUTE53", "route53",
                          "No public hosted zones found")
            for z in public_zones:
                zid   = z["Id"].split("/")[-1]
                zname = z["Name"]
                try:
                    dnssec = r53.get_dnssec(HostedZoneId=zid)
                    status = dnssec.get("Status", {}).get(
                        "ServeSignature", "NOT_SIGNING"
                    )
                    ksks = dnssec.get("KeySigningKeys", [])
                    if status == "SIGNING":
                        self._add("PASS", "R53-02", "ROUTE53", zname,
                                  f"DNSSEC signing ACTIVE | {zname} "
                                  f"KSKs={len(ksks)}")
                    else:
                        self._add("WARN", "R53-02", "ROUTE53", zname,
                                  f"DNSSEC NOT signing (status={status}) "
                                  f"| {zname} — susceptible to cache poisoning")
                except Exception as de:
                    self._add("WARN", "R53-02", "ROUTE53", zname,
                              f"Could not check DNSSEC for '{zname}': {de}")
        except Exception as e:
            self._read_failed("R53-02", "ROUTE53", "route53", "route53:ListHostedZones", e)

        # R53-03 — Domain transfer lock + auto-renewal
        self._log("R53-03: Route 53 — domain transfer lock and auto-renewal")
        try:
            r53d    = self._client("route53domains", region="us-east-1")
            domains = r53d.list_domains().get("Domains", [])
            if not domains:
                self._add("WARN", "R53-03", "ROUTE53", "domains",
                          "No Route 53 registered domains "
                          "(may be registered elsewhere)")
            for dom in domains:
                dname  = dom["DomainName"]
                detail = r53d.get_domain_detail(DomainName=dname)
                locked     = detail.get("StatusList", [])
                xfer_lock  = "TRANSFER_LOCK" in locked
                auto_renew = detail.get("AutoRenew", False)
                expiry     = str(detail.get("ExpirationDate", "N/A"))[:10]
                if xfer_lock:
                    self._add("PASS", "R53-03", "ROUTE53", dname,
                              f"Transfer lock=ON | {dname} (expires: {expiry})")
                else:
                    self._add("FAIL", "R53-03", "ROUTE53", dname,
                              f"Transfer lock=OFF | {dname} (expires: {expiry})")
                if auto_renew:
                    self._add("PASS", "R53-03", "ROUTE53", dname,
                              f"Auto-renew=ON | {dname}")
                else:
                    self._add("WARN", "R53-03", "ROUTE53", dname,
                              f"Auto-renew=OFF | {dname}")
        except Exception as e:
            self._add("WARN", "R53-03", "ROUTE53", "domains",
                      f"Route 53 Domains — {e}")

        # R53-04 — Health checks
        self._log("R53-04: Route 53 — health checks configured")
        try:
            checks = r53.list_health_checks()["HealthChecks"]
            if not checks:
                self._add("WARN", "R53-04", "ROUTE53", "health-checks",
                          "No Route 53 health checks — failover routing "
                          "may not function")
            else:
                self._add("INFO", "R53-04", "ROUTE53", "health-checks",
                          f"Total health checks: {len(checks)}")
                for hc in checks:
                    hcid  = hc["Id"]
                    cfg   = hc["HealthCheckConfig"]
                    htype = cfg.get("Type", "")
                    port  = cfg.get("Port", 0)
                    if htype == "HTTP" or port == 80:
                        self._add("WARN", "R53-04", "ROUTE53", hcid,
                                  f"Health check {hcid} uses HTTP "
                                  "(port 80) — consider HTTPS")
                    else:
                        self._add("PASS", "R53-04", "ROUTE53", hcid,
                                  f"Health check {hcid} type={htype} "
                                  f"port={port}")
        except Exception as e:
            self._read_failed("R53-04", "ROUTE53", "health-checks",
                              "route53:ListHealthChecks", e)

        # R53-05 — Resolver DNS Firewall + query logging
        self._log("R53-05: Route 53 Resolver — DNS Firewall and query logging")
        try:
            r53r   = self._client("route53resolver")
            assocs = r53r.list_firewall_rule_group_associations().get(
                "FirewallRuleGroupAssociations", []
            )
            if assocs:
                for a in assocs:
                    self._add("PASS", "R53-05", "ROUTE53",
                              a.get("Name", "N/A"),
                              f"DNS Firewall rule group associated | "
                              f"{a.get('Name', 'N/A')} "
                              f"Status={a.get('Status', 'N/A')}")
            else:
                self._add("WARN", "R53-05", "ROUTE53", "dns-firewall",
                          "No Route 53 Resolver DNS Firewall associations — "
                          "DNS exfiltration protection absent")
            configs = r53r.list_resolver_query_log_configs().get(
                "ResolverQueryLogConfigs", []
            )
            active = [c for c in configs if c.get("Status") == "CREATED"]
            if active:
                for c in active:
                    self._add("PASS", "R53-05", "ROUTE53", c["Name"],
                              f"Resolver query logging active | {c['Name']} "
                              f"→ {c.get('DestinationArn', 'N/A').split(':')[-1]}")
            else:
                self._add("FAIL", "R53-05", "ROUTE53", "resolver-logging",
                          "Route 53 Resolver query logging NOT configured — "
                          "DNS activity blind spot")
        except Exception as e:
            self._add("WARN", "R53-05", "ROUTE53", "route53resolver",
                      f"Resolver checks — {e}")

        # R53-06 — dangling DNS records / subdomain takeover
        self._check_dangling_dns()

    def _check_dangling_dns(self) -> None:
        """R53-06 — dangling DNS records / subdomain-takeover risk. S3-website and
        Elastic Beanstalk targets that no longer exist are CONFIRMED takeovers (FAIL +
        internet-CAN_TAKEOVER edge); CloudFront/ELB/API-GW absence can be cross-account,
        so WARN. Read-only: describe/list + a head_bucket existence probe only."""
        self._log("R53-06: dangling DNS records / subdomain takeover")
        try:
            r53 = self._client("route53", region="us-east-1")
            zones = []
            for page in r53.get_paginator("list_hosted_zones").paginate():
                zones.extend(page.get("HostedZones", []))
        except Exception as e:
            self._add("WARN", "R53-06", "ROUTE53", "route53", str(e))
            return
        public_zones = [z for z in zones if not z.get("Config", {}).get("PrivateZone", False)]
        if not public_zones:
            self._add("INFO", "R53-06", "ROUTE53", "route53", "No public hosted zones")
            return
        candidates, seen = [], set()
        for z in public_zones:
            zid = z["Id"].split("/")[-1]
            zname = z.get("Name", "").rstrip(".")
            try:
                for page in r53.get_paginator("list_resource_record_sets").paginate(HostedZoneId=zid):
                    for rr in page.get("ResourceRecordSets", []):
                        rtype = rr.get("Type", "")
                        alias = rr.get("AliasTarget")
                        if alias:
                            if alias.get("HostedZoneId") == zid:
                                continue                        # intra-zone self-alias
                            target = (alias.get("DNSName") or "").rstrip(".").lower()
                        elif rtype == "CNAME" and rr.get("ResourceRecords"):
                            target = (rr["ResourceRecords"][0].get("Value") or "").rstrip(".").lower()
                        else:
                            continue
                        fqdn = rr.get("Name", "").rstrip(".").lower()
                        # Route53 octal-escapes '*' as '\052' in record names
                        if not target or "*" in fqdn or "\\052" in fqdn:
                            continue
                        key = (fqdn, target)
                        if key not in seen:
                            seen.add(key)
                            candidates.append((fqdn, target, rtype, zname))
            except Exception as e:
                self._add("WARN", "R53-06", "ROUTE53", zname, f"could not list records: {e}")
        flagged = sum(1 for c in candidates if self._classify_dangling(*c))
        if flagged == 0 and candidates:
            self._add("PASS", "R53-06", "ROUTE53", "route53",
                      f"No dangling records across {len(public_zones)} public zone(s) "
                      f"({len(candidates)} alias/CNAME records checked)")

    def _classify_dangling(self, fqdn: str, target: str, rtype: str, zname: str) -> bool:
        # matches CNAME form '<bucket>.s3-website-<region>...' AND the ALIAS bare
        # regional endpoint 's3-website.<region>...' / 's3-website-<region>...'
        if re.search(r"(^|\.)s3-website[.-]", target):
            return self._dangling_s3(fqdn, target, rtype, zname)
        if target.endswith(".elasticbeanstalk.com"):
            return self._dangling_beanstalk(fqdn, target, rtype, zname)
        if target.endswith(".cloudfront.net"):
            return self._dangling_cloudfront(fqdn, target, rtype, zname)
        if target.endswith(".elb.amazonaws.com"):
            return self._dangling_elb(fqdn, target, rtype, zname)
        if ".execute-api." in target:
            self._add("WARN", "R53-06", "ROUTE53", fqdn,
                      f"API Gateway alias {target} — manually verify the API/custom domain "
                      f"still exists | zone {zname}")
            return True
        return False

    def _emit_dangling(self, fqdn, target, rtype, zname, service, confirmed) -> None:
        g = self._ensure_graph()
        g.add_node(fqdn, "DanglingDNSRecord", record_type=rtype, dangling_target=target,
                   dangling_service=service, zone_name=zname,
                   confidence="confirmed" if confirmed else "probable", scan_source="route53")
        if confirmed:
            g.add_node("internet", "InternetSource", cidr="0.0.0.0/0")
            g.add_edge("internet", fqdn, "CAN_TAKEOVER", dangling_service=service,
                       confidence="confirmed", scan_source="route53")

    @staticmethod
    def _s3_error_code(e) -> str:
        if hasattr(e, "response"):
            return ((getattr(e, "response", {}) or {}).get("Error", {}) or {}).get("Code", "")
        s = str(e)
        for c in ("NoSuchBucket", "NotFound", "AccessDenied", "Forbidden", "404", "403"):
            if c in s:
                return c
        return ""

    def _dangling_s3(self, fqdn, target, rtype, zname) -> bool:
        bucket = fqdn                       # S3 website hosting requires bucket name == FQDN
        s3 = self._client("s3")
        try:
            if bucket in {b["Name"].lower() for b in s3.list_buckets().get("Buckets", [])}:
                return False                # bucket exists in this account
        except Exception:
            pass
        try:
            s3.head_bucket(Bucket=bucket)
            return False                    # exists (200)
        except Exception as e:
            code = self._s3_error_code(e)
            if code in ("404", "NoSuchBucket", "NotFound"):
                self._emit_dangling(fqdn, target, rtype, zname, "s3-website", True)
                self._add("FAIL", "R53-06", "ROUTE53", fqdn,
                          f"S3-website bucket '{bucket}' does not exist — subdomain {fqdn} is "
                          f"TAKEABLE (S3 names are globally re-registerable) | zone {zname}")
                return True
            if code in ("403", "Forbidden", "AccessDenied"):
                self._add("WARN", "R53-06", "ROUTE53", fqdn,
                          f"S3-website bucket '{bucket}' exists outside this account — verify "
                          f"ownership (possible takeover) | zone {zname}")
                return True
            self._add("WARN", "R53-06", "ROUTE53", fqdn,
                      f"could not confirm S3-website target {bucket} — manually verify | zone {zname}")
            return True

    def _dangling_beanstalk(self, fqdn, target, rtype, zname) -> bool:
        m = re.search(r"\.([a-z]{2}-[a-z]+-\d+)\.elasticbeanstalk\.com$", target)
        if not m:
            self._add("WARN", "R53-06", "ROUTE53", fqdn,
                      f"legacy non-regionalized Elastic Beanstalk name {target} — manually "
                      f"verify | zone {zname}")
            return True
        region = m.group(1)
        try:
            eb = self._client("elasticbeanstalk", region=region)
            live, tok = set(), None
            while True:
                kw = {"NextToken": tok} if tok else {}
                resp = eb.describe_environments(**kw)
                for e in resp.get("Environments", []):
                    if e.get("Status") not in ("Terminated", "Terminating"):
                        cn = (e.get("CNAME") or "").rstrip(".").lower()
                        if cn:
                            live.add(cn)
                tok = resp.get("NextToken")
                if not tok:
                    break
        except Exception as e:
            self._add("WARN", "R53-06", "ROUTE53", fqdn,
                      f"could not verify Elastic Beanstalk target {target}: {e} | zone {zname}")
            return True
        if target in live:
            return False
        self._emit_dangling(fqdn, target, rtype, zname, "elasticbeanstalk", True)
        self._add("FAIL", "R53-06", "ROUTE53", fqdn,
                  f"Elastic Beanstalk env for {target} is gone/terminated — subdomain {fqdn} "
                  f"is TAKEABLE (EB CNAME re-registerable in {region}) | zone {zname}")
        return True

    def _dangling_cloudfront(self, fqdn, target, rtype, zname) -> bool:
        try:
            cf = self._client("cloudfront", region="us-east-1")
            dom_aliases = {}
            for page in cf.get_paginator("list_distributions").paginate():
                for d in (page.get("DistributionList", {}) or {}).get("Items", []):
                    dom_aliases[(d.get("DomainName") or "").lower()] = {
                        a.lower() for a in (d.get("Aliases", {}) or {}).get("Items", [])}
        except Exception as e:
            self._add("WARN", "R53-06", "ROUTE53", fqdn,
                      f"could not verify CloudFront target {target}: {e} | zone {zname}")
            return True
        if target in dom_aliases:
            if fqdn in dom_aliases[target]:
                return False                # properly associated
            self._emit_dangling(fqdn, target, rtype, zname, "cloudfront", False)
            self._add("WARN", "R53-06", "ROUTE53", fqdn,
                      f"CloudFront distribution {target} exists but {fqdn} is NOT in its "
                      f"alternate-domain list — serves error / takeover-adjacent | zone {zname}")
            return True
        self._emit_dangling(fqdn, target, rtype, zname, "cloudfront", False)
        self._add("WARN", "R53-06", "ROUTE53", fqdn,
                  f"CloudFront target {target} not owned by this account — deleted or "
                  f"cross-account; manually verify | zone {zname}")
        return True

    def _dangling_elb(self, fqdn, target, rtype, zname) -> bool:
        norm = target[len("dualstack."):] if target.startswith("dualstack.") else target
        m = re.search(r"\.([a-z]{2}-[a-z]+-\d+)\.elb\.amazonaws\.com$", norm)
        if not m:
            self._add("WARN", "R53-06", "ROUTE53", fqdn,
                      f"could not parse region from ELB target {target} — manually verify "
                      f"| zone {zname}")
            return True
        region = m.group(1)
        names = set()
        try:
            for page in self._client("elbv2", region=region).get_paginator(
                    "describe_load_balancers").paginate():
                for lb in page.get("LoadBalancers", []):
                    names.add((lb.get("DNSName") or "").lower())
        except Exception:
            pass
        try:
            for page in self._client("elb", region=region).get_paginator(
                    "describe_load_balancers").paginate():
                for d in page.get("LoadBalancerDescriptions", []):
                    names.add((d.get("DNSName") or "").lower())
        except Exception:
            pass
        if norm in names:
            return False
        self._emit_dangling(fqdn, target, rtype, zname, "elb", False)
        self._add("WARN", "R53-06", "ROUTE53", fqdn,
                  f"ELB DNS name {target} not present in {region} — LB deleted; AWS may "
                  f"recycle the name (takeover) | zone {zname}")
        return True

    # ══════════════════════════════════════════════════════════════════════════
    # SECTION 15: AWS BEDROCK
    # ══════════════════════════════════════════════════════════════════════════
    def _check_bedrock(self):
        self._section_header("BEDROCK")
        self._aispm_region_coverage_note()
        try:
            bedrock = self._client("bedrock")
        except Exception as e:
            self._add("WARN", "BDR-01", "BEDROCK", "bedrock",
                      f"Bedrock client error: {e}")
            return

        # BDR-01 — Model invocation logging
        self._log("BDR-01: Bedrock — model invocation logging")
        try:
            config = bedrock.get_model_invocation_logging_configuration().get(
                "loggingConfig", {}
            )
            if not config:
                self._add("FAIL", "BDR-01", "BEDROCK", "bedrock",
                          "Model invocation logging NOT configured — "
                          "no audit trail for LLM calls")
            else:
                cw = config.get("cloudWatchConfig", {}).get("logGroupName", "")
                s3 = config.get("s3Config", {}).get("bucketName", "")
                if cw or s3:
                    dest = f"CW={cw}" if cw else f"S3={s3}"
                    self._add("PASS", "BDR-01", "BEDROCK", "bedrock",
                              f"Invocation logging enabled → {dest}")
                    if not config.get("textDataDeliveryEnabled", False):
                        self._add("WARN", "BDR-01", "BEDROCK", "bedrock",
                                  "Text data delivery logging is disabled — "
                                  "prompt/response content not captured")
                else:
                    self._add("FAIL", "BDR-01", "BEDROCK", "bedrock",
                              "Invocation logging config present but "
                              "no destination (CW/S3) configured")
        except Exception as e:
            # A DENIED read is not an ABSENT service. Reporting AccessDenied as
            # "may not be available in this region" tells the operator the account
            # has no Bedrock when in fact we were refused — the one failure mode
            # that looks like a clean result. INFO carries no severity weight, so
            # an un-evaluated check never penalises the score either.
            if self._is_access_denied(e):
                self._add("INFO", "BDR-01", "BEDROCK", "bedrock",
                          "Model invocation logging NOT evaluated — missing permission "
                          "bedrock:GetModelInvocationLoggingConfiguration (no phantom pass)")
            else:
                self._add("WARN", "BDR-01", "BEDROCK", "bedrock",
                          f"Bedrock may not be available in this region: {e}")

        # BDR-02 — Guardrails configured
        self._log("BDR-02: Bedrock — Guardrails configured")
        try:
            guardrails = bedrock.list_guardrails().get("guardrails", [])
            if not guardrails:
                self._add("FAIL", "BDR-02", "BEDROCK", "bedrock",
                          "No Bedrock Guardrails — prompt injection, PII, "
                          "and content risks unmitigated")
            else:
                for g in guardrails:
                    self._add("PASS", "BDR-02", "BEDROCK",
                              g.get("name", "N/A"),
                              f"Guardrail '{g.get('name')}' "
                              f"id={g.get('id')} status={g.get('status')}")
        except Exception as e:
            self._add("WARN", "BDR-02", "BEDROCK", "bedrock", str(e))

        # AIGRD-01/02/04 — grade what BDR-02 only counted.
        self._grade_guardrails(bedrock)

        # BDR-03 — Custom model KMS encryption
        self._log("BDR-03: Bedrock — custom model encryption (KMS)")
        try:
            models = bedrock.list_custom_models().get("modelSummaries", [])
            if not models:
                self._add("INFO", "BDR-03", "BEDROCK", "bedrock",
                          "No custom Bedrock models found")
            else:
                for m in models:
                    mname = m.get("modelName", "N/A")
                    marn  = m.get("modelArn", "")
                    try:
                        detail = bedrock.get_custom_model(
                            modelIdentifier=marn
                        )
                        kms = detail.get("modelKmsKeyArn", "")
                        if kms:
                            self._add("PASS", "BDR-03", "BEDROCK", mname,
                                      f"KMS=CUSTOMER "
                                      f"({kms.split('/')[-1]}) | {mname}")
                        else:
                            self._add("WARN", "BDR-03", "BEDROCK", mname,
                                      f"KMS=AWS-managed | {mname}")
                    except Exception:
                        self._add("WARN", "BDR-03", "BEDROCK", mname,
                                  f"Could not get KMS details for '{mname}'")
        except Exception as e:
            self._add("WARN", "BDR-03", "BEDROCK", "bedrock", str(e))

        # BDR-04 — VPC endpoint (PrivateLink)
        self._log("BDR-04: Bedrock — VPC endpoint (PrivateLink)")
        try:
            ec2 = self._client("ec2")
            eps = ec2.describe_vpc_endpoints(
                Filters=[
                    {"Name": "service-name",        "Values": ["*bedrock*"]},
                    {"Name": "vpc-endpoint-state",   "Values": ["available",
                                                                 "pending"]},
                ]
            )["VpcEndpoints"]
            if eps:
                for ep in eps:
                    svc = ep["ServiceName"].split(".")[-1]
                    self._add("PASS", "BDR-04", "BEDROCK",
                              ep["VpcEndpointId"],
                              f"Bedrock VPC endpoint | "
                              f"{ep['VpcEndpointId']} svc={svc}")
            else:
                self._add("WARN", "BDR-04", "BEDROCK", "bedrock",
                          "No Bedrock VPC endpoints — traffic uses public "
                          "internet; consider PrivateLink for data isolation")
        except Exception as e:
            self._read_failed("BDR-04", "BEDROCK", "bedrock",
                              "ec2:DescribeVpcEndpoints", e)

        # BDR-05 — IAM least privilege for Bedrock
        self._log("BDR-05: Bedrock — IAM permissions wildcard check")
        try:
            iam          = self._client("iam")
            paginator    = iam.get_paginator("list_policies")
            found_issues = False
            for page in paginator.paginate(Scope="Local"):
                for policy in page["Policies"]:
                    parn = policy["Arn"]
                    vid  = policy["DefaultVersionId"]
                    try:
                        doc = iam.get_policy_version(
                            PolicyArn=parn, VersionId=vid
                        )["PolicyVersion"]["Document"]
                        for stmt in doc.get("Statement", []):
                            if stmt.get("Effect") != "Allow":
                                continue
                            actions  = stmt.get("Action", [])
                            resource = stmt.get("Resource", "")
                            if isinstance(actions, str):
                                actions = [actions]
                            bedrock_wild = any(
                                a in ("bedrock:*", "*") for a in actions
                            )
                            broad_invoke = (
                                any(a == "bedrock:InvokeModel" for a in actions)
                                and resource == "*"
                            )
                            if bedrock_wild or broad_invoke:
                                # FAIL, not WARN. A customer-managed policy allowing
                                # bedrock:* (or * ) on * is a definite over-grant, the
                                # same class the IAM checks already FAIL for -- and
                                # until this line changed, BDR-05's only FAIL was its
                                # own error handler, so its declared HIGH was reachable
                                # only by iam:ListPolicies throwing.
                                self._add("FAIL", "BDR-05", "BEDROCK",
                                          policy["PolicyName"],
                                          f"Overly broad Bedrock permission in "
                                          f"policy '{policy['PolicyName']}' "
                                          f"Action={actions} "
                                          f"Resource={resource}")
                                found_issues = True
                    except Exception:
                        pass
            if not found_issues:
                self._add("PASS", "BDR-05", "BEDROCK", "iam",
                          "No wildcard Bedrock permissions in "
                          "customer-managed policies")
        except Exception as e:
            self._read_failed("BDR-05", "BEDROCK", "iam", "iam:ListPolicies", e)

    # ══════════════════════════════════════════════════════════════════════════
    # SECTION 16: AWS BEDROCK AGENT CORE
    # ══════════════════════════════════════════════════════════════════════════
    def _check_bedrock_knowledge_bases(self, ba):
        """AGT-03 — Bedrock Knowledge Base encryption + data-source encryption.

        HOISTED out of ``for a in agents:``. Knowledge Bases are account-level, not
        agent-level, so nesting this produced one duplicate finding set PER AGENT —
        and, worse, it sat behind the ``if not agents: return`` early exit, so an
        account doing pure RAG (knowledge bases, no agents) was scanned as if it had
        no AI footprint at all. Runs before the agent enumeration so neither an
        empty agent list nor a failed ``list_agents`` can hide it.

        Guards are PER ITEM on purpose: ``bedrock:GetKnowledgeBase`` is not granted
        by SecurityAudit, so a single denial would otherwise abort the whole sweep
        at the first knowledge base and report nothing for the rest.
        """
        try:
            kbs = ba.list_knowledge_bases().get("knowledgeBaseSummaries", [])
        except Exception as e:
            if self._is_access_denied(e):
                self._add("INFO", "AGT-03", "BEDROCK_AGENTS", "bedrock-agent",
                          "Knowledge Bases NOT evaluated — missing permission "
                          "bedrock:ListKnowledgeBases (no phantom pass)")
            else:
                self._add("WARN", "AGT-03", "BEDROCK_AGENTS", "bedrock-agent", str(e))
            return

        if not kbs:
            self._add("INFO", "AGT-03", "BEDROCK_AGENTS", "bedrock-agent",
                      "No Bedrock Knowledge Bases found")
            return

        for kb in kbs:
            kbid   = kb["knowledgeBaseId"]
            kbname = kb.get("name", kbid)
            try:
                kb_detail = ba.get_knowledge_base(
                    knowledgeBaseId=kbid
                )["knowledgeBase"]
                kms_kb = kb_detail.get(
                    "serverSideEncryptionConfiguration", {}
                ).get("kmsKeyArn", "")
                if kms_kb:
                    self._add("PASS", "AGT-03", "BEDROCK_AGENTS", kbname,
                              f"KB '{kbname}' KMS=SET "
                              f"Status={kb.get('status', 'N/A')}")
                else:
                    self._add("WARN", "AGT-03", "BEDROCK_AGENTS", kbname,
                              f"KB '{kbname}' KMS=AWS-managed "
                              f"Status={kb.get('status', 'N/A')}")
            except Exception as e:
                if self._is_access_denied(e):
                    self._add("INFO", "AGT-03", "BEDROCK_AGENTS", kbname,
                              f"KB '{kbname}' encryption NOT evaluated — missing "
                              "permission bedrock:GetKnowledgeBase")
                else:
                    self._add("WARN", "AGT-03", "BEDROCK_AGENTS", kbname, str(e))

            try:
                sources = ba.list_data_sources(
                    knowledgeBaseId=kbid
                ).get("dataSourceSummaries", [])
            except Exception as e:
                self._add("INFO", "AGT-03", "BEDROCK_AGENTS", kbname,
                          f"Data sources for '{kbname}' NOT evaluated: {e}")
                continue

            ds_details, write_scopes = [], {}
            for ds in sources:
                dsid   = ds["dataSourceId"]
                dsname = ds.get("name", dsid)
                try:
                    ds_detail = ba.get_data_source(
                        knowledgeBaseId=kbid, dataSourceId=dsid
                    )["dataSource"]
                    # Slice 3.1 — the same response, read for a second question: is this
                    # a path for content the account does not author?
                    ds_details.append(ds_detail)
                    _cfg = ds_detail.get("dataSourceConfiguration") or {}
                    if str(_cfg.get("type") or "").upper() == "S3":
                        _b = (_cfg.get("s3Configuration") or {}).get("bucketArn")
                        _scope = self._bucket_write_scope(_b)
                        if _scope:
                            write_scopes[dsid] = _scope
                    ds_kms = ds_detail.get(
                        "serverSideEncryptionConfiguration", {}
                    ).get("kmsKeyArn", "")
                    if ds_kms:
                        self._add("PASS", "AGT-03", "BEDROCK_AGENTS", dsname,
                                  f"DataSource '{dsname}' KMS=SET")
                    else:
                        self._add("WARN", "AGT-03", "BEDROCK_AGENTS", dsname,
                                  f"DataSource '{dsname}' KMS=not set")
                except Exception as e:
                    self._add("INFO", "AGT-03", "BEDROCK_AGENTS", dsname,
                              f"DataSource '{dsname}' NOT evaluated: {e}")
            if ds_details:
                self._kb_surface[str(kbid)] = aws_toxicflow.injection_surface(
                    ds_details, write_scopes)

    def _check_bedrock_agents(self):
        self._section_header("BEDROCK_AGENTS")
        self._aispm_region_coverage_note()
        try:
            ba = self._client("bedrock-agent")
        except Exception as e:
            self._add("WARN", "AGT-01", "BEDROCK_AGENTS", "bedrock-agent",
                      f"Bedrock Agent client error: {e}")
            return

        # Knowledge Bases FIRST: they are account-level, they are the entire AI
        # surface of a RAG-only account, and nothing about them depends on an agent
        # existing or on list_agents succeeding.
        self._check_bedrock_knowledge_bases(ba)

        try:
            agents = ba.list_agents().get("agentSummaries", [])
        except Exception as e:
            if self._is_access_denied(e):
                self._add("INFO", "AGT-01", "BEDROCK_AGENTS", "bedrock-agent",
                          "Bedrock Agents NOT evaluated — missing permission "
                          "bedrock:ListAgents (no phantom pass)")
            else:
                self._add("WARN", "AGT-01", "BEDROCK_AGENTS", "bedrock-agent",
                          f"Bedrock Agents may not be available in this region: {e}")
            return

        if not agents:
            self._add("INFO", "AGT-01", "BEDROCK_AGENTS", "bedrock-agent",
                      "No Bedrock Agents found in this region")
            return

        iam = self._client("iam")
        lmb = self._client("lambda")

        for a in agents:
            aid   = a["agentId"]
            aname = a.get("agentName", aid)
            try:
                detail = ba.get_agent(agentId=aid)["agent"]
            except Exception as e:
                self._add("WARN", "AGT-01", "BEDROCK_AGENTS", aname,
                          f"Could not get details for agent '{aname}': {e}")
                continue

            # AGT-01 — KMS encryption
            kms    = detail.get("customerEncryptionKeyArn", "")
            status = detail.get("agentStatus", "N/A")
            if kms:
                self._add("PASS", "AGT-01", "BEDROCK_AGENTS", aname,
                          f"KMS=CUSTOMER ({kms.split('/')[-1]}) "
                          f"Status={status} | {aname}")
            else:
                self._add("WARN", "AGT-01", "BEDROCK_AGENTS", aname,
                          f"KMS=AWS-managed Status={status} | {aname}")

            # AGT-02 — IAM execution role least privilege
            role_arn = detail.get("agentResourceRoleArn", "")
            # AI-SPM stash — agent execution-role blast radius (no VPC surface -> not net-checkable)
            self._aispm_resources.append({
                "kind": "BedrockAgent", "name": aname,
                "arn": detail.get("agentArn"),
                "role_arn": role_arn or None,
                "network_checkable": False,
                "network": {},
                "data_bearing": False,
                # Read here rather than at AGT-05 so guardrail COVERAGE can be computed
                # over the whole estate, not just per agent — an account with no
                # guardrails at all has no per-agent gap to report and would otherwise
                # produce silence where the answer is "none of them".
                "guardrail_id": (detail.get("guardrailConfiguration") or {}).get(
                    "guardrailIdentifier", ""),
            })
            if not role_arn:
                self._add("FAIL", "AGT-02", "BEDROCK_AGENTS", aname,
                          f"No execution role found for agent '{aname}'")
            else:
                role_name = role_arn.split("/")[-1]
                self._add("PASS", "AGT-02", "BEDROCK_AGENTS", aname,
                          f"Agent '{aname}' uses role '{role_name}'")
                try:
                    inline = iam.list_role_policies(
                        RoleName=role_name
                    ).get("PolicyNames", [])
                    for pname in inline:
                        doc = iam.get_role_policy(
                            RoleName=role_name, PolicyName=pname
                        )["PolicyDocument"]
                        for stmt in doc.get("Statement", []):
                            if stmt.get("Effect") == "Allow":
                                actions  = stmt.get("Action", [])
                                resource = stmt.get("Resource", "")
                                if isinstance(actions, str):
                                    actions = [actions]
                                if "*" in actions or (
                                    resource == "*"
                                    and any(
                                        "bedrock" in str(act)
                                        for act in actions
                                    )
                                ):
                                    self._add("WARN", "AGT-02",
                                              "BEDROCK_AGENTS", aname,
                                              f"Agent '{aname}' role "
                                              f"'{role_name}' policy "
                                              f"'{pname}' has broad "
                                              "permissions")
                except Exception as e:
                    self._add("WARN", "AGT-02", "BEDROCK_AGENTS", aname,
                              f"Could not audit role for '{aname}': {e}")


            # AGT-04 — Action Group Lambda security
            try:
                groups = ba.list_agent_action_groups(
                    agentId=aid, agentVersion="DRAFT"
                ).get("actionGroupSummaries", [])
                agency_groups = []          # slice 2.4 — assessed after the loop
                for grp in groups:
                    gname = grp.get("actionGroupName", "N/A")
                    gid   = grp.get("actionGroupId", "")
                    grp_detail = ba.get_agent_action_group(
                        agentId=aid, agentVersion="DRAFT", actionGroupId=gid
                    )["agentActionGroup"]
                    agency_groups.append(grp_detail)
                    lambda_arn = grp_detail.get(
                        "actionGroupExecutor", {}
                    ).get("lambda", "")
                    if lambda_arn:
                        fn_name = lambda_arn.split(":")[-1]
                        self._agent_lambda_names.add(fn_name)
                        try:
                            pol_doc = json.loads(
                                lmb.get_policy(
                                    FunctionName=fn_name
                                )["Policy"]
                            )
                            for stmt in pol_doc.get("Statement", []):
                                p_val = str(stmt.get("Principal", {}))
                                if (stmt.get("Effect") == "Allow"
                                        and "*" in p_val):
                                    self._add("FAIL", "AGT-04",
                                              "BEDROCK_AGENTS", fn_name,
                                              f"Lambda '{fn_name}' for "
                                              f"'{gname}' has wildcard "
                                              "invoke principal")
                                else:
                                    self._add("PASS", "AGT-04",
                                              "BEDROCK_AGENTS", fn_name,
                                              f"Lambda '{fn_name}' policy "
                                              f"scoped | {gname}")
                        except lmb.exceptions.ResourceNotFoundException:
                            self._add("PASS", "AGT-04", "BEDROCK_AGENTS",
                                      fn_name,
                                      f"Lambda '{fn_name}' no resource "
                                      f"policy (IAM-only) | {gname}")
                # AGY-01/02/03 — excessive agency, from the detail just read
                self._emit_agency(aname, agency_groups)
                # Slice 3.1 — the same assessment, kept for the toxic-flow computation
                # so it is not recomputed from a second fetch.
                self._stash_flow_inputs(ba, aid, aname, detail, agency_groups)
                # TPOIS-01/02/03 — the same descriptions, read for what they say
                # to the MODEL rather than for what they document.
                self._emit_tool_poisoning(aname, agency_groups)
                # AMEM-01 — how long an injected instruction keeps being read back
                self._emit_agent_memory(aname, detail)
            except Exception as e:
                self._add("WARN", "AGT-04", "BEDROCK_AGENTS", aname,
                          f"Could not audit action groups for "
                          f"'{aname}': {e}")

            # AGT-05 — Guardrail on agent + session TTL
            try:
                bedrock = self._client("bedrock")
                grail   = detail.get(
                    "guardrailConfiguration", {}
                ).get("guardrailIdentifier", "")
                if grail:
                    self._add("PASS", "AGT-05", "BEDROCK_AGENTS", aname,
                              f"Guardrail applied to agent '{aname}' "
                              f"(id={grail})")
                else:
                    self._add("FAIL", "AGT-05", "BEDROCK_AGENTS", aname,
                              f"No Guardrail on agent '{aname}' — "
                              "prompt injection and content policy "
                              "risks unmitigated")
                session_ttl = detail.get("idleSessionTTLInSeconds", 0)
                if session_ttl > 3600:
                    self._add("WARN", "AGT-05", "BEDROCK_AGENTS", aname,
                              f"Session TTL={session_ttl}s (>3600s) on "
                              f"'{aname}' — long session window "
                              "increases hijack risk")
                else:
                    self._add("PASS", "AGT-05", "BEDROCK_AGENTS", aname,
                              f"Session TTL={session_ttl}s | {aname}")
            except Exception as e:
                self._add("WARN", "AGT-05", "BEDROCK_AGENTS", aname, str(e))

    # ══════════════════════════════════════════════════════════════════════════
    # SECTION 17: AWS LAMBDA
    # ══════════════════════════════════════════════════════════════════════════
    def _check_lambda(self):
        self._section_header("LAMBDA")
        lmb = self._client("lambda")

        try:
            paginator = lmb.get_paginator("list_functions")
            funcs = []
            for page in paginator.paginate():
                funcs.extend(page["Functions"])
        except Exception as e:
            self._read_failed("LMB-01", "LAMBDA", "lambda", "lambda:ListFunctions", e)
            return
        if not funcs:
            self._add("INFO", "LMB-01", "LAMBDA", "lambda",
                      "No Lambda functions in this region")
            return

        # LMB-01 — Public access via resource policy
        self._log("LMB-01: Lambda functions — public access check")
        for fn in funcs:
            fname = fn["FunctionName"]
            try:
                pol = json.loads(lmb.get_policy(FunctionName=fname)["Policy"])
                for stmt in pol.get("Statement", []):
                    p = stmt.get("Principal", {})
                    p_val = p if isinstance(p, str) else p.get("AWS", "")
                    if stmt.get("Effect") == "Allow" and p_val == "*" \
                            and not stmt.get("Condition"):
                        self._add("FAIL", "LMB-01", "LAMBDA", fname,
                                  f"Lambda '{fname}' has public invoke access")
            except ClientError as e:
                if e.response["Error"]["Code"] != "ResourceNotFoundException":
                    self._add("WARN", "LMB-01", "LAMBDA", fname, str(e))

        # LMB-02 — VPC connectivity
        self._log("LMB-02: Lambda functions — VPC configuration")
        for fn in funcs:
            fname = fn["FunctionName"]
            vpc = fn.get("VpcConfig", {})
            if not vpc or not vpc.get("SubnetIds"):
                self._add("WARN", "LMB-02", "LAMBDA", fname,
                          f"Lambda '{fname}' not in VPC — has public internet access")

        # LMB-03 — Environment variable secrets
        self._log("LMB-03: Lambda functions — plaintext secrets in env vars")
        secret_patterns = ["PASSWORD", "SECRET", "API_KEY", "TOKEN",
                           "DB_PASS", "PRIVATE_KEY", "CREDENTIALS"]
        for fn in funcs:
            fname = fn["FunctionName"]
            env = fn.get("Environment", {}).get("Variables", {})
            for k in env:
                if any(p in k.upper() for p in secret_patterns):
                    self._add("FAIL", "LMB-03", "LAMBDA", fname,
                              f"Potential secret in env var '{k}' on '{fname}'"
                              " — use Secrets Manager or SSM Parameter Store")
                    break

        # LMB-04 — Deprecated runtime
        self._log("LMB-04: Lambda functions — deprecated runtimes")
        deprecated = {"python2.7", "python3.6", "python3.7", "nodejs10.x",
                      "nodejs12.x", "dotnetcore2.1", "dotnetcore3.1",
                      "ruby2.5", "ruby2.7", "java8", "go1.x"}
        for fn in funcs:
            fname = fn["FunctionName"]
            runtime = fn.get("Runtime", "")
            if runtime in deprecated:
                self._add("FAIL", "LMB-04", "LAMBDA", fname,
                          f"Deprecated runtime '{runtime}' on '{fname}'")

        # LMB-05 — Reserved concurrency / throttle protection
        self._log("LMB-05: Lambda functions — reserved concurrency")
        for fn in funcs:
            fname = fn["FunctionName"]
            try:
                cc = lmb.get_function_concurrency(FunctionName=fname)
                if cc.get("ReservedConcurrentExecutions") is None:
                    self._add("WARN", "LMB-05", "LAMBDA", fname,
                              f"No reserved concurrency on '{fname}'")
            except Exception:
                pass

        # LMB-06 — code-signing enforcement (supply-chain integrity). Absent config is the
        # common default -> INFO aggregate only (a per-fn WARN would be noise). Enforce=PASS,
        # Warn=FAIL (configured but not enforced). Denied read -> unknown, which downgrades
        # the closing INFO to WARN (never a false all-clear from denied reads).
        self._log("LMB-06: Lambda functions — code signing enforcement")
        unsigned, unknown, evaluated = 0, 0, 0
        for fn in funcs:
            fname = fn["FunctionName"]
            try:
                csc_arn = lmb.get_function_code_signing_config(
                    FunctionName=fname).get("CodeSigningConfigArn")
            except Exception:
                unknown += 1
                continue
            evaluated += 1
            if not isinstance(csc_arn, str) or not csc_arn:
                unsigned += 1                          # missing arn == unsigned (common default)
                continue
            try:
                mode = (lmb.get_code_signing_config(CodeSigningConfigArn=csc_arn)
                        ["CodeSigningConfig"]["CodeSigningPolicies"]
                        ["UntrustedArtifactOnDeployment"])
            except Exception:
                unknown += 1
                continue
            if not isinstance(mode, str):
                unknown += 1
            elif mode == "Enforce":
                self._add("PASS", "LMB-06", "LAMBDA", fname,
                          f"Lambda '{fname}' enforces code signing")
            else:
                self._add("FAIL", "LMB-06", "LAMBDA", fname,
                          f"Lambda '{fname}' has code signing configured but "
                          f"UntrustedArtifactOnDeployment={mode} — unsigned/tampered code "
                          f"deploys with only a warning (not enforced)")
        if unknown:
            self._add("WARN", "LMB-06", "LAMBDA", "lambda",
                      f"Code-signing status undetermined for {unknown} function(s) (read "
                      f"denied); {unsigned}/{evaluated} evaluated have no code-signing config")
        elif unsigned:
            self._add("INFO", "LMB-06", "LAMBDA", "lambda",
                      f"{unsigned}/{evaluated} Lambda functions have no code-signing config")

        # LMB-08 / LMB-09 — Lambda function URLs. One extra API call per function
        # answers both: AuthType (is the endpoint anonymous?) and Cors (can any site
        # read its responses?). A function with no URL is not a finding, so the
        # ResourceNotFoundException path is silent rather than a PASS — most
        # functions have no URL and a per-function PASS would bury the ones that do.
        self._log("LMB-08/LMB-09: Lambda function URLs — auth type and CORS origins")
        urls_seen = 0
        undetermined = 0
        for fn in funcs:
            fname = fn["FunctionName"]
            try:
                cfg = lmb.get_function_url_config(FunctionName=fname)
            except Exception as e:
                # Read the error code off the exception rather than catching the
                # botocore type by name: `ClientError` is only bound when boto3
                # imported, so `except ClientError` would raise NameError here on
                # the COMMON path — most functions have no URL and answer with
                # ResourceNotFoundException.
                resp = getattr(e, "response", None)
                code = ""
                if isinstance(resp, dict):
                    code = str((resp.get("Error") or {}).get("Code") or "")
                if code != "ResourceNotFoundException":
                    undetermined += 1
                continue
            if not isinstance(cfg, dict):
                undetermined += 1
                continue
            urls_seen += 1

            auth = str(cfg.get("AuthType") or "").strip()
            if auth == "AWS_IAM":
                self._add("PASS", "LMB-08", "LAMBDA", fname,
                          f"Function URL on '{fname}' requires AWS_IAM authentication")
            elif auth:
                self._add("FAIL", "LMB-08", "LAMBDA", fname,
                          f"Function URL on '{fname}' has AuthType={auth} — an "
                          f"internet-reachable HTTPS endpoint that requires no AWS "
                          f"authentication")
            else:
                undetermined += 1

            cors = cfg.get("Cors")
            if isinstance(cors, dict):
                origins = [str(o) for o in (cors.get("AllowOrigins") or [])]
                if "*" in origins:
                    creds = bool(cors.get("AllowCredentials"))
                    self._add("FAIL", "LMB-09", "LAMBDA", fname,
                              f"Function URL on '{fname}' allows CORS origin '*'"
                              + (" WITH AllowCredentials=true — any site can make "
                                 "credentialed cross-origin calls and read the "
                                 "response" if creds else
                                 " — any site can read this endpoint's responses"))
                elif origins:
                    self._add("PASS", "LMB-09", "LAMBDA", fname,
                              f"Function URL CORS on '{fname}' is scoped to "
                              f"{len(origins)} explicit origin(s)")

        if undetermined:
            # Never a silent clean: a denied read is not the same as a safe config.
            self._add("WARN", "LMB-08", "LAMBDA", "lambda",
                      f"Function-URL configuration undetermined for {undetermined} "
                      f"function(s) (read denied or malformed) — not assessed, not clean")
        elif not urls_seen:
            self._add("INFO", "LMB-08", "LAMBDA", "lambda",
                      f"No Lambda function URLs configured across {len(funcs)} function(s)")

        # CIS-Compute 12.2/12.5/12.7/12.9/12.10/12.12/12.13/12.14.
        self._check_lambda_cis(lmb, funcs)

        # LMB-07 — the artifact side-scan. Opt-in; the guard inside returns
        # immediately on a default run, so this call costs nothing unasked.
        self._side_scan_lambda_artifacts(lmb, funcs)

    def _check_lambda_cis(self, lmb, funcs) -> None:
        """LMB-10..LMB-17 (CIS-Compute 12.2, 12.5, 12.7, 12.9, 12.10, 12.12-12.14).

        WHAT COSTS NOTHING AND WHAT COSTS A CALL. Insights layers, the KMS key and the
        execution-role ARN are all already on the list_functions result, so LMB-10,
        LMB-11 and LMB-15 are free. LMB-12/13 need IAM, LMB-14 needs the resource policy,
        LMB-17 needs the recursion config and LMB-16 needs the layer policies — each in
        its own guard, because a single denied grant must not silently drop seven checks
        that had nothing to do with it."""
        # ── free from list_functions ──
        insights_missing = 0
        for fn in funcs:
            fname = str(fn.get("FunctionName") or "?")
            ins = aws_cis_compute.lambda_insights(fn)
            if not ins["enabled"]:
                insights_missing += 1
                self._add("FAIL", "LMB-10", "LAMBDA", fname, f"{ins['statement']} | {fname}")
            env = aws_cis_compute.lambda_env_cmk(fn)
            if env["default_key"]:
                self._add("FAIL", "LMB-15", "LAMBDA", fname, f"{env['statement']} | {fname}")
        if funcs and not insights_missing:
            self._add("PASS", "LMB-10", "LAMBDA", "lambda",
                      f"All {len(funcs)} function(s) have the Lambda Insights extension")

        shared = aws_cis_compute.lambda_role_sharing(funcs)
        for r in shared:
            self._add("FAIL", "LMB-11", "LAMBDA", r["role"].rsplit("/", 1)[-1],
                      f"{r['statement']} | {r['role']}")
        if funcs and not shared:
            self._add("PASS", "LMB-11", "LAMBDA", "lambda",
                      f"Each of the {len(funcs)} function(s) has its own execution role")

        # ── LMB-12 / LMB-13: the execution role itself ──
        iam = self._client("iam")
        seen_roles: Dict[str, tuple] = {}      # role arn -> (exists, admin_statements)
        for fn in funcs:
            fname = str(fn.get("FunctionName") or "?")
            role_arn = str(fn.get("Role") or "")
            if not role_arn:
                continue
            if role_arn not in seen_roles:
                seen_roles[role_arn] = self._lambda_role_facts(iam, role_arn)
            exists, statements = seen_roles[role_arn]
            miss = aws_cis_compute.lambda_role_missing(fn, exists)
            if miss["missing"]:
                self._add("FAIL", "LMB-12", "LAMBDA", fname, f"{miss['statement']} | {fname}")
            if exists and statements is not None:
                adm = aws_cis_compute.lambda_role_admin(fn, statements)
                if adm["admin"]:
                    self._add("FAIL", "LMB-13", "LAMBDA", fname,
                              f"{adm['statement']} | {fname}")

        # ── LMB-14: cross-account grants in the resource policy ──
        for fn in funcs:
            fname = str(fn.get("FunctionName") or "?")
            try:
                pol = json.loads(lmb.get_policy(FunctionName=fname)["Policy"])
            except Exception as e:
                # A function with no resource policy answers ResourceNotFoundException,
                # which is the ordinary case and not a denial.
                if self._error_code(e) != "ResourceNotFoundException":
                    self._coverage.note_denied("LMB-14", "lambda:GetPolicy")
                continue
            r = aws_cis_compute.lambda_cross_account(
                fname, pol.get("Statement", []), self.account, self.trusted_accounts)
            if r["cross_account"]:
                self._add("FAIL", "LMB-14", "LAMBDA", fname, f"{r['statement']} | {fname}")

        # ── LMB-17: recursive-loop detection ──
        for fn in funcs:
            fname = str(fn.get("FunctionName") or "?")
            try:
                cfg = lmb.get_function_recursion_config(FunctionName=fname) or {}
            except Exception as e:
                if self._is_access_denied(e):
                    self._coverage.note_denied("LMB-17",
                                               "lambda:GetFunctionRecursionConfig")
                # Older botocore has no such operation at all -- an unknown-operation
                # error is a capability gap, not a posture finding, so stay silent.
                break
            r = aws_cis_compute.lambda_recursion(fname, cfg.get("RecursiveLoop"))
            if r["allowed"]:
                self._add("FAIL", "LMB-17", "LAMBDA", fname, f"{r['statement']} | {fname}")

        # ── LMB-16: publicly shared layers. Layers are account-level, not per function. ──
        self._check_lambda_layers(lmb)

    def _lambda_role_facts(self, iam, role_arn: str):
        """(role_exists, policy_statements) for one execution role, or (None, None).

        None for existence is "we could not tell", which LMB-12 must not report as a
        missing role -- a denied iam:GetRole and a deleted role look identical from the
        function's side and only one of them is a finding."""
        name = role_arn.rsplit("/", 1)[-1]
        try:
            iam.get_role(RoleName=name)
        except Exception as e:
            if self._error_code(e) in ("NoSuchEntity", "NoSuchEntityException"):
                return False, None
            self._coverage.note_denied("LMB-12", "iam:GetRole")
            return None, None

        statements: List[Dict] = []
        try:
            for pol in self._paginate_all(iam, "list_attached_role_policies",
                                          "AttachedPolicies", RoleName=name):
                arn = pol.get("PolicyArn")
                if not arn:
                    continue
                ver = iam.get_policy(PolicyArn=arn)["Policy"]["DefaultVersionId"]
                doc = iam.get_policy_version(PolicyArn=arn, VersionId=ver
                                             )["PolicyVersion"]["Document"]
                doc = json.loads(doc) if isinstance(doc, str) else doc
                st = (doc or {}).get("Statement") or []
                statements += [st] if isinstance(st, dict) else list(st)
            for pname in self._paginate_all(iam, "list_role_policies", "PolicyNames",
                                            RoleName=name):
                doc = iam.get_role_policy(RoleName=name, PolicyName=pname
                                          )["PolicyDocument"]
                doc = json.loads(doc) if isinstance(doc, str) else doc
                st = (doc or {}).get("Statement") or []
                statements += [st] if isinstance(st, dict) else list(st)
        except Exception as e:
            if self._is_access_denied(e):
                self._coverage.note_denied("LMB-13", "iam:GetPolicyVersion")
            return True, None
        return True, statements

    def _check_lambda_layers(self, lmb) -> None:
        """LMB-16 (CIS-Compute 12.13) — layers shared with every AWS account.

        A layer with no permission policy raises ResourceNotFoundException, which is the
        PASSING case and by far the common one, so it is silent rather than a per-layer
        PASS that would bury the shared ones."""
        try:
            layers = self._paginate_strict(lmb, "list_layers", "Layers")
        except Exception as e:
            if self._is_access_denied(e):
                self._coverage.note_denied("LMB-16", "lambda:ListLayers")
            return
        public = 0
        for layer in layers:
            lname = str(layer.get("LayerName") or "")
            version = ((layer.get("LatestMatchingVersion") or {}).get("Version"))
            if not lname or version is None:
                continue
            try:
                pol = json.loads((lmb.get_layer_version_policy(
                    LayerName=lname, VersionNumber=version) or {}).get("Policy") or "{}")
            except Exception as e:
                # No permission policy at all is the PASSING case and by far the common
                # one, so it must not be mistaken for a denied read.
                if self._error_code(e) != "ResourceNotFoundException":
                    self._coverage.note_denied("LMB-16", "lambda:GetLayerVersionPolicy")
                continue
            r = aws_cis_compute.lambda_layer_public(lname, version,
                                                    pol.get("Statement", []))
            if r["public"]:
                public += 1
                self._add("FAIL", "LMB-16", "LAMBDA", lname, f"{r['statement']} | {lname}")
        if layers and not public:
            self._add("PASS", "LMB-16", "LAMBDA", "lambda",
                      f"None of the {len(layers)} published layer(s) is shared publicly")

    def _side_scan_lambda_artifacts(self, lmb, funcs) -> None:
        """LMB-07 — agentless vulnerable-dependency detection inside a Lambda artefact.

        OPT-IN (``--side-scan-lambda``), mirroring the ECR layer pull it is modelled on:
        this downloads the function's deployment zip and every layer zip through the
        same allowlisted egress seam, so it is an operator decision rather than
        something a default scan does.

        WHY THE CHECK IS WORTH HAVING. Lambda code is packaged at deploy time and then
        runs unchanged. Patching the managed runtime never touches ``/var/task`` or
        ``/opt``, so a dependency that was current when the zip was built stays exactly
        as vulnerable until somebody redeploys — and nothing in the account reports
        that unless Inspector Lambda scanning happens to be switched on.

        THE MODULE THIS CALLS SHIPPED WITHOUT A CALLER. ``aws_sidescan_lambda``, its
        tests, the ``LMB-07`` id named in ``emit_node_vuln_edges``' own docstring and
        ``LambdaFunction`` in ``aws_correlate._EXPLOIT_KINDS`` were all in place, and
        ``docs/OVERWATCH_VULN_ROADMAP.md`` ticked LMB-07 complete. Only the producer was
        missing, so the check could never fire and the completeness claim was false.
        Three of the four side-scan siblings were wired; this one was not.

        FAIL-OPEN, NEVER A FALSE CLEAN. Every artefact that cannot be read becomes an
        INFO naming the function and the reason, because an unreadable zip and a
        function with no vulnerable dependencies must not render identically.
        """
        if not self.side_scan_lambda:
            return
        from engine import aws_layer_fetch
        from engine import aws_sidescan_lambda

        bundle = self._load_vuln_db()
        feed = bundle[0] if bundle else None
        epss = bundle[1] if bundle else {}
        kev = bundle[2] if bundle else set()
        exploits = bundle[3] if bundle else set()
        http_get = self._layer_get or aws_layer_fetch.http_get

        # Said once, like the registry path: without a feed this is an inventory, and
        # "no findings" must not be read as "no vulnerable dependencies".
        if feed is None and self.vuln_db_path is None:
            self._add("INFO", "LMB-07", "LAMBDA", "lambda",
                      "no --vuln-db supplied; Lambda dependency inventory only, "
                      "CVE match skipped")

        # A silent cap makes a partial scan look like a whole one.
        if len(funcs) > self.side_scan_lambda_max:
            self._add("INFO", "LMB-07", "LAMBDA", "lambda",
                      f"artifact side-scan covered the first {self.side_scan_lambda_max} "
                      f"of {len(funcs)} function(s) (--side-scan-lambda-max)")

        g = self._ensure_graph()
        for fn in funcs[:max(0, self.side_scan_lambda_max)]:
            fname = fn["FunctionName"]
            # The ARN, not the name: emit_node_vuln_edges keys the graph node on this,
            # and the same function name exists in every region.
            node_id = fn.get("FunctionArn") or fname
            notes: List[str] = []
            try:
                fn_zip, layer_zips, pkg_type = aws_sidescan_lambda.fetch_lambda_artifact(
                    lmb, fname, http_get=http_get, notes=notes)
            except aws_sidescan_lambda.LambdaArtifactUnavailable as e:
                self._add("INFO", "LMB-07", "LAMBDA", fname,
                          f"Lambda artifact side-scan skipped for {fname}: {e}")
                continue
            if pkg_type == "Image":
                # Container-packaged functions belong to the ECR path (CWPP-05/06).
                # Scanning them here would report the same image twice under two ids.
                continue
            if fn_zip is None and not layer_zips:
                self._add("INFO", "LMB-07", "LAMBDA", fname,
                          f"Lambda artifact side-scan skipped for {fname}: "
                          f"{'; '.join(notes) or 'no artifact bytes returned'}")
                continue

            ext = aws_sidescan_lambda.LambdaArtifactExtractor(
                fn_zip, layer_zips, notes=notes)
            # do_secrets=False deliberately: scan_secrets' roots do not include
            # /var/task, so it would search the layer half only and present a partial
            # result as a complete one. Secrets in Lambda configuration are LMB-03.
            res = aws_sidescan.sidescan_filesystem(
                ext, feed, epss, kev, exploits, do_secrets=False)
            # The registry path's severity bar, so the same CVE is reported at the same
            # level whichever artefact carries it.
            sev_vulns = [m for m in res.vulns
                         if m.kev or (m.severity or "").upper() in ("CRITICAL", "HIGH")]
            aws_sidescan.emit_node_vuln_edges(
                g, node_id, "LambdaFunction", sev_vulns,
                scan_source="lambda-sidescan", function_name=fname)
            for m in sev_vulns:
                self._add("FAIL", "LMB-07", "LAMBDA", fname,
                          f"Lambda dependency {m.severity} {m.cve} (EPSS {m.epss}, "
                          f"exploit={m.exploit_available}, "
                          f"kev={'YES' if m.kev else 'NO'}, "
                          f"fix={'YES' if m.fixed_version else 'NO'}) in "
                          f"{m.package} {m.installed_version} (agentless artifact scan)")
            for note in notes:
                self._add("INFO", "LMB-07", "LAMBDA", fname, f"{note} | {fname}")


    # ══════════════════════════════════════════════════════════════════════════
    # SECTION 18: AMAZON EKS
    # ══════════════════════════════════════════════════════════════════════════
    def _check_eks(self):
        self._section_header("EKS")
        eks = self._client("eks")

        try:
            clusters = eks.list_clusters().get("clusters", [])
        except Exception as e:
            self._add("WARN", "EKS-01", "EKS", "eks", str(e))
            return
        if not clusters:
            self._add("INFO", "EKS-01", "EKS", "eks",
                      "No EKS clusters in this region")
            return

        for cname in clusters:
            try:
                c = eks.describe_cluster(name=cname)["cluster"]
            except Exception as e:
                self._add("WARN", "EKS-01", "EKS", cname, str(e))
                continue

            # EKS-01 — Public endpoint
            vpc_cfg = c.get("resourcesVpcConfig", {})
            if vpc_cfg.get("endpointPublicAccess", True):
                cidrs = vpc_cfg.get("publicAccessCidrs", ["0.0.0.0/0"])
                if "0.0.0.0/0" in cidrs:
                    self._add("FAIL", "EKS-01", "EKS", cname,
                              f"EKS '{cname}' API endpoint public to 0.0.0.0/0")
                else:
                    self._add("WARN", "EKS-01", "EKS", cname,
                              f"EKS '{cname}' API endpoint public (restricted CIDRs)")

            # EKS-02 — Control plane logging
            logging_cfg = c.get("logging", {}).get("clusterLogging", [])
            enabled_types = []
            for lc in logging_cfg:
                if lc.get("enabled"):
                    enabled_types.extend(lc.get("types", []))
            expected = {"api", "audit", "authenticator", "controllerManager", "scheduler"}
            missing = expected - set(enabled_types)
            if missing:
                self._add("FAIL", "EKS-02", "EKS", cname,
                          f"EKS '{cname}' missing log types: {', '.join(sorted(missing))}")
            else:
                self._add("PASS", "EKS-02", "EKS", cname,
                          f"EKS '{cname}' all control plane logging enabled")

            # EKS-03 — Secrets encryption
            enc_cfg = c.get("encryptionConfig", [])
            secrets_enc = any("secrets" in e.get("resources", [])
                              for e in enc_cfg)
            if secrets_enc:
                self._add("PASS", "EKS-03", "EKS", cname,
                          f"EKS '{cname}' Kubernetes secrets encrypted with KMS")
            else:
                self._add("FAIL", "EKS-03", "EKS", cname,
                          f"EKS '{cname}' Kubernetes secrets NOT encrypted with KMS")

            # EKS-04 — Platform version
            version = c.get("version", "")
            platform = c.get("platformVersion", "")
            self._add("INFO", "EKS-04", "EKS", cname,
                      f"EKS '{cname}' version={version} platform={platform}")

            # EKS-05 — Security groups
            sg_ids = vpc_cfg.get("securityGroupIds", [])
            if not sg_ids:
                self._add("WARN", "EKS-05", "EKS", cname,
                          f"EKS '{cname}' no additional security groups configured")

            # EKS-06 — worker-nodegroup SSH exposed to the internet. OWN try/except: a
            # denied call (or a generic mock whose .get returns a non-list) must NOT break
            # EKS-01..05 above; a non-list result -> treat as no nodegroups.
            try:
                ng_names = eks.list_nodegroups(clusterName=cname).get("nodegroups", [])
                if not isinstance(ng_names, list):
                    ng_names = []
                if not ng_names:
                    self._add("INFO", "EKS-06", "EKS", cname,
                              f"EKS '{cname}' has no managed nodegroups "
                              f"(Fargate-only / self-managed)")
                else:
                    world_open, describe_err = 0, False
                    for ng_name in ng_names:
                        try:
                            ng = eks.describe_nodegroup(
                                clusterName=cname, nodegroupName=ng_name)["nodegroup"]
                        except Exception:
                            describe_err = True
                            self._add("WARN", "EKS-06", "EKS", f"{cname}/{ng_name}",
                                      "could not describe nodegroup (SSH exposure undetermined)")
                            continue
                        ra = ng.get("remoteAccess") or {}
                        if ra.get("ec2SshKey") and not ra.get("sourceSecurityGroups"):
                            world_open += 1
                            self._add("FAIL", "EKS-06", "EKS", f"{cname}/{ng_name}",
                                      f"Worker-node SSH(22) reachable from 0.0.0.0/0 "
                                      f"(remoteAccess SSH key set, no sourceSecurityGroups) "
                                      f"| {cname}/{ng_name}")
                        elif ra.get("ec2SshKey"):
                            self._add("INFO", "EKS-06", "EKS", f"{cname}/{ng_name}",
                                      f"Worker SSH scoped to source security groups "
                                      f"| {cname}/{ng_name}")
                    # AGGREGATE-PASS-MUST-COUNT: only all-clear when every nodegroup was read
                    if world_open == 0 and not describe_err:
                        self._add("PASS", "EKS-06", "EKS", cname,
                                  f"EKS '{cname}' nodegroups: no world-open worker SSH")
            except Exception as e:
                self._add("WARN", "EKS-06", "EKS", cname,
                          f"could not enumerate nodegroups (SSH exposure not evaluated): {e}")

            # EKS-07 — EKS-Fargate profiles (documented agentless boundary). An AWS-only
            # reader can see the profile (namespaces/labels that run on Fargate + the pod
            # EXECUTION role), but NOT the running pod images / IPs / IRSA app-role bindings
            # — those require the Kubernetes API and are deferred to the KSPM item. So there
            # is no side-scan / attack-path node here; EKS-07 records the surface honestly.
            try:
                fp_names = eks.list_fargate_profiles(
                    clusterName=cname).get("fargateProfileNames", [])
                if not isinstance(fp_names, list):
                    fp_names = []
            except Exception:
                fp_names = []
            for fp_name in fp_names:
                try:
                    fp = eks.describe_fargate_profile(
                        clusterName=cname, fargateProfileName=fp_name)["fargateProfile"]
                except Exception:
                    continue
                pod_role = fp.get("podExecutionRoleArn", "")
                ns = sorted({s.get("namespace", "") for s in (fp.get("selectors") or [])
                             if s.get("namespace")})
                self._add("INFO", "EKS-07", "EKS", f"{cname}/{fp_name}",
                          f"EKS-Fargate profile '{fp_name}' runs pods in namespace(s) "
                          f"{ns or ['*']} under pod-execution role "
                          f"{(pod_role or 'none').split('/')[-1]}. AGENTLESS BOUNDARY: running "
                          f"pod images / IPs / IRSA app-role bindings need the Kubernetes API "
                          f"(KSPM) and are NOT side-scanned here. | {cname}/{fp_name}")

            # Phase-3 KSPM/KIEM: always-on AWS-side identity/entitlement (EKS Access Entries +
            # Pod Identity) — no cluster reachability, no grant — then the optional K8s-API layer.
            self._check_eks_kiem(eks, cname, c)

    # ── Phase 3: KSPM (CIS-EKS K8s-side) + KIEM (identity/entitlement) ───────────
    _KUBE_ENTRY_CAP = 400        # access entries / pod-identity assocs scanned per cluster

    def _check_eks_kiem(self, eks, cname: str, c: Dict) -> None:
        """Layer A (always on, no grant, no reachability): EKS Access Entries -> AWS-principal
        cluster-admin/over-priv (KIEM-01/02/03), EKS Pod Identity -> ServiceAccount->IAM-role
        edges, and the authenticationMode posture (EKS-08). Stashes cross-plane graph edges for
        the VULN#40 replay. Every AWS call is guarded -> fail-open INFO, never a phantom PASS."""
        cluster_arn = c.get("arn") or f"eks:{cname}"
        acct = self.account
        admin_cap = f"capability:k8s-admin:{cluster_arn}"

        # EKS-08 — authentication mode posture (read from the already-fetched describe_cluster).
        acfg = c.get("accessConfig") or {}
        mode = acfg.get("authenticationMode") or "API_AND_CONFIG_MAP"
        bootstrap = acfg.get("bootstrapClusterCreatorAdminPermissions")
        if mode == "CONFIG_MAP":
            self._add("FAIL", "EKS-08", "EKS", cname,
                      f"EKS '{cname}' authenticationMode=CONFIG_MAP — the AWS->Kubernetes identity "
                      f"mapping lives ONLY in the aws-auth ConfigMap, invisible to AWS APIs. Grant "
                      f"an EKS access entry (aws eks update-cluster-config --access-config "
                      f"authenticationMode=API_AND_CONFIG_MAP) so identity/entitlement is auditable "
                      f"| {cname}")
        else:
            extra = " (residual aws-auth entries still AWS-blind)" if mode == "API_AND_CONFIG_MAP" else ""
            self._add("INFO", "EKS-08", "EKS", cname,
                      f"EKS '{cname}' authenticationMode={mode}{extra}; "
                      f"bootstrapClusterCreatorAdminPermissions={bool(bootstrap)}")

        # KIEM — EKS Access Entries: AWS principal -> K8s access policy / group.
        try:
            entries: List[str] = []
            for page in eks.get_paginator("list_access_entries").paginate(clusterName=cname):
                entries.extend(page.get("accessEntries", []))
        except Exception as e:
            self._add("INFO", "KIEM-01", "EKS", cname,
                      f"EKS access entries unavailable on '{cname}' (identity mapping not "
                      f"evaluated): {e}")
            entries = []
        for parn in entries[:self._KUBE_ENTRY_CAP]:
            try:
                entry = eks.describe_access_entry(
                    clusterName=cname, principalArn=parn)["accessEntry"]
            except Exception:
                continue
            if (entry.get("type") or "STANDARD") != "STANDARD":
                continue                          # EC2_LINUX/FARGATE_LINUX = node bootstrap identity
            try:
                assoc = []
                for page in eks.get_paginator("list_associated_access_policies").paginate(
                        clusterName=cname, principalArn=parn):
                    assoc.extend(page.get("associatedAccessPolicies", []))
            except Exception as e:
                # Fail-open: a denied policy list is NOT the same as "no policy" — a
                # cluster-admin grant could be hidden. Emit INFO (unless system:masters in the
                # entry's groups already makes it admin) rather than silently under-reporting.
                if "system:masters" not in (entry.get("kubernetesGroups") or []):
                    self._add("INFO", "KIEM-01", "EKS", (parn or "?").split("/")[-1],
                              f"AWS principal {parn} on EKS '{cname}': access-policy list denied "
                              f"(eks:ListAssociatedAccessPolicies) — entitlement NOT evaluated: {e} "
                              f"| {parn}")
                    continue
                assoc = []
            tier, scope, groups = aws_kube.classify_access_entry(entry, assoc)
            self._kiem_access_finding(cname, cluster_arn, admin_cap, parn, tier, scope, groups)

        # KIEM — EKS Pod Identity: ServiceAccount -> IAM role (readable without the K8s API).
        try:
            pias: List[Dict] = []
            for page in eks.get_paginator("list_pod_identity_associations").paginate(
                    clusterName=cname):
                pias.extend(page.get("associations", []))
        except Exception:
            pias = []
        for pia in pias[:self._KUBE_ENTRY_CAP]:
            ns, sa, role_arn = pia.get("namespace"), pia.get("serviceAccount"), pia.get("roleArn")
            if ns and sa and role_arn:
                self._stash_kube_sa_role(cluster_arn, ns, sa, role_arn, basis="pod-identity")

        # Layer B (optional, injected read-only K8s API): CIS-EKS K8s-side KSPM + RBAC graph.
        self._check_kspm(cname, c, cluster_arn, admin_cap)

    def _check_kspm(self, cname: str, c: Dict, cluster_arn: str, admin_cap: str) -> None:
        """Layer B — the read-only Kubernetes API (behind the injected ``k8s_get`` seam):
        KSPM-01..07 (CIS-EKS RBAC/PSA/NetworkPolicy/pod) + stash the K8s-RBAC + pod/SA graph
        edges. FAIL-OPEN: private-only endpoint / no grant / GET failure → KSPM-00 INFO naming
        the prerequisite, never a crash and never a phantom PASS. READ-ONLY (GET/LIST only)."""
        attemptable, reason = aws_kube.cluster_reachability(c)
        if not attemptable:
            self._add("INFO", "KSPM-00", "EKS", cname,
                      f"K8s-API KSPM/RBAC layer NOT run for '{cname}': {reason}. To enable, grant "
                      f"the scanner role an EKS read access entry (AmazonEKSViewPolicy for "
                      f"KSPM; AmazonEKSAdminViewPolicy or a read-only ClusterRole for the RBAC "
                      f"graph) via `aws eks create-access-entry` + a reachable endpoint. | {cname}")
            return
        ctx = self._cluster_ctx(c, cname)
        probe = self.k8s_get(ctx, "/api/v1/namespaces")
        if probe is None:
            self._add("INFO", "KSPM-00", "EKS", cname,
                      f"K8s API for '{cname}' reachable but the GET was denied/failed — grant the "
                      f"scanner role an EKS read access entry (AmazonEKSViewPolicy) so KSPM/RBAC "
                      f"can be evaluated via `aws eks create-access-entry`. | {cname}")
            return

        def _items(path):
            r = self.k8s_get(ctx, path)
            return (r or {}).get("items", []) or []

        namespaces = probe.get("items", []) or []
        pods = _items("/api/v1/pods")
        sas = _items("/api/v1/serviceaccounts")
        # NetworkPolicy absence is treated as a FAIL (KSPM-06), so a DENIED read must NOT look
        # like "no policies" — preserve None (denied) vs [] (genuinely none) to avoid a phantom
        # FAIL for every namespace. RBAC lists, by contrast, only FIND-then-FAIL, so [] is safe.
        _np_raw = self.k8s_get(ctx, "/apis/networking.k8s.io/v1/networkpolicies")
        netpols = None if _np_raw is None else (_np_raw.get("items") or [])
        crs = _items("/apis/rbac.authorization.k8s.io/v1/clusterroles")
        crbs = _items("/apis/rbac.authorization.k8s.io/v1/clusterrolebindings")
        roles = _items("/apis/rbac.authorization.k8s.io/v1/roles")
        rbs = _items("/apis/rbac.authorization.k8s.io/v1/rolebindings")

        # ── KSPM-01/02/03: RBAC (empty when only ViewPolicy is granted → RBAC lists 403 → []) ──
        ev = aws_kube.evaluate_rbac(crs, crbs, roles, rbs)
        for a in ev["anonymous"]:
            sname = (a["subject"] or {}).get("name", "?")
            self._add("FAIL", "KSPM-01", "EKS", f"{cname}/{a['binding']}",
                      f"EKS '{cname}': RBAC binding '{a['binding']}' ({a['scope']}) grants role "
                      f"'{a['role']}' to the built-in group {sname} — every matching caller "
                      f"inherits it{' (CLUSTER-ADMIN!)' if a['admin'] else ''}. | {cname}")
        for w in ev["wildcard"]:
            subj = w["subject"] or {}
            self._add("FAIL", "KSPM-02", "EKS", f"{cname}/{w['binding']}",
                      f"EKS '{cname}': binding '{w['binding']}' ({w['scope']}) grants a wildcard "
                      f"role '{w['role']}' (apiGroups/resources/verbs '*') to "
                      f"{subj.get('kind')}/{subj.get('name')} — over-broad RBAC. | {cname}")
        for ca in ev["cluster_admin"]:
            subj = ca["subject"] or {}
            if str(subj.get("name", "")).startswith("system:"):
                continue                                  # built-in controllers are expected
            self._add("FAIL", "KSPM-03", "EKS", f"{cname}/{ca['binding']}",
                      f"EKS '{cname}': ClusterRoleBinding '{ca['binding']}' grants CLUSTER-ADMIN to "
                      f"{subj.get('kind')}/{subj.get('name')} (ns {subj.get('namespace')}) — "
                      f"compromising that subject is full cluster takeover. | {cname}")
            if subj.get("kind") == "ServiceAccount" and subj.get("name"):
                self._kube_payloads.append({
                    "kind": "sa_admin", "admin_cap": admin_cap, "cluster_arn": cluster_arn,
                    "sa_node": f"k8s:sa:{cluster_arn}:{subj.get('namespace')}:{subj.get('name')}",
                    "namespace": subj.get("namespace"), "sa_name": subj.get("name")})

        # ── KSPM-04: default ServiceAccount auto-mounts its token ──
        for sa in sas:
            meta = sa.get("metadata") or {}
            if meta.get("name") == "default" and not aws_kube.is_system_namespace(meta.get("namespace")) \
                    and aws_kube.sa_automounts_token(sa):
                self._add("FAIL", "KSPM-04", "EKS", f"{cname}/{meta.get('namespace')}",
                          f"EKS '{cname}' ns {meta.get('namespace')}: the default ServiceAccount "
                          f"auto-mounts its API token (set automountServiceAccountToken: false). | {cname}")

        # ── KSPM-05: Pod Security Admission enforce level ──
        for ns in namespaces:
            name = (ns.get("metadata") or {}).get("name")
            if aws_kube.is_system_namespace(name):
                continue
            lvl = aws_kube.psa_enforce_level(ns)
            if lvl == "privileged":
                self._add("FAIL", "KSPM-05", "EKS", f"{cname}/{name}",
                          f"EKS '{cname}' ns {name}: Pod Security Admission enforce=privileged "
                          f"(no pod hardening enforced). | {cname}")
            elif lvl is None:
                self._add("INFO", "KSPM-05", "EKS", f"{cname}/{name}",
                          f"EKS '{cname}' ns {name}: no namespace PSA enforce label (cluster "
                          f"default applies; not readable via the API here). | {cname}")

        # ── KSPM-06: default-deny NetworkPolicy per namespace (skip if the read was denied) ──
        if netpols is None:
            self._add("INFO", "KSPM-00", "EKS", cname,
                      f"EKS '{cname}': NetworkPolicy read denied — KSPM-06 (default-deny) NOT "
                      f"evaluated. Grant networking.k8s.io get/list to the scanner role. | {cname}")
        for ns in (namespaces if netpols is not None else []):
            name = (ns.get("metadata") or {}).get("name")
            if aws_kube.is_system_namespace(name):
                continue
            if not aws_kube.namespace_has_default_deny(netpols, name):
                self._add("FAIL", "KSPM-06", "EKS", f"{cname}/{name}",
                          f"EKS '{cname}' ns {name}: no default-deny NetworkPolicy — pods accept "
                          f"all ingress/egress (flat network eases lateral movement). | {cname}")

        # ── KSPM-07: privileged / host-namespace / hostPath pods ──
        for pod in pods:
            meta = pod.get("metadata") or {}
            pns = meta.get("namespace")
            if aws_kube.is_system_namespace(pns):
                continue
            issues = aws_kube.pod_security_findings(pod, self._DANGEROUS_CAPS)
            if issues:
                self._add("FAIL", "KSPM-07", "EKS", f"{cname}/{pns}/{meta.get('name')}",
                          f"EKS '{cname}' pod {pns}/{meta.get('name')}: escape primitive(s) "
                          f"{issues}. | {cname}")

        # Layer-B graph edges (pod -> SA -> IRSA role; RBAC SA -> cluster-admin) — B5.
        cluster_vpc = (c.get("resourcesVpcConfig") or {}).get("vpcId", "")
        self._stash_kube_workload_graph(cluster_arn, cluster_vpc, pods, sas)

    def _stash_kube_workload_graph(self, cluster_arn: str, cluster_vpc: str,
                                   pods: List[Dict], sas: List[Dict]) -> None:
        """Stash the Layer-B workload graph for the VULN#40 replay: SA -CAN_ASSUME-> IRSA role
        (annotation), pod -HAS_ROLE-> SA, pod -RUNS_IMAGE-> ECRImage (image CVEs inherited via the
        kind-agnostic RUNS_IMAGE ex-gate, exactly like Fargate — no _EXPLOIT_KINDS change).
        ``cluster_vpc`` keys the pod IP so the EXPOSURE ip-target join can't cross clusters/VPCs."""
        for sa in sas:
            meta = sa.get("metadata") or {}
            ns, name = meta.get("namespace"), meta.get("name")
            role = aws_kube.irsa_role_arn(sa)
            if ns and name and role:
                self._stash_kube_sa_role(cluster_arn, ns, name, role, basis="irsa")
        for pod in pods:
            meta = pod.get("metadata") or {}
            ns, pname = meta.get("namespace"), meta.get("name")
            if not ns or not pname:
                continue
            sa = aws_kube.pod_service_account(pod)
            # Prefer the resolved running imageID (carries @sha256) for the digest, but take the
            # ECR COORDINATES from whichever ref parses — and fall back to the spec image's own
            # embedded @sha256 — so a digest-pinned spec ref isn't dropped when the running imageID
            # lacks a digest (mirrors the Fargate imageDigest fix; all-or-nothing 'or' was wrong).
            status_img = {cs.get("name"): cs.get("imageID", "")
                          for cs in ((pod.get("status") or {}).get("containerStatuses") or [])}
            image_nodes: List[tuple] = []
            for cont in ((pod.get("spec") or {}).get("containers") or []):
                cn = cont.get("name", "")
                resolved_p = parse_ecr_image_ref((status_img.get(cn) or "").split("://")[-1])
                spec_p = parse_ecr_image_ref(cont.get("image", ""))
                p = resolved_p or spec_p
                digest = (resolved_p and resolved_p["digest"]) or (spec_p and spec_p["digest"])
                if not p or not digest:
                    continue                          # non-ECR or unresolved → no digest CVE join
                for node in ecr_image_node_ids(p["account"], p["region"], p["repo"], digest):
                    image_nodes.append((node, {"repository": p["repo"], "digest": digest}, cn))
            self._kube_payloads.append({
                "kind": "pod_sa", "pod_node": f"k8s:pod:{cluster_arn}:{ns}:{pname}",
                "sa_node": f"k8s:sa:{cluster_arn}:{ns}:{sa}", "cluster_arn": cluster_arn,
                "cluster_vpc": cluster_vpc, "namespace": ns, "pod_name": pname, "sa_name": sa,
                "private_ip": (pod.get("status") or {}).get("podIP"), "image_nodes": image_nodes})

    def _kiem_access_finding(self, cname, cluster_arn, admin_cap, parn, tier, scope, groups):
        """One access-entry principal -> KIEM finding + (for admin/edit) a stashed cross-plane
        CAN_PRIVESC_TO edge principal -> KubeAdminCapability (namespace scope -> conditioned)."""
        acct = self.account
        # cross-account / external / root sharpen the severity (mirror IAMPRIVESC's external flag)
        external = bool(acct) and f":{acct}:" not in (parn or "")
        is_root = (parn or "").endswith(":root")
        pshort = (parn or "?").split("/")[-1] or parn
        if aws_kube.tier_is_admin(tier) or "system:masters" in groups:
            crit = external or is_root
            via = "system:masters group" if "system:masters" in groups else "AmazonEKSClusterAdminPolicy"
            self._add("FAIL", "KIEM-01", "EKS", pshort,
                      f"AWS principal {parn} has KUBERNETES CLUSTER-ADMIN on EKS '{cname}' (via "
                      f"{via}) — de-facto full control-plane admin (all Secrets, exec any pod, "
                      f"pivot via every ServiceAccount's IRSA role)"
                      f"{'; CROSS-ACCOUNT/root — treat as CRITICAL' if crit else ''}. | {parn}")
            # stash the cross-plane escalation edge (principal already a graph node post-IAMPRIVESC)
            self._kube_payloads.append({
                "kind": "principal_admin", "principal": parn, "admin_cap": admin_cap,
                "cluster_arn": cluster_arn, "conditioned": (scope != "cluster")})
        elif tier in ("NAMESPACE_ADMIN", "EDIT"):
            self._add("FAIL", "KIEM-02", "EKS", pshort,
                      f"AWS principal {parn} has {tier.lower().replace('_', '-')} "
                      f"({scope} scope) on EKS '{cname}' — in-cluster privilege that can often be "
                      f"escalated (rbac write / SA impersonation / secrets). Scope to least "
                      f"privilege. | {parn}")
        elif tier == "SECRET":
            self._add("FAIL", "KIEM-03", "EKS", pshort,
                      f"AWS principal {parn} can READ Kubernetes Secrets on EKS '{cname}' "
                      f"(AmazonEKSAdminViewPolicy). K8s Secrets often hold DB/cloud credentials — "
                      f"a crown-jewel read surface. | {parn}")

    def _stash_kube_sa_role(self, cluster_arn, ns, sa, role_arn, basis):
        """Stash a KubeServiceAccount -CAN_ASSUME-> IAM-role cross-plane edge (IRSA / Pod
        Identity). conditioned=False: the role's web-identity/pod-identity trust is definitionally
        satisfied from the SA, so it must not be capped to the conditioned band."""
        sa_node = f"k8s:sa:{cluster_arn}:{ns}:{sa}"
        self._kube_payloads.append({
            "kind": "sa_role", "sa_node": sa_node, "cluster_arn": cluster_arn,
            "namespace": ns, "sa_name": sa, "role_arn": role_arn, "basis": basis})

    # ══════════════════════════════════════════════════════════════════════════
    # SECTION 19: AMAZON ECS
    # ══════════════════════════════════════════════════════════════════════════
    def _check_ecs(self):
        self._section_header("ECS")
        ecs = self._client("ecs")

        try:
            cluster_arns = ecs.list_clusters().get("clusterArns", [])
        except Exception as e:
            self._add("WARN", "ECS-01", "ECS", "ecs", str(e))
            return
        if not cluster_arns:
            self._add("INFO", "ECS-01", "ECS", "ecs",
                      "No ECS clusters in this region")
            return

        # Check task definitions for security issues
        self._log("ECS-01/02/03: ECS task definition security")
        try:
            td_arns = ecs.list_task_definitions(status="ACTIVE"
                          ).get("taskDefinitionArns", [])
        except Exception:
            td_arns = []

        for td_arn in td_arns[:50]:  # cap at 50 to avoid rate limits
            try:
                # include=TAGS for ECS-13: tags are returned only when asked for, and
                # they arrive BESIDE taskDefinition in the response rather than inside
                # it, so both halves have to be kept.
                _td_resp = ecs.describe_task_definition(
                    taskDefinition=td_arn, include=["TAGS"])
                td = _td_resp["taskDefinition"]
                td_tags = _td_resp.get("tags") or []
            except Exception:
                continue
            td_name = td.get("family", td_arn.split("/")[-1])
            for cd in td.get("containerDefinitions", []):
                cname = cd.get("name", "unknown")
                # RUNS_IMAGE — workload -> ECRImage so image CVEs drive attack paths
                self._emit_runs_image(td, cd)
                # ECS-01 — Privileged mode
                if cd.get("privileged", False):
                    self._add("FAIL", "ECS-01", "ECS", f"{td_name}/{cname}",
                              f"Container '{cname}' runs in privileged mode")
                # ECS-02 — Root user
                user = cd.get("user", "")
                if not user or user == "root" or user == "0":
                    self._add("FAIL", "ECS-02", "ECS", f"{td_name}/{cname}",
                              f"Container '{cname}' runs as root (no user set)")
                # ECS-03 — Log configuration
                if not cd.get("logConfiguration"):
                    self._add("FAIL", "ECS-03", "ECS", f"{td_name}/{cname}",
                              f"Container '{cname}' has no log driver configured")
                # ECS-04 — Secrets as env vars
                env = cd.get("environment", [])
                secret_patterns = ["PASSWORD", "SECRET", "API_KEY", "TOKEN"]
                for e in env:
                    if any(p in e.get("name", "").upper() for p in secret_patterns):
                        self._add("FAIL", "ECS-04", "ECS", f"{td_name}/{cname}",
                                  f"Plaintext secret in env var '{e['name']}' "
                                  f"on '{cname}' — use secrets or SSM")
                        break
                # ECS-05 — Read-only root filesystem
                if not cd.get("readonlyRootFilesystem", False):
                    self._add("FAIL", "ECS-05", "ECS", f"{td_name}/{cname}",
                              f"Container '{cname}' root filesystem is writable")
                # ECS-08 — dangerous Linux capabilities (container-level). linuxParameters
                # and capabilities are both optional -> chain-guard the .get()s.
                add = set(((cd.get("linuxParameters") or {}).get("capabilities") or {})
                          .get("add") or [])
                risky = add & self._DANGEROUS_CAPS
                if risky:
                    self._add("FAIL", "ECS-08", "ECS", f"{td_name}/{cname}",
                              f"Container '{cname}' adds dangerous capabilities "
                              f"{sorted(risky)} (SYS_ADMIN/ALL ~ privileged; SYS_PTRACE crosses "
                              f"the container boundary)")

            # ── Task-level escape primitives (evaluate ONCE per task def, OUTSIDE the
            # containerDefinitions loop — pidMode/ipcMode/networkMode/volumes are on the
            # taskDefinition, not the container). ──
            # ECS-06 — host namespace share
            host_ns = [k for k in ("pidMode", "ipcMode", "networkMode")
                       if td.get(k) == "host"]
            if host_ns:
                self._add("FAIL", "ECS-06", "ECS", td_name,
                          f"Task shares host namespace(s) {host_ns} — host PID/IPC can "
                          f"read/ptrace host processes & secrets; host network reaches the "
                          f"node IMDS -> node-role credential theft | {td_name}")
            # ECS-07 — sensitive host-path bind mount
            for v in td.get("volumes", []):
                sp = (v.get("host") or {}).get("sourcePath")
                if not sp:
                    continue                    # no host volume / ephemeral -> benign
                sensitive = (sp in self._SENSITIVE_HOST_PATHS
                             or any(sp == d.rstrip("/") or sp.startswith(d)
                                    for d in self._SENSITIVE_HOST_DIRS))
                if sensitive:
                    self._add("FAIL", "ECS-07", "ECS", td_name,
                              f"Task bind-mounts sensitive host path '{sp}' "
                              f"(container->host escape; docker.sock = instant host root) "
                              f"| {td_name}")
                else:
                    self._add("WARN", "ECS-07", "ECS", td_name,
                              f"Task bind-mounts host path '{sp}' (hostPath mount) | {td_name}")

            # ── CIS-Compute 3.12/3.13/3.15, from the SAME describe_task_definition ──
            # ECS-16 — network mode. ECS-06 above already owns `host`; this is the rest.
            nm = aws_cis_compute.ecs_network_mode(td)
            if nm["not_awsvpc"]:
                self._add("FAIL", "ECS-16", "ECS", td_name, f"{nm['statement']} | {td_name}")
            # ECS-13 — task-definition tags, which arrive beside the definition rather
            # than inside it (see the include=TAGS call above).
            tg = aws_cis_compute.ecs_tags({"tags": td_tags}, "task definition", td_name)
            if tg["untagged"]:
                self._add("FAIL", "ECS-13", "ECS", td_name, f"{tg['statement']} | {td_name}")
            # ECS-14 — image provenance, per container.
            for cd in td.get("containerDefinitions", []):
                im = aws_cis_compute.ecs_image_trust(
                    cd.get("image"), self.account, self.trusted_accounts)
                if im["external"]:
                    self._add("FAIL", "ECS-14", "ECS",
                              f"{td_name}/{cd.get('name', 'unknown')}",
                              f"{im['statement']} | {td_name}")

        # CIS-Compute 3.8/3.9/3.10/3.11/3.14/3.16 + 11.1 — cluster- and service-level.
        self._check_ecs_cis(ecs, cluster_arns)

        # Phase-3: fold RUNNING Fargate tasks into the attack-path graph (task-defs above
        # are hygiene only; the running task is the exposure + identity anchor).
        self._check_fargate_tasks(ecs, cluster_arns)

    def _check_ecs_cis(self, ecs, cluster_arns: List[str]) -> None:
        """ECS-09..ECS-12, ECS-15, ECS-17 and FARGATE-03 (CIS-Compute 3.8-3.11, 3.14,
        3.16 and 11.1).

        ONE describe_clusters WITH INCLUDES. Container Insights lives under SETTINGS, ECS
        Exec logging and the Fargate storage key under CONFIGURATIONS, and cluster tags
        under TAGS -- all three are includes on the same call, so four checks cost one
        request rather than three. Every block guards itself: a cluster whose services
        cannot be listed must not discard the cluster-level findings already emitted."""
        if not cluster_arns:
            return
        try:
            clusters = (ecs.describe_clusters(
                clusters=cluster_arns,
                include=["SETTINGS", "CONFIGURATIONS", "TAGS"]) or {}).get("clusters") or []
        except Exception as e:
            if self._is_access_denied(e):
                self._coverage.note_denied("ECS-10", "ecs:DescribeClusters")
            return

        for cluster in clusters:
            cname = str(cluster.get("clusterName") or "?")
            carn = str(cluster.get("clusterArn") or cname)

            ci = aws_cis_compute.ecs_container_insights(cluster)
            if ci["off"]:
                self._add("FAIL", "ECS-10", "ECS", cname, f"{ci['statement']} | {cname}")
            else:
                self._add("PASS", "ECS-10", "ECS", cname,
                          f"ECS cluster {cname} has Container Insights {ci['value']}")

            ct = aws_cis_compute.ecs_tags(cluster, "cluster", cname)
            if ct["untagged"]:
                self._add("FAIL", "ECS-12", "ECS", cname, f"{ct['statement']} | {cname}")

            fk = aws_cis_compute.ecs_fargate_ephemeral_cmk(cluster)
            if fk["aws_owned"]:
                self._add("FAIL", "FARGATE-03", "ECS", cname,
                          f"{fk['statement']} | {cname}")
            else:
                self._add("PASS", "FARGATE-03", "ECS", cname,
                          f"ECS cluster {cname} encrypts Fargate ephemeral storage with a "
                          f"customer-managed key")

            # Services: 3.8 platform version, 3.10 tags, 3.14 task sets, and the
            # Exec-enabled list 3.16 needs before the cluster can be judged at all.
            try:
                svc_arns = self._paginate_strict(ecs, "list_services", "serviceArns",
                                                 cluster=carn)
            except Exception as e:
                if self._is_access_denied(e):
                    self._coverage.note_denied("ECS-09", "ecs:ListServices")
                continue
            exec_enabled: List[str] = []
            for chunk in [svc_arns[i:i + 10] for i in range(0, len(svc_arns), 10)]:
                try:
                    services = (ecs.describe_services(
                        cluster=carn, services=chunk,
                        include=["TAGS"]) or {}).get("services") or []
                except Exception as e:
                    if self._is_access_denied(e):
                        self._coverage.note_denied("ECS-09", "ecs:DescribeServices")
                    continue
                for svc in services:
                    sname = str(svc.get("serviceName") or "?")
                    if svc.get("enableExecuteCommand"):
                        exec_enabled.append(sname)
                    pv = aws_cis_compute.ecs_platform_version(svc)
                    if pv["outdated"]:
                        self._add("FAIL", "ECS-09", "ECS", f"{cname}/{sname}",
                                  f"{pv['statement']} | {sname}")
                    st = aws_cis_compute.ecs_tags(svc, "service", sname)
                    if st["untagged"]:
                        self._add("FAIL", "ECS-11", "ECS", f"{cname}/{sname}",
                                  f"{st['statement']} | {sname}")
                    self._check_ecs_task_sets(ecs, carn, cname, svc)

            el = aws_cis_compute.ecs_exec_logging(cluster, exec_enabled)
            if el["unlogged"]:
                self._add("FAIL", "ECS-17", "ECS", cname, f"{el['statement']} | {cname}")
            elif el["applicable"]:
                self._add("PASS", "ECS-17", "ECS", cname,
                          f"ECS cluster {cname} logs ECS Exec sessions (logging=OVERRIDE)")

    def _check_ecs_task_sets(self, ecs, cluster_arn: str, cname: str, svc) -> None:
        """ECS-15 (CIS-Compute 3.14). Task sets exist only for EXTERNAL and blue/green
        deployment controllers, so on an ordinary ECS service describe_task_sets returns
        an empty list — cheap, and skipping the call by guessing the controller type
        would silently miss a service whose controller was changed later."""
        sname = str(svc.get("serviceName") or "?")
        try:
            sets = (ecs.describe_task_sets(
                cluster=cluster_arn,
                service=str(svc.get("serviceArn") or sname)) or {}).get("taskSets") or []
        except Exception as e:
            if self._is_access_denied(e):
                self._coverage.note_denied("ECS-15", "ecs:DescribeTaskSets")
            return
        for ts in sets:
            r = aws_cis_compute.ecs_task_set_public_ip(ts)
            if r["public"]:
                self._add("FAIL", "ECS-15", "ECS", f"{cname}/{sname}",
                          f"{r['statement']} | {sname}")

    # ECS-07/08 dangerous-primitive tables (bare cap names, no CAP_ prefix in the ECS API)
    _DANGEROUS_CAPS = {"ALL", "SYS_ADMIN", "NET_ADMIN", "SYS_PTRACE", "SYS_MODULE",
                       "DAC_READ_SEARCH", "SYS_RAWIO", "BPF", "NET_RAW"}
    _SENSITIVE_HOST_PATHS = {"/", "/etc", "/root", "/proc", "/sys",
                             "/var/run/docker.sock"}
    _SENSITIVE_HOST_DIRS = ("/var/run/", "/var/lib/docker/", "/var/lib/kubelet/",
                            "/etc/", "/root/", "/proc/", "/sys/")

    def _emit_runs_image(self, td: Dict, cd: Dict) -> None:
        """RUNS_IMAGE — ECS task-def container -> ECRImage node so image CVEs (from
        CNT-02 native scan OR Inspector VULN-03, which use DIFFERENT node ids) drive
        attack paths. Dual-emits to both id conventions. :tag refs resolve to a digest
        via a live in-account describe_images (best-effort); else a tag-keyed node."""
        p = parse_ecr_image_ref(cd.get("image", ""))
        if not p:
            return                              # non-ECR (Docker Hub etc.) — no ECRImage node
        digest = p["digest"]
        if not digest and p["tag"] and p["account"] == self.account:
            try:
                imgs = self._client("ecr", p["region"]).describe_images(
                    repositoryName=p["repo"], imageIds=[{"imageTag": p["tag"]}]
                ).get("imageDetails", [])
                if imgs:
                    digest = imgs[0].get("imageDigest")
            except Exception:
                digest = None
        g = self._ensure_graph()
        src = td.get("taskDefinitionArn", td.get("family", "ecs-task"))
        g.add_node(src, "ECSTaskDefinition", family=td.get("family"))
        cname = cd.get("name", "")
        # Stash each RUNS_IMAGE payload for replay in VULN#39: this section (ECS#20) runs
        # BEFORE IAMPRIVESC#36 hard-replaces the graph, so the inline edge is clobbered —
        # without the replay the Phase-7 image-CVE inheritance (_iter_vuln_edges) is dead.
        if digest:
            for node in ecr_image_node_ids(p["account"], p["region"], p["repo"], digest):
                g.add_node(node, "ECRImage", repository=p["repo"], digest=digest)
                g.add_edge(src, node, "RUNS_IMAGE", container=cname, scan_source="ecs")
                self._runs_image_payloads.append(
                    (src, {"family": td.get("family")}, node,
                     {"repository": p["repo"], "digest": digest},
                     {"container": cname, "scan_source": "ecs"}))
        else:
            # best-effort topology node (won't join digest-keyed CVE nodes)
            node = f"{p['account']}.dkr.ecr.{p['region']}.amazonaws.com/{p['repo']}:{p['tag'] or 'latest'}"
            g.add_node(node, "ECRImage", repository=p["repo"])
            g.add_edge(src, node, "RUNS_IMAGE", container=cname, resolved=False, scan_source="ecs")
            self._runs_image_payloads.append(
                (src, {"family": td.get("family")}, node, {"repository": p["repo"]},
                 {"container": cname, "resolved": False, "scan_source": "ecs"}))

    # ── Phase 3: running Fargate tasks (the exposure + identity anchor) ───────────
    _FARGATE_TASK_CAP = 200         # running tasks scanned per cluster (bounds cost)

    def _check_fargate_tasks(self, ecs, cluster_arns: List[str]) -> None:
        """Enumerate RUNNING Fargate tasks and STASH one payload per task (image ECRImage
        node ids + task role + ENI/IP). The running task — not the task-def — is what a
        serverless-container attack path hangs off, so EXPOSURE#37 folds it into internet
        exposure and VULN#40 replays its RUNS_IMAGE/HAS_ROLE edges past the graph clobber.
        Read-only; every ECS call is guarded so a denied API degrades to INFO, never crashes."""
        td_cache: Dict[str, Dict] = {}
        for carn in cluster_arns:
            cname = carn.split("/")[-1]
            try:
                # NB: do NOT server-side filter launchType="FARGATE" — a capacity-provider
                # task (FARGATE_SPOT) has launchType UNSET, so that filter would drop the
                # common Fargate-Spot shape. List ALL running tasks; classify client-side in
                # _stash_fargate_task (which accepts launchType==FARGATE OR a FARGATE* provider).
                task_arns: List[str] = []
                for page in ecs.get_paginator("list_tasks").paginate(
                        cluster=carn, desiredStatus="RUNNING"):
                    task_arns.extend(page.get("taskArns", []))
            except Exception as e:
                self._add("INFO", "FARGATE-01", "ECS", cname,
                          f"Fargate task enumeration unavailable on cluster {cname}: {e}")
                continue
            task_arns = task_arns[:self._FARGATE_TASK_CAP]
            for i in range(0, len(task_arns), 100):
                try:
                    tasks = ecs.describe_tasks(
                        cluster=carn, tasks=task_arns[i:i + 100]).get("tasks", [])
                except Exception as e:
                    self._add("INFO", "FARGATE-01", "ECS", cname,
                              f"Fargate task detail unavailable on cluster {cname} "
                              f"(DescribeTasks denied) — those tasks are not graphed: {e}")
                    continue
                for t in tasks:
                    self._stash_fargate_task(ecs, cname, t, td_cache)

    def _stash_fargate_task(self, ecs, cluster: str, t: Dict, td_cache: Dict) -> None:
        # Re-guard launch type client-side: capacity-provider tasks can report launchType
        # unset, so accept a FARGATE/FARGATE_SPOT capacityProviderName too.
        lt = t.get("launchType")
        cp = (t.get("capacityProviderName") or "").upper()
        if lt != "FARGATE" and not cp.startswith("FARGATE"):
            return
        task_arn = t.get("taskArn")
        if not task_arn:
            return
        td_arn = t.get("taskDefinitionArn", "")
        td = td_cache.get(td_arn)
        if td is None and td_arn:
            try:
                td = ecs.describe_task_definition(taskDefinition=td_arn)["taskDefinition"]
            except Exception:
                td = {}
            td_cache[td_arn] = td
        td = td or {}
        # taskRoleArn is the APP identity (what the container's code assumes) — the privesc/
        # data anchor; executionRoleArn (image-pull/logs) is deliberately ignored.
        task_role = (t.get("overrides") or {}).get("taskRoleArn") or td.get("taskRoleArn")

        eni_ids: List[str] = []
        private_ips: List[str] = []
        subnet_id = None
        for att in t.get("attachments", []):
            if att.get("type") != "ElasticNetworkInterface":
                continue
            for d in att.get("details", []):
                name, val = d.get("name"), d.get("value")
                if not val:
                    continue
                if name == "networkInterfaceId":
                    eni_ids.append(val)
                elif name in ("privateIPv4Address", "privateIpv4Address"):  # attachment vs container form
                    private_ips.append(val)
                elif name == "subnetId":
                    subnet_id = val

        # Prefer the running container's ALREADY-RESOLVED imageDigest (present on Fargate
        # platform 1.4+ in describe_tasks) so a mutable :tag ref still keys the digest-keyed
        # ECRImage node CNT-02/Inspector build — WITHOUT needing ecr:DescribeImages. Fall
        # back to the task def (no resolved digest there) and only then to describe_images.
        imgs = [(c.get("name", ""), c.get("image", ""), c.get("imageDigest"))
                for c in (t.get("containers") or []) if c.get("image")]
        if not imgs:
            imgs = [(c.get("name", ""), c.get("image", ""), None) for c in
                    (td.get("containerDefinitions") or []) if c.get("image")]
        image_nodes: List[tuple] = []
        for container, image, running_digest in imgs:
            p = parse_ecr_image_ref(image)
            if not p:
                continue                      # non-ECR (Docker Hub etc.) — no ECRImage node
            digest = p["digest"] or running_digest      # embedded @sha256, else the resolved one
            if not digest and p["tag"] and p["account"] == self.account:
                try:
                    di = self._client("ecr", p["region"]).describe_images(
                        repositoryName=p["repo"], imageIds=[{"imageTag": p["tag"]}]
                    ).get("imageDetails", [])
                    if di:
                        digest = di[0].get("imageDigest")
                except Exception:
                    digest = None
            if digest:
                for node in ecr_image_node_ids(p["account"], p["region"], p["repo"], digest):
                    image_nodes.append((node, {"repository": p["repo"], "digest": digest}, container))
            else:
                node = (f"{p['account']}.dkr.ecr.{p['region']}.amazonaws.com/"
                        f"{p['repo']}:{p['tag'] or 'latest'}")
                image_nodes.append((node, {"repository": p["repo"]}, container))

        props = {"cluster": cluster, "group": t.get("group"), "launch_type": "FARGATE",
                 "family": td.get("family"), "task_definition": td_arn,
                 "private_ip": private_ips[0] if private_ips else None,
                 "eni_id": eni_ids[0] if eni_ids else None, "subnet_id": subnet_id,
                 "assign_public_ip": None}
        self._fargate_payloads.append({
            "node_id": task_arn, "node_props": props, "task_role_arn": task_role,
            "image_nodes": image_nodes, "eni_ids": eni_ids, "private_ips": private_ips,
            "subnet_id": subnet_id, "cluster": cluster})
        self._add("INFO", "FARGATE-01", "ECS", cluster,
                  f"Running Fargate task {task_arn.split('/')[-1]} "
                  f"(family {td.get('family') or '?'}, {len(image_nodes)} image ref(s), "
                  f"task role {(task_role or 'none').split('/')[-1]}) — folded into the "
                  f"attack-path graph | {task_arn}")

    @staticmethod
    def _emit_one_fargate(g, pl: dict) -> None:
        """Emit ONE stashed task's node + RUNS_IMAGE + HAS_ROLE (MERGE-idempotent). Shared by
        the EXPOSURE#37 inline path (exposed tasks, so the attack path is graph-complete for
        DATA#42/CORRELATE#43 even when VULN is deselected) and the VULN#40 full replay."""
        g.add_node(pl["node_id"], "ECSFargateTask",
                   **{k: v for k, v in pl["node_props"].items() if v is not None})
        for node, nprops, container in pl["image_nodes"]:
            g.add_node(node, "ECRImage", **{k: v for k, v in nprops.items() if v is not None})
            g.add_edge(pl["node_id"], node, "RUNS_IMAGE",
                       container=container, scan_source="ecs-fargate")
        if pl.get("task_role_arn"):
            g.add_edge(pl["node_id"], pl["task_role_arn"], "HAS_ROLE", role_type="task")

    def _replay_fargate_edges(self) -> None:
        """Re-emit ALL stashed Fargate task node + RUNS_IMAGE + HAS_ROLE edges (VULN#40, after
        IAMPRIVESC#36 rebuilds the graph — covers private tasks EXPOSURE didn't wire). A
        SEPARATE lane from _replay_runs_image_edges (which hardcodes ECSTaskDefinition), so the
        existing ECS task-def replay stays byte-identical. MERGE-idempotent."""
        if not self._fargate_payloads:
            return
        g = self._ensure_graph()
        if g is None:
            return
        for pl in self._fargate_payloads:
            self._emit_one_fargate(g, pl)

    # ── Phase 3 KSPM/KIEM: clobber-safe K8s cross-plane graph lane ───────────────
    @staticmethod
    def _emit_one_kube(g, pl: dict) -> None:
        """Emit ONE stashed K8s payload's nodes/edges (MERGE-idempotent). Every edge reuses an
        existing E_PATH kind, so aws_correlate is UNCHANGED. ``KubeAdminCapability`` carries
        crown_jewel=True so aws_correlate.crown_nodes picks it up (prop-based) as a data terminal
        with no kind edit. Shared by the EXPOSURE inline path and the VULN#40 replay."""
        kind = pl.get("kind")
        if kind == "principal_admin":
            cap = pl["admin_cap"]
            g.add_node(cap, "KubeAdminCapability", cluster_arn=pl["cluster_arn"], crown_jewel=True)
            # AWS principal (already an IAMUser/IAMRole node post-IAMPRIVESC) -> K8s cluster-admin.
            g.add_edge(pl["principal"], cap, "CAN_PRIVESC_TO",
                       basis="eks-access-entry", conditioned=bool(pl.get("conditioned")))
        elif kind == "sa_role":
            g.add_node(pl["sa_node"], "KubeServiceAccount", cluster_arn=pl["cluster_arn"],
                       namespace=pl.get("namespace"), name=pl.get("sa_name"))
            # IRSA / Pod Identity: the IAM role's web-identity/pod-identity trust is definitionally
            # satisfied from the SA, so conditioned=False (must not cap to the conditioned band).
            g.add_edge(pl["sa_node"], pl["role_arn"], "CAN_ASSUME",
                       basis=pl.get("basis", "irsa"), conditioned=False)
        elif kind == "sa_admin":
            cap = pl["admin_cap"]
            g.add_node(cap, "KubeAdminCapability", cluster_arn=pl["cluster_arn"], crown_jewel=True)
            g.add_node(pl["sa_node"], "KubeServiceAccount", cluster_arn=pl["cluster_arn"],
                       namespace=pl.get("namespace"), name=pl.get("sa_name"))
            g.add_edge(pl["sa_node"], cap, "CAN_PRIVESC_TO", basis="k8s-rbac", conditioned=False)
        elif kind == "pod_sa":
            pod = pl["pod_node"]
            g.add_node(pod, "KubePod", cluster_arn=pl["cluster_arn"], namespace=pl.get("namespace"),
                       name=pl.get("pod_name"), private_ip=pl.get("private_ip"))
            g.add_node(pl["sa_node"], "KubeServiceAccount", cluster_arn=pl["cluster_arn"],
                       namespace=pl.get("namespace"), name=pl.get("sa_name"))
            g.add_edge(pod, pl["sa_node"], "HAS_ROLE", role_type="k8s-sa")
            for node, nprops, container in pl.get("image_nodes", []):
                g.add_node(node, "ECRImage", **{k: v for k, v in nprops.items() if v is not None})
                g.add_edge(pod, node, "RUNS_IMAGE", container=container, scan_source="eks-pod")

    def _replay_kube_edges(self) -> None:
        """Re-emit ALL stashed K8s cross-plane edges (VULN#40, after IAMPRIVESC#36 rebuilds the
        graph) so a principal->KubeAdminCapability escalation and an SA->IRSA-role CAN_ASSUME land
        on the already-built IAM principal/role nodes (with their live CAN_PRIVESC_TO/CAN_READ_DATA).
        MERGE-idempotent; EXPOSURE#37 may have emitted the exposed subset already."""
        if not self._kube_payloads:
            return
        g = self._ensure_graph()
        if g is None:
            return
        for pl in self._kube_payloads:
            self._emit_one_kube(g, pl)

    # ══════════════════════════════════════════════════════════════════════════
    # SECTION 20: AWS SECRETS MANAGER
    # ══════════════════════════════════════════════════════════════════════════
    def _check_secrets(self):
        self._section_header("SECRETS")
        sm = self._client("secretsmanager")

        try:
            paginator = sm.get_paginator("list_secrets")
            secrets = []
            for page in paginator.paginate():
                secrets.extend(page["SecretList"])
        except Exception as e:
            self._read_failed("SEC-01", "SECRETS", "secrets",
                              "secretsmanager:ListSecrets", e)
            return
        if not secrets:
            self._add("INFO", "SEC-01", "SECRETS", "secrets",
                      "No secrets found in Secrets Manager")
            return

        now = datetime.now(timezone.utc)
        for s in secrets:
            sname = s.get("Name", "unknown")
            # SEC-01 — Rotation enabled
            if not s.get("RotationEnabled", False):
                self._add("FAIL", "SEC-01", "SECRETS", sname,
                          f"Secret '{sname}' rotation NOT enabled")
            else:
                # SEC-02 — Rotation frequency
                rules = s.get("RotationRules", {})
                days = rules.get("AutomaticallyAfterDays", 0)
                if days > 90:
                    self._add("FAIL", "SEC-02", "SECRETS", sname,
                              f"Secret '{sname}' rotates every {days}d, past the "
                              f"90-day maximum — a credential lives that long "
                              f"after a compromise nobody noticed")
                else:
                    self._add("PASS", "SEC-02", "SECRETS", sname,
                              f"Secret '{sname}' rotation every {days}d")
            # SEC-03 — KMS encryption
            kms_id = s.get("KmsKeyId", "")
            if not kms_id or kms_id == "aws/secretsmanager":
                self._add("WARN", "SEC-03", "SECRETS", sname,
                          f"Secret '{sname}' uses AWS-managed KMS key "
                          "(consider CMK)")
            else:
                self._add("PASS", "SEC-03", "SECRETS", sname,
                          f"Secret '{sname}' encrypted with CMK")
            # SEC-04 — Last accessed / unused
            last_accessed = s.get("LastAccessedDate")
            if last_accessed:
                age = (now - last_accessed).days
                if age > 90:
                    self._add("WARN", "SEC-04", "SECRETS", sname,
                              f"Secret '{sname}' not accessed in {age} days")
            # SEC-05 — resource policy public / cross-account exposure
            self._check_secret_policy(sm, s)

    def _check_secret_policy(self, sm, s: Dict) -> None:
        """SEC-05 — Secrets Manager resource-policy public/cross-account exposure. Its
        own try/except per secret so one AccessDenied never aborts the SECRETS section.
        No resource policy attached => IAM-only access (the common case) => silent."""
        arn = s.get("ARN", "")
        sname = s.get("Name", arn)
        try:
            pol_str = sm.get_resource_policy(SecretId=arn).get("ResourcePolicy")
        except Exception:
            return
        if not pol_str:
            return
        try:
            stmts = json.loads(pol_str).get("Statement", [])
        except Exception:
            return
        if isinstance(stmts, dict):
            stmts = [stmts]
        trusted = getattr(self, "trusted_accounts", set())
        public = public_cond = False
        cross: set = set()
        org_id = None
        for st in stmts:
            c = classify_resource_policy_stmt(st, self.account or "")
            if not c:
                continue
            if c["kind"] == "public":
                public = True
            elif c["kind"] == "public_conditioned":
                public_cond = True
            elif c["kind"] == "org":
                org_id = c.get("org_id") or org_id
            elif c["kind"] == "cross_account":
                cross.update(a for a in c["external_accounts"] if a not in trusted)
        if not (public or public_cond or cross or org_id):
            return                              # same-account only — no noise
        g = self._ensure_graph()
        g.add_node(arn, "SecretsManagerSecret", name=sname, scan_source="secrets")
        if public:
            g.add_node("internet", "InternetSource", cidr="0.0.0.0/0")
            g.add_edge("internet", arn, "SHARED_SECRET", public=True, scan_source="secrets")
            self._add("FAIL", "SEC-05", "SECRETS", sname,
                      f"Secret resource policy grants PUBLIC access (wildcard principal, "
                      f"unconditioned) — readable by any AWS principal | {sname}")
        elif cross:
            for acct in sorted(cross):
                g.add_node("account:" + acct, "AWSAccount", account=acct, external=True)
                g.add_edge("account:" + acct, arn, "SHARED_SECRET", external_account=acct,
                           scan_source="secrets")
            self._add("FAIL", "SEC-05", "SECRETS", sname,
                      f"Secret resource policy grants CROSS-ACCOUNT access to "
                      f"{', '.join(sorted(cross))} | {sname}")
        elif public_cond:
            self._add("WARN", "SEC-05", "SECRETS", sname,
                      f"Secret resource policy wildcard principal is condition-guarded — "
                      f"verify it restricts access | {sname}")
        elif org_id:
            self._add("WARN", "SEC-05", "SECRETS", sname,
                      f"Secret resource policy shares to AWS Organization {org_id} — "
                      f"verify it is your org | {sname}")

    # ══════════════════════════════════════════════════════════════════════════
    # SECTION 21: AWS WAF
    # ══════════════════════════════════════════════════════════════════════════
    def _check_waf(self):
        self._section_header("WAF")
        waf = self._client("wafv2")

        for scope in ("REGIONAL", "CLOUDFRONT"):
            region = "us-east-1" if scope == "CLOUDFRONT" else None
            client = self._client("wafv2", region=region) if region else waf
            try:
                acls = client.list_web_acls(Scope=scope).get("WebACLs", [])
            except Exception as e:
                self._add("WARN", "WAF-01", "WAF", scope, str(e))
                continue

            if not acls:
                self._add("WARN", "WAF-01", "WAF", scope,
                          f"No WAFv2 Web ACLs ({scope})")
                continue

            for acl in acls:
                aname = acl.get("Name", "unknown")
                acl_arn = acl.get("ARN", "")
                # WAF-02 — Logging
                try:
                    log_cfg = client.get_logging_configuration(
                        ResourceArn=acl_arn
                    ).get("LoggingConfiguration", {})
                    if log_cfg:
                        self._add("PASS", "WAF-02", "WAF", aname,
                                  f"WAF logging enabled | {aname}")
                    else:
                        self._add("FAIL", "WAF-02", "WAF", aname,
                                  f"WAF logging NOT enabled | {aname}")
                except ClientError:
                    self._add("FAIL", "WAF-02", "WAF", aname,
                              f"WAF logging NOT configured | {aname}")

                # WAF-03 — Rules count
                try:
                    detail = client.get_web_acl(
                        Name=aname, Scope=scope, Id=acl.get("Id", "")
                    ).get("WebACL", {})
                    rules = detail.get("Rules", [])
                    if not rules:
                        self._add("FAIL", "WAF-03", "WAF", aname,
                                  f"WAF '{aname}' has no rules defined")
                    else:
                        self._add("PASS", "WAF-03", "WAF", aname,
                                  f"WAF '{aname}' has {len(rules)} rule(s)")
                    # WAF-04 — Default action
                    default_action = detail.get("DefaultAction", {})
                    if "Allow" in default_action:
                        self._add("FAIL", "WAF-04", "WAF", aname,
                                  f"WAF '{aname}' default action is ALLOW — any "
                                  f"request matching no rule is permitted, so the "
                                  f"ACL only blocks what it explicitly names")
                    # WAF-05 — managed rule group presence (baseline OWASP coverage). Only
                    # when rules exist (WAF-03 owns the no-rules FAIL). A managed group nested
                    # inside And/Or/Not/ScopeDown is not detected — top-level is the norm.
                    if rules:
                        has_managed = any(
                            (r.get("Statement") or {}).get("ManagedRuleGroupStatement")
                            for r in rules)
                        if has_managed:
                            self._add("PASS", "WAF-05", "WAF", aname,
                                      f"WAF '{aname}' includes an AWS/vendor managed rule group")
                        else:
                            self._add("FAIL", "WAF-05", "WAF", aname,
                                      f"WAF '{aname}' has {len(rules)} rule(s) but NO AWS/vendor "
                                      f"managed rule group — no managed OWASP/known-bad-input coverage")
                except Exception as e:
                    # was a bare `except: pass` — surface the read error instead of vanishing
                    self._add("WARN", "WAF-03", "WAF", aname,
                              f"could not read WebACL detail: {e}")

        self._check_waf_unprotected_entry_points()

    def _check_drs(self):
        """DRS-01..04 — AWS Elastic Disaster Recovery.

        WHY THIS SECTION EXISTS. A DR setup keeps a continuous copy of every
        protected disk in a staging subnet that is not production, is rarely looked
        at, and is administered by a different template from the workloads it
        shadows. `ebsEncryption` carries a real NONE value, so "the whole estate's
        data, unencrypted, somewhere nobody watches" is a state the API will report
        if you ask — and nothing in OverWatch asked until now.

        The benchmark's section 6 is the only part of the document that names real,
        readable settings; see engine/aws_cis_storage_map.py for what the other 43
        recommendations turned out to be.
        """
        self._section_header("DRS")
        try:
            drs = self._client("drs")
            templates = self._tokens(
                drs.describe_replication_configuration_templates,
                "items", token_key="nextToken")
        except Exception as e:
            if self._is_access_denied(e):
                for cid in ("DRS-01", "DRS-02"):
                    self._coverage.note_denied(
                        cid, "drs:DescribeReplicationConfigurationTemplates")
            templates = None

        for tpl in (templates or []):
            p = aws_cis_storage.replication_template_posture(tpl)
            name = p["id"] or "replication-template"
            if p["encryption_known"] and p["unencrypted"]:
                self._add("FAIL", "DRS-01", "DRS", name,
                          f"Replication template {name} stages replicated disks with "
                          f"EBS encryption set to NONE — a continuous copy of every "
                          f"protected volume sits unencrypted in the staging subnet, "
                          f"which is the one place production data lives outside "
                          f"production | {name}")
            elif p["encryption_known"]:
                self._add("PASS", "DRS-01", "DRS", name,
                          f"Replication template {name} encrypts staging volumes "
                          f"({p['encryption']}) | {name}")

            if p["routing_known"] and p["public_routing"]:
                self._add("FAIL", "DRS-02", "DRS", name,
                          f"Replication template {name} routes replication traffic "
                          f"over PUBLIC_IP — a byte-for-byte copy of production "
                          f"disks crosses the public internet continuously. The "
                          f"benchmark's own guidance for this setting is to keep it "
                          f"on private connectivity | {name}")
            elif p["routing_known"]:
                self._add("PASS", "DRS-02", "DRS", name,
                          f"Replication template {name} keeps replication on "
                          f"{p['routing']} | {name}")

        try:
            servers = self._tokens(drs.describe_source_servers, "items",
                                   token_key="nextToken")
        except Exception as e:
            if self._is_access_denied(e):
                for cid in ("DRS-03", "DRS-04"):
                    self._coverage.note_denied(cid, "drs:DescribeSourceServers")
            return

        for srv in (servers or []):
            p = aws_cis_storage.source_server_posture(srv)
            name = p["id"] or "source-server"
            # DRS-03 — is the copy current? An in-flight state (INITIAL_SYNC,
            # BACKLOG, RESCAN) is a server catching up rather than a broken one, so
            # only the states in UNHEALTHY_REPLICATION_STATES fail.
            if p["state_known"] and p["unhealthy"]:
                lag = f", lag {p['lag']}" if p["lag"] else ""
                self._add("FAIL", "DRS-03", "DRS", name,
                          f"Source server {name} replication is {p['state']}{lag} — "
                          f"the recovery point is frozen at whenever it stopped, so "
                          f"the protection this server appears to have is stale by "
                          f"an unknown amount | {name}")
            elif p["state_known"]:
                self._add("PASS", "DRS-03", "DRS", name,
                          f"Source server {name} replication is {p['state']} | {name}")

            # DRS-04 — has recovery ever been exercised? Benchmark 6.8 asks for a
            # drill; lastLaunchResult answers it without inference.
            if p["never_launched"]:
                self._add("FAIL", "DRS-04", "DRS", name,
                          f"Source server {name} has never been launched — no drill "
                          f"and no real recovery has ever run against it, so nothing "
                          f"has demonstrated that the replicated disks boot. An "
                          f"untested recovery is a plan, not a capability | {name}")
            elif p["launch_failed"]:
                self._add("FAIL", "DRS-04", "DRS", name,
                          f"Source server {name} last recovery launch FAILED and has "
                          f"not succeeded since — worse than untested, because the "
                          f"one attempt on record did not work | {name}")
            elif p["launch_known"]:
                self._add("PASS", "DRS-04", "DRS", name,
                          f"Source server {name} last recovery launch: "
                          f"{p['launch_result']} | {name}")

    def _check_workspaces(self):
        """WKS-01..09 — Amazon WorkSpaces, an employee's whole desktop.

        WHY THIS SECTION EXISTS. A WorkSpace is a persistent Windows or Linux
        desktop holding whatever its owner put on it, reachable from any device on
        the internet unless somebody narrowed that. Nothing in OverWatch could see
        one. Section 2 of the CIS End User Compute benchmark is the largest in that
        document and most of it maps onto fields the API returns plainly.

        WKS-08 answers no recommendation: the benchmark never asks whether desktop
        users are local administrators of their own machine. See
        engine/aws_cis_euc_map.py.
        """
        self._section_header("WORKSPACES")
        try:
            ws = self._client("workspaces")
            directories = self._tokens(ws.describe_workspace_directories,
                                       "Directories")
        except Exception as e:
            if self._is_access_denied(e):
                for cid in ("WKS-02", "WKS-03", "WKS-04", "WKS-06", "WKS-08",
                            "WKS-09"):
                    self._coverage.note_denied(
                        cid, "workspaces:DescribeWorkspaceDirectories")
            return

        # The RADIUS configuration lives on the Directory Service directory, not on
        # the WorkSpaces registration, so WKS-06/07 need a second read. Scoped to
        # directories WorkSpaces actually uses: a directory serving something else
        # is not failed for a second factor it has no reason to carry.
        radius_by_id = {}
        if directories:
            try:
                ds = self._client("ds")
                for d in self._tokens(ds.describe_directories,
                                      "DirectoryDescriptions") or []:
                    r = aws_cis_euc.radius_posture(d)
                    if r["id"]:
                        radius_by_id[r["id"]] = r
            except Exception as e:
                if self._is_access_denied(e):
                    for cid in ("WKS-06", "WKS-07"):
                        self._coverage.note_denied(cid, "ds:DescribeDirectories")

        for d in (directories or []):
            p = aws_cis_euc.directory_posture(d)
            name = p["name"] or p["id"] or "workspaces-directory"
            if p["web_known"] and p["web_allowed"]:
                self._add("FAIL", "WKS-02", "WORKSPACES", name,
                          f"WorkSpaces directory {name} permits browser access to "
                          f"desktops — the one client that runs on an unmanaged "
                          f"machine with nothing installed, which is what makes it "
                          f"convenient and what makes it the weakest way in "
                          f"| {name}")
            elif p["web_known"]:
                self._add("PASS", "WKS-02", "WORKSPACES", name,
                          f"WorkSpaces directory {name} denies browser access "
                          f"| {name}")

            if not p["ip_restricted"]:
                self._add("FAIL", "WKS-03", "WORKSPACES", name,
                          f"WorkSpaces directory {name} has no IP access control "
                          f"group, so the default group applies and a desktop can "
                          f"be reached from any source address on the internet "
                          f"| {name}")
            else:
                self._add("PASS", "WKS-03", "WORKSPACES", name,
                          f"WorkSpaces directory {name} restricts source addresses "
                          f"({len(p['ip_groups'])} group(s)) | {name}")

            if p["maintenance_known"] and not p["maintenance_enabled"]:
                self._add("FAIL", "WKS-04", "WORKSPACES", name,
                          f"WorkSpaces directory {name} has maintenance mode off, "
                          f"so desktops get no window in which to install "
                          f"operating-system patches. If another tool patches them, "
                          f"record that and accept this finding | {name}")
            elif p["maintenance_known"]:
                self._add("PASS", "WKS-04", "WORKSPACES", name,
                          f"WorkSpaces directory {name} has maintenance mode on "
                          f"| {name}")

            if p["local_admin_known"] and p["users_are_local_admin"]:
                self._add("FAIL", "WKS-08", "WORKSPACES", name,
                          f"WorkSpaces directory {name} makes every user a local "
                          f"administrator of their own desktop, so anything running "
                          f"as them can install a service, disable the agent and "
                          f"survive a reboot. The benchmark never asks this "
                          f"| {name}")
            elif p["local_admin_known"]:
                self._add("PASS", "WKS-08", "WORKSPACES", name,
                          f"WorkSpaces directory {name} does not grant users local "
                          f"administrator | {name}")

            if p["internet_known"] and p["direct_internet"]:
                self._add("FAIL", "WKS-09", "WORKSPACES", name,
                          f"WorkSpaces directory {name} attaches a public address "
                          f"to every desktop it creates, putting each one directly "
                          f"on the internet instead of behind mediated egress "
                          f"| {name}")
            elif p["internet_known"]:
                self._add("PASS", "WKS-09", "WORKSPACES", name,
                          f"WorkSpaces directory {name} does not assign public "
                          f"addresses to desktops | {name}")

            r = radius_by_id.get(p["id"])
            if r is not None and (not r["configured"] or r["failed"]):
                why = ("is in a FAILED state, so the console shows a second factor "
                       "that sign-in does not actually require"
                       if r["failed"] else "has no RADIUS server attached")
                self._add("FAIL", "WKS-06", "WORKSPACES", name,
                          f"The directory behind WorkSpaces {name} {why} — desktop "
                          f"sign-in rests on a password alone | {name}")
            elif r is not None:
                self._add("PASS", "WKS-06", "WORKSPACES", name,
                          f"The directory behind WorkSpaces {name} requires a second "
                          f"factor (RADIUS {r['status']}) | {name}")
            if r is not None and r["protocol_known"] and r["weak_protocol"]:
                self._add("FAIL", "WKS-07", "WORKSPACES", name,
                          f"The directory behind WorkSpaces {name} carries its "
                          f"second factor over {r['protocol']}, which does not "
                          f"protect the credential it transports. "
                          f"{aws_cis_euc.STRONGEST_RADIUS_PROTOCOL} is the "
                          f"strongest of the four protocols the service offers — "
                          f"which is not the same as strong | {name}")
            elif r is not None and r["protocol_known"]:
                self._add("PASS", "WKS-07", "WORKSPACES", name,
                          f"The directory behind WorkSpaces {name} uses "
                          f"{r['protocol']} | {name}")

        try:
            spaces = self._tokens(ws.describe_workspaces, "Workspaces")
        except Exception as e:
            if self._is_access_denied(e):
                self._coverage.note_denied("WKS-01", "workspaces:DescribeWorkspaces")
            return

        for w in (spaces or []):
            p = aws_cis_euc.workspace_volume_posture(w)
            name = p["id"] or "workspace"
            who = f" ({p['user_name']})" if p["user_name"] else ""
            if p["known"] and p["any_unencrypted"]:
                self._add("FAIL", "WKS-01", "WORKSPACES", name,
                          f"WorkSpace {name}{who} has its "
                          f"{' and '.join(p['unencrypted'])} volume(s) unencrypted "
                          f"— the desktop holds whatever its owner put on it, and "
                          f"encryption cannot be added after launch | {name}")
            elif p["known"]:
                self._add("PASS", "WKS-01", "WORKSPACES", name,
                          f"WorkSpace {name}{who} encrypts both volumes | {name}")

        try:
            statuses = self._tokens(ws.describe_workspaces_connection_status,
                                    "WorkspacesConnectionStatus")
        except Exception as e:
            if self._is_access_denied(e):
                self._coverage.note_denied(
                    "WKS-05", "workspaces:DescribeWorkspacesConnectionStatus")
            return

        now = datetime.now(timezone.utc).timestamp()
        for s in (statuses or []):
            p = aws_cis_euc.workspace_idle_posture(s, now)
            name = p["id"] or "workspace"
            if p["never"]:
                self._add("FAIL", "WKS-05", "WORKSPACES", name,
                          f"WorkSpace {name} has never been connected to. It is "
                          f"being billed, and it is an account that can still sign "
                          f"in | {name}")
            elif p["idle"]:
                self._add("FAIL", "WKS-05", "WORKSPACES", name,
                          f"WorkSpace {name} has not been used for {p['days']} days "
                          f"| {name}")
            else:
                self._add("PASS", "WKS-05", "WORKSPACES", name,
                          f"WorkSpace {name} was last used {p['days']} day(s) ago "
                          f"| {name}")

    def _check_appstream(self):
        """APS-01..06 — AppStream 2.0, applications streamed to a browser.

        The same shape of asset as WorkSpaces and the same blind spot: a fleet runs
        software a user chose, on an instance holding an IAM role, and nothing here
        looked at one. APS-05 answers no recommendation — the benchmark never asks
        whether the fleet still serves IMDSv1, which is the AppStream form of the
        credential path EC2 closed with IMDSv2.
        """
        self._section_header("APPSTREAM")
        try:
            ap = self._client("appstream")
            fleets = self._tokens(ap.describe_fleets, "Fleets")
        except Exception as e:
            if self._is_access_denied(e):
                for cid in ("APS-01", "APS-02", "APS-04", "APS-05"):
                    self._coverage.note_denied(cid, "appstream:DescribeFleets")
            return

        for f in (fleets or []):
            n = aws_cis_euc.fleet_network_posture(f)
            name = n["name"] or "fleet"
            if n["internet_known"] and n["direct_internet"]:
                self._add("FAIL", "APS-01", "APPSTREAM", name,
                          f"AppStream fleet {name} gives streaming instances public "
                          f"addresses through the default internet path rather than "
                          f"routing their egress through your VPC | {name}")
            elif n["internet_known"]:
                self._add("PASS", "APS-01", "APPSTREAM", name,
                          f"AppStream fleet {name} does not use default internet "
                          f"access | {name}")

            if not n["in_vpc"]:
                self._add("FAIL", "APS-02", "APPSTREAM", name,
                          f"AppStream fleet {name} is not attached to a VPC, so its "
                          f"traffic is subject to none of your routing, security "
                          f"groups or flow logs | {name}")
            else:
                self._add("PASS", "APS-02", "APPSTREAM", name,
                          f"AppStream fleet {name} runs in your VPC "
                          f"({len(n['subnets'])} subnet(s)) | {name}")

            if n["imds_known"] and n["imdsv1_enabled"]:
                self._add("FAIL", "APS-05", "APPSTREAM", name,
                          f"AppStream fleet {name} still answers IMDSv1, so any "
                          f"process inside a streaming session can read the fleet "
                          f"role's credentials with one unauthenticated request. "
                          f"The benchmark never asks this | {name}")
            elif n["imds_known"]:
                self._add("PASS", "APS-05", "APPSTREAM", name,
                          f"AppStream fleet {name} requires IMDSv2 | {name}")

            s = aws_cis_euc.fleet_session_posture(f)
            if s["known"] and s["any_over"]:
                self._add("FAIL", "APS-04", "APPSTREAM", name,
                          f"AppStream fleet {name} session limits exceed the "
                          f"benchmark: {'; '.join(s['over'])} — a session nobody is "
                          f"sitting at stays live and billable | {name}")
            elif s["known"]:
                self._add("PASS", "APS-04", "APPSTREAM", name,
                          f"AppStream fleet {name} session limits are within the "
                          f"benchmark | {name}")

        try:
            stacks = self._tokens(ap.describe_stacks, "Stacks")
        except Exception as e:
            if self._is_access_denied(e):
                self._coverage.note_denied("APS-03", "appstream:DescribeStacks")
            stacks = None

        for st in (stacks or []):
            p = aws_cis_euc.stack_endpoint_posture(st)
            name = p["name"] or "stack"
            if not p["private_streaming"]:
                self._add("FAIL", "APS-03", "APPSTREAM", name,
                          f"AppStream stack {name} has no VPC streaming endpoint, "
                          f"so every session — keystrokes, screen and clipboard — "
                          f"crosses the public internet to reach the user | {name}")
            else:
                self._add("PASS", "APS-03", "APPSTREAM", name,
                          f"AppStream stack {name} streams over a VPC endpoint "
                          f"({', '.join(p['endpoints'])}) | {name}")

        try:
            images = self._tokens(ap.describe_images, "Images", Type="PRIVATE")
        except Exception as e:
            if self._is_access_denied(e):
                self._coverage.note_denied("APS-06", "appstream:DescribeImages")
            return

        now = datetime.now(timezone.utc).timestamp()
        for im in (images or []):
            name = (im or {}).get("Name") or "image"
            p = aws_cis_euc.image_age_posture((im or {}).get("CreatedTime"), now)
            if p["known"] and p["stale"]:
                self._add("FAIL", "APS-06", "APPSTREAM", name,
                          f"AppStream image {name} was built {p['days']} days ago, "
                          f"so every session launched from it carries whatever was "
                          f"unpatched that day | {name}")
            elif p["known"]:
                self._add("PASS", "APS-06", "APPSTREAM", name,
                          f"AppStream image {name} was built {p['days']} day(s) ago "
                          f"| {name}")

    def _check_waf_unprotected_entry_points(self):
        """WAF-06 — an internet-facing load balancer with no Web ACL in front of it.

        WHY THIS IS A NEW ID AND NOT A FAIL ADDED TO WAF-01. WAF-01 warns when a
        scope holds no Web ACLs at all, which on a correct estate that needs no WAF
        is an unactionable finding — tranche 7 recorded that and declined to flip
        it. The useful question is not "are there Web ACLs" but "is anything
        reachable from the internet left unprotected", and that is a different
        subject: it is about the load balancer, not the ACL. Giving WAF-01 this
        logic would silently change what the id means for anyone already filtering
        or waiving on it, so the meaning stays put and the new question gets its
        own id.

        FAIL-OPEN ON EVERY DENIAL. Either read being refused makes the comparison
        unsound in the direction that matters: an unreadable association list looks
        exactly like an empty one, and an empty one turns every load balancer into
        a finding. A denial is recorded in the coverage ledger and nothing is
        claimed.
        """
        protected: set = set()
        try:
            waf = self._client("wafv2")
            acls = waf.list_web_acls(Scope="REGIONAL").get("WebACLs", []) or []
        except Exception as e:
            if self._is_access_denied(e):
                self._coverage.note_denied("WAF-06", "wafv2:ListWebACLs")
            return
        for acl in acls:
            arn = (acl or {}).get("ARN")
            if not arn:
                continue
            try:
                protected.update(
                    waf.list_resources_for_web_acl(WebACLArn=arn).get(
                        "ResourceArns", []) or [])
            except Exception as e:
                if self._is_access_denied(e):
                    self._coverage.note_denied(
                        "WAF-06", "wafv2:ListResourcesForWebACL")
                return                      # a partial set would invent findings

        try:
            elb = self._client("elbv2")
            balancers = elb.describe_load_balancers().get(
                "LoadBalancers", []) or []
        except Exception as e:
            if self._is_access_denied(e):
                self._coverage.note_denied(
                    "WAF-06", "elasticloadbalancing:DescribeLoadBalancers")
            return

        for lb in balancers:
            # Only APPLICATION load balancers can carry a Web ACL at all; a
            # network load balancer operates below the layer a WAF inspects, so
            # reporting one would be a finding nobody can act on.
            if (lb or {}).get("Type") != "application":
                continue
            if lb.get("Scheme") != "internet-facing":
                continue
            arn, name = lb.get("LoadBalancerArn"), lb.get("LoadBalancerName")
            if not arn:
                continue
            if arn in protected:
                self._add("PASS", "WAF-06", "WAF", name or arn,
                          f"Internet-facing ALB {name} is associated with a Web "
                          f"ACL | {name}")
            else:
                self._add("FAIL", "WAF-06", "WAF", name or arn,
                          f"Internet-facing application load balancer {name} has "
                          f"no WAFv2 Web ACL associated — every request reaches "
                          f"the application unfiltered, including the "
                          f"known-bad-input classes a managed rule group would "
                          f"drop | {name}")

    # ══════════════════════════════════════════════════════════════════════════
    # SECTION 22: AMAZON ELASTICACHE
    # ══════════════════════════════════════════════════════════════════════════
    def _check_elasticache(self):
        self._section_header("ELASTICACHE")
        ec = self._client("elasticache")

        # ELC-01..04 + ELC-06 — Redis/Valkey replication groups. Do NOT early-return on
        # empty/error: ELC-05 (engine EOL, below) must still run — it covers Memcached
        # (which has no replication group at all) via describe_cache_clusters.
        try:
            clusters = ec.describe_replication_groups().get(
                "ReplicationGroups", [])
        except Exception as e:
            self._add("WARN", "ELC-01", "ELASTICACHE", "elasticache", str(e))
            clusters = None
        if clusters is not None and not clusters:
            self._add("INFO", "ELC-01", "ELASTICACHE", "elasticache",
                      "No ElastiCache replication groups found")

        for rg in (clusters or []):
            rgid = rg.get("ReplicationGroupId", "unknown")
            # ELC-09 (CIS-DB 5.6) — log delivery. Reads a field this same
            # describe_replication_groups response already carried, so no extra call.
            _r = aws_cis_db2.elasticache_log_delivery(rg)
            if _r.get("failed"):
                self._add("FAIL", "ELC-09", "ELASTICACHE", rgid, _r["statement"])
            elif not _r.get("unknown"):
                self._add("PASS", "ELC-09", "ELASTICACHE", rgid,
                          f"Log delivery configured | {rgid}")
            # ELC-01 — Encryption at rest
            if rg.get("AtRestEncryptionEnabled", False):
                self._add("PASS", "ELC-01", "ELASTICACHE", rgid,
                          f"Encryption at rest=ON | {rgid}")
            else:
                self._add("FAIL", "ELC-01", "ELASTICACHE", rgid,
                          f"Encryption at rest=OFF | {rgid}")
            # ELC-02 — Encryption in transit
            if rg.get("TransitEncryptionEnabled", False):
                self._add("PASS", "ELC-02", "ELASTICACHE", rgid,
                          f"Encryption in transit=ON | {rgid}")
            else:
                self._add("FAIL", "ELC-02", "ELASTICACHE", rgid,
                          f"Encryption in transit=OFF | {rgid}")
            # ELC-03 — Auth token (password)
            if rg.get("AuthTokenEnabled", False):
                self._add("PASS", "ELC-03", "ELASTICACHE", rgid,
                          f"AUTH token=ON | {rgid}")
            else:
                self._add("FAIL", "ELC-03", "ELASTICACHE", rgid,
                          f"AUTH token=OFF (unauthenticated access) | {rgid}")
            # ELC-04 — Auto failover
            if rg.get("AutomaticFailover", "") == "enabled":
                self._add("PASS", "ELC-04", "ELASTICACHE", rgid,
                          f"Auto failover=ON | {rgid}")
            else:
                self._add("FAIL", "ELC-04", "ELASTICACHE", rgid,
                          f"Auto failover=OFF | {rgid}")
            # ELC-06 — Redis/Valkey RBAC (user groups). Replication groups are Redis/Valkey
            # only (Memcached has none), so absent/empty UserGroupIds means no per-user
            # access control — the cache falls back to an AUTH token or network-only.
            engine = (rg.get("Engine") or "redis").lower()
            if engine in ("redis", "valkey"):
                if rg.get("UserGroupIds"):
                    self._add("PASS", "ELC-06", "ELASTICACHE", rgid,
                              f"RBAC user group attached | {rgid}")
                else:
                    self._add("FAIL", "ELC-06", "ELASTICACHE", rgid,
                              f"No RBAC user group — no per-user access control "
                              f"(relies on AUTH token / network isolation) | {rgid}")
            # ELC-07 — automatic backups. A retention of 0 means ElastiCache takes no
            # snapshots at all, so a flushed or corrupted cache is gone: for the many
            # deployments that treat Redis as a datastore rather than a cache, that is
            # data loss and not just a cold start. Replication groups are Redis/Valkey
            # only, which is what keeps this off Memcached — where the field exists but
            # means nothing, because Memcached cannot be snapshotted.
            retention = rg.get("SnapshotRetentionLimit")
            if isinstance(retention, int) and retention <= 0:
                self._add("FAIL", "ELC-07", "ELASTICACHE", rgid,
                          f"Automatic backups DISABLED (SnapshotRetentionLimit=0) "
                          f"| {rgid} — nothing to restore from")
            elif isinstance(retention, int):
                self._add("PASS", "ELC-07", "ELASTICACHE", rgid,
                          f"Snapshot retention={retention}d | {rgid}")
            # ELC-08 — Multi-AZ. NOTE the shape: MultiAZ is a STRING enum
            # ('enabled'/'disabled'), not a boolean, so a truthiness test would read
            # 'disabled' as True and pass every unprotected group.
            multi_az = str(rg.get("MultiAZ") or "").lower()
            if multi_az == "enabled":
                self._add("PASS", "ELC-08", "ELASTICACHE", rgid,
                          f"Multi-AZ=ON | {rgid}")
            elif multi_az == "disabled":
                self._add("FAIL", "ELC-08", "ELASTICACHE", rgid,
                          f"Multi-AZ=OFF | {rgid} — an AZ failure takes the cache with "
                          f"it, and ELC-04's failover has nowhere to fail over to")

        # ELC-05 — Engine end-of-life. describe_replication_groups carries NO EngineVersion
        # (verified), so this uses describe_cache_clusters. Dedup by replication group so an
        # N-node Redis cluster yields ONE finding/edge; standalone Memcached (never in a
        # replication group) is covered here. Inline-paginate in OWN try/except.
        self._log("ELC-05: ElastiCache engine end-of-life")
        try:
            cache_clusters = []
            for page in ec.get_paginator("describe_cache_clusters").paginate():
                cache_clusters.extend(page.get("CacheClusters", []))
        except Exception as e:
            self._add("WARN", "ELC-05", "ELASTICACHE", "elasticache",
                      f"describe_cache_clusters failed (engine EOL not evaluated): {e}")
            cache_clusters = None
        if cache_clusters is not None:
            if not cache_clusters:
                self._add("INFO", "ELC-05", "ELASTICACHE", "elasticache",
                          "No ElastiCache clusters found in this region")
            seen: set = set()
            for cc in cache_clusters:
                rgid = cc.get("ReplicationGroupId")
                ccid = cc.get("CacheClusterId", "unknown")
                key  = rgid or ccid
                if key in seen:
                    continue
                seen.add(key)
                engine = cc.get("Engine", "")
                ev     = cc.get("EngineVersion", "")
                node_id = cc.get("ARN", key)
                verdict, matches = self._eol_check("elasticache", engine, ev)
                if verdict == "EOL":
                    self._add("FAIL", "ELC-05", "ELASTICACHE", key,
                              f"Engine END-OF-LIFE: {engine} {ev} "
                              f"(upgrade to >= {matches[0].fixed_version}) | {key}")
                    self._stash_eol_edge(node_id, "ElastiCacheCluster", matches,
                                         engine=engine, engine_version=ev, region=self.region,
                                         replication_group_id=(rgid or ""))
                elif verdict == "OK":
                    self._add("PASS", "ELC-05", "ELASTICACHE", key,
                              f"Engine supported: {engine} {ev} | {key}")
                else:
                    self._add("INFO", "ELC-05", "ELASTICACHE", key,
                              f"Engine EOL not evaluable: {engine} {ev} | {key}")

    # ══════════════════════════════════════════════════════════════════════════
    # SECTION 23: AMAZON OPENSEARCH
    # ══════════════════════════════════════════════════════════════════════════
    def _check_opensearch(self):
        self._section_header("OPENSEARCH")
        osr = self._client("opensearch")

        try:
            domains = osr.list_domain_names().get("DomainNames", [])
        except Exception as e:
            self._add("WARN", "OSR-01", "OPENSEARCH", "opensearch", str(e))
            return
        if not domains:
            self._add("INFO", "OSR-01", "OPENSEARCH", "opensearch",
                      "No OpenSearch domains found")
            return

        for d in domains:
            dname = d["DomainName"]
            try:
                cfg = osr.describe_domain(DomainName=dname)["DomainStatus"]
            except Exception as e:
                self._add("WARN", "OSR-01", "OPENSEARCH", dname, str(e))
                continue

            # OSR-01 — HTTPS enforcement
            ep_opts = cfg.get("DomainEndpointOptions", {})
            if ep_opts.get("EnforceHTTPS", False):
                tls = ep_opts.get("TLSSecurityPolicy", "")
                self._add("PASS", "OSR-01", "OPENSEARCH", dname,
                          f"HTTPS enforced (TLS={tls}) | {dname}")
            else:
                self._add("FAIL", "OSR-01", "OPENSEARCH", dname,
                          f"HTTPS NOT enforced | {dname}")
            # OSR-02 — Encryption at rest
            enc = cfg.get("EncryptionAtRestOptions", {})
            if enc.get("Enabled", False):
                self._add("PASS", "OSR-02", "OPENSEARCH", dname,
                          f"Encryption at rest=ON | {dname}")
            else:
                self._add("FAIL", "OSR-02", "OPENSEARCH", dname,
                          f"Encryption at rest=OFF | {dname}")
            # OSR-03 — Node-to-node encryption
            n2n = cfg.get("NodeToNodeEncryptionOptions", {})
            if n2n.get("Enabled", False):
                self._add("PASS", "OSR-03", "OPENSEARCH", dname,
                          f"Node-to-node encryption=ON | {dname}")
            else:
                self._add("FAIL", "OSR-03", "OPENSEARCH", dname,
                          f"Node-to-node encryption=OFF | {dname}")
            # OSR-04 — VPC deployment
            vpc_opts = cfg.get("VPCOptions", {})
            if vpc_opts.get("SubnetIds"):
                self._add("PASS", "OSR-04", "OPENSEARCH", dname,
                          f"Deployed in VPC | {dname}")
            else:
                self._add("FAIL", "OSR-04", "OPENSEARCH", dname,
                          f"Public endpoint (not in VPC) | {dname}")
            # OSR-05 — Fine-grained access control
            adv = cfg.get("AdvancedSecurityOptions", {})
            if adv.get("Enabled", False):
                self._add("PASS", "OSR-05", "OPENSEARCH", dname,
                          f"Fine-grained access control=ON | {dname}")
            else:
                self._add("FAIL", "OSR-05", "OPENSEARCH", dname,
                          f"Fine-grained access control=OFF | {dname}")
            # OSR-06 — TLS policy depth (reuses ep_opts; 0 new API calls). Only meaningful
            # when HTTPS is enforced — OSR-01 already owns the not-enforced FAIL, so gate on
            # it here to avoid double-reporting. Policy-Min-TLS-1-0-2019-07 permits TLS 1.0/1.1.
            if ep_opts.get("EnforceHTTPS", False):
                pol = ep_opts.get("TLSSecurityPolicy", "")
                if pol == "Policy-Min-TLS-1-0-2019-07":
                    self._add("FAIL", "OSR-06", "OPENSEARCH", dname,
                              f"Weak TLS policy {pol} (permits TLS 1.0/1.1) | {dname}")
                elif pol:
                    self._add("PASS", "OSR-06", "OPENSEARCH", dname,
                              f"TLS policy {pol} (min TLS 1.2) | {dname}")
                else:
                    self._add("INFO", "OSR-06", "OPENSEARCH", dname,
                              f"TLS policy not reported | {dname}")
            else:
                self._add("INFO", "OSR-06", "OPENSEARCH", dname,
                          f"TLS policy N/A (HTTPS not enforced; see OSR-01) | {dname}")
            # OSR-07 — Engine end-of-life. EngineVersion is 'OpenSearch_2.11' /
            # 'Elasticsearch_7.10'; split on '_' (all Elasticsearch engines are legacy/EOL).
            ever = cfg.get("EngineVersion", "")
            eng, _sep, ver = ever.partition("_")
            eng = eng.lower()
            pending = ""
            if cfg.get("ServiceSoftwareOptions", {}).get("UpdateAvailable"):
                pending = " (service software update available)"
            verdict, matches = self._eol_check("opensearch", eng, ver)
            arn = cfg.get("ARN", dname)
            if verdict == "EOL":
                self._add("FAIL", "OSR-07", "OPENSEARCH", dname,
                          f"Engine END-OF-LIFE: {ever or '(unknown)'}{pending} | {dname}")
                self._stash_eol_edge(arn, "OpenSearchDomain", matches,
                                     engine=eng, engine_version=ver, region=self.region)
            elif verdict == "OK":
                self._add("PASS", "OSR-07", "OPENSEARCH", dname,
                          f"Engine supported: {ever}{pending} | {dname}")
            else:
                self._add("INFO", "OSR-07", "OPENSEARCH", dname,
                          f"Engine EOL not evaluable: {ever or '(unknown)'} | {dname}")

    # ══════════════════════════════════════════════════════════════════════════
    # SECTION 24: AMAZON DYNAMODB
    # ══════════════════════════════════════════════════════════════════════════
    # ══════════════════════════════════════════════════════════════════════════
    # CIS AWS Database Services Benchmark v2.0.0 — tranche 2 (the recorded gaps)
    # ══════════════════════════════════════════════════════════════════════════
    def _fgac_principals(self, check_id: str, rule, section: str) -> None:
        """DDB-06 / TS-03 — unscoped item-level data grants, per principal.

        Both recommendations ask the same question of two services, and both are decided
        from the IAM principal set this scan has already built and cached. `rule` is the
        pure function from aws_cis_db2 that knows which actions and condition keys the
        service uses."""
        try:
            principals = self._get_iam_principals()
        except Exception as e:
            if self._is_access_denied(e):
                self._coverage.note_denied(check_id, "iam:GetPolicyVersion")
            self._add("INFO", check_id, section, "iam",
                      f"NOT EVALUATED — the IAM principal set could not be read ({e})")
            return
        if not principals:
            self._add("INFO", check_id, section, "iam",
                      "NOT EVALUATED — no IAM principals were resolved, so policy "
                      "conditions could not be inspected")
            return
        hits = 0
        for p in principals:
            r = rule(p)
            if r.get("failed"):
                hits += 1
                self._add("FAIL", check_id, section,
                          str(p.get("name") or p.get("arn") or "?"), r["statement"])
        if not hits:
            self._add("PASS", check_id, section, "iam",
                      f"No principal of {len(principals)} holds unscoped item-level "
                      f"access across every table")

    def _check_dynamodb_access_and_endpoints(self, has_tables: bool) -> None:
        """DDB-06 (CIS-DB 4.2) and DDB-07 (4.5)."""
        self._log("DDB-06: DynamoDB fine-grained access control")
        self._fgac_principals("DDB-06", aws_cis_db2.dynamodb_fine_grained_access,
                              "DYNAMODB")

        self._log("DDB-07: DynamoDB VPC endpoints")
        ec2 = self._client("ec2")
        try:
            eps = self._paginate_strict(ec2, "describe_vpc_endpoints", "VpcEndpoints")
            rtbs = self._paginate_strict(ec2, "describe_route_tables", "RouteTables")
            vpcs = self._paginate_strict(ec2, "describe_vpcs", "Vpcs")
        except Exception as e:
            if self._is_access_denied(e):
                self._coverage.note_denied("DDB-07", "ec2:DescribeVpcEndpoints")
            self._add("INFO", "DDB-07", "DYNAMODB", "vpc-endpoints",
                      f"NOT EVALUATED — the VPC endpoint inventory could not be read ({e})")
            return

        by_vpc: Dict[str, List[str]] = {}
        for ep in eps:
            v = str(ep.get("VpcId") or "")
            if v and str(ep.get("State", "available")) in ("available", "pendingAcceptance"):
                by_vpc.setdefault(v, []).append(str(ep.get("ServiceName") or ""))
        outbound: Set[str] = set()
        for rtb in rtbs:
            v = str(rtb.get("VpcId") or "")
            for r in (rtb.get("Routes") or []):
                if (str(r.get("GatewayId") or "").startswith("igw-")
                        or r.get("NatGatewayId")
                        or r.get("EgressOnlyInternetGatewayId")):
                    outbound.add(v)
        bad = 0
        for vpc in vpcs:
            vid = str(vpc.get("VpcId") or "?")
            r = aws_cis_db2.dynamodb_vpc_endpoint(
                vid, has_tables, vid in outbound, by_vpc.get(vid, []))
            if r.get("failed"):
                bad += 1
                self._add("FAIL", "DDB-07", "DYNAMODB", vid, r["statement"])
        if vpcs and not bad:
            self._add("PASS", "DDB-07", "DYNAMODB", "vpc-endpoints",
                      "Every internet-connected VPC reaches DynamoDB through a gateway "
                      "endpoint (or the account holds no tables)")

    def _cluster_event_subs(self, client, check_id: str, section: str, service: str,
                            cluster_ids: List[str]) -> None:
        """DOCDB-10 (CIS-DB 7.8) and NEP-11 (9.7) — one shape, two services."""
        if not cluster_ids:
            return
        try:
            subs = self._paginate_strict(client, "describe_event_subscriptions",
                                         "EventSubscriptionsList")
        except Exception as e:
            subs = None
            if self._is_access_denied(e):
                # rds:, not docdb:/neptune:. Both services are authorised under the RDS
                # IAM namespace they share a control plane with, so naming the client's
                # own prefix here would tell an operator to grant an action that does
                # not exist.
                self._coverage.note_denied(
                    check_id, "rds:DescribeEventSubscriptions")
        for cid in cluster_ids:
            r = aws_cis_db2.cluster_event_subscription(cid, service, subs)
            if r.get("failed"):
                self._add("FAIL", check_id, section, cid, r["statement"])
            elif r.get("unknown"):
                self._add("INFO", check_id, section, cid,
                          f"NOT EVALUATED — {r['reason']}")
            else:
                self._add("PASS", check_id, section, cid,
                          f"{service} cluster {cid} is covered by an event subscription")

    def _check_docdb_maintenance(self, docdb, cluster_ids: List[str]) -> None:
        """DOCDB-09 (CIS-DB 7.7) — engine updates AWS has queued and the cluster has not
        taken. The closest the control plane comes to answering 'is this engine patched'."""
        if not cluster_ids:
            return
        try:
            actions = self._paginate_strict(
                docdb, "describe_pending_maintenance_actions",
                "PendingMaintenanceActions")
        except Exception as e:
            actions = None
            if self._is_access_denied(e):
                self._coverage.note_denied(
                    "DOCDB-09", "rds:DescribePendingMaintenanceActions")
        for cid in cluster_ids:
            mine = None if actions is None else [
                a for a in actions
                if cid in str(a.get("ResourceIdentifier") or "")]
            r = aws_cis_db2.docdb_pending_maintenance(cid, mine)
            if r.get("failed"):
                self._add("FAIL", "DOCDB-09", "DOCDB", cid, r["statement"])
            elif r.get("unknown"):
                self._add("INFO", "DOCDB-09", "DOCDB", cid,
                          f"NOT EVALUATED — {r['reason']}")
            else:
                self._add("PASS", "DOCDB-09", "DOCDB", cid,
                          f"No pending maintenance actions on {cid}")

    def _check_timestream_cis_db2(self, table_arns: List[str]) -> None:
        """TS-03 (CIS-DB 10.5) and TS-04 (10.10)."""
        self._log("TS-03: Timestream fine-grained access control")
        self._fgac_principals("TS-03", aws_cis_db2.timestream_fine_grained_access,
                              "TIMESTREAM")

        if not table_arns:
            return
        self._log("TS-04: Timestream tables covered by AWS Backup")
        try:
            protected = [str(p.get("ResourceArn") or "") for p in self._paginate_strict(
                self._client("backup"), "list_protected_resources", "Results")]
        except Exception as e:
            protected = None
            if self._is_access_denied(e):
                self._coverage.note_denied("TS-04", "backup:ListProtectedResources")
        for arn in table_arns:
            r = aws_cis_db2.timestream_backup_coverage(arn, protected)
            if r.get("failed"):
                self._add("FAIL", "TS-04", "TIMESTREAM", arn, r["statement"])
            elif r.get("unknown"):
                self._add("INFO", "TS-04", "TIMESTREAM", arn,
                          f"NOT EVALUATED — {r['reason']}")
            else:
                self._add("PASS", "TS-04", "TIMESTREAM", arn,
                          f"An AWS Backup plan protects {arn}")

    def _check_dynamodb(self):
        self._section_header("DYNAMODB")
        ddb = self._client("dynamodb")

        try:
            tables = []
            paginator = ddb.get_paginator("list_tables")
            for page in paginator.paginate():
                tables.extend(page.get("TableNames", []))
        except Exception as e:
            self._read_failed("DDB-01", "DYNAMODB", "dynamodb", "dynamodb:ListTables", e)
            return
        # DDB-06/07 (CIS-DB 4.2, 4.5) run BEFORE the empty-table early return, and
        # deliberately: DDB-06 is about IAM grants, which exist whether or not a table
        # does — a role holding item-level access to every table in an account with no
        # tables today is still a grant that reaches every table created tomorrow.
        self._check_dynamodb_access_and_endpoints(bool(tables))

        if not tables:
            self._add("INFO", "DDB-01", "DYNAMODB", "dynamodb",
                      "No DynamoDB tables found")
            return

        for tname in tables:
            try:
                t = ddb.describe_table(TableName=tname)["Table"]
            except Exception as e:
                self._add("WARN", "DDB-01", "DYNAMODB", tname, str(e))
                continue

            # DDB-01 — Encryption (CMK vs AWS-owned)
            sse = t.get("SSEDescription", {})
            sse_type = sse.get("SSEType", "")
            if sse_type == "KMS":
                self._add("PASS", "DDB-01", "DYNAMODB", tname,
                          f"CMK encryption | {tname}")
            else:
                self._add("WARN", "DDB-01", "DYNAMODB", tname,
                          f"AWS-owned encryption (consider CMK) | {tname}")
            # DDB-02 — Point-in-time recovery
            try:
                pitr = ddb.describe_continuous_backups(TableName=tname
                    )["ContinuousBackupsDescription"]
                status = pitr.get("PointInTimeRecoveryDescription", {}).get(
                    "PointInTimeRecoveryStatus", "DISABLED")
                if status == "ENABLED":
                    self._add("PASS", "DDB-02", "DYNAMODB", tname,
                              f"PITR enabled | {tname}")
                else:
                    self._add("FAIL", "DDB-02", "DYNAMODB", tname,
                              f"PITR disabled | {tname}")
            except Exception:
                self._add("WARN", "DDB-02", "DYNAMODB", tname,
                          f"Could not check PITR for {tname}")
            # DDB-03 — Auto scaling / on-demand
            billing = t.get("BillingModeSummary", {}).get(
                "BillingMode", "PROVISIONED")
            if billing == "PAY_PER_REQUEST":
                self._add("PASS", "DDB-03", "DYNAMODB", tname,
                          f"On-demand billing (auto scales) | {tname}")
            else:
                self._add("INFO", "DDB-03", "DYNAMODB", tname,
                          f"Provisioned billing — ensure auto scaling | {tname}")
            # DDB-04 — Deletion protection
            if t.get("DeletionProtectionEnabled", False):
                self._add("PASS", "DDB-04", "DYNAMODB", tname,
                          f"Deletion protection=ON | {tname}")
            else:
                self._add("FAIL", "DDB-04", "DYNAMODB", tname,
                          f"Deletion protection=OFF | {tname}")

            # DDB-05 — resource-based policy exposure (public / cross-account). Recent (2024)
            # feature — most tables have none, so PolicyNotFound is silent (private, common).
            try:
                pol_str = ddb.get_resource_policy(ResourceArn=t["TableArn"]).get("Policy")
            except Exception as e:
                if "denied" in str(e).lower():
                    self._add("WARN", "DDB-05", "DYNAMODB", tname,
                              f"could not evaluate table resource policy (access denied) | {tname}")
                pol_str = None
            if pol_str:
                try:
                    stmts = json.loads(pol_str).get("Statement", [])
                    if isinstance(stmts, dict):
                        stmts = [stmts]
                except Exception:
                    stmts = []
                for st in stmts:
                    res = classify_resource_policy_stmt(st, self.account or "")
                    if not res:
                        continue
                    kind = res["kind"]
                    if kind == "public":
                        self._add("FAIL", "DDB-05", "DYNAMODB", tname,
                                  f"Table resource policy grants PUBLIC access (any AWS "
                                  f"principal can read/write table data) | {tname}")
                    elif kind == "public_conditioned":
                        self._add("WARN", "DDB-05", "DYNAMODB", tname,
                                  f"Wildcard principal condition-guarded — verify | {tname}")
                    elif kind == "cross_account":
                        ext = [a for a in res.get("external_accounts", [])
                               if a not in self.trusted_accounts]
                        if ext:
                            self._add("FAIL", "DDB-05", "DYNAMODB", tname,
                                      f"Table resource policy grants CROSS-ACCOUNT access to "
                                      f"{', '.join(ext)} | {tname}")
                    elif kind == "org":
                        self._add("WARN", "DDB-05", "DYNAMODB", tname,
                                  f"Shared to AWS Organization {res.get('org_id')} — verify | {tname}")

    # ══════════════════════════════════════════════════════════════════════════
    # SECTION 25: AWS STEP FUNCTIONS
    # ══════════════════════════════════════════════════════════════════════════
    def _check_stepfunctions(self):
        self._section_header("STEPFUNCTIONS")
        sfn = self._client("stepfunctions")

        try:
            machines = sfn.list_state_machines().get("stateMachines", [])
        except Exception as e:
            self._add("WARN", "SFN-01", "STEPFUNCTIONS", "stepfunctions", str(e))
            return
        if not machines:
            self._add("INFO", "SFN-01", "STEPFUNCTIONS", "stepfunctions",
                      "No Step Functions state machines found")
            return

        for sm in machines:
            sname = sm.get("name", "unknown")
            arn = sm.get("stateMachineArn", "")
            try:
                detail = sfn.describe_state_machine(stateMachineArn=arn)
            except Exception as e:
                self._add("WARN", "SFN-01", "STEPFUNCTIONS", sname, str(e))
                continue

            # SFN-01 — Logging
            log_cfg = detail.get("loggingConfiguration", {})
            level = log_cfg.get("level", "OFF")
            if level == "OFF":
                self._add("FAIL", "SFN-01", "STEPFUNCTIONS", sname,
                          f"Logging disabled on '{sname}'")
            else:
                self._add("PASS", "SFN-01", "STEPFUNCTIONS", sname,
                          f"Logging level={level} | {sname}")
            # SFN-02 — X-Ray tracing
            tracing = detail.get("tracingConfiguration", {})
            if tracing.get("enabled", False):
                self._add("PASS", "SFN-02", "STEPFUNCTIONS", sname,
                          f"X-Ray tracing=ON | {sname}")
            else:
                self._add("WARN", "SFN-02", "STEPFUNCTIONS", sname,
                          f"X-Ray tracing=OFF | {sname}")
            # SFN-03 — Encryption
            enc_cfg = detail.get("encryptionConfiguration", {})
            kms = enc_cfg.get("kmsKeyId", "")
            if kms:
                self._add("PASS", "SFN-03", "STEPFUNCTIONS", sname,
                          f"KMS encryption | {sname}")
            else:
                self._add("WARN", "SFN-03", "STEPFUNCTIONS", sname,
                          f"AWS-managed encryption | {sname}")

    # ══════════════════════════════════════════════════════════════════════════
    # SECTION 26: AMAZON API GATEWAY
    # ══════════════════════════════════════════════════════════════════════════
    def _check_apigateway(self):
        self._section_header("APIGATEWAY")
        apigw = self._client("apigateway")

        try:
            apis = apigw.get_rest_apis().get("items", [])
        except Exception as e:
            self._add("WARN", "APIGW-01", "APIGATEWAY", "apigateway", str(e))
            return
        if not apis:
            self._add("INFO", "APIGW-01", "APIGATEWAY", "apigateway",
                      "No API Gateway REST APIs found")
            return

        for api in apis:
            api_id = api.get("id", "unknown")
            api_nm = api.get("name", api_id)
            try:
                stages = apigw.get_stages(restApiId=api_id).get("item", [])
            except Exception as e:
                self._add("WARN", "APIGW-01", "APIGATEWAY", api_nm, str(e))
                continue
            if not stages:
                self._add("INFO", "APIGW-01", "APIGATEWAY", api_nm,
                          f"No deployed stages | {api_nm}")
                continue

            for st in stages:
                stage = st.get("stageName", "unknown")
                label = f"{api_nm}/{stage}"
                method_settings = st.get("methodSettings", {}).get("*/*", {})

                # APIGW-01 — Stage logging (access logs or execution logging)
                access_log = st.get("accessLogSettings", {}).get("destinationArn")
                log_level  = method_settings.get("loggingLevel", "OFF")
                if access_log or log_level not in ("OFF", ""):
                    self._add("PASS", "APIGW-01", "APIGATEWAY", label,
                              f"Logging enabled (level={log_level or 'access'}) | {label}")
                else:
                    self._add("FAIL", "APIGW-01", "APIGATEWAY", label,
                              f"No access/execution logging | {label}")

                # APIGW-02 — WAF Web ACL associated with stage
                if st.get("webAclArn"):
                    self._add("PASS", "APIGW-02", "APIGATEWAY", label,
                              f"WAF Web ACL associated | {label}")
                else:
                    self._add("FAIL", "APIGW-02", "APIGATEWAY", label,
                              f"No WAF Web ACL associated | {label}")

                # APIGW-03 — Cache data encryption (when caching enabled)
                if st.get("cacheClusterEnabled", False):
                    if method_settings.get("cacheDataEncrypted", False):
                        self._add("PASS", "APIGW-03", "APIGATEWAY", label,
                                  f"Cache encryption=ON | {label}")
                    else:
                        self._add("FAIL", "APIGW-03", "APIGATEWAY", label,
                                  f"Cache enabled but data NOT encrypted | {label}")
                else:
                    self._add("INFO", "APIGW-03", "APIGATEWAY", label,
                              f"Stage caching disabled | {label}")

                # APIGW-04 — X-Ray tracing
                if st.get("tracingEnabled", False):
                    self._add("PASS", "APIGW-04", "APIGATEWAY", label,
                              f"X-Ray tracing=ON | {label}")
                else:
                    self._add("WARN", "APIGW-04", "APIGATEWAY", label,
                              f"X-Ray tracing=OFF | {label}")

    # ══════════════════════════════════════════════════════════════════════════
    # SECTION 27: ELASTIC LOAD BALANCING
    # ══════════════════════════════════════════════════════════════════════════
    # TLS policies considered weak (allow TLS 1.0/1.1 or legacy ciphers)
    _WEAK_TLS_POLICIES = {
        "ELBSecurityPolicy-2015-05", "ELBSecurityPolicy-2016-08",
        "ELBSecurityPolicy-TLS-1-0-2015-04", "ELBSecurityPolicy-TLS-1-1-2017-01",
        "ELBSecurityPolicy-FS-2018-06", "ELBSecurityPolicy-FS-1-1-2019-08",
    }

    def _check_elb(self):
        self._section_header("ELB")
        elb = self._client("elbv2")

        try:
            lbs = []
            for page in elb.get_paginator("describe_load_balancers").paginate():
                lbs.extend(page.get("LoadBalancers", []))
        except Exception as e:
            self._add("WARN", "ELB-01", "ELB", "elb", str(e))
            return
        if not lbs:
            self._add("INFO", "ELB-01", "ELB", "elb",
                      "No Application/Network Load Balancers found")
            return

        for lb in lbs:
            arn   = lb.get("LoadBalancerArn", "")
            name  = lb.get("LoadBalancerName", "unknown")
            lbtype = lb.get("Type", "application")

            # Attributes (access logs, deletion protection, drop invalid headers)
            attrs = {}
            try:
                for a in elb.describe_load_balancer_attributes(
                        LoadBalancerArn=arn).get("Attributes", []):
                    attrs[a.get("Key")] = a.get("Value")
            except Exception as e:
                self._add("WARN", "ELB-01", "ELB", name, str(e))

            # ELB-01 — Access logging
            if attrs.get("access_logs.s3.enabled") == "true":
                self._add("PASS", "ELB-01", "ELB", name,
                          f"Access logging=ON | {name}")
            else:
                self._add("FAIL", "ELB-01", "ELB", name,
                          f"Access logging=OFF | {name}")

            # ELB-04 — Deletion protection
            if attrs.get("deletion_protection.enabled") == "true":
                self._add("PASS", "ELB-04", "ELB", name,
                          f"Deletion protection=ON | {name}")
            else:
                self._add("WARN", "ELB-04", "ELB", name,
                          f"Deletion protection=OFF | {name}")

            # ELB-05 — Drop invalid HTTP headers (ALB only)
            if lbtype == "application":
                if attrs.get("routing.http.drop_invalid_header_fields.enabled") == "true":
                    self._add("PASS", "ELB-05", "ELB", name,
                              f"Drop invalid headers=ON | {name}")
                else:
                    self._add("FAIL", "ELB-05", "ELB", name,
                              f"Drop invalid headers=OFF | {name}")

                # ELB-07 — HTTP desync mitigation mode (request-smuggling defense)
                mode = attrs.get("routing.http.desync_mitigation_mode", "defensive")
                if mode in ("defensive", "strictest"):
                    self._add("PASS", "ELB-07", "ELB", name,
                              f"Desync mitigation mode='{mode}' | {name}")
                else:
                    self._add("FAIL", "ELB-07", "ELB", name,
                              f"Desync mitigation mode='{mode}' — HTTP request-smuggling "
                              f"exposure; set 'defensive' or 'strictest' | {name}")

            # ELB-08 — Load balancer with no healthy backend targets (cost/hygiene; ALB + NLB).
            # Fail-open: a throttled/denied read must NOT change the scan outcome.
            try:
                tgs = elb.describe_target_groups(LoadBalancerArn=arn).get("TargetGroups", [])
                if tgs:
                    any_healthy = False
                    for tg in tgs:
                        thds = elb.describe_target_health(
                            TargetGroupArn=tg.get("TargetGroupArn", "")).get(
                            "TargetHealthDescriptions", [])
                        if any((t.get("TargetHealth") or {}).get("State") == "healthy"
                               for t in thds):
                            any_healthy = True
                            break
                    if not any_healthy:
                        self._add("WARN", "ELB-08", "ELB", name,
                                  f"Load balancer has no healthy backend targets across "
                                  f"{len(tgs)} target group(s) — likely orphaned, incurring cost | {name}")
            except Exception:
                pass                                     # fail-open (cost/hygiene, not security)

            # Listener-level checks (TLS)
            try:
                listeners = elb.describe_listeners(
                    LoadBalancerArn=arn).get("Listeners", [])
            except Exception as e:
                self._add("WARN", "ELB-02", "ELB", name, str(e))
                continue

            for ls in listeners:
                proto = ls.get("Protocol", "")
                port  = ls.get("Port", "")
                llabel = f"{name}:{port}/{proto}"

                # ELB-02 — Plaintext listener without HTTPS redirect
                if proto == "HTTP":
                    actions = ls.get("DefaultActions", [])
                    redirects = any(a.get("Type") == "redirect" and
                                    a.get("RedirectConfig", {}).get("Protocol") == "HTTPS"
                                    for a in actions)
                    if redirects:
                        self._add("PASS", "ELB-02", "ELB", llabel,
                                  f"HTTP listener redirects to HTTPS | {llabel}")
                    else:
                        self._add("FAIL", "ELB-02", "ELB", llabel,
                                  f"HTTP listener does NOT redirect to HTTPS | {llabel}")

                # ELB-03 — Weak TLS policy on HTTPS/TLS listeners
                if proto in ("HTTPS", "TLS"):
                    policy = ls.get("SslPolicy", "")
                    self._crypto_material["tls"].append({
                        "ref": f"tls/elbv2/{name}/{port}", "name": llabel,
                        "service": "elbv2", "policy": policy})
                    if policy in self._WEAK_TLS_POLICIES:
                        self._add("FAIL", "ELB-03", "ELB", llabel,
                                  f"Weak TLS policy '{policy}' | {llabel}")
                    else:
                        self._add("PASS", "ELB-03", "ELB", llabel,
                                  f"TLS policy '{policy}' | {llabel}")

        # CLB-01/02 — Classic Load Balancers (elb v1, distinct client + listener shape)
        self._check_classic_elb()

    def _check_classic_elb(self):
        """CLB-01 internet-facing plaintext CLB + CLB-02 weak SSL policy. Uses the elb (v1)
        client — its Listener shape (LoadBalancerPort/InstancePort) differs from elbv2."""
        elb = self._client("elb")
        try:
            clbs = []
            for page in elb.get_paginator("describe_load_balancers").paginate():
                clbs.extend(page.get("LoadBalancerDescriptions", []))
        except Exception as e:
            self._add("WARN", "CLB-01", "ELB", "classic-elb",
                      f"describe_load_balancers (classic) failed: {e}")
            return
        if not clbs:
            self._add("INFO", "CLB-01", "ELB", "classic-elb",
                      "No Classic Load Balancers in this region")
            return
        for lb in clbs:
            name = lb.get("LoadBalancerName", "unknown")
            scheme = lb.get("Scheme", "")
            listeners = lb.get("ListenerDescriptions", [])
            protos = {(ld.get("Listener") or {}).get("Protocol", "").upper()
                      for ld in listeners}
            secure = protos & {"HTTPS", "SSL"}
            # CLB-01 — plaintext-only (FAIL only when internet-facing AND no HTTPS/SSL)
            if not listeners:
                self._add("INFO", "CLB-01", "ELB", name, f"Classic LB has no listeners | {name}")
            elif not secure and scheme == "internet-facing":
                self._add("FAIL", "CLB-01", "ELB", name,
                          f"Internet-facing Classic LB has NO HTTPS/SSL listener — plaintext "
                          f"in transit | {name}")
            elif not secure:
                self._add("INFO", "CLB-01", "ELB", name,
                          f"Internal Classic LB has no HTTPS/SSL listener (lower risk) | {name}")
            else:
                self._add("PASS", "CLB-01", "ELB", name,
                          f"Classic LB terminates HTTPS/SSL | {name}")
            # CLB-02 — weak SSL negotiation policy (only for HTTPS/SSL-terminating CLBs)
            if secure:
                try:
                    pols = elb.describe_load_balancer_policies(
                        LoadBalancerName=name).get("PolicyDescriptions", [])
                except Exception as e:
                    self._add("WARN", "CLB-02", "ELB", name,
                              f"could not read SSL policies: {e}")
                    continue
                weak = False
                for pd in pols:
                    if pd.get("PolicyTypeName") != "SSLNegotiationPolicyType":
                        continue
                    for attr in pd.get("PolicyAttributeDescriptions", []):
                        an = attr.get("AttributeName", "")
                        av = str(attr.get("AttributeValue", "")).lower()
                        if an in ("Protocol-TLSv1", "Protocol-TLSv1.1") and av == "true":
                            weak = True
                        if (an == "Reference-Security-Policy"
                                and attr.get("AttributeValue") in self._WEAK_TLS_POLICIES):
                            weak = True
                if weak:
                    self._add("FAIL", "CLB-02", "ELB", name,
                              f"Classic LB HTTPS/SSL listener uses a weak SSL policy "
                              f"(permits TLS 1.0/1.1) | {name}")
                else:
                    self._add("PASS", "CLB-02", "ELB", name,
                              f"Classic LB SSL policy OK | {name}")

    # ══════════════════════════════════════════════════════════════════════════
    # SECTION 28: EBS VOLUMES & SNAPSHOTS
    # ══════════════════════════════════════════════════════════════════════════
    def _check_ebs(self):
        self._section_header("EBS")
        ec2 = self._client("ec2")

        # EBS-01 — Account-level encryption by default
        try:
            ebd = ec2.get_ebs_encryption_by_default().get(
                "EbsEncryptionByDefault", False)
            if ebd:
                self._add("PASS", "EBS-01", "EBS", "account",
                          "EBS encryption by default=ON")
            else:
                self._add("FAIL", "EBS-01", "EBS", "account",
                          "EBS encryption by default=OFF")
        except Exception as e:
            self._add("WARN", "EBS-01", "EBS", "account", str(e))

        # EBS-02 — Unencrypted volumes  (+ EBS-05 orphaned/unattached, same page — zero new API)
        try:
            unenc = []
            orphaned = []
            paginator = ec2.get_paginator("describe_volumes")
            for page in paginator.paginate():
                for vol in page.get("Volumes", []):
                    if not vol.get("Encrypted", False):
                        unenc.append(vol.get("VolumeId", "unknown"))
                    # 'available' = not attached to any instance = paid-for but unused (waste)
                    if vol.get("State") == "available":
                        orphaned.append(vol.get("VolumeId", "unknown"))
            if unenc:
                for vid in unenc:
                    self._add("FAIL", "EBS-02", "EBS", vid,
                              f"Unencrypted EBS volume | {vid}")
            else:
                self._add("PASS", "EBS-02", "EBS", "all-volumes",
                          "All EBS volumes are encrypted")
            # EBS-05 — orphaned (unattached) volumes: cost/hygiene WARN, no posture-score impact
            for vid in orphaned:
                self._add("WARN", "EBS-05", "EBS", vid,
                          f"Orphaned EBS volume — 'available' (unattached), incurring cost | {vid}")
        except Exception as e:
            self._add("WARN", "EBS-02", "EBS", "volumes", str(e))

        # EBS-03 — Unencrypted owned snapshots
        try:
            unenc_snaps = []
            paginator = ec2.get_paginator("describe_snapshots")
            for page in paginator.paginate(OwnerIds=["self"]):
                for snap in page.get("Snapshots", []):
                    if not snap.get("Encrypted", False):
                        unenc_snaps.append(snap.get("SnapshotId", "unknown"))
            if unenc_snaps:
                for sid in unenc_snaps:
                    self._add("FAIL", "EBS-03", "EBS", sid,
                              f"Unencrypted EBS snapshot | {sid}")
            else:
                self._add("PASS", "EBS-03", "EBS", "all-snapshots",
                          "All owned EBS snapshots are encrypted")
        except Exception as e:
            self._add("WARN", "EBS-03", "EBS", "snapshots", str(e))

        # EBS-04 — Publicly restorable snapshots
        try:
            public = []
            paginator = ec2.get_paginator("describe_snapshots")
            for page in paginator.paginate(OwnerIds=["self"],
                                           RestorableByUserIds=["all"]):
                for snap in page.get("Snapshots", []):
                    public.append(snap.get("SnapshotId", "unknown"))
            if public:
                for sid in public:
                    self._add("FAIL", "EBS-04", "EBS", sid,
                              f"PUBLIC EBS snapshot (restorable by anyone) | {sid}")
            else:
                self._add("PASS", "EBS-04", "EBS", "all-snapshots",
                          "No public EBS snapshots")
        except Exception as e:
            self._add("WARN", "EBS-04", "EBS", "snapshots", str(e))

    # ══════════════════════════════════════════════════════════════════════════
    # SECTION 29: AMAZON REDSHIFT
    # ══════════════════════════════════════════════════════════════════════════
    def _check_redshift(self):
        self._section_header("REDSHIFT")
        rs = self._client("redshift")

        # Do NOT early-return on empty/error: RSS-01..04 (Redshift Serverless, below) must
        # still run — Serverless can exist with zero provisioned clusters.
        try:
            clusters = rs.describe_clusters().get("Clusters", [])
        except Exception as e:
            self._add("WARN", "RS-01", "REDSHIFT", "redshift", str(e))
            clusters = None
        if clusters is not None and not clusters:
            self._add("INFO", "RS-01", "REDSHIFT", "redshift",
                      "No Redshift clusters found")

        pg_ssl_cache: Dict[str, object] = {}   # parameter-group name -> require_ssl value / error
        for c in (clusters or []):
            cid = c.get("ClusterIdentifier", "unknown")

            # RS-01 — Encryption at rest
            if c.get("Encrypted", False):
                self._add("PASS", "RS-01", "REDSHIFT", cid,
                          f"Encryption at rest=ON | {cid}")
            else:
                self._add("FAIL", "RS-01", "REDSHIFT", cid,
                          f"Encryption at rest=OFF | {cid}")

            # RS-02 — Public accessibility
            if c.get("PubliclyAccessible", False):
                self._add("FAIL", "RS-02", "REDSHIFT", cid,
                          f"Cluster is publicly accessible | {cid}")
            else:
                self._add("PASS", "RS-02", "REDSHIFT", cid,
                          f"Not publicly accessible | {cid}")

            # RS-03 — Audit logging
            try:
                logging = rs.describe_logging_status(ClusterIdentifier=cid)
                if logging.get("LoggingEnabled", False):
                    self._add("PASS", "RS-03", "REDSHIFT", cid,
                              f"Audit logging=ON | {cid}")
                else:
                    self._add("FAIL", "RS-03", "REDSHIFT", cid,
                              f"Audit logging=OFF | {cid}")
            except Exception as e:
                self._add("WARN", "RS-03", "REDSHIFT", cid, str(e))

            # RS-04 — Enhanced VPC routing
            if c.get("EnhancedVpcRouting", False):
                self._add("PASS", "RS-04", "REDSHIFT", cid,
                          f"Enhanced VPC routing=ON | {cid}")
            else:
                self._add("FAIL", "RS-04", "REDSHIFT", cid,
                          f"Enhanced VPC routing=OFF | {cid}")

            # RS-05 — Default admin username
            if c.get("MasterUsername", "").lower() == "awsuser":
                self._add("WARN", "RS-05", "REDSHIFT", cid,
                          f"Default master username 'awsuser' in use | {cid}")
            else:
                self._add("PASS", "RS-05", "REDSHIFT", cid,
                          f"Non-default master username | {cid}")

            # RS-06 — require_ssl parameter (stock default.redshift-1.0 ships 'false', so
            # in-transit encryption is optional unless explicitly required). Cached per
            # parameter group; OWN try/except -> WARN, never a PASS on a failed read.
            pgs = c.get("ClusterParameterGroups", [])
            pgname = pgs[0].get("ParameterGroupName") if pgs else None
            if pgname:
                if pgname not in pg_ssl_cache:
                    try:
                        params = rs.describe_cluster_parameters(
                            ParameterGroupName=pgname).get("Parameters", [])
                        val = None
                        for p in params:
                            if p.get("ParameterName") == "require_ssl":
                                val = (p.get("ParameterValue") or "").lower()
                                break
                        pg_ssl_cache[pgname] = val
                    except Exception as e:
                        pg_ssl_cache[pgname] = RuntimeError(str(e))
                cached = pg_ssl_cache[pgname]
                if isinstance(cached, Exception):
                    self._add("WARN", "RS-06", "REDSHIFT", cid,
                              f"require_ssl not read ({pgname}): {cached}")
                elif cached == "true":
                    self._add("PASS", "RS-06", "REDSHIFT", cid,
                              f"require_ssl=true (TLS required) | {cid}")
                else:
                    self._add("FAIL", "RS-06", "REDSHIFT", cid,
                              f"require_ssl not enforced (in-transit encryption optional) | {cid}")
            else:
                self._add("WARN", "RS-06", "REDSHIFT", cid,
                          f"No cluster parameter group resolved (require_ssl unknown) | {cid}")

            # RS-07 — AllowVersionUpgrade (managed maintenance-track patching). Default is
            # True; OFF means the cluster is pinned and receives no managed upgrades.
            if c.get("AllowVersionUpgrade", True):
                self._add("PASS", "RS-07", "REDSHIFT", cid,
                          f"AllowVersionUpgrade=ON | {cid}")
            else:
                mt = c.get("MaintenanceTrackName", "")
                extra = f" (maintenance track '{mt}')" if mt else ""
                self._add("WARN", "RS-07", "REDSHIFT", cid,
                          f"AllowVersionUpgrade=OFF — pinned, no managed upgrades{extra} | {cid}")

        # ── RSS-01..04 — Redshift Serverless (separate client + camelCase API). Runs
        # regardless of provisioned clusters. Region-guarded: Serverless is unavailable in
        # some regions -> WARN, not a crash.
        self._log("RSS-01..04: Redshift Serverless workgroups and namespaces")
        try:
            rss = self._client("redshift-serverless")
        except Exception as e:
            self._add("WARN", "RSS-01", "REDSHIFT", "redshift-serverless", str(e))
            rss = None
        if rss is not None:
            # Workgroups: public accessibility (RSS-01), require_ssl (RSS-03), enhanced VPC (RSS-04)
            try:
                workgroups = []
                token = None
                for _ in range(200):                 # bounded: never trust nextToken to terminate
                    resp = rss.list_workgroups(**({"nextToken": token} if token else {}))
                    workgroups.extend(resp.get("workgroups", []) or [])
                    token = resp.get("nextToken")
                    if not token or not isinstance(token, str):
                        break
            except Exception as e:
                self._add("WARN", "RSS-01", "REDSHIFT", "redshift-serverless",
                          f"list_workgroups failed: {e}")
                workgroups = None
            if workgroups is not None:
                if not workgroups:
                    self._add("INFO", "RSS-01", "REDSHIFT", "redshift-serverless",
                              "No Redshift Serverless workgroups in this region")
                for wg in workgroups:
                    wgn = wg.get("workgroupName", "unknown")
                    if wg.get("publiclyAccessible", False):
                        self._add("FAIL", "RSS-01", "REDSHIFT", wgn,
                                  f"Serverless workgroup PUBLICLY ACCESSIBLE | {wgn}")
                    else:
                        self._add("PASS", "RSS-01", "REDSHIFT", wgn,
                                  f"Not publicly accessible | {wgn}")
                    ssl_val = None
                    for p in wg.get("configParameters", []):
                        if p.get("parameterKey") == "require_ssl":
                            ssl_val = (p.get("parameterValue") or "").lower()
                            break
                    if ssl_val == "true":
                        self._add("PASS", "RSS-03", "REDSHIFT", wgn, f"require_ssl=true | {wgn}")
                    elif ssl_val is None:
                        self._add("INFO", "RSS-03", "REDSHIFT", wgn,
                                  f"require_ssl not in workgroup projection | {wgn}")
                    else:
                        self._add("FAIL", "RSS-03", "REDSHIFT", wgn,
                                  f"require_ssl not enforced | {wgn}")
                    if wg.get("enhancedVpcRouting", False):
                        self._add("PASS", "RSS-04", "REDSHIFT", wgn,
                                  f"Enhanced VPC routing=ON | {wgn}")
                    else:
                        self._add("FAIL", "RSS-04", "REDSHIFT", wgn,
                                  f"Enhanced VPC routing=OFF | {wgn}")
            # Namespaces: customer-managed CMK gap (RSS-02)
            try:
                namespaces = []
                token = None
                for _ in range(200):                 # bounded: never trust nextToken to terminate
                    resp = rss.list_namespaces(**({"nextToken": token} if token else {}))
                    namespaces.extend(resp.get("namespaces", []) or [])
                    token = resp.get("nextToken")
                    if not token or not isinstance(token, str):
                        break
            except Exception as e:
                self._add("WARN", "RSS-02", "REDSHIFT", "redshift-serverless",
                          f"list_namespaces failed: {e}")
                namespaces = None
            if namespaces is not None:
                for ns in namespaces:
                    nsn = ns.get("namespaceName", "unknown")
                    kms = ns.get("kmsKeyId")
                    # Serverless is always encrypted; the gap is AWS-owned key vs a CMK.
                    if kms in (None, "", "AWS_OWNED_KMS_KEY"):
                        self._add("WARN", "RSS-02", "REDSHIFT", nsn,
                                  f"Namespace encrypted with an AWS-owned key "
                                  f"(no customer-managed CMK) | {nsn}")
                    else:
                        self._add("PASS", "RSS-02", "REDSHIFT", nsn,
                                  f"Customer-managed CMK in use | {nsn}")

    # ══════════════════════════════════════════════════════════════════════════
    # SECTION 30: AMAZON EFS
    # ══════════════════════════════════════════════════════════════════════════
    def _check_efs(self):
        self._section_header("EFS")
        efs = self._client("efs")

        try:
            filesystems = efs.describe_file_systems().get("FileSystems", [])
        except Exception as e:
            self._add("WARN", "EFS-01", "EFS", "efs", str(e))
            return
        if not filesystems:
            self._add("INFO", "EFS-01", "EFS", "efs",
                      "No EFS file systems found")
            return

        for fs in filesystems:
            fsid = fs.get("FileSystemId", "unknown")
            name = fs.get("Name") or fsid

            # EFS-01 — Encryption at rest
            if fs.get("Encrypted", False):
                self._add("PASS", "EFS-01", "EFS", name,
                          f"Encryption at rest=ON | {name}")
            else:
                self._add("FAIL", "EFS-01", "EFS", name,
                          f"Encryption at rest=OFF | {name}")

            # EFS-02 — File system policy enforces in-transit encryption
            try:
                policy = efs.describe_file_system_policy(
                    FileSystemId=fsid).get("Policy", "")
                if "aws:SecureTransport" in policy:
                    self._add("PASS", "EFS-02", "EFS", name,
                              f"Policy enforces TLS in transit | {name}")
                else:
                    self._add("FAIL", "EFS-02", "EFS", name,
                              f"Policy does NOT enforce TLS (aws:SecureTransport) | {name}")
            except Exception:
                self._add("FAIL", "EFS-02", "EFS", name,
                          f"No file system policy enforcing TLS | {name}")

            # EFS-03 — Automatic backups
            try:
                bp = efs.describe_backup_policy(
                    FileSystemId=fsid).get("BackupPolicy", {})
                if bp.get("Status") in ("ENABLED", "ENABLING"):
                    self._add("PASS", "EFS-03", "EFS", name,
                              f"Automatic backups=ON | {name}")
                else:
                    self._add("WARN", "EFS-03", "EFS", name,
                              f"Automatic backups=OFF | {name}")
            except Exception:
                self._add("WARN", "EFS-03", "EFS", name,
                          f"Automatic backups=OFF | {name}")

    # ══════════════════════════════════════════════════════════════════════════
    # SECTION 31: AWS CERTIFICATE MANAGER
    # ══════════════════════════════════════════════════════════════════════════
    # Key algorithms considered weak (below 2048-bit RSA strength)
    _WEAK_KEY_ALGORITHMS = {"RSA_1024"}

    def _check_acm(self):
        self._section_header("ACM")
        acm = self._client("acm")

        # ListCertificates defaults to RSA_1024/RSA_2048 ONLY — must pass keyTypes to
        # see ECDSA (EC_*) and RSA_3072/4096 certs — and it is paginated.
        _ACM_KEY_TYPES = ["RSA_1024", "RSA_2048", "RSA_3072", "RSA_4096",
                          "EC_prime256v1", "EC_secp384r1", "EC_secp521r1"]
        try:
            certs = []
            for page in acm.get_paginator("list_certificates").paginate(
                Includes={"keyTypes": _ACM_KEY_TYPES}
            ):
                certs.extend(page.get("CertificateSummaryList", []))
        except Exception as e:
            self._add("WARN", "ACM-01", "ACM", "acm", str(e))
            return
        if not certs:
            self._add("INFO", "ACM-01", "ACM", "acm",
                      "No ACM certificates found")
            return

        now = datetime.now(timezone.utc)
        for summary in certs:
            arn = summary.get("CertificateArn", "")
            try:
                cert = acm.describe_certificate(
                    CertificateArn=arn).get("Certificate", {})
            except Exception as e:
                self._add("WARN", "ACM-01", "ACM", arn, str(e))
                continue
            self._crypto_material["acm"].append(cert)

            domain = cert.get("DomainName", arn)

            # ACM-01 — Expiry
            not_after = cert.get("NotAfter")
            if not_after:
                if getattr(not_after, "tzinfo", None) is None:
                    not_after = not_after.replace(tzinfo=timezone.utc)
                days_left = (not_after - now).days
                if days_left < 0:
                    self._add("FAIL", "ACM-01", "ACM", domain,
                              f"Certificate EXPIRED {abs(days_left)}d ago | {domain}")
                elif days_left <= 30:
                    self._add("WARN", "ACM-01", "ACM", domain,
                              f"Certificate expires in {days_left}d | {domain}")
                else:
                    self._add("PASS", "ACM-01", "ACM", domain,
                              f"Certificate valid for {days_left}d | {domain}")
            else:
                self._add("INFO", "ACM-01", "ACM", domain,
                          f"Certificate not yet issued | {domain}")

            # ACM-02 — Key algorithm strength
            key_algo = cert.get("KeyAlgorithm", "")
            if key_algo in self._WEAK_KEY_ALGORITHMS:
                self._add("FAIL", "ACM-02", "ACM", domain,
                          f"Weak key algorithm '{key_algo}' | {domain}")
            elif key_algo:
                self._add("PASS", "ACM-02", "ACM", domain,
                          f"Key algorithm '{key_algo}' | {domain}")

            # ACM-03 — Unused certificate
            if cert.get("InUseBy"):
                self._add("PASS", "ACM-03", "ACM", domain,
                          f"Certificate in use | {domain}")
            else:
                self._add("WARN", "ACM-03", "ACM", domain,
                          f"Certificate not associated with any resource | {domain}")

            # ACM-04 — Unhealthy certificate status (TLS broken for the domain)
            status = cert.get("Status", "")
            if status in ("FAILED", "VALIDATION_TIMED_OUT", "REVOKED"):
                self._add("FAIL", "ACM-04", "ACM", domain,
                          f"Certificate status is {status} — TLS is broken for this "
                          f"domain | {domain}")

            # ACM-05 — Renewal risk (imported / ineligible for managed auto-renewal)
            ctype = cert.get("Type", "")
            if cert.get("RenewalEligibility") == "INELIGIBLE" and status == "ISSUED":
                self._add("WARN", "ACM-05", "ACM", domain,
                          f"Certificate is INELIGIBLE for managed renewal — it will "
                          f"expire without action | {domain}")
            elif ctype == "IMPORTED":
                self._add("WARN", "ACM-05", "ACM", domain,
                          f"Imported certificate — ACM will not auto-renew; rotate "
                          f"manually before expiry | {domain}")

    # ══════════════════════════════════════════════════════════════════════════
    # SECTION 35: SHADOW AI (slice 4.4)
    # ══════════════════════════════════════════════════════════════════════════
    def _check_shadow_ai(self):
        """SHAI-01..03 — AI nobody told the security team about.

        Shadow AI is not a property of a resource. A knowledge base built by the ML
        platform team in the governed region is the system working; the identical
        resource built by an application role in a region nobody scans is the thing this
        section surfaces. An inventory cannot tell those apart, which is why this asks
        WHO and WHERE rather than WHAT.

        The third-party SaaS half -- someone pasting company data into a hosted
        assistant -- is not attempted and is declared instead. See D9."""
        self._section_header("SHADOW_AI")
        self._add("INFO", "SHAI-00", "SHADOW_AI", "shadow-ai",
                  f"{aws_shadowai.SAAS_NOT_DETECTABLE} | shadow-ai")
        self._check_undeclared_ai_creators()
        self._check_bedrock_private_path()

    def _check_undeclared_ai_creators(self):
        """SHAI-01/02 — who built AI, and where.

        Only MANAGEMENT events. bedrock:InvokeModel is a data event that LookupEvents
        never sees, which is what AILOG-04 reports as a gap -- and that limit is a
        feature here: creation is the moment shadow AI becomes visible, and usage is
        AITHR-01's question."""
        events, denied = [], []
        for reg in self._ai_scan_regions():
            try:
                ct = self._client("cloudtrail", region=reg)
                pages = ct.get_paginator("lookup_events").paginate(
                    LookupAttributes=[{"AttributeKey": "EventSource",
                                       "AttributeValue": "bedrock.amazonaws.com"}],
                    PaginationConfig={"MaxItems": 2000, "PageSize": 50})
                for page in pages:
                    for row in page.get("Events", []):
                        raw = row.get("CloudTrailEvent")
                        if not raw:
                            continue
                        try:
                            events.append(json.loads(raw))
                        except (TypeError, ValueError):
                            continue
            except Exception as e:
                denied.append(f"{reg}: {e}")

        if denied and not events:
            for cid in ("SHAI-01", "SHAI-02"):
                self._coverage.note_denied(cid, "cloudtrail:LookupEvents")
            self._add("INFO", "SHAI-00", "SHADOW_AI", "cloudtrail",
                      f"CloudTrail event history not readable ({denied[0]}) — who built "
                      f"AI in this account was NOT established, which is not the same "
                      f"as nobody having built any | cloudtrail")
            return

        found = aws_shadowai.creators(events)
        if not found:
            return

        declared = list(self._ai_owners or ())
        if not declared:
            # A check that fires on the correct configuration is one people turn off.
            # The absence of a declared set is the operator's unanswered question, not
            # the account's fault, and it is reported as exactly that.
            self._add("INFO", "SHAI-00", "SHADOW_AI", "shadow-ai",
                      f"{len(found)} identity/identities have created AI resources in "
                      f"this account. No owner set was declared (--ai-owners), so "
                      f"OverWatch cannot say which of them is expected: "
                      f"{', '.join(sorted(found))} | shadow-ai")
        else:
            undeclared = aws_shadowai.undeclared_creators(found, declared)
            for row in undeclared:
                self._add("FAIL", "SHAI-01", "SHADOW_AI", row["principal"],
                          f"{aws_shadowai.describe_creator(row)} | {row['principal']}")
            if not undeclared:
                self._add("PASS", "SHAI-01", "SHADOW_AI", "shadow-ai",
                          f"All {len(found)} AI creator(s) are in the declared owner "
                          f"set | shadow-ai")

        # SHAI-02 — AI built where nothing was assessed.
        seen = aws_shadowai.active_regions(found)
        scanned = set(self._coverage.scanned_regions or [self.region])
        unassessed = sorted(seen - scanned)
        if unassessed:
            self._add("FAIL", "SHAI-02", "SHADOW_AI", "shadow-ai",
                      f"AI resources were created in {', '.join(unassessed)}, which "
                      f"this scan did not enumerate — their guardrails, network posture "
                      f"and key custody are unknown rather than clean. Re-run with "
                      f"--all-regions | shadow-ai")

    def _check_bedrock_private_path(self):
        """SHAI-03 — whether Bedrock traffic has a governed path.

        The config-only substitute for the flow-log query the roadmap proposed. An
        interface endpoint keeps Bedrock traffic on the AWS network where an endpoint
        policy can bound which models are reachable; without one it leaves via NAT or an
        internet gateway and no such policy applies."""
        try:
            ec2 = self._client("ec2")
            eps = (ec2.describe_vpc_endpoints() or {}).get("VpcEndpoints") or []
        except Exception as e:
            if self._is_access_denied(e):
                self._coverage.note_denied("SHAI-03", "ec2:DescribeVpcEndpoints")
                self._add("INFO", "SHAI-00", "SHADOW_AI", "vpc",
                          "Bedrock private-path posture NOT audited — missing "
                          "ec2:DescribeVpcEndpoints (no phantom pass) | vpc")
            return
        try:
            vpcs = [v.get("VpcId") for v in
                    ((ec2.describe_vpcs() or {}).get("Vpcs") or []) if v.get("VpcId")]
        except Exception:
            vpcs = []

        posture = aws_shadowai.vpc_endpoint_posture(eps, vpcs)
        if not posture["checked"]:
            return
        if posture["without_endpoint"]:
            self._add("WARN", "SHAI-03", "SHADOW_AI", "vpc",
                      f"{len(posture['without_endpoint'])} VPC(s) have no Bedrock "
                      f"interface endpoint ({', '.join(posture['without_endpoint'])}) — "
                      f"any Bedrock traffic from them leaves via NAT or an internet "
                      f"gateway, where no VPC endpoint policy can bound which models "
                      f"are reachable. Not applicable if the VPC does not use Bedrock "
                      f"| vpc")
        else:
            self._add("PASS", "SHAI-03", "SHADOW_AI", "vpc",
                      f"Every enumerated VPC has a Bedrock interface endpoint | vpc")

    def _ai_scan_regions(self):
        """Regions to query for AI creation events.

        The scanned set, which --all-regions widens. Deliberately NOT every AWS region:
        an unbounded sweep is slow and expensive, and SHAI-02 reports what the chosen
        set could not see rather than pretending the set was complete."""
        return list(self._coverage.scanned_regions or [self.region])

    # ══════════════════════════════════════════════════════════════════════════
    # SECTION 34: AI LOGGING DEPTH (slice 4.3)
    # ══════════════════════════════════════════════════════════════════════════
    def _check_ai_logging(self):
        """AILOG-01..06 — where the prompts land, and who saw the call.

        The second half of BDR-01's own advice. BDR-01 says turn invocation logging on,
        which is right — it is the only control in the AI pillar that produces evidence
        after an incident. What it never asked is what that produces: with
        textDataDeliveryEnabled, the destination receives every prompt and every
        completion in the account and becomes a crown jewel on the day it is switched on.

        Configuration only. The reason the destination matters is that it holds prompts,
        and a scanner that read them to check them would be the second copy of the
        problem — D2 and D8."""
        self._section_header("AI_LOGGING")
        self._check_prompt_log_destinations()
        self._check_ai_data_events()

    def _check_prompt_log_destinations(self):
        """AILOG-01..03 — the sink BDR-01 names, assessed as the crown jewel it is."""
        try:
            bedrock = self._client("bedrock")
            config = (bedrock.get_model_invocation_logging_configuration() or {}
                      ).get("loggingConfig") or {}
        except Exception as e:
            if self._is_access_denied(e):
                for cid in ("AILOG-01", "AILOG-02", "AILOG-03"):
                    self._coverage.note_denied(
                        cid, "bedrock:GetModelInvocationLoggingConfiguration")
                self._add("INFO", "AILOG-00", "AI_LOGGING", "bedrock",
                          "Prompt-log destinations NOT audited — missing "
                          "bedrock:GetModelInvocationLoggingConfiguration "
                          "(no phantom pass)")
            return

        posture = aws_ailog.delivery_posture(config)
        sinks = aws_ailog.log_destinations(config)
        if not posture["enabled"]:
            return                      # BDR-01 already reports logging being off
        if not posture["carries_content"]:
            # Metrics-shaped logging. Saying nothing would be wrong too: an operator who
            # believes they have an audit trail of prompts should learn they do not.
            self._add("INFO", "AILOG-00", "AI_LOGGING", "bedrock",
                      f"Invocation logging is on but delivers no prompt or completion "
                      f"payloads ({', '.join(posture['modalities']) or 'metadata only'}) "
                      f"— there is no record of what was actually asked or answered")
            return

        self._add("INFO", "AILOG-00", "AI_LOGGING", "bedrock",
                  f"{aws_ailog.describe_delivery(posture, sinks)}. "
                  f"{aws_ailog.CONTENTS_NOT_READ}")

        for sink in sinks:
            label = f"{sink['name']}"
            if sink["kind"] == "s3":
                self._assess_prompt_log_bucket(sink, posture)
            else:
                self._assess_prompt_log_group(sink, posture)

    def _assess_prompt_log_bucket(self, sink, posture):
        """AILOG-01/02/03 for an S3 prompt-log destination."""
        bucket = sink["name"]
        s3 = self._client("s3")
        role = f" ({sink['role']})" if sink.get("role") != "primary" else ""

        # Public? Same discipline as LOG-09: AccessDenied means the bucket belongs to
        # another account, which is a COVERAGE fact, never a FAIL.
        try:
            bpa = (s3.get_public_access_block(Bucket=bucket) or {}).get(
                "PublicAccessBlockConfiguration") or {}
            blocked = bool(bpa) and all(bpa.values())
        except Exception as e:
            if self._is_access_denied(e):
                self._coverage.note_denied("AILOG-01", "s3:GetBucketPublicAccessBlock")
                self._add("INFO", "AILOG-00", "AI_LOGGING", bucket,
                          f"Prompt-log bucket '{bucket}'{role} is owned by another "
                          f"account — its exposure cannot be verified from here "
                          f"(no phantom pass)")
                return
            blocked = False

        exposed = False
        if not blocked:
            try:
                pol = (s3.get_bucket_policy(Bucket=bucket) or {}).get("Policy")
                for st in (json.loads(pol) or {}).get("Statement", []) if pol else []:
                    # The shared classifier's field is "kind", and its public values
                    # are "public" and "public_conditioned" -- read off the function
                    # rather than recalled, after the first authoring of this line
                    # invented a "scope" key that never existed and therefore never
                    # matched. A condition-scoped public grant still counts: a
                    # condition narrows WHO, not whether the principal is the world.
                    verdict = classify_resource_policy_stmt(st, self.account or "")
                    if verdict and verdict.get("kind") in ("public",
                                                           "public_conditioned"):
                        exposed = True
            except Exception as e:
                if self._is_access_denied(e):
                    self._coverage.note_denied("AILOG-01", "s3:GetBucketPolicy")

        if exposed:
            self._add("FAIL", "AILOG-01", "AI_LOGGING", bucket,
                      f"Prompt-log bucket '{bucket}'{role} is PUBLICLY accessible and "
                      f"receives {' and '.join(posture['modalities'])} payloads — every "
                      f"prompt users sent and every completion the model returned. "
                      f"Treat as a disclosure until access logs say otherwise | {bucket}")
        elif blocked:
            self._add("PASS", "AILOG-01", "AI_LOGGING", bucket,
                      f"Prompt-log bucket '{bucket}'{role} blocks public access | {bucket}")

        # AILOG-02 — key custody on the sink.
        try:
            enc = (s3.get_bucket_encryption(Bucket=bucket) or {}).get(
                "ServerSideEncryptionConfiguration", {}).get("Rules", [])
            cmk = any((r.get("ApplyServerSideEncryptionByDefault") or {}).get(
                "KMSMasterKeyID") for r in enc)
        except Exception as e:
            if self._is_access_denied(e):
                self._coverage.note_denied("AILOG-02", "s3:GetEncryptionConfiguration")
                return
            cmk = False
        self._add("FAIL" if not cmk else "PASS", "AILOG-02", "AI_LOGGING", bucket,
                  (f"Prompt-log bucket '{bucket}'{role} is not encrypted with a "
                   f"customer-managed key — no key you can disable to cut access to "
                   f"the prompt history | {bucket}") if not cmk else
                  f"Prompt-log bucket '{bucket}'{role} uses a customer-managed key "
                  f"| {bucket}")

    def _assess_prompt_log_group(self, sink, posture):
        """AILOG-02/03 for a CloudWatch prompt-log destination.

        AILOG-01 does not apply: a log group has no public-access concept. Emitting a
        PASS for it would be a clean answer to a question that was never asked."""
        group = sink["name"]
        logs = self._client("logs")
        try:
            found = (logs.describe_log_groups(logGroupNamePrefix=group) or {}
                     ).get("logGroups") or []
        except Exception as e:
            if self._is_access_denied(e):
                for cid in ("AILOG-02", "AILOG-03"):
                    self._coverage.note_denied(cid, "logs:DescribeLogGroups")
            return
        lg = next((g for g in found if g.get("logGroupName") == group), None)
        if lg is None:
            self._add("INFO", "AILOG-00", "AI_LOGGING", group,
                      f"Prompt-log group '{group}' is configured on Bedrock but was not "
                      f"found in this region — logging may be silently failing")
            return
        cmk = bool(lg.get("kmsKeyId"))
        self._add("FAIL" if not cmk else "PASS", "AILOG-02", "AI_LOGGING", group,
                  (f"Prompt-log group '{group}' is not encrypted with a customer-managed "
                   f"key — no key you can disable to cut access to the prompt history "
                   f"| {group}") if not cmk else
                  f"Prompt-log group '{group}' uses a customer-managed key | {group}")
        retention = lg.get("retentionInDays")
        self._add("FAIL" if not retention else "PASS", "AILOG-03", "AI_LOGGING", group,
                  (f"Prompt-log group '{group}' has NO retention policy — every prompt "
                   f"and completion is kept indefinitely. Prompt logs are evidence, and "
                   f"evidence with no expiry is also a growing liability | {group}")
                  if not retention else
                  f"Prompt-log group '{group}' retains for {retention} day(s) | {group}")

    def _check_ai_data_events(self):
        """AILOG-04..06 — whether any trail records AI data-plane activity.

        LOG-08 asks whether a trail records data events at all, so an account passes it
        while no trail anywhere names AWS::Bedrock::Model. That is the difference between
        'we log data events' and 'we can tell you who invoked which model'."""
        try:
            ct = self._client("cloudtrail")
            trails = (ct.describe_trails(includeShadowTrails=True) or {}
                      ).get("trailList") or []
        except Exception as e:
            if self._is_access_denied(e):
                for cid in ("AILOG-04", "AILOG-05", "AILOG-06"):
                    self._coverage.note_denied(cid, "cloudtrail:DescribeTrails")
                self._add("INFO", "AILOG-00", "AI_LOGGING", "cloudtrail",
                          "AI data-event coverage NOT audited — missing "
                          "cloudtrail:DescribeTrails (no phantom pass)")
            return

        seen, collected, denied = set(), [], False
        for t in trails:
            arn = t.get("TrailARN") or t.get("Name")
            if not arn or arn in seen:
                continue
            seen.add(arn)
            try:
                collected.append({"name": t.get("Name") or arn,
                                  "selectors": ct.get_event_selectors(TrailName=arn)})
            except Exception as e:
                if self._is_access_denied(e):
                    denied = True
        if denied and not collected:
            for cid in ("AILOG-04", "AILOG-05", "AILOG-06"):
                self._coverage.note_denied(cid, "cloudtrail:GetEventSelectors")
            self._add("INFO", "AILOG-00", "AI_LOGGING", "cloudtrail",
                      "AI data-event coverage NOT established — event selectors "
                      "unreadable on every trail (no phantom pass)")
            return
        if not collected:
            return                      # no trails at all: LOG-01 already reports that

        cov = aws_ailog.trail_ai_data_events(collected)

        self._add("FAIL" if not cov["model_invocations"] else "PASS", "AILOG-04",
                  "AI_LOGGING", "cloudtrail",
                  ("No CloudTrail trail records AWS::Bedrock::Model data events — there "
                   "is no record of who invoked which model, with which identity, from "
                   "where. Basic event selectors cannot express this; it needs an "
                   "ADVANCED selector | cloudtrail")
                  if not cov["model_invocations"] else
                  f"Model invocations are recorded as data events by "
                  f"{', '.join(t for t, v in cov['by_trail'].items() if aws_ailog.MODEL_DATA_TYPE in v)}"
                  f" | cloudtrail")

        # AILOG-05/06 report the REMAINING gaps only where some AI coverage exists.
        # On an account with no AI data events at all, AILOG-04 is the finding and
        # repeating it twice more is noise rather than depth.
        if cov["any"]:
            missing = [t for t in cov["bedrock_missing"]
                       if t != aws_ailog.MODEL_DATA_TYPE]
            if missing:
                # WARN, deliberately, and declared LOW to match. AILOG-04 is THE
                # finding when there is no model data-event coverage at all; 05 and 06
                # report PARTIAL coverage, a gradation beneath it. Raising them to FAIL
                # would report one gap three times -- which
                # test_no_ai_coverage_at_all_reports_once_not_three_times exists to
                # prevent, and which the bucket-B pass nearly did.
                self._add("WARN", "AILOG-05", "AI_LOGGING", "cloudtrail",
                          f"Bedrock data events cover model invocations but not "
                          f"{', '.join(missing)} — agent, knowledge-base and guardrail "
                          f"activity leaves no data-plane record | cloudtrail")
            if cov["agentcore_missing"] and self._has_agentcore_estate():
                self._add("WARN", "AILOG-06", "AI_LOGGING", "cloudtrail",
                          f"No data events for {len(cov['agentcore_missing'])} AgentCore "
                          f"resource type(s) — an agent's own actions leave no "
                          f"data-plane record, which is the trail an incident responder "
                          f"follows after a prompt injection | cloudtrail")

    def _has_agentcore_estate(self) -> bool:
        """Whether this account runs AgentCore at all.

        Reporting an AgentCore logging gap to an account with no AgentCore is noise, and
        noise is how a category gets ignored. Derived from what the AGENTCORE section
        already stashed rather than from a second enumeration."""
        return any((r.get("kind") or "").startswith("AgentCore")
                   for r in (self._aispm_resources or []))

    # ══════════════════════════════════════════════════════════════════════════
    # SECTION 33: RAG VECTOR STORES (slice 4.2)
    # ══════════════════════════════════════════════════════════════════════════
    def _org_policy_docs(self, org, nodes, filt, denied):
        """Every policy document of one type attached from the account up to the root.

        Returns None when ANY level was unreadable — an unread level cannot be reported
        as an absent control, and a partial walk would understate the perimeter. Only a
        complete walk returning nothing means "no policy of this type"."""
        docs = []
        for node in nodes:
            try:
                # NOT _paginate_all: it swallows every exception and returns [], which
                # would turn a denied ListPoliciesForTarget into "no policies exist" --
                # a finding manufactured out of a permission error. Paginate by hand so
                # the denial actually reaches the caller.
                pols, token, guard = [], None, 0
                while guard < 100:              # bounded: never loop on a bad token
                    guard += 1
                    kw = {"TargetId": node, "Filter": filt}
                    if token:
                        kw["NextToken"] = token
                    resp = org.list_policies_for_target(**kw) or {}
                    pols += list(resp.get("Policies") or [])
                    token = resp.get("NextToken")
                    # A continuation token is a STRING. Anything else -- notably a
                    # MagicMock, which is truthy -- ends the walk instead of spinning
                    # forever: an unguarded `if not token` hung every mocked test that
                    # reaches this section.
                    if not isinstance(token, str) or not token:
                        break
            except Exception as e:
                if self._is_access_denied(e):
                    denied.append("organizations:ListPoliciesForTarget")
                return None
            for pol in pols:
                pid = pol.get("Id")
                if not pid:
                    continue
                try:
                    docs.append(org.describe_policy(
                        PolicyId=pid)["Policy"]["Content"])
                except Exception as e:
                    if self._is_access_denied(e):
                        denied.append("organizations:DescribePolicy")
                    return None
        return docs

    # ══════════════════════════════════════════════════════════════════════════
    # BATCH 1 — services from the 426-service coverage gap analysis
    # Each section is TOP-LEVEL and self-contained: a denial degrades that one
    # section to a coverage note and never becomes a clean pass elsewhere.
    # ══════════════════════════════════════════════════════════════════════════
    # ══════════════════════════════════════════════════════════════════════════
    # BATCH 2 — declared via aws_checkdef (see aws_extsvc2)
    # ══════════════════════════════════════════════════════════════════════════
    def _tokens(self, fn, key, token_key="NextToken", **kw):
        """Bounded pagination that lets denials REACH the caller.

        A continuation token is a STRING. Anything else -- notably a truthy MagicMock --
        ends the walk rather than spinning, which is the defect that cost a suite run."""
        out, token, guard = [], None, 0
        while guard < 100:
            guard += 1
            call = dict(kw)
            if token:
                call[token_key] = token
            resp = fn(**call) or {}
            out += list(resp.get(key) or [])
            token = resp.get(token_key)
            if not isinstance(token, str) or not token:
                break
        return out

    # ══════════════════════════════════════════════════════════════════════════
    # BATCH 3 — declared via aws_checkdef (see aws_extsvc3)
    # ══════════════════════════════════════════════════════════════════════════
    # ══════════════════════════════════════════════════════════════════════════
    # BATCH 4 — declared via aws_checkdef (see aws_extsvc4)
    # ══════════════════════════════════════════════════════════════════════════
    # ══════════════════════════════════════════════════════════════════════════
    # BATCH 5 — declared via aws_checkdef (see aws_extsvc5)
    # ══════════════════════════════════════════════════════════════════════════
    # ══════════════════════════════════════════════════════════════════════════
    # BATCH 6 — declared via aws_checkdef (see aws_extsvc6)
    # ══════════════════════════════════════════════════════════════════════════
    # ══════════════════════════════════════════════════════════════════════════
    # BATCH 7 — declared via aws_checkdef (see aws_extsvc7)
    # NOTE: CloudFormation's checks are STACK-*. CFN-01..06 are CLOUDFRONT.
    # ══════════════════════════════════════════════════════════════════════════
    def _check_cloudformation(self):
        """STACK-01/02 — a stack is the definition of its infrastructure."""
        self._section_header("CLOUDFORMATION")
        try:
            cf = self._client("cloudformation")
            stacks = self._tokens(cf.describe_stacks, "Stacks", token_key="NextToken")
        except Exception as e:
            if self._is_access_denied(e):
                for cid in ("STACK-01", "STACK-02"):
                    self._coverage.note_denied(cid, "cloudformation:ListStacks")
            return

        for st in stacks:
            name = (st or {}).get("StackName")
            if not name:
                continue
            r = aws_extsvc7.stack_service_role(st)
            if not r["has_role"]:
                self._add("FAIL", "STACK-02", "CLOUDFORMATION", name,
                          f"{r['statement']} | {name}")
            else:
                self._add("PASS", "STACK-02", "CLOUDFORMATION", name,
                          f"CloudFormation stack {name} runs under service role "
                          f"{r['role']} | {name}")
            try:
                body = (cf.get_stack_policy(StackName=name) or {}).get("StackPolicyBody")
            except Exception as e:
                if self._is_access_denied(e):
                    self._coverage.note_denied("STACK-01",
                                               "cloudformation:GetStackPolicy")
                continue
            p = aws_extsvc7.stack_policy(name, body)
            if not p["has_policy"]:
                self._add("FAIL", "STACK-01", "CLOUDFORMATION", name,
                          f"{p['statement']} | {name}")
            else:
                self._add("PASS", "STACK-01", "CLOUDFORMATION", name,
                          f"CloudFormation stack {name} has a stack policy | {name}")

    def _check_firewallmanager(self):
        """FMS-01/02 — a control that reports without enforcing, and without telling."""
        self._section_header("FIREWALLMANAGER")
        try:
            fms = self._client("fms")
            policies = self._tokens(fms.list_policies, "PolicyList",
                                    token_key="NextToken")
        except Exception as e:
            if self._is_access_denied(e):
                self._coverage.note_denied("FMS-01", "fms:ListPolicies")
            policies = None

        for p in (policies or []):
            pid = (p or {}).get("PolicyId")
            if not pid:
                continue
            try:
                full = (fms.get_policy(PolicyId=pid) or {}).get("Policy") or {}
            except Exception as e:
                if self._is_access_denied(e):
                    self._coverage.note_denied("FMS-01", "fms:GetPolicy")
                continue
            r = aws_extsvc7.fms_policy({**full, **(p or {})})
            nm = r["name"] or pid
            if r["known"] and not r["remediates"]:
                self._add("FAIL", "FMS-01", "FIREWALLMANAGER", nm,
                          f"{r['statement']} | {nm}")
            elif r["remediates"]:
                self._add("PASS", "FMS-01", "FIREWALLMANAGER", nm,
                          f"Firewall Manager policy {nm} remediates non-compliance "
                          f"| {nm}")

        try:
            ch = fms.get_notification_channel() or {}
            r = aws_extsvc7.fms_notification(ch)
        except Exception as e:
            if self._is_access_denied(e):
                self._coverage.note_denied("FMS-02", "fms:GetNotificationChannel")
                return
            # ResourceNotFound means no channel is set, which IS the finding.
            r = aws_extsvc7.fms_notification(None,
                                             readable="NotFound" in str(e))
        if not r["configured"] and r["known"]:
            self._add("FAIL", "FMS-02", "FIREWALLMANAGER", "notifications",
                      f"{r['statement']} | notifications")
        elif r["configured"]:
            self._add("PASS", "FMS-02", "FIREWALLMANAGER", "notifications",
                      f"Firewall Manager notifies {r['topic']} | notifications")

